window.__Q=window.__Q||{};window.__Q["prev/3/A1"]=[{"q":"CO2的扩散系数约是O2的20倍，主要是由于","o":["CO2的分子量大","CO2的分子量小","CO2的溶解度大","CO2的溶解度小","呼吸膜两侧分压差大"],"a":2,"e":"气体扩散系数与溶解度成正比、与分子量平方根成反比，CO2在水中的溶解度远大于O2约20倍，而两者分子量差异有限，故CO2扩散系数约为O2的20倍。A项CO2分子量44大于O2的32，并非更大分子量造成；B项分子量小与事实不符；D项溶解度小相反；E项分压差影响扩散速率却不决定扩散系数本身"},{"q":"在异丙肾上腺素作用（只增强心室肌收缩力）下，心室功能曲线向哪个方向移位","o":["正上方","右上方","左上方","右下方","左下方"],"a":0,"e":"心室功能曲线反映每搏功与心室舒张末期压的关系。异丙肾上腺素增强心肌收缩力，使同一前负荷下搏出量增加，曲线整体上移，即向正上方移位。B项右上方、C项左上方多见于前负荷或后负荷改变伴收缩力变化；D、E项下移提示收缩力减弱，与正性肌力作用相反"},{"q":"以下关于心肌收缩特点的描述，错误的是","o":["肌质网发达","收缩对细胞外Ca2+依赖性大","呈“全或无”式收缩","不发生完全强直收缩","长度-张力曲线一般不出现降支"],"a":0,"e":"心肌细胞肌质网不发达，储钙能力弱，收缩高度依赖细胞外Ca2+内流，故“肌质网发达”的描述错误。心肌为功能性合胞体，兴奋迅速扩布使整块心肌近于同步收缩，呈“全或无”式；其有效不应期长，故不发生完全强直收缩。长度-张力曲线因肌节被过度拉长受限而一般不出现降支"},{"q":"下列情况可引起颈动脉窦的传入神经冲动增加的是","o":["循环血量降低","PaO2降低","PaCO2升高","血液中H+增多","平均动脉压升高"],"a":4,"e":"颈动脉窦是压力感受器，在耐受范围内血管壁被牵张程度随动脉压升高而增大，经窦神经传入的冲动增加，反射性抑制交感、兴奋迷走使血压下降。A项循环血量降低、B项PaO2降低、C项PaCO2升高、D项血中H+增多主要影响容量感受器或化学感受器，血压下降时压力感受器传入反而减少"},{"q":"关于肾小管葡萄糖重吸收的描述，正确是","o":["全部肾小管均能重吸收葡萄糖","葡萄糖重吸收属于易化扩散","只有近端小管能吸收葡萄糖，属于易化扩散","只有近端小管能吸收葡萄糖，顶端膜的转运属于继发性主动转运，基底侧膜的转运属于被动易化扩散","只有近端小管能吸收葡萄糖，顶端膜和基底侧膜的转运都属于继发性主动转运"],"a":3,"e":"葡萄糖仅在近端小管被重吸收，其顶端膜经Na+-葡萄糖同向转运体实现继发性主动转运，基底侧膜经葡萄糖转运体以被动易化扩散入血。葡萄糖重吸收不属于单纯易化扩散；全部肾小管均能重吸收、顶端膜与基底侧膜均为继发性主动转运的说法均错误"},{"q":"在心肌状态和大动脉压力保持恒定的情况下，在一定范围内增加静脉回流量可以增加心室肌的","o":["前负荷","后负荷","心率","代谢率","前负荷和后负荷"],"a":0,"e":"心肌状态与大动脉压力恒定时，增加静脉回流量使心室舒张末期容积增大，即增加前负荷，通过Starling机制使搏出量增加。后负荷由大动脉压力决定，题设已恒定；心率与代谢率并非静脉回流直接改变的对象；大动脉压不变意味着后负荷不变，故不是前负荷与后负荷同时增加"},{"q":"在体内，主要用于供能的营养物质是","o":["糖、脂肪与蛋白质","糖与蛋白质","脂肪与蛋白质","脂肪与核酸","糖与脂肪"],"a":4,"e":"糖与脂肪是体内主要供能物质，糖供能约占50%～70%，脂肪是主要储能形式，氧化1g脂肪释放的能量约为糖的两倍。蛋白质主要在糖和脂肪耗竭时供能，核酸不供能，故仅含蛋白质或含核酸的组合均不准确，供能以糖和脂肪为主"},{"q":"关于瘦素的分泌特点，以下哪项是错误的","o":["具有昼夜节律","只有白色脂肪组织合成分泌","体脂量可影响瘦素的分泌","摄食时，瘦素分泌增多","大多肥胖者瘦素分泌增多"],"a":1,"e":"瘦素主要由白色脂肪组织分泌，但棕色脂肪、胎盘、骨骼肌等也能合成，故“只有白色脂肪组织合成分泌”这一绝对化表述错误。瘦素分泌具有昼夜节律，夜间浓度升高；其水平与体脂量正相关，摄食后可增多，大多肥胖者血瘦素反而增高并存在瘦素抵抗。A项昼夜节律、C项体脂量影响、D项摄食增多、E项肥胖者增高均为正确描述"},{"q":"下列关于外周化学感受器的描述，正确的是","o":["O2含量的降低是外周化学感受器的敏感刺激","外周化学感受器对动脉血中H+浓度的增加不敏感","PCO2的升高是外周化学感受器的敏感刺激","外周化学感受器的适宜刺激是动脉血中的血红蛋白含量","颈动脉体中起感受器作用的部分是Ⅱ型细胞"],"a":2,"e":"外周化学感受器（颈动脉体、主动脉体）的敏感刺激为动脉血PO2降低、PCO2升高和H+浓度升高，故PCO2升高为其敏感刺激之一。A项把刺激写成氧含量降低，实际敏感的是氧分压而非含量；E项感受器实为Ⅰ型球细胞，Ⅱ型只是支持细胞；B项称对H+不敏感与事实相悖，D项血红蛋白含量更非其适宜刺激"},{"q":"胆汁中参与消化作用的主要成分是","o":["胆色素","胆盐","胆固醇","脂肪酸","卵磷脂"],"a":1,"e":"胆盐是胆汁中参与消化的主要成分，可乳化脂肪、增大脂肪与脂肪酶接触面积，并形成混合微胶粒促进脂肪酸与甘油一酯吸收。胆色素为血红蛋白分解产物，无消化作用；胆固醇为胆汁成分但不参与消化；脂肪酸是消化产物；卵磷脂虽参与微胶粒形成，作用不及胆盐主要"},{"q":"对肺泡气体分压变化起缓冲作用的是","o":["补吸气量","补呼气量","深吸气量","功能余气量","余气量"],"a":3,"e":"功能余气量为平静呼气末存留于肺内的气量，吸气时稀释新鲜空气、呼气时补充气体，从而缓冲肺泡气体分压的剧烈波动。E项余气量是最大呼气后残余气量，不能代表平静呼吸的缓冲容量；A项补吸气量与B项补呼气量只是肺容量的组成，C项深吸气量为潮气量与补吸气量之和，均无缓冲肺泡分压的作用"},{"q":"正常人在下列各种情况下能量代谢水平最低的是","o":["安静状态","心算","散步","劳动","基础状态"],"a":4,"e":"基础状态指清醒、安静、空腹、室温20～25℃的条件，排除了食物特殊动力效应、肌肉活动和环境温度影响，能量代谢水平最低。安静状态可能处于餐后，代谢高于基础状态；心算、散步、劳动均增加能量消耗，故基础状态最低"},{"q":"人体在运动状态下的主要产热器官是","o":["心脏","肝脏","肾脏","平滑肌","骨骼肌"],"a":4,"e":"安静时主要产热器官为肝脏、脑等内脏，运动时骨骼肌大量收缩，代谢急剧增强，产热量可占总产热量绝大部分，成为主要产热器官。心脏（A项）、肾脏（C项）产热有限；肝脏（B项）为安静时主要产热器官；平滑肌（D项）产热少，均非运动时主导"},{"q":"下列各项中，不属于神经纤维兴奋传导特征的是","o":["完整性","绝缘性","双向性","衰减性","相对不疲劳性"],"a":3,"e":"神经纤维兴奋传导具有完整性、绝缘性、双向性和相对不疲劳性，动作电位沿纤维传导时不衰减，故衰减性不是其特征。完整性（A项）要求结构功能完整；绝缘性（B项）保证各纤维互不干扰；双向性（C项）指刺激中点向两端传导；相对不疲劳性（E项）为神经纤维的特点"},{"q":"下列哪种因素使冠脉血流量增加最为明显","o":["动脉血流速度加快","心率加快","心肌收缩力减弱","射血速度加快","动脉舒张压升高"],"a":4,"e":"冠脉循环的特点是心肌收缩时冠脉受压、血流减少，舒张期血流增加，因此主动脉舒张压升高是增加冠脉血流最明显的因素。A项动脉血流速度加快、D项射血速度加快影响有限；B项心率加快缩短舒张期，反不利于冠脉灌注；C项心肌收缩力减弱虽减轻压迫，但不如舒张压升高显著"},{"q":"甲状腺激素能降低以下哪项","o":["糖酵解","糖原异生","血浆胆固醇的水平","血浆氨基酸水平","血浆游离脂肪酸浓度"],"a":2,"e":"甲状腺激素促进胆固醇的合成与分解，但分解更强并促进胆固醇经胆汁排出，故可降低血浆胆固醇水平，甲减患者常伴高胆固醇血症。A项糖酵解、B项糖原异生均被甲状腺激素增强；D项血浆氨基酸水平因蛋白分解加强可升高；E项游离脂肪酸因脂肪动员增强而增多，均非降低项"},{"q":"眼尽最大能力调节时所能看清物体的最近距离称为","o":["远点","节点","后主焦点","前主焦点","近点"],"a":4,"e":"近点是指眼尽最大调节能力所能看清物体的最近距离，反映晶状体的最大调节能力，随年龄增长而增大。远点是眼在完全放松调节时能看清的最远距离；节点、前主焦点和后主焦点均为简化眼模型中的光学参数，与调节时看清物体的最近距离无关"},{"q":"自主神经系统对内脏活动调节的重要特点是","o":["所有脏器均有双重神经支配","均为双重神经支配拮抗作用","具有持久紧张性作用","调节作用与效应器本身机能状态无关","副交感神经系统兴奋时作用广泛"],"a":2,"e":"自主神经对内脏的调节具有持久的紧张性活动，安静时仍持续发放低频冲动，维持心血管、呼吸道等基础功能，这是其重要特点。并非所有脏器都有双重支配（A、B项），如汗腺、肾上腺髓质仅受交感支配；调节与效应器机能状态有关（D项错）；副交感兴奋作用局限（E项错），交感兴奋作用才广泛"},{"q":"血浆晶体渗透压主要来自血浆的","o":["NaCl","葡萄糖","白蛋白","球蛋白","纤维蛋白"],"a":0,"e":"血浆晶体渗透压主要来自Na+和Cl-即NaCl，因其含量高、颗粒数多，是形成晶体渗透压的主要物质。葡萄糖虽为晶体物质但浓度低，贡献小；白蛋白、球蛋白与纤维蛋白为血浆蛋白，主要形成胶体渗透压而非晶体渗透压"},{"q":"胰岛素受体具有酪氨酸蛋白激酶活性的结构域位于受体的哪一部分","o":["α亚单位的N端","α亚单位的C端","β亚单位N端膜外部分","β亚单位的中间跨膜部分","β亚单位C端膜内部分"],"a":4,"e":"胰岛素受体由α、β亚单位组成，α亚单位位于膜外结合胰岛素，β亚单位跨膜，其胞内C端含酪氨酸蛋白激酶结构域，可自磷酸化并磷酸化底物。A、B项α亚单位无激酶活性；C项β亚单位N端膜外部分主要与α亚单位结合；D项跨膜部分仅起锚定作用，都不是激酶活性域所在"},{"q":"纤溶酶的主要作用是","o":["激活因子Ⅻ","激活补体系统","抑制激肽系统","水解凝血酶及因子Ⅴ、Ⅶ","水解纤维蛋白原和纤维蛋白"],"a":4,"e":"纤溶酶是纤溶系统的核心蛋白酶，主要水解纤维蛋白原和纤维蛋白，生成纤维蛋白降解产物，使血栓溶解、保持血管通畅。激活因子Ⅻ（A项）属内源性凝血启动，由接触激活完成；激活补体系统（B项）为免疫防御；抑制激肽系统（C项）非其主要作用；水解凝血酶及因子Ⅴ、Ⅶ（D项）实为蛋白C系统的抗凝作用，不是纤溶酶"},{"q":"体外实验中，用葡萄糖逐渐替代浸浴液中的Na+，神经元或神经纤维动作电位的幅度将","o":["逐渐增大","逐渐减小","不发生改变","先增大后减小","先减小后增大"],"a":1,"e":"动作电位的幅度取决于Na+内流的电化学驱动力，细胞外Na+被葡萄糖替换后浓度梯度减小，Na+内流减少，幅度逐渐减小。葡萄糖不能替代Na+产生内向电流，故幅度不会增大或不变；由于幅度随Na+浓度梯度单调下降，也不会出现先增大后减小或先减小后增大的双向变化"},{"q":"关于基底膜振动的正确叙述是","o":["不同频率的声音在同一部位产生最大振动","声音频率越高，最大振动越近顶部","对于特定频率的振动，在基底膜上有一特定的行波传播范围和最大振幅区","声音频率越低，最大振动越近底部","不同频率的声波引起的行波是从基底膜底不同部位开始的"],"a":2,"e":"行波学说认为，特定频率声波在基底膜上形成行波，自底部向顶部传播并逐渐增大振幅，在某一特定部位达最大后迅速衰减，该部位即此频率的最大振幅区。A项不同频率最大振动部位不同；B项频率越高最大振动越近底部蜗底；D项频率越低越近顶部；E项行波均自蜗底开始，非从底部不同部位起始"},{"q":"慢波睡眠的特征是","o":["脑电呈去同步化的慢波","多梦","生长激素分泌减少","促进生长和体力恢复","促进神经系统发育成熟"],"a":3,"e":"慢波睡眠中生长激素分泌明显增多，促进蛋白质合成与组织修复，有利于生长和体力恢复。脑电去同步化快波与多梦是快眼动睡眠的特点；生长激素在慢波睡眠分泌增加而非减少；促进神经系统发育成熟主要是快眼动睡眠的作用"},{"q":"衡量可兴奋组织兴奋性常用的指标是","o":["阈强度","阈电位","静息电位","动作电位幅值","动作电位传导速度"],"a":0,"e":"衡量可兴奋组织兴奋性最常用的指标是阈强度，即在刺激时间与强度-时间变化率固定时引起兴奋的最小刺激强度，阈强度越小兴奋性越高。阈电位（B项）是触发动作电位的临界膜电位，反映细胞本身特性而非兴奋性指标；静息电位（C项）、动作电位幅值（D项）、传导速度（E项）均不直接度量兴奋性高低"},{"q":"血小板减少导致皮肤出现自发性出血斑点的主要原因是","o":["血小板不能聚集成团","血小板不能释放足够的血管活性物质","不能修复和保持血管内皮细胞完整性","血凝块回缩障碍","血小板黏附减少"],"a":2,"e":"血小板可填充血管内皮细胞间隙，参与修复并维持血管壁完整性，其减少时红细胞易外渗形成出血斑点。不能聚集成团（A项）与黏附减少（E项）主要妨碍止血栓形成，并非自发性出血点的主因。血凝块回缩障碍（D项）源于血小板收缩蛋白，与此无关"},{"q":"胰岛素的生物学作用不包括","o":["促进葡萄糖进入细胞","促进脂肪酸转变成葡萄糖","促进糖原合成","促进机体生长","抑制脂肪和蛋白质分解"],"a":1,"e":"胰岛素促进葡萄糖进入细胞、糖原合成和机体生长，并抑制脂肪与蛋白质分解。脂肪酸经β氧化生成乙酰CoA，不能逆转为丙酮酸进而变成葡萄糖，故促进脂肪酸转变成葡萄糖不是胰岛素的作用；该过程在生物体内本身也几乎不能发生，更不受胰岛素促进"},{"q":"听觉感受器是","o":["螺旋器","耳蜗","椭圆囊斑","球囊斑","壶腹嵴"],"a":0,"e":"螺旋器又称Corti器，位于蜗管鼓壁的螺旋膜上，是听觉感受器。壶腹嵴为感受头部旋转变速运动的位置觉感受器；椭圆囊斑和球囊斑感受直线变速运动及静止体位；血管纹与内淋巴的产生有关；基底膜为螺旋器的附着部位，本身不是感受器"},{"q":"机体的内环境是指","o":["体液","细胞内液","细胞外液","血浆","组织液"],"a":2,"e":"内环境指细胞直接生活的液体环境，即细胞外液，包括血浆和组织液等，是细胞与外界进行物质交换的媒介。细胞内液不属于内环境；体液范围更广，包含细胞内液；血浆和组织液都只是细胞外液的一部分，不能单独等同于内环境整体"},{"q":"下列关于生理学的叙述，错误的是","o":["是生物科学的1个分支","是1门实验性科学","是1门重要的医学基础理论课程","其研究对象是生物体","研究水平仅包括系统器官和细胞分子两个方面"],"a":4,"e":"生理学的研究水平包括整体、系统器官、细胞分子多个层次，故仅包括系统器官和细胞分子两个方面错误。生理学是生物科学的分支、实验性科学和重要医学基础课程，其研究对象为生物体，这些表述均正确，本题以研究水平的范围设错"},{"q":"体内调节血钙水平最重要的激素是","o":["甲状旁腺激素","甲状腺激素","醛固酮","糖皮质激素","生长素"],"a":0,"e":"甲状旁腺激素是调节血钙最重要的激素，通过促进骨钙动员、增强肾小管对钙的重吸收及促进活性维生素D生成而升高血钙。降钙素虽能降低血钙，但作用较弱、居次要地位；甲状腺激素、醛固酮、糖皮质激素、生长素均非血钙稳态的主要调节者"},{"q":"神经纤维动作电位去极化过程中，膜电位值超过0mV的部分称为","o":["去极化","超极化","复极化","超射","极化"],"a":3,"e":"动作电位去极化时膜电位超过0mV的正电位部分称为超射，其数值接近Na+平衡电位，反映Na+内流的驱动力。去极化（A项）指膜电位向0mV方向减小；超极化（B项）为膜电位负值增大；复极化（C项）为回到静息电位；极化（E项）为静息时膜两侧电荷分布状态，均非超过0mV的部分"},{"q":"引起促胰液素释放作用最强的物质是","o":["蛋白质分解产物","HCl","脂酸钠","淀粉","葡萄糖"],"a":1,"e":"促胰液素由十二指肠S细胞释放，盐酸是刺激其释放的最强因素，进入小肠的HCl可直接作用于S细胞。蛋白质分解产物虽也刺激释放，却是缩胆囊素的最强刺激因素，两者常被互换设错；脂酸钠刺激作用较弱，淀粉与葡萄糖基本无刺激作用"},{"q":"对雄激素分泌减少导致生育力降低的男性患者，临床上治疗主要采用的激素是","o":["雄激素","糖皮质激素","FSH","hCG","GnRH"],"a":3,"e":"hCG的生物学作用类似LH，可刺激睾丸间质细胞合成与分泌睾酮，从而促进精子发生并改善生育力，临床用于低促性腺激素性性腺功能减退。A项直接补充雄激素会经负反馈抑制下丘脑垂体，反而抑制生精；C项FSH主要促进生精上皮发育，需与睾酮协同；B项糖皮质激素、E项GnRH都不是针对雄激素缺乏的主要治疗激素"},{"q":"正常情况下，声波由外耳传入内耳最主要的途径是","o":["外耳道→鼓膜→听骨链→卵圆窗膜→内耳外淋巴","外耳道→鼓膜→听骨链→卵圆窗膜→内耳内淋巴","外耳道→鼓膜→鼓室空气→圆窗膜→内耳外淋巴","外耳道→鼓膜→鼓室壁→内耳内淋巴","颅骨→耳蜗骨壁→内耳外淋巴"],"a":0,"e":"正常情况下声波经外耳道振动鼓膜，经听骨链（锤骨、砧骨、镫骨）传递并增压，由镫骨底板作用于卵圆窗膜，传入内耳外淋巴，这是最主要的气传导途径。B项终点写成内淋巴错误，卵圆窗通向外淋巴；C项经鼓室空气、圆窗膜为次要途径；D项鼓室壁传导、E项颅骨骨传导均非主要途径"},{"q":"可被胃黏膜吸收的物质是","o":["糖的消化产物","维生素","水和酒精","肽类物质","无机盐"],"a":2,"e":"胃黏膜仅能吸收少量水、酒精及某些脂溶性药物，故水和酒精可被吸收。糖的消化产物、肽类、维生素、无机盐等主要在小肠吸收，胃几乎不吸收；胃黏膜的吸收能力有限，与其主要承担储存和初步消化功能相适应"},{"q":"当人在紧张的情况下，会出现口干舌燥的感觉，这可能是因为","o":["交感神经兴奋抑制唾液的分泌","交感神经兴奋促进黏稠唾液的分泌","副交感神经兴奋抑制唾液的分泌","前列腺素分泌增加","副交感神经兴奋促进稀薄唾液的分泌"],"a":1,"e":"紧张时交感神经兴奋，其末梢释放去甲肾上腺素，使唾液腺分泌量少而黏稠、固体成分多，同时血管收缩，因而出现口干舌燥。交感抑制唾液分泌（A项）不准确，交感实际促进黏稠分泌；副交感兴奋（C、E项）产生量多稀薄唾液，与口干相反；前列腺素（D项）与此无关"},{"q":"神经纤维中相邻两个锋电位，其中后一个锋电位最早见于前一次兴奋的","o":["绝对不应期","相对不应期","超常期","低常期","兴奋性恢复正常后"],"a":1,"e":"锋电位后有绝对不应期和相对不应期，绝对不应期内Na+通道失活，任何刺激都不能产生新动作电位；相对不应期时部分Na+通道恢复，较强刺激可再次兴奋，故后一个锋电位最早见于相对不应期。超常期、低常期出现在相对不应期之后"},{"q":"在骨骼肌标本浸液中加入筒箭毒碱后，刺激支配该肌的运动神经纤维，肌细胞终板电位的变化是","o":["去极化加大","维持原水平","去极化减小","爆发动作电位","发生超极化"],"a":2,"e":"筒箭毒碱可竞争性阻断神经-肌接头终板膜上的N2型ACh受体，使ACh作用减弱，终板电位幅度即去极化减小。它不增强去极化，也不使电位维持原水平或爆发动作电位；筒箭毒碱不引起膜超极化，超极化见于抑制性递质作用或钾电导增高，与接头传递阻断机制不同"},{"q":"某患者急需大量输血，与B型供血者行交叉配血实验主次侧均发生凝集反应，该患者血型为","o":["A型","B型","O型","AB型","Rh型"],"a":0,"e":"主侧为患者血清加供血者红细胞，次侧为供血者血清加患者红细胞。B型供血者红细胞含B抗原，主侧凝集说明患者血清含抗B，患者为A型或O型；供血者血清含抗A，次侧凝集说明患者红细胞含A抗原，故患者为A型。C项O型红细胞无A抗原，次侧不凝集；B项B型主侧不凝集；D项AB型主次侧均不凝集"},{"q":"躯体感觉不包括","o":["触压觉","温度觉","运动觉","位置觉","牵涉痛"],"a":4,"e":"躯体感觉包括触压觉、温度觉、痛觉以及本体感觉中的运动觉、位置觉等。牵涉痛是内脏疾患引起的远隔体表部位疼痛，属内脏痛的特殊表现，不属于躯体感觉范畴"},{"q":"全血的比重主要决定于","o":["血浆蛋白含量","渗透压的高低","红细胞数量","白细胞数量","NaCl的浓度"],"a":2,"e":"全血比重约为1.050～1.060，明显高于血浆，主要取决于红细胞数量，红细胞越多比重越大，故血细胞比容与全血比重密切相关。血浆蛋白含量（A项）主要影响血浆比重与胶体渗透压；渗透压高低（B项）、NaCl浓度（E项）主要取决于晶体物质；白细胞数量（D项）极少，对比重影响可忽略"},{"q":"房室交界处传导速度较慢的生理意义在于","o":["有利于增强心肌收缩能力","有利于心房或心室同步收缩","有利于心室充盈和射血的交替","有效避免出现完全强直收缩","有效防止出现期前收缩"],"a":2,"e":"房室交界传导缓慢形成房室延搁，使心房收缩完毕后心室才开始收缩，利于心室充盈与射血交替进行。增强心肌收缩力与传导速度无关；心房心室同步收缩恰与延搁相反；避免完全强直收缩靠心肌有效不应期长；防止期前收缩非其功能"},{"q":"血浆清除率是指肾脏在单位时间内","o":["将血浆中某物质完全清除出去的能力","将血浆中某物质完全清除出去的速率","将血浆中某物质完全清除出去的容量","将血浆中某物质完全清除出去的血浆毫升数","将肾小球滤出的某物质完全清除出去的能力"],"a":3,"e":"血浆清除率指肾脏在单位时间内能将某物质从多少毫升血浆中完全清除出去，以毫升每分钟表示，反映肾对该物质的排泄能力。A、B项把清除率理解为能力或速率不够精确，其量化的是血浆容积；C项容量未体现单位时间与完全清除的含义；E项限定为肾小球滤出的物质过窄，清除率还包括肾小管分泌与重吸收的综合结果"},{"q":"对暗光敏感的区域是","o":["视网膜中央凹处","视盘处","视网膜周缘部分","整个视网膜","视盘"],"a":2,"e":"视网膜周缘部分以视杆细胞为主，对暗光敏感，司暗视觉；中央凹仅含视锥细胞，主司明视觉与精细视觉。视盘为视神经传出部位，无感光细胞，形成生理盲点；整个视网膜并非都对暗光同样敏感，故周缘部是暗光敏感区域"},{"q":"类固醇激素调控靶细胞功能的机制是","o":["主要是膜受体机制","主要是核受体机制，也有膜受体机制","主要是膜受体机制，也有核受体机制","热休克蛋白机制","仅为核受体机制"],"a":1,"e":"类固醇激素为脂溶性，可透入细胞与胞质或核内受体结合，调控基因转录发挥慢而持久的基因组效应；此外也存在作用于膜受体的快速非基因组效应，故以核受体机制为主兼有膜受体机制。A项仅膜受体、E项仅核受体均片面；C项主次颠倒；D项热休克蛋白只是胞质受体复合物的伴侣蛋白，并非独立机制"},{"q":"骨髓中自我复制能力最强的细胞是","o":["造血干细胞","定向祖细胞","前体细胞","网织红细胞","淋巴细胞"],"a":0,"e":"造血干细胞具有高度自我更新和多向分化能力，是骨髓中自我复制能力最强的细胞。定向祖细胞和前体细胞已失去自我更新能力；网织红细胞是成熟中的红细胞，淋巴细胞的分化方向受限。造血干细胞主要存在于骨髓，也可少量存在于外周血和脐血"},{"q":"青春期的启动与下列哪种物质的脉冲性释放有关","o":["GHRH","TRH","CRH","GnRH","PRH"],"a":3,"e":"青春期启动源于下丘脑促性腺激素释放激素（GnRH）脉冲式分泌增强，进而促进腺垂体分泌促性腺激素，促使性腺发育与性成熟。GHRH调节生长激素，TRH调节促甲状腺激素，CRH调节促肾上腺皮质激素，PRH调节催乳素，均不承担启动青春期的关键作用"},{"q":"严重哮喘患者肺通气指标降低最为显著的是","o":["潮气量","肺活量","一秒用力呼气量","功能余气量","肺总量"],"a":2,"e":"严重哮喘时小气道阻塞，呼气受限尤为突出，一秒用力呼气量及FEV1与用力肺活量之比下降最显著，是阻塞性通气障碍的特征。潮气量与肺活量可正常或轻度下降；功能余气量、肺总量因气体陷闭反而增大，降低最显著的并非这些指标"},{"q":"关于人在单位时间内的能量代谢率，下列哪项叙述是错误的","o":["与体表面积成正比","随着劳动强度的加大而增加","始终随着外界温度的升高而减少","与年龄有关","与性别有关"],"a":2,"e":"能量代谢率与环境温度呈U形关系，在20～30℃环境最为稳定低下，过低时寒战产热、过高时散热耗能均使代谢升高，故始终随外界温度升高而减少一项错误。代谢率与体表面积成正比，随劳动强度增加而升高，并与年龄、性别相关"},{"q":"与心室肌细胞动作电位3期复极化有关的离子跨膜流动是","o":["因Na+内流而产生","因Ca2+内流而产生","因Cl-内流而产生","因K+内流而产生","因K+外流而产生"],"a":4,"e":"心室肌动作电位3期复极化由K+外流即延迟整流钾电流引起，膜电位迅速恢复至静息水平。0期去极化由Na+内流产生，2期平台由Ca2+内流与K+外流平衡形成，Cl-内流不参与3期复极化，K+内流会使膜去极化，均不符合"},{"q":"压力感受性反射最敏感的动脉血压波动范围是","o":["＜50mmHg","50～100mmHg","100mmHg左右","100～150mmHg","＞150mmHg"],"a":2,"e":"压力感受性反射在平均动脉压正常水平约100毫米汞柱附近最敏感，此区压力感受器放电随血压变化最陡，能最有效缓冲血压波动。A项小于50毫米汞柱时感受器几乎无放电；B项50至100毫米汞柱、D项100至150毫米汞柱为曲线过渡区，敏感性不及正常水平附近；E项大于150毫米汞柱时反射趋于饱和，调节能力下降"},{"q":"凝血酶的主要作用是","o":["加速FⅦ复合物的形成","加速凝血酶原酶复合物的形成","使纤维蛋白原转变为纤维蛋白","激活FⅫ","促进血小板聚集"],"a":2,"e":"凝血酶的核心作用是把可溶性纤维蛋白原水解为纤维蛋白单体，后者聚合成纤维蛋白网，构成血凝块骨架，同时正反馈激活因子Ⅴ、Ⅷ、Ⅺ等放大凝血。加速FⅦ复合物形成（A项）属组织因子途径启动；加速凝血酶原酶复合物形成（B项）为凝血酶原激活前的阶段；激活FⅫ（D项）属接触激活；促进血小板聚集（E项）主要由ADP、TXA2介导"},{"q":"Na+重吸收受醛固酮调节的部位是","o":["近端小管","髓袢降支粗段","远端小管、集合管","髓袢升支粗段","髓袢降支细段"],"a":2,"e":"醛固酮作用于远端小管即远曲小管和集合管的主细胞，促进Na+重吸收并排K+，实现保钠排钾。近端小管重吸收大部分Na+但不依赖醛固酮；髓袢降支粗段、升支粗段及降支细段的Na+转运也不受醛固酮调节"},{"q":"能抑制血小板聚集的前列腺素是以下哪种","o":["PGA2","PGI2","PGE2","PGF2","PGA1"],"a":1,"e":"前列环素（PGI2）由血管内皮细胞合成，可升高血小板内cAMP，抑制血小板聚集并舒张血管，是体内重要的抗聚集物质。A项PGA2、C项PGE2、D项PGF2、E项PGA1均无此主要作用；与PGI2作用相反、促进血小板聚集和血管收缩的是血栓素A2，这也是最常被混淆的一对物质"},{"q":"切除双侧肾上腺后动物死亡的主要原因是缺乏","o":["肾上腺素","肾素","去甲肾上腺素","肾上腺皮质激素","血管紧张素"],"a":3,"e":"肾上腺皮质激素尤其糖皮质激素维持糖与电解质平衡及应激能力，切除双侧肾上腺后因皮质功能急性丧失、水盐代谢紊乱与循环衰竭而死亡，故主要缺乏皮质激素。A项肾上腺素、C项去甲肾上腺素由髓质分泌，缺失不致迅速致死；B项肾素由肾小球旁器分泌、E项血管紧张素为血浆多肽，都不是肾上腺切除后直接缺失的致死因素"},{"q":"某患者被诊断为Addison病（醛固酮分泌不足），此患者可出现","o":["低血钠、低血钾和酸中毒","高血钠、低血钾和碱中毒","低血钠、高血钾和酸中毒","高血钠、高血钾和碱中毒","高血钠、低血钾和酸中毒"],"a":2,"e":"Addison病因肾上腺皮质功能低下、醛固酮分泌不足，肾小管保钠排钾及排H+障碍，导致Na+排出增多、K+与H+潴留，出现低血钠、高血钾和酸中毒。A、B、E项所述高血钠与本病相反；D项高血钠高血钾碱中毒也不符合；碱中毒多见于醛固酮过多或呕吐，本病则为酸中毒"},{"q":"在外周感觉传入神经，神经元的动作电位一般首先发生在","o":["胞体","轴突末梢","轴突始段","周围突距离胞体最近的第1个郎飞结","周围突距离远端末梢最近的第1个郎飞结"],"a":4,"e":"外周感觉神经元为假单极神经元，其动作电位通常在周围突靠近感受器末梢的第一个郎飞结处爆发，再沿轴突向中枢传导。胞体不参与动作电位的发起；轴突始段是多数中枢神经元动作电位的触发部位；轴突末梢和靠近胞体的郎飞结均不是感觉传入神经元动作电位首先发生的部位"},{"q":"下列关于简化眼的描述，错误的是","o":["一种假想的模型而非真实眼","光线仅在入单球界面时折射一次","折射界面的曲率半径为5mm","与人眼充分调节时的折光系统等效","可用于计算视网膜像的大小"],"a":3,"e":"简化眼是假想的单球面折光模型，光线入眼时只折射一次，折射面曲率半径约5mm，可用于计算视网膜像的大小，它模拟的是正常眼安静、未调节（视远物）时的折光系统。眼充分调节时晶状体变凸、曲率改变，与简化眼不等效，故该项错误"},{"q":"下列维生素中不在小肠被吸收的是","o":["维生素K","维生素B12","维生素D","维生素E","维生素A"],"a":1,"e":"维生素B12的吸收局限于回肠末端且依赖内因子，并非一般意义上小肠上段随脂类吸收的维生素，故本题以其为例外。维生素A、D、E、K均属脂溶性维生素，在小肠随脂肪消化产物一同被吸收，吸收部位和机制与B12明显不同"},{"q":"内源性凝血途径的始动因子是","o":["FⅫ","FⅪ","FⅩ","FⅦ","FⅢ"],"a":0,"e":"内源性凝血途径由血管内膜损伤、血液接触胶原等带负电表面启动，首先激活凝血因子Ⅻ为Ⅻa，继而激活Ⅺ、Ⅸ等，形成内源性凝血酶原酶复合物。FⅪ与FⅩ为下游共同通路因子，不是始动因子；FⅦ是外源性凝血途径的启动因子，与组织因子FⅢ结合后启动，均非内源性始动因子"},{"q":"甲状腺手术时误切甲状旁腺会引起","o":["肾结石","黏液水肿","骨质疏松","手足搐搦","消瘦"],"a":3,"e":"甲状旁腺激素是调节血钙的核心激素，误切甲状旁腺后血钙下降，神经肌肉兴奋性增高，出现手足搐搦。黏液水肿为甲状腺功能减退的表现；骨质疏松为长期钙负平衡的慢性后果，非急性表现；肾结石与高钙相关；消瘦见于甲亢或消耗性疾病，均与低钙抽搐无关"},{"q":"合成后在细胞外大量储存的激素是","o":["肾上腺素","甲状腺激素","胰岛素","皮质醇","生长激素"],"a":1,"e":"甲状腺激素合成后以甲状腺球蛋白形式大量储存于滤泡腔内，可供机体使用数月，是细胞外大量储存的典型。肾上腺素储存于嗜铬细胞颗粒但量有限；胰岛素储存于胰岛β细胞分泌颗粒；皮质醇与生长激素均随合成随分泌，储存量小，均需在需要时合成补充"},{"q":"因胚胎期缺碘或甲状腺功能减退，儿童罹患的疾病是","o":["艾迪生病","侏儒症","肢端肥大症","呆小症","佝偻病"],"a":3,"e":"胚胎期缺碘或甲状腺功能减退致甲状腺激素严重不足，影响脑与骨骼发育，患儿表现为智力低下、身材矮小，即呆小症（克汀病）。侏儒症为幼年生长激素缺乏所致，智力正常；肢端肥大症为成年后生长激素过多；艾迪生病为肾上腺皮质功能减退；佝偻病由维生素D缺乏引起"},{"q":"突触后神经元活动取决于","o":["EPSP的总和","IPSP的总和","EPSP和IPSP的代数和","大脑皮层的下行冲动","小脑皮层的下行冲动"],"a":2,"e":"突触后神经元是否兴奋取决于同一时刻所有兴奋性突触后电位与抑制性突触后电位的代数和，在轴突始段的总和达到阈电位才爆发动作电位。仅EPSP总和（A项）忽略抑制性输入，仅IPSP总和（B项）只导致抑制；大脑皮质（D项）与小脑皮质（E项）的下行冲动属上位调控，不是突触后神经元活动的直接决定因素"},{"q":"下列各种功能活动所消耗的能量中，最终不能转化为体热的是","o":["心脏泵血并推动血液流动","细胞合成某种蛋白质","肌肉收缩对外界物体做功","兴奋在神经纤维上传导","内、外分泌腺体的分泌活动"],"a":2,"e":"肌肉收缩对外界物体做功时，一部分能量以机械功形式转移到体外，未转化为体热；而心脏泵血、蛋白合成、神经传导和腺体分泌所耗能量最终均转化为热。A项心脏泵血的能量随血流耗散为热；B、D、E项细胞内合成、传导与分泌最终都以热形式散失，只有肌肉对外做功不转化为体热"},{"q":"依据前列腺素的五碳环构造，目前可以分几种主型","o":["5","6","7","8","9"],"a":4,"e":"前列腺素依据五碳环及侧链结构分为PGA、PGB、PGC、PGD、PGE、PGF、PGG、PGH、PGI等九种主型，各类再按侧链双键数分亚型。5（A项）、6（B项）、7（C项）、8（D项）数目不足，未涵盖全部主型，均与前列腺素分类不符"},{"q":"下列功能中，脑干网状结构上行激动系统所具有的是","o":["形成模糊感觉","激发情绪反应","具有唤醒作用","维持身体平衡","增加肌紧张度"],"a":2,"e":"脑干网状结构上行激动系统经丘脑非特异投射系统弥散作用于大脑皮层，具有唤醒和维持觉醒的作用，损伤可致昏迷。A项形成模糊感觉为非特异投射系统的次要作用，并非该系统核心功能；B项情绪反应主要由边缘系统介导；D项身体平衡由前庭小脑等维持；E项肌紧张调节主要靠网状脊髓束等下行系统"},{"q":"关于胰岛素受体的描述，错误的是","o":["由两个α亚单位和两个β亚单位组成","属于酪氨酸激酶受体家族成员","不同细胞胰岛素受体的数量无显著差异","α亚单位起着抑制β亚单位酪氨酸激酶的作用","胰岛素受体底物介导细胞内的多种生物效应"],"a":2,"e":"胰岛素受体由两个α亚单位与两个β亚单位组成，属酪氨酸激酶受体，α亚单位在胞外结合胰岛素并抑制β亚单位激酶，经胰岛素受体底物传递信号。不同组织细胞受体数量差异明显，肝、脂肪、肌肉细胞受体密度各不相同，直接影响胰岛素敏感性，故C项所称无显著差异错误。A、B、D、E项均为受体的正确描述"},{"q":"对冠脉血流量调节的叙述，错误的是","o":["对其调节最重要的是心肌本身的代谢水平","心肌提高从单位血液中摄取氧的潜力小","在代谢产物中腺苷作用最重要","迷走神经兴奋使冠脉扩张","交感神经兴奋只能使冠脉收缩"],"a":4,"e":"冠脉受交感和副交感双重支配，交感兴奋既可通过α受体使冠脉收缩，又因心肌代谢增强、腺苷等代谢产物增多而间接使冠脉舒张，总体冠脉血流量增加，故“只能使收缩”错误。代谢水平最重要（A项）、摄取氧潜力小（B项）、腺苷作用最重要（C项）、迷走使冠脉扩张（D项）均为正确叙述"},{"q":"临床上用α2受体激动剂（可乐定）治疗高血压是由于它能","o":["抑制心肌收缩力","减慢心率","舒张阻力血管","增加肾排水量","抑制突触前膜释放递质"],"a":4,"e":"可乐定为α2受体激动剂，激动延髓孤束核等处突触前膜α2受体，通过负反馈抑制去甲肾上腺素的释放，降低外周交感神经张力，使血压下降。它并非通过直接抑制心肌收缩力、减慢心率或舒张阻力血管发挥主要作用，增加肾排水量也不是其降压的主要机制"},{"q":"肾脏血流中的钾离子在肾单位和集合管中","o":["仅滤过","仅滤过和重吸收","仅滤过和分泌","滤过、重吸收和分泌","滤过、重吸收和代谢"],"a":3,"e":"钾离子经肾小球自由滤过，近端小管和髓袢升支粗段将其重吸收，远曲小管与集合管主细胞又可分泌钾，故其在肾单位中经历滤过、重吸收和分泌三个过程。A项仅滤过、B项仅滤过和重吸收、C项仅滤过和分泌均不全面；E项代谢并非肾小管处理钾的方式，钾不被肾小管代谢分解"},{"q":"血浆胶体渗透压降低时可引起","o":["组织液减少","组织液增多","尿少","红细胞萎缩","红细胞膨胀和破裂"],"a":1,"e":"血浆胶体渗透压主要由白蛋白形成，是维持毛细血管内外水平衡、将组织液回吸收入血管的力量；其降低时组织液回流减少，导致组织液增多甚至水肿。C项尿少并非胶体渗透压降低的直接效应；D项红细胞萎缩、E项红细胞膨胀破裂取决于血浆晶体渗透压变化；A项组织液减少与事实相反"},{"q":"下列关于神经递质的描述，正确的是","o":["神经系统内凡能与受体结合的化学物质都是递质","其功能是调节突触传递效率","一个神经元的全部末梢均释放同一种递质","一种神经递质只作用于一种特定的受体","递质作用于受体产生效应后很快被消除"],"a":4,"e":"神经递质作用于突触后受体产生效应后，须迅速被酶降解、被突触前膜重摄取或扩散清除，以保证突触传递的精确与可重复性。能与受体结合的化学物质（A项）还包括激素、药物，不一定是递质；调节突触传递效率（B项）为调质作用；一个神经元可释放多种递质（C项错）；一种递质可作用于多种受体亚型（D项错）"},{"q":"下列关于波尔效应的描述正确的是","o":["主要是由于PaCO2和血液中pH改变使血红蛋白构象发生改变","使组织毛细血管中氧解离曲线左移","促进组织毛细血管血液摄取CO2，肺泡毛细血管血液释放CO2","增加红细胞中2，3-DPG含量","与Cl-在红细胞内外转运过程有关"],"a":0,"e":"波尔效应指CO2分压升高或pH降低使Hb构象改变、对O2亲和力下降，氧解离曲线右移，利于组织释氧，其本质是PaCO2和pH改变引起Hb构象变化。使组织曲线左移错误；促进组织摄取CO2、肺泡释放CO2属霍尔丹效应；2，3-DPG及Cl-转运与波尔效应不同"},{"q":"肺表面活性物质减少将导致","o":["肺难以扩张","小肺泡内压小于大肺泡内压","肺弹性阻力减小","肺泡表面张力降低","肺顺应性增加"],"a":0,"e":"肺表面活性物质降低肺泡表面张力，减小弹性阻力、增加顺应性。其减少时表面张力增大，肺弹性阻力升高、顺应性下降，肺难以扩张，见于新生儿呼吸窘迫。此时小肺泡内压大于大肺泡而趋于萎陷，而非小于；肺泡表面张力升高、顺应性降低，故相应选项均与实际相反"},{"q":"引起逆行性失忆症的原因是","o":["由前额叶白质切断术消除","对阻断多巴胺受体的药物有反应","通常由头部打击引起","可由抗利尿激素治疗所引起","由于脑干损伤引起"],"a":2,"e":"逆行性失忆症指脑损伤后不能回忆受伤前一段时间的经历，常由头部打击、脑震荡等急性脑损伤引起，与颞叶、海马等结构受损有关。A项前额叶白质切断术主要影响行为与情绪；B项阻断多巴胺受体药物主要影响精神运动；D项抗利尿激素治疗与此无关；E项脑干损伤多影响意识与生命体征，并非逆行性失忆的典型原因"},{"q":"兴奋性是指活组织细胞接受刺激产生反应的能力，下列有关兴奋性及其特征的描述，正确的是","o":["刺激都能引起机体的反应","动作电位去极化速度常被用作反映组织的兴奋性大小的指标","引起肌肉组织收缩反应的最大刺激称为最适刺激","阈强度是指能引起可兴奋组织细胞产生反应的最小刺激强度","组织细胞的兴奋性越低，其阈值也较低。"],"a":3,"e":"阈强度指在一定刺激持续时间和强度-时间变化率下，能引起可兴奋组织产生反应的最小刺激强度，是衡量兴奋性的指标，阈值越低兴奋性越高。A项并非所有刺激都能引起反应，需达阈值；B项常用阈值而非去极化速度反映兴奋性；C项引起最大反应的是最大刺激；E项兴奋性越低阈值越高，表述相反"},{"q":"下列各体液中，不属于机体内环境范畴的是","o":["血浆","细胞内液","组织间液","淋巴液","脑脊液"],"a":1,"e":"细胞内液位于细胞膜之内，不属于机体内环境。血浆、组织间液与淋巴液是细胞直接生活的细胞外液，脑脊液亦属细胞外液并构成中枢神经元的内环境，均属于内环境范畴"},{"q":"通常认为，控制生物节律的主要中枢结构是","o":["视上核","下丘脑前核","视前核","视交叉上核","灰白结节"],"a":3,"e":"下丘脑视交叉上核是哺乳动物昼夜节律的主起搏中枢，控制生物节律。视上核合成抗利尿激素和催产素，下丘脑前核参与体温调节，视前核与散热有关，灰白结节为垂体调节相关区域，均非生物节律的主要中枢"},{"q":"心脏的重要潜在起搏点是","o":["窦房结","浦肯野细胞","心室肌","左心房肌","右心房肌"],"a":1,"e":"窦房结为正常起搏点，浦肯野细胞自律性较高、传导快，是最重要的潜在起搏点，在窦房结功能障碍时可取而代之。窦房结（A项）是正常而非潜在起搏点；心室肌（C项）、左心房肌（D项）、右心房肌（E项）为工作细胞，无自律性，不能作为起搏点"},{"q":"最重要的消化液是","o":["胃液","胰液","胆汁","小肠液","唾液"],"a":1,"e":"胰液含胰淀粉酶、胰脂肪酶、胰蛋白酶原和糜蛋白酶原等多种消化酶，能全面消化糖、脂肪和蛋白质，是消化力最强、最重要的消化液。A项胃液主要消化蛋白质；C项胆汁不含消化酶，仅乳化脂肪；D项小肠液、E项唾液消化作用有限，均不如胰液全面"},{"q":"有关肝脏血液供应的叙述，下列正确的是","o":["肝动脉含有来自于小肠吸收的营养物质","门静脉是肝细胞供O2的主要来源","进入肝脏进行解毒的有害物质来源于肝动脉","成年人肝每分钟血流量为1000～1500ml","肝静脉窦具有储存血液的作用"],"a":4,"e":"肝窦（肝静脉窦）是肝内宽大的血窦，可储存一定量血液，起储血库作用。A项含小肠吸收营养物质的是门静脉而非肝动脉；B项门静脉为肝细胞供O2的主要来源错误，肝动脉才主要供氧；C项入肝解毒的有害物质主要来自门静脉；D项成年人肝血流量约为1500ml/min，表述区间偏低，故本题正确项为肝静脉窦储血"},{"q":"在手术过程中不慎损伤食管下2/3部的肌间神经丛，不会出现的是下列哪一项","o":["吞咽困难","胸骨下疼痛","食物反流","食管下括约肌松弛","食管下括约肌痉挛"],"a":3,"e":"食管下2/3肌间神经丛损伤致贲门失弛缓，LES出现痉挛、高压而不能松弛，故出现吞咽困难、胸骨下疼痛与食物反流。食管下括约肌松弛与LES高压、痉挛的病理相反，正是不会出现的表现；其余三项均为该病典型症状"},{"q":"含氮激素发挥作用的第一步是","o":["与细胞膜上的专一性受体结合","与胞浆受体结合","与核内受体结合","使细胞内的ATP转变为cAMP","与核内DNA结合"],"a":0,"e":"含氮激素为水溶性，难以穿过细胞膜，发挥作用的第一步是与靶细胞膜上的专一性受体结合，随后经G蛋白和第二信使系统传递信号。B项胞浆受体、C项核内受体及E项核内DNA结合是类固醇激素、甲状腺激素等脂溶性激素的作用途径。D项使ATP转变为cAMP是结合受体之后的信号放大步骤，并非第一步"},{"q":"衡量心肌自律性高低的指标是","o":["动作电位幅度","0期去极化速度","最大复极电位水平","4期自动去极化速度","复极化的时程"],"a":3,"e":"衡量心肌自律性高低的指标是4期自动去极化速度，速度越快，达到阈电位所需时间越短，自律性越高。动作电位幅度与0期去极化速度反映兴奋性与传导性；最大复极电位水平影响自律性但不是直接衡量指标；复极化时程与自律性高低无直接对应"},{"q":"甲状旁腺激素的主要靶器官是","o":["甲状旁腺","胃肠道","骨组织","肾上腺","甲状腺"],"a":2,"e":"甲状旁腺激素主要作用于骨和肾，骨是其最重要的靶器官，可促进破骨细胞活动、动员骨钙入血。胃肠道为其间接作用部位即经活性维生素D；甲状旁腺、肾上腺、甲状腺并非PTH的靶器官"},{"q":"精子在女性生殖道内其功能活性可以保持约","o":["4~8小时","12~24小时","16~36小时","24~48小时","48~72小时"],"a":3,"e":"精子进入女性生殖道后，其受精能力（功能活性）一般可保持约24～48小时，而卵子排卵后受精能力约12～24小时，这是安全期避孕的依据。4～8小时（A项）、12～24小时（B项）时间偏短，更接近卵子受精时限；16～36小时（C项）不准确；48～72小时（E项）过长"},{"q":"细胞膜内、外，正常的Na＋和K＋浓度的维持主要是由于","o":["膜在安静时对K＋的通透性高","膜在兴奋时对Na＋的通透性增加","Na＋、K＋易化扩散的结果","膜上Na＋-K＋泵的作用","Na＋外流，K＋内流"],"a":3,"e":"细胞膜上Na+-K+ATP酶（钠泵）主动将Na+泵出、K+泵入，维持细胞内高K+、细胞外高Na+的正常浓度梯度，这是静息电位产生的基础。安静时膜对K+通透性高、兴奋时对Na+通透性增加只影响离子的被动扩散，易化扩散属被动转运，均不能建立和维持浓度差；Na+外流、K+内流的方向也与事实相反"},{"q":"关于分节运动的叙述，错误的是","o":["是一种以环形肌为主的节律性舒缩活动","是小肠所特有的","空腹时即有明显分节运动","分节运动存在频率梯度","不明显的推进食糜"],"a":2,"e":"分节运动是小肠特有的以环形肌为主的节律性舒缩，进食后明显，空腹时很弱；其频率存在由十二指肠到回肠递减的梯度，主要混和食糜而非明显推进。空腹时即有明显分节运动（C项错误）违背其生理特点；A、B、D、E项均为分节运动的正确描述"},{"q":"关于静脉血压，下列叙述中错误的是","o":["站立时颅内静脉窦的压力低于大气压","正常成人在立正状态下，足背静脉压和主动脉平均压几乎相等","深吸气时中心静脉压升高","中心静脉压的高低与心脏的射血能力有关","足背静脉压在行走时比立正时低"],"a":2,"e":"深吸气时胸膜腔负压增大，中心静脉压降低，有利于静脉回流，故深吸气时中心静脉压升高一项错误。站立时颅内静脉窦压力低于大气压；立正时足背静脉压接近主动脉平均压；中心静脉压与心脏射血能力有关；行走时足背静脉压较立正时低，均正确"},{"q":"正常人吸入下列哪种混合气体时，肺通气量明显增加","o":["21%O2和79%N2","19%O2和81%N2","20%CO2和80%O2","3%CO2和97%O2","0、5%CO2和99、5%O2"],"a":3,"e":"CO2是调节呼吸最重要的生理性化学因素，吸入气中CO2适度升高（如3%）可刺激中枢及外周化学感受器，使肺通气量明显增加。C项20%CO2浓度过高反而抑制中枢；A项21%O2即空气、B项19%O2的轻度低氧对通气刺激很弱；E项0.5%CO2接近正常水平，通气增加并不明显，只有3%CO2最显著"},{"q":"下列物质的清除率最高的是","o":["肌酐","菊粉","葡萄糖","碘锐特","氨基酸"],"a":3,"e":"碘锐特可被肾小球自由滤过且被肾小管完全分泌、不重吸收，其清除率接近肾血浆流量，是选项中最高。A项肌酐清除率约等于肾小球滤过率；B项菊粉清除率等于滤过率；C项葡萄糖、E项氨基酸被完全重吸收，清除率为零"},{"q":"交感神经兴奋引起的心率加快，由下列哪种受体介导","o":["α1肾上腺素能受体","α2肾上腺素能受体","β1肾上腺素能受体","β2肾上腺素能受体","M胆碱能受体"],"a":2,"e":"交感神经末梢释放去甲肾上腺素，作用于心肌β1肾上腺素能受体，使窦房结自律性升高、心率加快并增强收缩力。A项α1受体介导血管收缩；B项α2受体多为突触前抑制性受体；D项β2受体主要引起支气管和血管舒张；E项M胆碱能受体介导迷走神经的负性变时作用，与心率加快无关"},{"q":"一条神经干中许多纤维在同时传导兴奋时互不干扰，其主要原因是","o":["髓鞘对电流的绝缘作用","细胞膜的膜电阻很大","细胞外液对电流的短路作用","生物电很微弱，干扰也很微弱","动作电位只沿膜内侧传向远处"],"a":2,"e":"神经干中多条纤维同时传导时，动作电位产生的局部电流大部分经细胞外液短路回流，各纤维之间的跨膜电流影响极小，故兴奋互不干扰。髓鞘的绝缘作用仅见于有髓纤维，不能解释无髓纤维；膜电阻大、生物电微弱及动作电位沿膜内侧传导都不是互不干扰的主要原因"},{"q":"小管液中的Na+浓度影响肾小球滤过是通过","o":["颗粒细胞","足细胞","髓袢","远端小管和集合管","致密斑"],"a":4,"e":"致密斑位于远曲小管起始部，感受小管液中Na+浓度变化，是管球反馈的感受器，可将信息传至球旁细胞调节肾素释放，进而影响肾小球滤过。A项颗粒细胞（球旁细胞）分泌肾素，是效应器；B项足细胞为滤过膜成分；C项髓袢、D项远曲小管和集合管不直接承担该感受功能"},{"q":"促进脂肪分解代谢的激素不包括","o":["胰岛素","胰高血糖素","生长素","甲状腺激素","肾上腺素"],"a":0,"e":"胰岛素是主要的合成代谢激素，促进脂肪合成并抑制脂肪分解，故不属于促进脂肪分解的激素。胰高血糖素（B项）、生长素（C项）、甲状腺激素（D项）、肾上腺素（E项）均可激活脂肪酶或增强激素敏感性脂肪酶活性，促进脂肪动员与分解，与胰岛素作用相反"},{"q":"神经细胞动作电位和局部兴奋的共同点是","o":["反应幅度都随刺激强度增大而增大","反应幅度都随传播距离增大而减小","都可以叠加或总和","都有不应期","都有钠离子通道的激活"],"a":4,"e":"动作电位与局部兴奋的产生均以细胞膜上Na+通道的激活开放为前提，故两者都有Na+通道激活。动作电位具全或无、有不应期、不总和、不随距离衰减；局部兴奋有等级性、可总和、电紧张扩布、无不应期，故其余选项均非共同点"},{"q":"胎儿和新生儿脑发育的关键激素是","o":["糖皮质激素","生长激素","甲状腺激素","肾上腺素","盐皮质激素"],"a":2,"e":"甲状腺激素是胎儿和新生儿脑发育的关键激素，促进神经元增殖、分化、髓鞘形成与突触建立，缺乏可致智力与发育障碍。糖皮质激素、盐皮质激素、肾上腺素与生长激素虽参与代谢与生长调节，但对脑发育的决定性作用远不及甲状腺激素"},{"q":"体外受精-胚胎移植的超排卵方案中，应用外源性FSH的目的不包括","o":["促进多个卵泡同步发育成熟","提供卵泡发育必需的激素支持，防止卵泡闭锁","促进卵泡颗粒细胞分泌雌激素","促进下丘脑分泌大量GnRH","防止卵泡过早黄素化"],"a":3,"e":"外源性FSH直接作用于卵巢颗粒细胞，促进多个卵泡同步发育成熟、分泌雌激素并防止卵泡闭锁与过早黄素化，用于超排卵。GnRH由下丘脑脉冲式分泌，外源性FSH不仅不促进其分泌，反而通过性激素负反馈抑制下丘脑-垂体轴，故该项不属于应用FSH的目的"},{"q":"醛固酮的作用是促进","o":["Na+的重吸收和K+的排泄","Na+的重吸收和H+的分泌","K+的重吸收和Na+的排泄","H+的重吸收和Na+的排泄","K+的重吸收和H+的分泌"],"a":0,"e":"醛固酮作用于远曲小管和集合管，促进Na+重吸收和K+排泄，即保Na+排K+，同时伴H+分泌。Na+重吸收与H+分泌的表述未涵盖排K+这一核心；K+重吸收、Na+排泄等均与醛固酮的实际作用相反"},{"q":"血浆与组织液各种成分浓度的主要区别是","o":["钠离子","钾离子","蛋白质","有机酸","血细胞"],"a":2,"e":"血浆与组织液的主要成分区别是蛋白质，血浆蛋白多而组织液含量极少。Na+、K+、有机酸、尿素等小分子可自由通过毛细血管壁，两侧浓度接近，不构成主要差别"},{"q":"胆碱能交感节后纤维支配的效应器是","o":["心肌","胃肠平滑肌","汗腺","冠状血管","肾血管"],"a":2,"e":"支配汗腺的交感节后纤维属胆碱能纤维，释放乙酰胆碱，作用于M受体促进排汗。A项心肌主要受肾上腺素能纤维支配；B项胃肠平滑肌主要受副交感胆碱能纤维支配；D项冠状血管、E项肾血管主要受肾上腺素能等纤维支配。题干特指“胆碱能交感节后纤维”，典型支配汗腺"},{"q":"以下情况中，可使静脉回流量减少的是","o":["体循环平均充盈压升高","心脏收缩力量加强","由卧位转为立位时","有节律的慢跑","吸气时相"],"a":2,"e":"由卧位转为立位时受重力影响，下肢静脉扩张、血液淤积，回心血量减少，静脉回流量下降。A项体循环平均充盈压升高促进回流；B项心脏收缩力加强使射血充分、利于回流；D项节律性慢跑通过肌肉泵促进回流；E项吸气时胸膜腔负压增大，也促进静脉回流"},{"q":"在肾素-血管紧张素系统中，具有极强缩血管效应的是","o":["肾素","血管紧张素Ⅰ","血管紧张素Ⅱ","血管紧张素Ⅲ","血管紧张素转换酶"],"a":2,"e":"血管紧张素Ⅱ由血管紧张素Ⅰ经转换酶作用生成，是肾素-血管紧张素系统中缩血管作用最强的物质，可使全身小动脉强烈收缩并刺激醛固酮分泌。肾素只是水解血管紧张素原的酶，本身无缩血管作用；血管紧张素Ⅰ活性很弱，转换酶仅为催化生成Ⅱ的酶。血管紧张素Ⅲ缩血管作用远弱于Ⅱ"},{"q":"支配气道平滑肌的副交感神经兴奋将使","o":["平滑肌舒张，气道阻力降低","平滑肌舒张，气道阻力增加","平滑肌舒张，气道阻力不变","平滑肌收缩，气道阻力增加","平滑肌收缩，气道阻力降低"],"a":3,"e":"支配气道平滑肌的副交感神经兴奋时释放乙酰胆碱，作用于M3受体使平滑肌收缩、气道口径缩小，气道阻力增加。平滑肌舒张（A、B、C项）为交感兴奋或β2受体激动的表现；平滑肌收缩而阻力降低（E项）自相矛盾，管径缩小必使阻力升高"},{"q":"人幼年时期缺乏下列哪种激素可导致侏儒症","o":["T3","1,25-(OH)2-D3","GH","PRL","皮质醇"],"a":2,"e":"幼年时期生长激素即GH缺乏导致生长发育迟缓、身材矮小但智力正常，即侏儒症。T3缺乏致呆小症伴智力低下；1,25-(OH)2-D3缺乏致佝偻病；PRL与皮质醇缺乏并不导致侏儒症，其缺乏或过多表现为其他内分泌异常"},{"q":"肾小球滤过一般只发生在入球端毛细血管段的主要原因是","o":["毛细血管内胶体渗透压逐渐升高","囊内压逐渐升高","毛细血管内晶体渗透压逐渐升高","肾小囊内胶体渗透压逐渐降低","毛细血管血压降低"],"a":0,"e":"血液流经肾小球毛细血管时，水和小分子滤出使血浆蛋白浓缩，毛细血管内胶体渗透压逐渐升高，有效滤过压不断下降，至出球端达到滤过平衡，故滤过主要发生于入球端。B项囊内压正常情况下基本恒定；C项晶体渗透压因溶质自由滤过而两侧相等；D项肾小囊内胶体渗透压极低且不变；E项毛细血管血压略降但胶体渗透压升高才是主因"},{"q":"下列关于肠神经系统的叙述，错误的是","o":["是指消化道壁内的神经丛","能独立行使其功能","不受外来神经的调节","含有大量的神经纤维和神经元","参与消化道运动和消化液分泌的调节"],"a":2,"e":"肠神经系统是消化道壁内的神经丛，含大量神经元和神经纤维，可相对独立地调节消化道运动和消化液分泌；但它仍接受交感和副交感等外来神经的调节，并非完全不受外来神经影响。其余关于其位置、独立功能及参与调节的叙述均正确"},{"q":"在体内主要依靠糖的无氧酵解供能的组织细胞是","o":["肝细胞","脑细胞","红细胞","骨骼肌","心肌"],"a":2,"e":"成熟红细胞缺乏线粒体，不能进行有氧氧化，主要依靠葡萄糖的无氧酵解产生ATP以维持生命活动。肝细胞（A项）、脑细胞（B项）、心肌（E项）富含线粒体，以有氧氧化为主；骨骼肌（D项）在剧烈运动时虽可无氧酵解，但静息时以有氧供能为主，均非主要依靠糖酵解的组织"},{"q":"肥胖病人体内瘦素水平升高会导致以下哪种情况","o":["体重下降","心肌收缩力增强","食欲增加","能量消耗增加","胰岛素合成增多"],"a":4,"e":"瘦素由脂肪细胞分泌，肥胖者脂肪组织增多使瘦素水平升高，同时常伴胰岛素抵抗与代偿性胰岛素合成增多，二者均随脂肪量增加而上升。瘦素本可抑制食欲、增加能耗、减轻体重，但肥胖者存在瘦素抵抗，这些效应被削弱，故体重下降、食欲增加、能量消耗增加均非本题所指结果"},{"q":"限制性通气不足的原因是","o":["肺泡扩张受限","肺泡壁厚度增加","气道阻力增高","肺泡面积减少","肺泡通气与血流比例失调"],"a":0,"e":"限制性通气不足指吸气时肺泡扩张受限，常见于胸廓畸形、呼吸肌麻痹、肺纤维化等，肺泡通气量因扩张受限而减少。肺泡壁厚度增加和面积减少主要影响换气；气道阻力增高是阻塞性通气不足的机制；通气与血流比例失调属于换气障碍，均非限制性通气不足的原因"},{"q":"关于前庭自主神经反应的叙述，正确的是","o":["可见于前庭器官受到的刺激过弱时","主要表现为躯体运动神经功能失调","有皮肤苍白、恶心呕吐、心率加快、血压升高及唾液分泌增加等症状","前庭感受器不敏感的人，即使一般强度的前庭刺激也会导致明显的自主神经反应","晕船、晕车是前庭自主神经反应的表现"],"a":4,"e":"前庭自主神经反应是前庭器官受过大或不适当刺激时出现的自主神经功能紊乱，晕船、晕车即其典型表现，常伴恶心、呕吐、皮肤苍白等。A项刺激过弱不易引起；B项表现为自主神经而非躯体运动神经功能失调；C项血压升高描述不确切，多伴心率减慢、血压下降；D项前庭敏感者易发生，表述相反"},{"q":"促进胃排空的因素是","o":["胃内的氨基酸和肽浓度升高","十二指肠内的酸刺激","十二指肠内的脂肪浓度升高","十二指肠内渗透压升高","机械扩张刺激十二指肠"],"a":0,"e":"胃内食物氨基酸、肽浓度升高通过迷走-迷走反射和促胃液素促进胃运动，加速排空；食糜进入十二指肠后，酸、脂肪、高渗及机械扩张则通过肠-胃反射等抑制胃排空。B项十二指肠内酸刺激、C项脂肪浓度升高、D项渗透压升高、E项机械扩张十二指肠均为抑制胃排空的因素"},{"q":"人耳最敏感的声波频率范围是","o":["0～1000Hz","1000～3000Hz","3000～5000Hz","5000～10000Hz","8000～20000Hz"],"a":1,"e":"人耳可听范围为20～20000Hz，其中1000～3000Hz最敏感，这与外耳道共振及中耳传导特性有关，也是言语频率的主要范围。A项0～1000Hz覆盖低频但非最敏感区；C项3000～5000Hz、D项5000～10000Hz偏向高频，敏感度下降；E项8000～20000Hz接近听力上限，敏感度最低"},{"q":"右心室的每搏功为左心室每搏功的","o":["1/3","1/4","1/5","1/6","1/7"],"a":3,"e":"右心室每搏功约为左心室的1/6，因肺循环阻力与肺动脉压远低于体循环，右心室做功显著较小。1/3、1/4、1/5高于实际比例，1/7则偏低，均未正确反映肺循环与体循环压力差所决定的心室做功比"},{"q":"双侧海马功能的损失影响是","o":["丧失远程记忆","丧失工作记忆","丧失编码长期记忆中最近事件的能力","丧失回忆面孔和形态的能力，但不影响回忆印刷或口头文字","当回忆最近事件时产生不适当的情绪反应"],"a":2,"e":"双侧海马损伤使患者丧失将新近事件编码为长期记忆的能力，表现为顺行性遗忘，既往远期记忆相对保留。工作记忆主要依赖前额叶皮层；面孔与形态识别障碍见于颞叶特定区域损伤；回忆最近事件时产生不适当情绪反应与杏仁核有关，均非双侧海马损失的核心表现"},{"q":"中性粒细胞的主要功能是","o":["产生抗体","吞噬异物","参与止血","释放细胞毒素","释放组胺"],"a":1,"e":"中性粒细胞是血液中数量最多的白细胞，具有趋化和吞噬功能，主要吞噬入侵的细菌等异物，是急性炎症和抗细菌感染的第一道防线。A项产生抗体是浆细胞的功能；C项参与止血主要是血小板；D项释放细胞毒素主要为NK细胞、CTL；E项释放组胺主要是肥大细胞和嗜碱性粒细胞"},{"q":"下列关于肺循环特征的描述，错误的是","o":["血流阻力低","平均动脉压低","循环血量少","血容量变化范围大","有效滤过压为负值"],"a":2,"e":"肺循环与体循环串联，每分钟血流量与体循环相等，并不存在循环血量少的特点；相反肺血管床容量大、血容量变化范围大，是重要储血库，故该项错误。A项肺循环血流阻力低、B项平均动脉压低、D项血容量变化范围大、E项有效滤过压为负值利于肺泡保持干燥，均为肺循环的正确特征"},{"q":"某种食物氧化时，消耗1L氧所产生的热量称为","o":["氧热价","食物的热价","物理热价","非蛋白呼吸商","呼吸商"],"a":0,"e":"氧热价指某种食物氧化时每消耗1升氧所产生的热量，糖、脂肪、蛋白质各有其氧热价，用于间接测热法计算能耗。B项食物热价为1克食物氧化释放的热量；C项物理热价指体外燃烧热价；D项非蛋白呼吸商为排除蛋白后的CO2/O2比值；E项呼吸商为CO2产生量与耗氧量的比值，都不是每升氧的产热量"},{"q":"生理情况下，对收缩压的影响最大的是","o":["心率的变化","每搏输出量的变化","外周阻力的变化","循环血量的变化","大动脉管壁弹性的变化"],"a":1,"e":"收缩压高低主要反映每搏输出量，每搏输出量增加时收缩压明显升高而舒张压升高较少，脉压增大。心率变化（A项）主要影响舒张压；外周阻力（C项）升高主要抬高舒张压；循环血量（D项）与大动脉管壁弹性（E项）影响血压但非收缩压的首要决定因素"},{"q":"心肌缺氧引起冠脉舒张，在该反应中起主要作用的是","o":["前列腺素","乳酸","氢离子","组胺","腺苷"],"a":4,"e":"心肌缺氧时ATP分解加速，腺苷生成增多并释放至组织间隙，作用于冠脉平滑肌腺苷受体，引起冠脉显著舒张，是局部代谢性舒血管的主要介质。B项乳酸、C项氢离子在缺血时也可增多并参与舒血管，但作用弱于腺苷；A项前列腺素、D项组胺并非心肌缺氧性冠脉舒张的主导因素，腺苷才是关键"},{"q":"在下列选项中，人体生命活动最基本的生命特征是","o":["适应性","兴奋性","新陈代谢","生殖","衰老"],"a":2,"e":"新陈代谢是机体与环境进行物质和能量交换并实现自我更新的过程，是一切生命活动的基础，是最基本的生命特征，也是生物与非生物的本质区别。兴奋性是细胞对刺激产生反应的能力；适应性是随环境调整功能；生殖与衰老均为生命过程，但都以新陈代谢为前提"},{"q":"引起促胰液素释放的因素由强到弱的排列顺序为","o":["蛋白质分解产物、脂肪酸、盐酸","脂肪酸、蛋白质分解产物、盐酸","盐酸、蛋白质分解产物、脂肪酸","盐酸、脂肪酸、蛋白质分解产物","蛋白质分解产物、盐酸、脂肪酸"],"a":2,"e":"刺激促胰液素释放的因素强弱依次为盐酸、蛋白质分解产物、脂肪酸，糖类几乎无作用，故该排序正确。盐酸是最强刺激因素，这一点与缩胆囊素不同，后者以蛋白质分解产物最强、脂肪酸次之，两者顺序常被互换设错"},{"q":"某患者血沉增快，主要是由于","o":["红细胞脆性增大","血浆中球蛋白和纤维蛋白原含量增多","血浆中白蛋白和卵磷脂含量增多","红细胞内血红蛋白浓度降低","血细胞比容减小"],"a":1,"e":"血浆中球蛋白和纤维蛋白原等大分子蛋白增多时，可中和红细胞表面负电荷、促进红细胞叠连，使血沉增快；白蛋白和卵磷脂增多则抑制叠连、使血沉减慢。红细胞脆性增大（A项）与溶血相关；白蛋白和卵磷脂增多（C项）使血沉减慢；血红蛋白浓度降低（D项）、血细胞比容减小（E项）非血沉增快的主要原因"},{"q":"自律细胞与非自律细胞的区别是","o":["0期去极化的快慢","1期复极化的快慢","2期平台期的有无","3期复极化的快慢","4期自动去极化的有无"],"a":4,"e":"自律细胞（如窦房结P细胞、浦肯野细胞）在4期存在自动去极化，可自发产生动作电位；非自律细胞（如心室肌细胞）4期膜电位稳定，无自动去极化。A项0期去极化快慢区分快、慢反应细胞；B项1期、D项3期复极化速度、C项2期平台期有无均非自律性的本质区别"},{"q":"根据球-管平衡现象，近端小管的重吸收率约为肾小球滤过率的","o":["1/5","1/3","1/2","2/3","4/5"],"a":3,"e":"球-管平衡指近端小管的重吸收率始终保持在肾小球滤过率的65%～70%左右，即约2/3，使尿量不因滤过率增减而大幅波动。这是近端小管重吸收随滤过率成正比变化的机制，1/5、1/3、1/2及4/5均与近端小管实际重吸收比例不符"},{"q":"突触后神经元兴奋时，动作电位首先在轴突始段爆发的原因是","o":["此处的EPSP幅度大","EPSP总和仅发生于此处","此处的细胞膜电阻小","此处阈电位靠近静息电位","此处电压门控钠通道密度大"],"a":4,"e":"轴突始段即轴丘膜上电压门控Na+通道密度最高，阈电位最低，故突触后神经元的动作电位首先在此爆发。EPSP主要在树突和胞体产生，并非仅发生于轴丘，且其在该处幅度未必最大；膜电阻小、阈电位靠近静息电位均非主要原因"},{"q":"血中二氧化碳分压升高使呼吸运动增强，其主要刺激是","o":["脑脊液中氢离子浓度增加","动脉血中氧分压降低","动脉血中氢离子浓度增加","脑脊液中氧分压降低","脑脊液中二氧化碳分压升高"],"a":0,"e":"血中CO2分压升高时，CO2迅速透过血脑屏障进入脑脊液，与水结合生成碳酸并解离出H+，H+刺激延髓腹外侧的中枢化学感受器，反射性增强呼吸。血中H+不易透过血脑屏障，脑脊液中O2分压与CO2本身并非主要刺激，直接刺激中枢化学感受器的是脑脊液中的H+"},{"q":"保钠排钾作用最强的肾上腺皮质激素是","o":["醛固酮","皮质醇","皮质酮","去氧皮质酮","可的松"],"a":0,"e":"醛固酮是作用最强的盐皮质激素，作用于远曲小管和集合管，促进Na+重吸收和K+、H+分泌，实现保钠排钾。B项皮质醇、C项皮质酮、E项可的松主要为糖皮质激素，保钠作用弱；D项去氧皮质酮虽为盐皮质激素，但效力远低于醛固酮，故醛固酮作用最强"},{"q":"不需要蛋白质辅助的跨膜转运方式为","o":["出胞","原发性主动转运","单纯扩散","继发性主动转运","易化扩散"],"a":2,"e":"单纯扩散是脂溶性物质顺浓度梯度直接穿过脂质双层的过程，不需膜蛋白帮助，如O2、CO2的转运。出胞依赖膜蛋白与囊泡机制；原发性和继发性主动转运分别依赖泵和载体蛋白；易化扩散需通道或载体蛋白介导，均需蛋白质参与"},{"q":"抑制钠泵的活动会导致","o":["细胞内Na+浓度降低","细胞内K+浓度增加","细胞内Ca2+浓度增加","增加Na+-葡萄糖同向转运","增加Na+-Ca2+交换"],"a":2,"e":"抑制钠泵使细胞内Na+浓度升高、K+浓度降低，Na+跨膜浓度梯度减小，Na+-Ca2+交换减弱甚至反向，导致细胞内Ca2+排出减少而浓度升高。钠泵抑制不会使细胞内Na+降低或K+增加；Na+-葡萄糖同向转运因驱动力下降而减弱；Na+-Ca2+交换本身也被抑制而非增强"},{"q":"生理状态下，能促进肝外组织蛋白质分解的激素是","o":["糖皮质激素","生长激素","胰岛素","甲状腺激素","雄激素"],"a":0,"e":"糖皮质激素在生理状态下促进肝外组织尤其是肌肉的蛋白质分解，抑制蛋白质合成，分解产生的氨基酸被肝摄取用于糖异生。生长激素、胰岛素和雄激素促进蛋白质合成；甲状腺激素在生理剂量下也以合成代谢为主，大剂量才促进分解，均不符合题意"},{"q":"十二指肠-结肠反射可以","o":["抑制胃液分泌","抑制胃窦运动","抑制结肠运动","增强十二指肠运动","增强结肠运动"],"a":4,"e":"进食后十二指肠充盈，通过神经反射引起结肠运动增强、出现集团蠕动，常产生便意，称十二指肠-结肠反射。抑制胃液分泌（A项）为肠抑胃素等作用；抑制胃窦运动（B项）属肠胃反射；抑制结肠运动（C项）与该反射相反；增强十二指肠运动（D项）非此反射的主要效应"},{"q":"全心舒张期时长为","o":["0、2s","0、3s","0、4s","0、5s","0、6s"],"a":2,"e":"一个心动周期约0.8秒，其中心房与心室同时处于舒张状态的全心舒张期约0.4秒，此时心肌充分松弛、心室充盈。0.2秒与0.3秒过短，不符合实际时程；0.5秒与0.6秒接近或超过整个心室舒张期，而心房收缩占据其中一段，故不是全心舒张期"},{"q":"与窦房结细胞动作电位0期去极化有关的离子跨膜流动是","o":["因Na+内流而产生","因Ca2+内流而产生","因Cl-内流而产生","因K+内流而产生","因K+外流而产生"],"a":1,"e":"窦房结细胞属慢反应自律细胞，其0期去极化由L型Ca2+通道开放、Ca2+内流引起，去极化幅度小、速度慢，可被钙通道阻断剂抑制。快反应细胞0期的Na+内流（A项）属心室肌、浦肯野细胞机制；Cl-内流（C项）与K+内流（D项）不参与0期去极化；K+外流（E项）是复极化的主要离子流"},{"q":"能直接刺激肾上腺皮质球状带细胞分泌醛固酮的是","o":["血管紧张素Ⅰ","血管紧张素原","血管紧张素Ⅱ","促肾上腺皮质激素","肾素"],"a":2,"e":"血管紧张素Ⅱ可直接作用于肾上腺皮质球状带细胞，促进醛固酮的合成与分泌，是调节醛固酮的重要因素，血K+升高也有直接刺激作用。血管紧张素Ⅰ和血管紧张素原需转化后才生效，肾素仅为生成血管紧张素Ⅰ的酶；ACTH对球状带醛固酮分泌只有允许的次要作用"},{"q":"下列哪种物质可减小气道阻力","o":["乙酰胆碱","儿茶酚胺","内皮素","组胺","白三烯"],"a":1,"e":"儿茶酚胺激动支气管平滑肌β2受体，使气道舒张、口径增大，按泊肃叶定律阻力与半径四次方成反比，故气道阻力减小。A项乙酰胆碱、D项组胺、E项白三烯均引起支气管收缩而增加阻力；C项内皮素为强烈的缩血管缩支气管肽，也增大阻力，都不是减小气道阻力的物质"},{"q":"肾小管分泌氢离子增多时可减少","o":["钠的重吸收","钾的分泌","氨的分泌","氯的排泄","尿素的排泄"],"a":1,"e":"远曲小管和集合管存在Na+-H+交换与Na+-K+交换的竞争，H+分泌增多时Na+-K+交换受抑，K+分泌随之减少，故酸中毒时常伴高血钾。钠的重吸收、氨的分泌、氯和尿素的排泄并不因H+分泌增多而减少，其中氨分泌反而随H+分泌增加而增多"},{"q":"下列关于胆汁生理作用的描述，错误的是","o":["胆盐、胆固醇、卵磷脂都可乳化脂肪","胆汁可与脂肪酸结合，促进脂肪酸的吸收","胆汁可促进脂溶性维生素的吸收","胆汁的消化酶可促进脂肪的消化","胆汁在十二指肠可中和一部分胃酸"],"a":3,"e":"胆汁中不含消化酶，对脂肪的作用是物理性乳化与促进吸收，故“消化酶可促进脂肪消化”错误。胆盐、胆固醇、卵磷脂共同乳化脂肪形成微胶粒；胆盐与脂肪酸结合成混合微胶粒促进其吸收，并携带脂溶性维生素；胆汁入十二指肠还可中和部分胃酸"},{"q":"下列因素对气道阻力影响最大的是","o":["气道平滑肌张力","气道壁表面光滑程度","气体密度与黏度","气流性质","气道内径"],"a":4,"e":"按泊肃叶定律，气道阻力与气道半径的四次方成反比，故气道内径是影响气道阻力最大的因素，内径稍缩小阻力即显著升高。气道平滑肌张力通过改变口径间接起作用；气体密度与黏度、气流性质、气道壁光滑程度虽均可影响阻力，但作用均远不及内径显著"},{"q":"下列关于腱反射的描述，正确的是","o":["腱反射是多突触反射","腱反射减弱提示高位中枢有病变","腱反射亢进提示反射弧损害","是由于缓慢牵拉肌梭引起的反射","腱反射的感受器是肌梭"],"a":4,"e":"腱反射是快速牵拉肌腱引发的单突触牵张反射，感受器为肌梭。其亢进提示高位中枢对脊髓的抑制减弱；减弱或消失才提示反射弧损害。缓慢牵拉引起的是肌紧张，属多突触反射，与腱反射不同"},{"q":"可引起射血分数增大的因素是","o":["心室舒张末期容积增大","动脉血压升高","心率减慢","心肌收缩能力增强","快速射血相缩短"],"a":3,"e":"射血分数为每搏输出量与心室舒张末期容积之比，心肌收缩能力增强使每搏输出量增多、收缩末期容积减小，射血分数增大。心室舒张末期容积增大虽可增加每搏量，但分母同步增大，射血分数未必升高；动脉血压升高增加后负荷，心率减慢及快速射血期缩短均不利于射血分数增大"},{"q":"通常引起GH分泌显著增加的机体状况是","o":["觉醒状态","轻度运动","进餐期间","慢波睡眠","异相睡眠"],"a":3,"e":"生长激素分泌呈脉冲式，慢波睡眠即深睡眠期出现分泌高峰，尤其入睡后不久，故慢波睡眠时分泌显著增加。A项觉醒状态GH分泌较低；B项轻度运动虽可短暂刺激，但不如慢波睡眠显著；C项进餐期间血糖升高反而抑制GH；E项异相睡眠GH分泌减少，与慢波睡眠形成鲜明对比"},{"q":"循环系统对体温的调节主要通过改变下列哪一因素而实现","o":["血流速度","血液温度","心输出量","逆流交换效率","皮肤血流量"],"a":4,"e":"循环系统通过调节皮肤血流量改变体表散热量：炎热时皮肤血管舒张、血流量增多，散热加强；寒冷时皮肤血管收缩，散热减少。血液温度是体温本身的指标而非调节手段；心输出量变化主要影响循环功能；逆流交换效率与血流速度均为局部因素，不是循环调节体温的主要途径"},{"q":"促代谢型受体是指","o":["电压门控通道","离子通道型受体","G蛋白耦联受体","化学门控通道","N2型ACh受体阳离子通道"],"a":2,"e":"促代谢型受体通过G蛋白及胞内第二信使系统间接调节离子通道和细胞功能，其本质是G蛋白耦联受体。电压门控通道由膜电位变化门控，离子通道型受体（包括化学门控通道和N2型ACh受体阳离子通道）属于促离子型受体，通过开放通道直接引起跨膜离子流动，与促代谢型受体机制不同"},{"q":"感受器的结构多种多样，最简单的感受器是","o":["肌梭","环层小体","鲁菲尼小体","游离感觉神经末梢","颈动脉体化学感受器"],"a":3,"e":"游离感觉神经末梢是结构最简单的感受器，仅为感觉神经元外周突的末端，无被囊和附属结构，可感受痛觉、温度觉等。A项肌梭、B项环层小体、C项鲁菲尼小体均有结缔组织被囊或复杂结构，属有被囊感受器；E项颈动脉体为含多种细胞的化学感受器，结构远比游离神经末梢复杂"},{"q":"下列关于胃排空的描述，正确的是","o":["扩张胃可抑制胃排空","胃内压不是胃排空的动力","胃排空的调节无激素参与","胃排空速度与胃内容物的体积呈直线关系","胃排空的速度与胃内容物的种类无关"],"a":3,"e":"胃排空的直接动力是胃内压与十二指肠内压之差，胃内容物体积越大，胃内压越高，排空越快，二者近似呈直线关系。A项扩张胃通过迷走迷走反射与壁内神经丛促进排空而非抑制；B项胃内压正是排空动力；C项胃泌素促排空、促胰液素与抑胃肽抑制排空，激素参与调节；E项排空速度因食物种类而异，糖最快脂肪最慢"},{"q":"异相睡眠区别于慢波睡眠的特点是","o":["感觉功能和肌张力更加增强","可出现阵发性副交感兴奋表现","多梦","生长素分泌增多","代谢率降低"],"a":2,"e":"异相睡眠即快波睡眠，区别于慢波睡眠的显著特点是梦境生动、眼球快速运动与肌张力显著降低，脑电呈去同步化快波。A项肌张力在异相睡眠反而减弱；D项生长素分泌高峰出现在慢波睡眠；E项代谢率降低是慢波睡眠特征；B项阵发性自主神经活动并非与慢波睡眠的最典型区别，多梦才是"},{"q":"Starling机制在生理状态下的主要功能在于","o":["使心输出量增加","使心指数下降","调节搏出量和回心血量的平衡","使射血分数增加","使每搏功增加"],"a":2,"e":"Starling机制指回心血量增多使心室舒张末期容积即前负荷增大，心肌收缩力相应增强、搏出量增加，从而使搏出量与回心血量保持平衡。该机制在于匹配而非单纯使心输出量增加；它不直接改变心指数、射血分数或每搏功，这些指标受心率、后负荷等多因素影响，并非其主要功能"},{"q":"下列哪项不是导致子宫内膜功能层剥离、脱落出现月经的主要原因","o":["体内促性腺激素水平降低","体内雌激素水平降低","体内孕激素水平降低","体内催乳素水平降低","体内促性腺激素释放激素水平降低"],"a":3,"e":"月经发生主要因黄体退化后雌激素、孕激素水平骤降，子宫内膜功能层失去激素支持而剥脱出血，促性腺激素及其释放激素的变化参与调节。催乳素主要促进乳汁分泌，与子宫内膜周期性剥脱无直接关系，其水平降低不是月经成因，故为答案"},{"q":"心交感神经节后纤维释放的神经递质是","o":["乙酰胆碱","去甲肾上腺素","血管紧张素Ⅱ","血管升压素","缓激肽"],"a":1,"e":"心交感神经节后纤维末梢释放去甲肾上腺素，作用于心肌β1受体，使心率加快、传导加速、收缩力增强。A项乙酰胆碱是心迷走神经节后纤维的递质；C项血管紧张素Ⅱ、D项血管升压素为体液因素；E项缓激肽为舒血管物质，均非心交感节后纤维递质"},{"q":"可分泌肾素的结构是肾脏的","o":["球外系膜细胞","间质细胞","球旁细胞","感受器细胞","致密斑"],"a":2,"e":"肾素由肾小球球旁器中的球旁细胞（近球细胞）分泌，为含肾素颗粒的上皮样细胞。致密斑是化学感受器，感受远曲小管液Na+浓度变化并调节肾素释放，本身不分泌肾素；球外系膜细胞与间质细胞无分泌肾素功能；感受器细胞属泛指，非分泌结构"},{"q":"以下不经过特异性投射系统传入的感觉是","o":["视觉","嗅觉","听觉","味觉","本体感觉"],"a":1,"e":"嗅觉感受器冲动经嗅神经传入，不经过丘脑接替而直接投射至大脑皮层嗅觉代表区，故不经过特异性投射系统。A项视觉、C项听觉、D项味觉及E项本体感觉均需经丘脑特异核团接替后投射至皮层特定区域，属于特异性投射系统；嗅觉是唯一不经过丘脑接替的特异感觉"},{"q":"红细胞所需的能量主要来自","o":["葡萄糖的有氧氧化","糖异生","糖原分解","糖酵解","脂肪酸氧化"],"a":3,"e":"成熟红细胞无线粒体，不能进行有氧氧化，其能量几乎全部来自胞质中的无氧糖酵解。A项葡萄糖有氧氧化需线粒体参与，成熟红细胞无法完成；B项糖异生是合成葡萄糖的途径而非供能方式；C项糖原分解并非红细胞主要能量来源；E项脂肪酸氧化同样依赖线粒体，均与红细胞的供能特点不符"},{"q":"脊髓闰绍细胞构成的抑制称为","o":["周围性抑制","侧支性抑制","除极化抑制","回返性抑制","交互性抑制"],"a":3,"e":"脊髓前角α运动神经元发出轴突支配骨骼肌，同时发出侧支兴奋闰绍细胞，闰绍细胞作为抑制性中间神经元反过来抑制该α运动神经元及其协同神经元，这种反馈形式称为回返性抑制。周围性抑制和侧支性抑制属于其他分类，除极化抑制与交互性抑制的机制和环路均不同"},{"q":"肾上腺素的生理作用不包括","o":["使心跳加快，心肌收缩力增强，心输出量增加","使皮肤与肾脏的小动脉收缩，骨骼肌的小动脉与冠状动脉舒张","可加速肝糖原分解","大剂量引起血压下降，小剂量引起全部血管收缩，血压升高","使支气管平滑肌舒张"],"a":3,"e":"肾上腺素激动β受体使心率加快、心肌收缩力增强、心输出量增加，激动α受体使皮肤与肾小动脉收缩而骨骼肌血管和冠脉舒张，还能促进肝糖原分解并舒张支气管平滑肌。所谓大剂量引起血压下降、小剂量引起全部血管收缩恰与肾上腺素的受体作用相反，小剂量以β效应为主、大剂量才显现α缩血管效应"},{"q":"细胞膜结构中，促使4,5-二磷酸磷脂酰肌醇（PIP2）分解生成IP3和DG的物质是","o":["磷脂酶C","乙酰胆碱酯酶","蛋白激酶C","腺苷酸环化酶","磷酸二酯酶"],"a":0,"e":"含氮激素与膜受体结合后经Gq蛋白激活磷脂酶C，后者水解膜上PIP2生成IP3和DG两个第二信使，分别引起细胞内Ca2+释放和激活蛋白激酶C。B项乙酰胆碱酯酶水解乙酰胆碱；C项蛋白激酶C是DG的下游效应酶；D项腺苷酸环化酶催化生成cAMP；E项磷酸二酯酶降解cAMP"},{"q":"去甲肾上腺素与β受体结合后引起收缩或收缩加强的肌组织是","o":["心房肌","子宫平滑肌","小肠平滑肌","血管平滑肌","支气管平滑肌"],"a":0,"e":"心脏表达β1受体，去甲肾上腺素与之结合后产生正性变时、变力、变传导作用，使心房肌等心肌收缩加强。支气管平滑肌、血管平滑肌及子宫平滑肌上的β2受体被激动后引起舒张，而非收缩，故只有心房肌符合题意"},{"q":"为气体医学研究拉开序幕的诺奖分子是","o":["CO","H2S","N2","NO","H2"],"a":3,"e":"一氧化氮作为血管内皮舒张因子被证实，开创了气体信号分子研究，相关发现获诺贝尔奖，推动气体医学发展。一氧化碳、硫化氢虽也是气体信号分子，但开创性工作以NO为代表；氮气为惰性气体、无信号作用；氢气同样不具备该里程碑意义"},{"q":"下列功能中，大脑优势半球占优势的是","o":["空间辨认","深度知觉","语言活动","触觉认识","音乐欣赏"],"a":2,"e":"大脑优势半球（多为左侧）在语言活动、逻辑思维和计算等方面占优势，语言中枢主要位于此半球。空间辨认、深度知觉、触觉认识和音乐欣赏则更多由非优势半球（多为右侧）承担，这些功能并非优势半球占优势的方面"},{"q":"具有局部兴奋特征的电信号是","o":["神经纤维的动作电位","神经干的动作电位","锋电位","终板电位","后电位"],"a":3,"e":"终板电位是神经-肌接头处终板膜产生的局部去极化电位，具有局部兴奋特征，可总和、随距离衰减、无全或无。A项神经纤维动作电位、B项神经干动作电位、C项锋电位均为可传导的全或无动作电位；E项后电位为动作电位的一部分，属再生性电信号，不具局部兴奋特征"},{"q":"下列哪种情况下ADH的分泌将会减少","o":["大出血","大量出汗","严重呕吐或腹泻","大量饮清水","血糖浓度升高"],"a":3,"e":"抗利尿激素分泌主要受血浆晶体渗透压与循环血量调节，大量饮清水使血浆渗透压降低，下丘脑渗透压感受器受抑，ADH分泌减少，尿量增多即为水利尿。A项大出血、B项大量出汗、C项严重呕吐腹泻均致循环血量减少，ADH分泌反而增加；E项血糖升高不是刺激ADH的有效渗透因素，但最直接的抑制因素仍是大量饮清水"},{"q":"请问下列哪种情况可引起右室容量负荷增大","o":["肺动脉高压","肺动脉栓塞","室间隔缺损","心肌炎","肺动脉瓣狭窄"],"a":2,"e":"室间隔缺损使左室血液经缺损向右分流，肺循环血量及回流至右心的血量增加，导致右室舒张期容量负荷增大。A项肺动脉高压、B项肺动脉栓塞、E项肺动脉瓣狭窄均增加右室射血阻力，属压力负荷即后负荷增大；D项心肌炎主要损害心肌收缩力，不造成容量负荷增加"},{"q":"心室肌细胞绝对不应期的产生是由于","o":["Na＋通道处于激活状态","Na＋通道处于备用状态","Na＋通道处于失活状态","Ca2＋通道处于激活状态","Ca2＋通道处于失活状态"],"a":2,"e":"心室肌细胞0期去极化后，Na+通道迅速进入失活状态，在此状态下无论多大刺激都不能再次开放，故形成绝对不应期，直至复极达一定电位才逐步恢复备用。Na+通道激活或备用时细胞具有兴奋性；Ca2+通道的激活与失活主要影响平台期，不是绝对不应期产生的原因"},{"q":"静息心指数等于","o":["每搏输出量/心室舒张末期容积","心输出量/体表面积","每搏输出量/体表面积","心室舒张末期容积/体表面积","每分功/体表面积"],"a":1,"e":"静息心指数指安静空腹状态下单位体表面积的心输出量，即心输出量/体表面积，用于比较不同身材个体的心功能。每搏输出量/体表面积是每搏指数；每搏输出量/心室舒张末期容积为射血分数"},{"q":"关于紧张性收缩的叙述，下面说法错误的是","o":["是胃肠共有的运动形式","有助于消化管保持正常的形态和位置","有助于消化液渗入食物中","当紧张性收缩减弱时，食物吸收加快","是其他运动形式的基础"],"a":3,"e":"紧张性收缩减弱时消化管张力下降、蠕动无力，食物推进与吸收反而减慢，故该说法错误。紧张性收缩是胃肠共有的运动形式，可维持消化管正常形态与位置，有助于消化液渗入食物，并作为其他运动形式的基础，其余表述均正确"},{"q":"雌激素的生理作用不包括","o":["促进卵泡发育","促进子宫内膜分化","促进乳房脂肪沉积","促进阴道上皮细胞增生","促进输卵管发育"],"a":1,"e":"雌激素促进卵泡发育、阴道上皮增生、乳房脂肪沉积及输卵管发育；对子宫内膜主要促进增生期变化，而分泌期的分化即分泌转化由孕激素主导，故促进子宫内膜分化不属于雌激素作用。A、C、D、E均为雌激素的生理作用，该项所述分化实为孕激素效应"},{"q":"丘脑特异感觉接替核中躯体感觉的中继站是","o":["内侧膝状体","外侧膝状体","后腹核","丘脑外侧核","丘脑前核"],"a":2,"e":"丘脑后腹核是躯体感觉的特异感觉接替核，为躯干四肢感觉的中继站。内侧膝状体为听觉中继站，外侧膝状体为视觉中继站，丘脑外侧核、丘脑前核分属其他功能核团，均非躯体感觉中继站"},{"q":"损伤后可发生平衡障碍的小脑部位是","o":["左侧小脑外侧部","右侧小脑外侧部","小脑蚓部","绒球小结叶","小脑半球中间部"],"a":3,"e":"绒球小结叶属前庭小脑，与前庭器官联系密切，主要维持身体平衡和协调眼球运动，受损时出现平衡障碍、站立不稳和眼球震颤。A项左侧、B项右侧小脑外侧部受损主要表现为同侧肢体共济失调；C项小脑蚓部受损影响躯干四肢近端协调；E项小脑半球中间部受损表现为肢体共济失调、意向性震颤"},{"q":"当血钾逐步升高时，心肌的兴奋性","o":["逐步升高","逐步降低","先升高后降低","先降低后升高","不变"],"a":2,"e":"轻度高血钾使静息电位上移、距阈电位变近，兴奋性升高；显著高血钾使Na+通道失活，兴奋性降低乃至消失，故呈先升高后降低。持续升高或持续降低都不符合这一双向变化"},{"q":"远端小管和集合管所分泌的氨主要来自","o":["精氨酸","甘氨酸","丙氨酸","谷氨酰胺","亮氨酸"],"a":3,"e":"远端小管和集合管上皮细胞内的谷氨酰胺经谷氨酰胺酶脱氨生成氨，扩散入小管液与H+结合成铵盐排出，是肾小管泌氨的主要来源，参与酸碱平衡调节。精氨酸、甘氨酸、丙氨酸和亮氨酸虽为氨基酸，但并不是肾小管生成氨的主要底物"},{"q":"在日常生活当中，下列哪种情况会促进唾液分泌","o":["睡眠","恶心","疲劳","失水","恐惧"],"a":1,"e":"恶心时常伴迷走神经等自主神经反应，使唾液分泌明显增多，出现流涎。睡眠、疲劳时副交感活动相对减弱，唾液分泌减少；失水时因体液丢失唾液分泌受抑而口干；恐惧时交感兴奋抑制唾液分泌，均不能促进唾液分泌"},{"q":"下列关于肌梭的描述，正确的是","o":["与梭外肌纤维呈串联关系","适宜刺激是骨骼肌张力的变化","接受α运动神经元的支配","传入纤维有Ⅰa和Ⅰb两类纤维","感受并传入有关肌肉活动状态的信息"],"a":4,"e":"肌梭是位于骨骼肌内的长度感受器，与梭外肌并联，感受肌肉长度及其变化速率，传入纤维（Ⅰa、Ⅱ类）把肌肉活动状态信息传入中枢，参与牵张反射。与梭外肌串联（A项）为腱器官；适宜刺激为张力变化（B项）的是腱器官；肌梭受γ运动神经元支配（C项错）；Ⅰb纤维（D项）来自腱器官"},{"q":"关于搏出量储备，下列说法错误的是","o":["搏出量储备可分为收缩期储备和舒张期储备","提高射血分数可增加收缩期储备","增强心肌收缩能力可增加收缩期储备","增加舒张末期容积可增加舒张期储备","舒张期储备较收缩期储备大"],"a":4,"e":"搏出量储备分为收缩期储备与舒张期储备，收缩期储备通过增强心肌收缩力、提高射血分数实现，幅度较大；舒张期储备受心室舒张末期容积限制、增加有限，故舒张期储备较大一说错误。A项分类正确；B项提高射血分数、C项增强收缩力均增加收缩期储备；D项增加舒张末期容积可增加舒张期储备"},{"q":"调节胰高血糖素分泌的最重要因素是","o":["生长激素分泌量","血中氨基酸浓度","胰岛素分泌量","生长抑素分泌量","血糖浓度"],"a":4,"e":"血糖浓度是调节胰高血糖素分泌的最重要因素，血糖降低时分泌明显增加，血糖升高时被抑制，与胰岛素分泌呈相反变化。血中氨基酸增多、胰岛素和生长抑素的旁分泌作用也可影响分泌，但均不及血糖浓度重要；生长激素分泌量不是主要调节因素"},{"q":"婴幼儿时期甲状腺分泌不足可产生","o":["侏儒症","肢端肥大症","向心性肥胖","呆小症","糖尿病"],"a":3,"e":"婴幼儿期甲状腺激素缺乏导致呆小症即克汀病，表现为智力低下、身材矮小与骨骼发育迟缓，因甲状腺激素促进脑与骨骼发育。A项侏儒症为幼年生长激素缺乏且智力正常；B项肢端肥大症为成年生长激素过多；C项向心性肥胖见于库欣综合征；E项糖尿病与胰岛素不足或抵抗有关，均非婴幼儿甲减所致"},{"q":"cAMP作为第二信使主要是激活","o":["AC","PLC","PKA","PKC","PKG"],"a":2,"e":"cAMP作为第二信使主要通过激活蛋白激酶A即PKA来磷酸化靶蛋白、放大信号。cGMP激活蛋白激酶G，DG激活蛋白激酶C，PLC为生成IP3和DG的酶，AC为生成cAMP的酶，均非cAMP直接激活的对象"},{"q":"糖类、蛋白质和脂肪的消化产物大部分被吸收的部位是","o":["十二指肠","空肠及回肠","十二指肠和空肠","十二指肠、空肠及回肠","回肠"],"a":2,"e":"糖类、蛋白质和脂肪的消化产物大部分在十二指肠和空肠被吸收，此处绒毛丰富、吸收面积大，食物在此已充分消化。仅十二指肠（A项）不完整；空肠及回肠（B项）、十二指肠空肠及回肠（D项）范围过宽，回肠主要吸收胆盐和维生素B12；回肠（E项）单独不是主要部位"},{"q":"关于胃的蠕动，下列说法正确的是","o":["空腹时基本不发生","起始于胃底部","蠕动波向胃底和幽门两个方向传播","发生频率约为12次/分","抑制胃的排空"],"a":0,"e":"胃的蠕动通常在进食后约半小时开始，空腹时基本不发生（仅见弱的移行性复合运动）。B项蠕动起始于胃体和胃窦而非胃底；C项蠕动波主要向幽门方向传播，不向胃底双向传播；D项胃蠕动频率约3次/分，而非12次/分；E项蠕动促进胃排空，而非抑制"},{"q":"下列关于胃酸分泌的描述，错误的是","o":["由壁细胞分泌","分泌过程是耗能过程","质子泵在H+分泌中起关键作用","壁细胞分泌HCl增多时，血浆pH将下降","质子泵可被奥美拉唑抑制"],"a":3,"e":"壁细胞分泌H+进入胃腔的同时，将HCO3-释放入血，餐后血浆pH暂时升高，称餐后碱潮，故分泌HCl增多时血浆pH下降的说法错误。由壁细胞分泌（A项）、耗能过程（B项）、质子泵起关键作用（C项）、奥美拉唑可抑制质子泵（E项）均为胃酸分泌的正确描述"},{"q":"血凝块形成后回缩的原因是","o":["纤维蛋白收缩","红细胞叠连","白细胞变形","血小板收缩蛋白收缩","红细胞破裂"],"a":3,"e":"血凝块回缩依赖血小板内肌动蛋白与肌球蛋白的收缩蛋白收缩，使纤维蛋白网拉紧、血清析出，血小板数量与功能直接影响回缩程度。纤维蛋白收缩（A项）实为纤维蛋白原在凝血酶作用下变成纤维蛋白的网络形成，本身无主动收缩能力；红细胞叠连（B项）影响血沉，白细胞变形（C项）与炎症游走相关，红细胞破裂（E项）为溶血，均不参与血块回缩"},{"q":"心房收缩挤入心室的血量约占心室总充盈量的","o":["1/10","1/6","1/5","1/4","1/3"],"a":3,"e":"心房收缩期挤入心室的血量约占心室总充盈量的四分之一，其余大部分由心室舒张时的抽吸作用完成，心房收缩仅起辅助充盈作用。A项1/10、B项1/6、C项1/5均低估了心房的辅助泵作用；E项1/3则高估，正常心律下心房收缩约提供25%的充盈量，房颤时失去该作用"},{"q":"红细胞悬浮稳定性降低是由于红细胞出现","o":["聚集","黏着","叠连","凝集","凝固"],"a":2,"e":"红细胞悬浮稳定性降低指红细胞易于下沉，主要原因是红细胞发生叠连，即多个红细胞彼此以凹面相贴成串，使表面积体积比减小、与血浆摩擦阻力减小，血沉加快。聚集（A项）、黏着（B项）为细胞黏附现象；凝集（D项）为抗原抗体反应；凝固（E项）为血液凝固，均非悬浮稳定性降低的机制"},{"q":"下列有关等容舒张期的说法错误的是","o":["室内压下降","心房血液流向心室","发生在收缩期结束后","半月瓣处于关闭状态","房室瓣处于关闭状态"],"a":1,"e":"等容舒张期位于收缩期结束之后，室内压迅速下降，半月瓣与房室瓣均关闭，心室容积不变，血液并不流动。B项称心房血液流向心室错误，此时房室瓣尚未开放，充盈发生在随后快速充盈期。A项室内压下降、C项发生于收缩期结束后、D项半月瓣关闭、E项房室瓣关闭均为该期正确特征"},{"q":"球-管平衡指的是哪一段小管的重吸收规律","o":["近端小管","髓袢","远端小管","集合管","所有肾脏小管节段"],"a":0,"e":"球-管平衡指近端小管重吸收率始终占肾小球滤过率的一定比例（约65%～70%），使尿量和尿中溶质不会因滤过率增加而大幅增加。髓袢（B项）、远端小管（C项）、集合管（D项）的重吸收随机体需要调节，不保持固定比例；所有肾脏小管节段（E项）说法过于笼统，球-管平衡特指近端小管"},{"q":"下列物质属于第二信使的是","o":["AC和GC","IP3和DG","PKA和PKC","PLC和PLA","CaM和CaMK"],"a":1,"e":"IP3和DG是膜受体经G蛋白偶联激活磷脂酶C后由PIP2水解生成的经典第二信使，分别促使内质网释放Ca2+和激活蛋白激酶C。AC、GC、PLC、PLA是催化生成第二信使的酶，PKA、PKC及CaMK是蛋白激酶，CaM是钙结合蛋白，均不是第二信使本身"},{"q":"关于视力的叙述，下列哪一项是正确的","o":["色盲患者视力减弱","中央凹视力比周边区高","是测量视网膜对光的敏感度指标","单眼视物比双眼视物时的视力高","黄斑处视力最高是因为此处视锥细胞多而集中，呈聚合联系"],"a":1,"e":"中央凹处视锥细胞密集且与双极细胞呈单线联系，故视力最高，明显高于周边区。色盲患者主要辨色障碍，视力不一定减弱；视力是分辨两点最小距离的能力，而非对光的敏感度；单眼视力低于双眼；黄斑处视锥多而集中，但呈单线而非聚合联系，聚合会降低分辨力"},{"q":"影响PTH分泌最重要的因素是","o":["血磷浓度","血钙离子浓度","血镁离子浓度","血中儿茶酚胺浓度","血中前列腺素浓度"],"a":1,"e":"甲状旁腺主细胞分泌PTH，血钙离子浓度是调节其分泌的最重要因素，低钙刺激分泌、高钙抑制分泌，呈负反馈。血磷升高虽可间接促进PTH分泌，但作用弱于血钙；血镁浓度异常严重时才有影响，儿茶酚胺与前列腺素并非主要调节因素"},{"q":"瘦素的分泌量主要反映体内哪种物质的储存量","o":["糖","蛋白质","脂肪","肌肉","ATP"],"a":2,"e":"瘦素由脂肪细胞分泌，其血浆水平与体内脂肪储量呈正相关，可反映能量储备并参与食欲与能量代谢调节。糖、蛋白质、肌肉量及ATP的储存量并不决定瘦素分泌水平，故瘦素主要反映脂肪的储存量"},{"q":"关于心动周期的论述，下列说法错误的是","o":["舒张期大于收缩期","左、右心室的搏出血量相等","等容舒张期末左心室容积最大","等容收缩期末主动脉压力最低","快速射血期末主动脉和左心室压力最高"],"a":2,"e":"心动周期中舒张期长于收缩期，左右心室搏出量相等，等容收缩期末主动脉压最低，快速射血期末主动脉压与左室压最高。等容舒张期末左心室处于收缩末期容积，为全程最小，最大容积出现在舒张末、心房收缩之后，故C项错误。A、B、D、E项均为心动周期的正确论述"},{"q":"窦房结能成为心脏正常起搏点的原因是","o":["静息电位仅为-70mV","阈电位为-40mV","0期去极化速度快","动作电位没有明显的平台期","4期自动去极化速度最快"],"a":4,"e":"窦房结4期自动去极化速度在所有自律细胞中最快，故其自律性最高，抢先激动并抑制其他潜在起搏点，成为正常起搏点。最大复极电位仅-70mV、阈电位-40mV是快反应自律细胞的特征，但不是决定起搏主导地位的关键；0期去极化速度慢、无明显平台期均为其电生理特点，与起搏点地位无直接关系"},{"q":"关于肾脏逆流倍增机制对尿液浓缩能力的叙述，正确的是","o":["与髓袢的长度无关","与肾髓质部血流速度无关","与髓袢肾小管的流速无关","取决于近端小管对水的通透性","取决于血中抗利尿激素的浓度"],"a":4,"e":"尿液浓缩依赖肾髓质高渗梯度与集合管对水的通透性，抗利尿激素提高集合管主细胞对水的通透性，使水在髓质高渗梯度下被重吸收，故浓缩能力取决于血中ADH浓度。A项髓袢越长逆流倍增越强、B项髓质血流过快会带走溶质、C项小管流速影响梯度建立，三者均有关；D项近端小管等渗重吸收水，与终尿浓缩关系不大"},{"q":"尿的浓缩与稀释主要取决于","o":["肾小球滤过率","血浆胶体渗透压","抗利尿激素分泌量","肾素分泌量","醛固酮分泌量"],"a":2,"e":"尿的浓缩与稀释取决于集合管对水的通透性，而该通透性由抗利尿激素分泌量决定；ADH多时水重吸收增加、尿浓缩，ADH少时尿稀释。A项肾小球滤过率影响尿量却不决定浓缩程度；B项血浆胶体渗透压主要影响滤过与容量；D项肾素、E项醛固酮主要调节钠钾与血容量，并非尿浓缩稀释的主导因素"},{"q":"甘氨酸受体的阻断剂是","o":["4-羟基喹啉酸","氯胺酮","荷包牡丹碱","士的宁","印防己毒素"],"a":3,"e":"甘氨酸是脊髓和脑干重要的抑制性递质，其受体为氯离子通道，士的宁是甘氨酸受体的特异性阻断剂，可解除抑制引起惊厥。C项荷包牡丹碱阻断的是GABA_A受体；E项印防己毒素亦作用于GABA_A受体通道；A项4-羟基喹啉酸为代谢型谷氨酸受体激动剂；B项氯胺酮阻断NMDA受体，均非甘氨酸受体阻断剂"},{"q":"下列关于肌紧张的叙述，错误的是","o":["缓慢持续牵拉肌肉时发生的牵张反射","是维持躯体姿势的最基本的反射活动","其感受器为肌梭","主要是屈肌表现明显","是多突触反射"],"a":3,"e":"肌紧张是缓慢持续牵拉肌肉时发生的牵张反射，是多突触反射，感受器为肌梭，是维持躯体姿势最基本的反射，在抗重力肌（伸肌）表现最明显，而非屈肌。缓慢持续牵拉（A项）、维持姿势（B项）、感受器为肌梭（C项）、多突触反射（E项）均为肌紧张的正确叙述"},{"q":"肾上腺皮质功能亢进时，可发生","o":["侏儒症","水中毒","向心性肥胖","肢端肥大症","呆小症"],"a":2,"e":"肾上腺皮质功能亢进时糖皮质激素分泌过多，引起库欣综合征，表现为向心性肥胖、满月脸、水牛背。侏儒症、呆小症源于幼年生长激素或甲状腺激素不足，肢端肥大症为成年生长激素过多，水中毒与抗利尿激素分泌过多有关"},{"q":"胃黏膜屏障的作用一般是指","o":["防止H+由胃腔侵入黏膜","防止胃蛋白酶消化胃黏膜","防止Ca2+从黏膜向胃肠弥散","防止Cl-由胃腔侵入黏膜","防止细菌侵入黏膜"],"a":0,"e":"胃黏膜屏障由表面黏液细胞及细胞间紧密连接构成，核心作用是阻挡胃腔内H+向黏膜内逆向弥散，防止酸损伤。黏液层中HCO3-中和胃酸并阻隔胃蛋白酶；Ca2+、Cl-的跨膜转运并非该屏障的定义，细菌入侵主要靠胃酸杀灭，均非胃黏膜屏障的主要含义"},{"q":"分泌胰岛素的B细胞约占胰岛细胞总数的","o":["小于1%","0、05","0、2","0、6","0、75"],"a":3,"e":"胰岛B细胞约占胰岛细胞总数的60%即0.6，是数量最多的细胞，分泌胰岛素。A细胞约占20%分泌胰高血糖素，D细胞分泌生长抑素，PP细胞分泌胰多肽，均远少于B细胞，故0.6符合B细胞占比"},{"q":"细胞膜对Na＋通透性增加时，静息电位将","o":["增大","减小","不变","先增大后减小","先减小后增大"],"a":1,"e":"静息电位主要由K+外流形成，接近K+平衡电位（负值）。膜对Na+通透性增加时Na+内流，使膜内负电位减小，静息电位绝对值下降即去极化，故静息电位减小。A项增大表示超极化，与Na+内流相反；C项不变忽略Na+内流影响；D、E项先变后恢复不符合单纯通透性改变的结果"},{"q":"下列哪种酶在TSH促进甲状腺激素合成的过程中起关键性作用","o":["脱碘酶","蛋白水解酶","过氧化酶","腺苷酸环化酶","磷脂酶C"],"a":2,"e":"TSH促进甲状腺激素合成的关键酶是甲状腺过氧化物酶，催化碘的活化、酪氨酸碘化与偶联。脱碘酶参与T4向T3转化和碘再利用，蛋白水解酶参与激素释放，腺苷酸环化酶与磷脂酶C为胞内信号转导酶，均非合成过程的关键酶"},{"q":"红细胞沉降率的快慢主要取决于红细胞的","o":["体积","表面积","数量","比重","叠连的加速或抑制"],"a":4,"e":"红细胞沉降率主要取决于红细胞叠连的快慢，叠连加速使细胞总表面积与容积比减小、下沉摩擦阻力下降，血沉因而加快，血浆纤维蛋白原、球蛋白增多也通过促进叠连起作用。A项体积、B项表面积、C项数量、D项比重均为红细胞自身参数，并非决定血沉快慢的关键因素，叠连才是主要决定环节"},{"q":"由腺垂体分泌的激素是","o":["GH","CRH","GHRH","GHIH","GnRH"],"a":0,"e":"生长激素即GH，由腺垂体生长激素细胞分泌，是腺垂体的主要激素之一。CRH、GHRH、GnRH均由下丘脑神经内分泌细胞分泌，经垂体门脉调节腺垂体；GHIH即生长抑素，也主要由下丘脑及胰岛等组织产生，均非腺垂体分泌"},{"q":"下列关于胆汁分泌与排出的叙述，正确的是","o":["肝细胞分泌胆汁是间断的","胆汁是持续进入十二指肠的","在食物消化期的头期和胃期胆囊收缩由CCK引起","在食物消化的肠期胆囊收缩主要由迷走神经兴奋引起","进食开始后数分钟胆囊便开始收缩排放胆汁"],"a":4,"e":"进食开始后数分钟内，迷走神经兴奋及胆囊收缩素释放使胆囊收缩、Oddi括约肌舒张，胆汁排入十二指肠参与消化。肝细胞持续分泌胆汁，并非间断；胆汁在非消化期储存于胆囊，也不是持续进入十二指肠。头期和胃期的胆囊收缩主要由迷走神经引起，肠期才主要由胆囊收缩素引起"},{"q":"下列有关ABO血型系统的叙述，正确的是","o":["新生儿血浆中存在IgG型抗A或抗B抗体","新生儿血浆中存在IgM型抗A或抗B抗体","新生儿红细胞上A或B抗原的含量与成人相同","新生儿血浆中存在的抗A或抗B抗体是自己产生的","新生儿体内的A或B抗原只存在于红细胞上"],"a":0,"e":"新生儿自身尚不能产生抗A、抗B抗体，其血浆中的抗A或抗B抗体来自母体，免疫球蛋白中只有IgG能通过胎盘，故新生儿血浆中可存在IgG型抗A或抗B抗体。IgM不能通过胎盘；新生儿红细胞上A、B抗原尚未发育完全，含量低于成人；抗A或抗B抗体也不是新生儿自己产生的"},{"q":"下列哪种物质不属于第二信使","o":["cAMP","ACh","钙离子","三磷酸肌醇","二酰甘油"],"a":1,"e":"乙酰胆碱是细胞间传递信息的第一信使，通过与膜受体结合发挥作用，本身不是第二信使。cAMP、Ca2＋、三磷酸肌醇和二酰甘油均为细胞内第二信使，由第一信使激活膜受体后产生或释放，介导下游信号级联反应"},{"q":"严重营养不良引起的水肿的主要原因是","o":["毛细血管血压升高","组织液静水压降低","组织液胶体渗透压升高","血浆胶体渗透压降低","淋巴回流受阻"],"a":3,"e":"严重营养不良时蛋白质摄入不足，血浆蛋白尤白蛋白合成减少，血浆胶体渗透压下降，毛细血管内水分滤出增多、重吸收减少，组织液积聚形成水肿。A项毛细血管血压升高见于心衰、静脉阻塞；B项组织液静水压降低、C项组织液胶体渗透压升高并非主因；E项淋巴回流受阻引起淋巴性水肿，均非营养不良水肿机制"},{"q":"下列关于腱器官的叙述，正确的是","o":["梭外肌纤维发生等长收缩时，腱器官传入冲动发放频率不变","梭外肌纤维发生等张收缩时，腱器官传入冲动发放频率增加","其传入冲动对同一肌肉的α运动神经元起抑制作用","传入神经纤维为Ⅱ类纤维","是一种长度感受器"],"a":2,"e":"腱器官是位于肌腱的张力感受器，与梭外肌串联，传入纤维为Ⅰb类；肌肉张力过大时传入冲动兴奋抑制性中间神经元，抑制同一肌肉的α运动神经元，防止肌肉过度收缩而损伤。传入频率等长收缩不变（A项）、等张收缩增加（B项）描述错误；Ⅱ类纤维（D项）为肌梭传入；长度感受器（E项）是肌梭"},{"q":"肾小管超滤液中葡萄糖被重吸收的部位是","o":["髓袢降支","近端小管","髓袢升支","远端小管","集合管"],"a":1,"e":"小管液中的葡萄糖几乎全部在近端小管尤其近曲小管被重吸收，由Na+-葡萄糖同向转运体以继发性主动转运完成，故正常尿中无糖。A项髓袢降支、C项髓袢升支、D项远端小管、E项集合管基本不重吸收葡萄糖"},{"q":"心脏副交感神经的节前神经元位于","o":["延髓","颈髓","胸髓","腰髓","骶髓"],"a":0,"e":"心脏副交感（迷走）神经的节前神经元位于延髓的疑核和迷走神经背核，节后纤维在心内神经节换元后支配心脏，释放乙酰胆碱使心率减慢。B项颈髓、C项胸髓为交感节前神经元所在（胸腰段）；D项腰髓、E项骶髓含支配盆腔脏器的副交感节前神经元，与心脏无关"},{"q":"关于呼吸商的叙述，错误的是","o":["糖的呼吸商为1.00","脂肪的呼吸商为0.71","任何情况下，呼吸商不能大于1.00","是指一定时间内呼出的CO2量和吸入的O2量的比值","从非蛋白呼吸商可以推测体内氧化的糖和脂肪量的比例"],"a":2,"e":"呼吸商为一定时间内呼出CO2量与吸入O2量之比，糖为1.00，脂肪约0.71。但某些情况下可大于1，如摄入过多糖转化为脂肪时，或剧烈运动后CO2排出增多，呼吸商可超过1.00，故该项错误。A项糖的呼吸商、B项脂肪的呼吸商、D项定义、E项非蛋白呼吸商的推测作用均正确"},{"q":"蛙的有髓神经纤维动作电位的锋电位持续时间约2毫秒，从理论上讲，1秒内所产生的动作电位次数不可能超过多少次","o":["100","200","300","400","500"],"a":4,"e":"有髓神经纤维锋电位持续约2毫秒，存在绝对不应期，故每秒最多产生动作电位的次数为1000除以2等于500次，不应期由钠通道失活决定，限定了发放冲动的最高频率。A项100、B项200、C项300、D项400均低于理论上限，1秒仅1000毫秒，2毫秒一次即上限500次，不可能超过该值"},{"q":"下列关于微循环血流动力学的描述，正确的是","o":["毛细血管前后阻力比约为2∶1","毛细血管前括约肌对血流量控制起主要作用","毛细血管前括约肌交替收缩和舒张50次/分","安静状态下同一时间内约20%的毛细血管处于开放状态","毛细血管前括约肌的舒缩主要受血中儿茶酚胺调节"],"a":3,"e":"微循环中毛细血管前括约肌受局部代谢产物调节而交替舒缩，安静时同一时间仅约20%的毛细血管开放。前括约肌舒缩频率约为每分钟5～10次，而非50次；其舒缩主要受局部代谢产物调节，血中儿茶酚胺并非主导。毛细血管血压取决于前后阻力之比，前阻力大于后阻力，选项所给2∶1的比值并不成立"},{"q":"调节胰岛素分泌最重要的刺激因素是","o":["血中氨基酸水平","血糖水平","血中脂肪酸水平","乙酰胆碱","胰高血糖素"],"a":1,"e":"血糖水平是调节胰岛素分泌最重要的因素，血糖升高直接刺激胰岛B细胞，经葡萄糖代谢使ATP增多、KATP通道关闭、膜去极化、Ca2+内流而释放胰岛素。A项氨基酸、C项脂肪酸及D项乙酰胆碱、E项胰高血糖素虽可促进分泌，但作用均弱于血糖，生理状态下血糖浓度变化才是主导信号"},{"q":"在壁细胞完全缺乏的人体内，下列哪种情况不会发生","o":["消化蛋白质能力降低","维生素B12吸收减少","胃蛋白酶活性降低或消失","肠道细菌生长加速","胰碳酸氢盐分泌减少"],"a":0,"e":"壁细胞分泌盐酸与内因子；完全缺乏时盐酸缺失，胃蛋白酶原无法激活，内因子缺乏致维生素B12吸收障碍，胃酸杀菌减弱使肠菌繁殖，入十二指肠酸减少使促胰液素释放下降、胰碳酸氢盐分泌减少。蛋白质消化主要依赖小肠胰蛋白酶等，胃蛋白酶缺失影响有限，消化蛋白质能力基本不降低"},{"q":"下列哪种激素由非内分泌腺器官产生","o":["甲状旁腺素","降钙素","醛固酮","心房钠尿肽","胰高血糖素"],"a":3,"e":"心房钠尿肽由心房肌细胞产生，不属专门内分泌腺，具有利钠、利尿、舒张血管和降低血压的作用。A项甲状旁腺素由甲状旁腺、B项降钙素由甲状腺C细胞、C项醛固酮由肾上腺皮质、E项胰高血糖素由胰岛α细胞分泌，这些器官或细胞均属专门的内分泌腺或内分泌细胞"},{"q":"营养物质在体内氧化所释放的能量，迅速转化为热能占总量的","o":["20%以上","30%以上","50%以上","70%以上","80%以上"],"a":2,"e":"营养物质在体内氧化释放的能量，超过一半迅速以热能形式散发，用于维持体温；其余以化学能形式储存于ATP中供机体做功，最终也多转为热。A项20%以上、B项30%以上数值偏低，低估了直接产热比例；D项70%以上、E项80%以上偏高，与ATP储能约占不足一半的事实不符"},{"q":"排便反射的初级中枢位于","o":["脊髓腰骶段","脊髓胸段","延髓","脑桥","大脑皮质"],"a":0,"e":"排便反射的初级中枢位于脊髓腰骶段，直肠充盈刺激感受器，冲动传至该中枢并上传至大脑皮层产生便意。脑桥、中脑、延髓及脊髓胸段均非排便反射初级中枢所在"},{"q":"下列关于脂联素的生物学作用，哪项是错误的","o":["抑制外周组织对葡萄糖的摄取","增加靶细胞对胰岛素的敏感性","促进血浆中游离脂肪酸氧化","减少脂肪合成","抗炎、保护心肌"],"a":0,"e":"脂联素由脂肪细胞分泌，可提高靶细胞对胰岛素的敏感性，促进外周组织摄取葡萄糖和血浆游离脂肪酸氧化，并抑制脂肪合成，还具有抗炎和保护心肌的作用。它能促进而非抑制外周组织对葡萄糖的摄取，故该项错误。增加胰岛素敏感性、减少脂肪合成及抗炎护心肌均为脂联素的真实作用"},{"q":"肾素-血管紧张素系统激活时以下减少或降低的是","o":["动脉血压","静脉紧张性","醛固醇分泌","肾上腺素分泌","肾脏的钠盐排出量"],"a":4,"e":"肾素血管紧张素系统激活后，血管紧张素Ⅱ收缩血管并刺激醛固酮分泌，促进肾小管保钠排钾，使肾脏钠盐排出量减少，同时动脉血压升高、静脉紧张性增强。A项动脉血压应升高；B项静脉紧张性增强；C项醛固酮分泌增多而非减少；D项肾上腺素分泌不受该系统直接抑制，均非降低项"},{"q":"心室肌细胞与浦肯野细胞动作电位的主要区别在于","o":["0期去极化速度与幅度不同","1期复极化的机制不同","平台期复极化的机制不同","3期复极化的机制不同","4期自动去极化的有无"],"a":4,"e":"心室肌细胞4期膜电位稳定无自动去极化，浦肯野细胞4期有缓慢自动去极化而具自律性，此为二者主要区别。两者0期（E项）、1期（A项）、2期（B项）、3期（C项）的形成机制基本相似"},{"q":"下列各项中，能使通气/血流比值升高的是","o":["肺水肿","肺气肿","哮喘发作","肺纤维化","肺毛细血管阻塞"],"a":4,"e":"通气/血流比值升高意味着肺泡通气相对过多或肺血流相对不足，肺毛细血管阻塞使局部血流减少，通气与血流不能匹配，比值升高并形成功能性死腔。A项肺水肿、C项哮喘发作、D项肺纤维化主要损害通气或气体交换，使比值降低并形成功能性分流；B项肺气肿多为通气与血流同时减少，不如毛细血管阻塞直接使血流锐减"},{"q":"甲状腺激素负反馈调节主要作用部位是","o":["下丘脑促垂体区","腺垂体","神经垂体","下丘脑室旁核","下丘脑视上核"],"a":1,"e":"血液中游离甲状腺激素升高主要作用于腺垂体，抑制促甲状腺激素的合成与释放，同时也抑制下丘脑促甲状腺激素释放激素的分泌，构成负反馈调节。神经垂体不参与此轴；下丘脑室旁核、视上核主要合成缩宫素和抗利尿激素，与甲状腺激素负反馈无关"},{"q":"具有分泌肾素功能的结构是","o":["致密斑","系膜细胞","颗粒细胞","间质细胞","近髓肾单位"],"a":2,"e":"肾素由肾小球旁器的颗粒细胞（球旁细胞）合成和释放，在肾灌注压下降或交感兴奋时分泌增加，启动肾素-血管紧张素-醛固酮系统。致密斑是远曲小管感受小管液Na+浓度的化学感受器，系膜细胞起支持和收缩作用，间质细胞分泌前列腺素，近髓肾单位参与尿液浓缩，均不分泌肾素"},{"q":"在视5m以内近物时，人眼所进行的最重要的调节是","o":["角膜曲率增加","晶状体变凸","瞳孔近反射","瞳孔对光反射","眼轴会聚"],"a":1,"e":"视5m以内近物时眼的调节包括晶状体变凸、瞳孔缩小和双眼球会聚，其中晶状体变凸最重要，靠睫状肌收缩、悬韧带松弛使曲率增大、折光力增强，将像聚焦视网膜。角膜曲率固定不可调；瞳孔对光反射由光强变化引起而非视近；眼轴长度为固定结构，不参与调节"},{"q":"血中哪种物质浓度升高刺激醛固酮的分泌","o":["氯离子浓度","氢离子浓度","钠离子浓度","钾离子浓度","ACTH"],"a":3,"e":"血K＋浓度升高直接刺激肾上腺皮质球状带分泌醛固酮，促进肾脏排K＋以维持血钾稳定；血管紧张素Ⅱ也是重要刺激因素。氯离子浓度与ACTH并非主要调节因素；血钠浓度降低虽可刺激醛固酮但作用弱于血K＋；氢离子浓度升高对醛固酮的影响也不如K＋直接和显著"},{"q":"骨骼肌细胞中横管的功能是","o":["钙离子的贮存库","钙离子进出肌纤维的通道","营养物质进出肌细胞的通道","将兴奋传向肌细胞深部","使钙离子和肌钙蛋白结合"],"a":3,"e":"骨骼肌横管是肌膜向肌纤维深部凹陷形成的管道，可将肌膜上的动作电位迅速传入细胞内部，触发肌质网释放Ca2+。钙离子的贮存库是肌质网而非横管；钙离子进出肌纤维经肌膜钙通道与钙泵；营养物质转运由肌膜载体完成；Ca2+与肌钙蛋白结合发生在肌丝，均非横管功能"},{"q":"副交感舒血管纤维末梢释放的神经递质是","o":["去甲肾上腺素","肾上腺素","乙酰胆碱","P物质","血管活性肠肽"],"a":2,"e":"副交感舒血管纤维末梢释放乙酰胆碱，作用于血管内皮M受体引起血管舒张，参与局部血流调节。去甲肾上腺素是交感缩血管纤维的主要递质；肾上腺素主要由肾上腺髓质分泌；P物质和血管活性肠肽虽可作为递质共存，但副交感舒血管纤维的主要递质仍是乙酰胆碱"},{"q":"肾内存在哪种细胞可参与血管紧张素原转化为血管紧张素Ⅰ的过程","o":["肾小囊上皮细胞","球旁细胞","致密斑细胞","球外系膜细胞","近端小管上皮细胞"],"a":1,"e":"肾素主要由球旁细胞即近球细胞合成并释放，可催化血浆中的血管紧张素原水解为血管紧张素Ⅰ。肾小囊上皮细胞参与滤过屏障；致密斑感受小管液Na+浓度并调节肾素释放，但本身不产生肾素；球外系膜细胞具吞噬与信息传递功能；近端小管上皮细胞主司重吸收，均不承担此转化"},{"q":"人类处于清醒、安静并闭眼状态时，脑电活动的主要表现为","o":["α波","β波","θ波","δ波","棘慢波"],"a":0,"e":"正常成人清醒、安静并闭眼时，枕叶皮质记录到频率8～13Hz、振幅较大的α波，睁眼或视物时α波立即消失转为β波，称α波阻断。β波（B项）出现在睁眼、紧张或觉醒状态，频率快而波幅小；θ波（C项）见于困倦与儿童；δ波（D项）见于深睡或婴儿；棘慢波（E项）为癫痫样异常放电，均非清醒闭眼主波形"},{"q":"精子与卵子结合受精一般在何处完成","o":["输卵管伞部","输卵管壶腹部","输卵管峡部","输卵管子宫部","子宫底部"],"a":1,"e":"受精通常发生于输卵管壶腹部，此处管腔较宽，卵子在此停留并等待精子，精卵结合形成受精卵。输卵管伞部负责拾取卵子；峡部为输卵管结扎部位，管腔较窄；子宫部及子宫底部不是受精场所，受精卵在此已完成卵裂并向宫腔移行"},{"q":"成年人脑电图α波在","o":["安静闭目时出现阻断现象","糖皮质激素血浓度高时频率减慢","高血糖时频率减慢","发热时频率减慢","动脉血二氧化碳分压高时频率减慢"],"a":4,"e":"α波频率受多种因素调制，动脉血二氧化碳分压升高（高碳酸血症）可使脑电α波频率减慢。安静闭目时α波明显而非阻断（A项错），睁眼视物才出现α波阻断；糖皮质激素（B项）、高血糖（C项）、发热（D项）并非α波频率减慢的典型决定因素"},{"q":"心脏的等长调节是通过下列哪个因素对心脏泵血功能进行调节的","o":["心肌初长度","肌小节初长度","粗、细肌丝间横桥结合数目","心脏收缩能力","心室舒张末期容积"],"a":3,"e":"心脏等长调节通过改变心肌收缩能力即变力状态来调节泵血功能，不依赖心肌初长度。心肌初长度、肌小节初长度、心室舒张末期容积属异长调节即Starling机制的要素；横桥结合数目是收缩的分子基础，非等长调节的调节因素"},{"q":"成年人甲状腺激素分泌不足，可出现下列哪种疾病或症状","o":["呆小症","侏儒症","黏液性水肿","肢端肥大症","水中毒"],"a":2,"e":"成年人甲状腺激素分泌不足引起黏液性水肿，表现为组织间隙黏液样物质潴留、畏寒、乏力、反应迟钝等。呆小症（A项）为婴幼儿甲减；侏儒症（B项）为幼年生长激素缺乏；肢端肥大症（D项）为成年生长激素过多；水中毒（E项）为水排泄障碍，均非成年甲减的表现"},{"q":"分娩过程中，促进子宫节律性收缩最重要的激素是","o":["缩宫素","雌激素","孕激素","前列腺素","糖皮质激素"],"a":0,"e":"分娩时缩宫素是促进子宫节律性收缩最重要的激素，通过正反馈使子宫收缩不断增强直至胎儿娩出。雌激素提高子宫兴奋性、前列腺素也促宫缩，但作用居次；孕激素抑制子宫收缩；糖皮质激素不直接主导宫缩"},{"q":"反射活动所表现的后放现象的结构基础是神经元间的","o":["辐射式联系","聚合式联系","链锁状联系","环状联系","单线式联系"],"a":3,"e":"反射后放是指刺激停止后反射活动仍持续一段时间，其结构基础是神经元之间的环状（环路）联系，兴奋在环内反复循环，使传出神经元持续发放。辐射式联系（A项）扩大兴奋范围；聚合式联系（B项）实现总和；链锁状联系（C项）延长空间传播但可终止；单线式联系（E项）一对一传递，均无持续反复兴奋的作用"},{"q":"受体阻断剂阻断突触传递的效应，是通过以下何种途径实现的","o":["抑制突触前神经末梢神经递质的释放","抑制DNA转录","与受体结合进而占据受体或改变受体的空间构型","在突触后膜上诱发超极化电位","增强神经递质的降解"],"a":2,"e":"受体阻断剂本身无内在活性，通过与突触后膜受体特异性结合，占据受体或改变其空间构型，使递质无法结合，从而阻断突触传递。抑制递质释放（A项）为突触前抑制或毒素作用；抑制DNA转录（B项）影响蛋白合成；在突触后膜诱发超极化（D项）是抑制性递质效应；增强递质降解（E项）属酶抑制剂作用，均非阻断剂机制"},{"q":"小肠特有的运动形式是","o":["紧张性收缩","分节运动","蠕动","容受性舒张","集团蠕动"],"a":1,"e":"分节运动是小肠特有的节律性环形肌舒缩运动，将食糜反复分割与混合，利于消化液混合和营养吸收，不显著推进食糜。蠕动冲项实为小肠可出现的快速远距离推进运动，非小肠特有。集团蠕动项实为大肠特有的推进运动，袋状往返运动为大肠特有的混合运动，紧张性收缩为胃肠共有"},{"q":"水和尿素容易通透、而钠离子不容易通透的肾小管和集合管部位是","o":["近曲小管","远曲小管","髓袢降支细段","髓袢升支细段","集合管"],"a":2,"e":"髓袢降支细段对水与尿素通透性高，而对Na+不易通透，水在此段被重吸收使小管液浓缩。近曲小管对水与Na+均易通透；远曲小管与集合管对水的通透性受ADH调节；髓袢升支细段对Na+通透而对水几乎不通透，与降支细段正好相反"},{"q":"室性期前收缩之后常出现代偿间歇的原因是","o":["窦房结传来的节律性兴奋落在室性期前兴奋的有效不应期内","窦房结的节律性兴奋少发放一次","窦房结的节律性兴奋延迟发放","室性期前兴奋的有效不应期特别长","窦房结的节律性兴奋传出速度大大减慢"],"a":0,"e":"室性期前收缩后，下一次窦房结转来的节律性兴奋恰好落在期前兴奋引起的有效不应期内，不能引起心室再次兴奋，须等再次窦性兴奋到达才收缩，故出现代偿间歇。窦房结并未少发放或延迟发放兴奋，其节律未变；期前兴奋的有效不应期并非特别长；传导速度减慢也不是代偿间歇的原因"},{"q":"胰岛素对脂肪代谢的调节作用是","o":["促进脂肪组织释放脂肪酸","抑制葡萄糖进入脂肪细胞","促进脂肪的合成与储存","增强脂肪酶的活性","增加酮体的生成"],"a":2,"e":"胰岛素促进脂肪细胞摄取葡萄糖、合成甘油三酯并抑制脂肪分解，从而促进脂肪的合成与储存。A项促进脂肪组织释放脂肪酸与胰岛素作用相反，胰岛素抑制脂解；B项抑制葡萄糖进入脂肪细胞错误，胰岛素促进之；D项增强脂肪酶活性会促进分解；E项酮体生成增加见于胰岛素缺乏时"},{"q":"影响血流阻力的最主要的因素是","o":["血液黏度","血管长度","小动脉口径","小静脉口径","大动脉的顺应性"],"a":2,"e":"根据泊肃叶定律，血流阻力与血管半径四次方成反比，血管口径是影响阻力最显著的因素，尤其小动脉和微动脉口径的微小变化即可明显改变外周阻力。A项血液黏度、B项血管长度影响较小且相对恒定；D项小静脉口径、E项大动脉顺应性对阻力影响远小于小动脉"},{"q":"CO2在体循环静脉血中运输时，将出现","o":["CO2与水反应在红细胞中转变成H+和HCO3-","H+被氧合血红蛋白缓冲","HCO3-从血浆进入红细胞内，同时交换出Cl-","HCO3-与血红蛋白结合","红细胞碱化"],"a":0,"e":"组织产生的CO2进入红细胞，在碳酸酐酶催化下与水生成碳酸并解离为H+和HCO3-，HCO3-扩散入血浆并发生氯转移。B项H+主要由去氧血红蛋白缓冲，氧合血红蛋白缓冲力弱；C项方向相反，应为HCO3-出红细胞、Cl-入红细胞；D项与Hb结合成氨基甲酰血红蛋白比例较小；E项红细胞因H+产生而酸化，非碱化"},{"q":"平静呼吸时，肺内压在下列哪一时相内等于大气压","o":["吸气中和呼气中","吸气中和呼气末","吸气末和呼气中","吸气末和呼气末","呼气中和呼气末"],"a":3,"e":"平静呼吸时，吸气末和呼气末气流暂停，肺内压与大气压相等。吸气中和呼气中因胸廓与肺容积变化，肺内压分别低于和高于大气压，形成进出气动力，故这两个时相肺内压不等于大气压"},{"q":"血液中的I-向甲状腺滤泡细胞内转运的方式是","o":["单纯扩散","载体易化扩散","继发性主动转运","原发性主动转运","入胞"],"a":2,"e":"甲状腺滤泡细胞通过Na+-I-同向转运体，借助Na+浓度梯度将I-逆浓度差转入细胞内，属继发性主动转运，可被哇巴因间接抑制。单纯扩散（A项）不耗能、顺浓度差；载体易化扩散（B项）不逆浓度；原发性主动转运（D项）直接水解ATP，如钠泵；入胞（E项）转运大分子颗粒，均与I-的小分子逆浓度转运不符"},{"q":"促胃液素不具有的作用是","o":["促进胃酸分泌","促进胃蛋白酶原分泌","抑制胆囊收缩","促进胃的蠕动","刺激小肠黏膜组织的生长"],"a":2,"e":"促胃液素可促进胃酸与胃蛋白酶原分泌、增强胃蠕动并刺激胃肠黏膜生长。它对胆囊的作用是促进胆囊收缩而非抑制，与缩胆囊素类似；因此抑制胆囊收缩不是促胃液素的作用，其余各项均为其生理作用"},{"q":"髓袢升支粗段对钠离子、氯离子和钾离子主动重吸收的比例是","o":["2∶1∶1","1∶2∶1","1∶1∶1","1∶1∶2","3∶2∶1"],"a":1,"e":"髓袢升支粗段顶端膜的Na+-K+-2Cl-共转运体按1个Na+、2个Cl-、1个K+的比例同向重吸收，故比例为1∶2∶1。该段对水不通透，造成小管液低渗和髓质高渗，是尿液浓缩稀释的关键，2∶1∶1等比例均与转运体化学计量不符"},{"q":"下列有关平静呼吸与用力呼吸的描述，正确的是","o":["平静呼吸过程中，吸气和呼气均为主动过程","斜角肌和胸锁乳突肌也作为吸气肌参与平静吸气过程","平静呼气时，膈肌和肋间外肌舒张","膈肌和肋间外肌作为呼气肌参与呼吸过程","用力呼吸时，呼吸加深但频率不变"],"a":2,"e":"平静呼吸时吸气由膈肌和肋间外肌收缩主动完成，呼气靠这些肌舒张、肺弹性回缩被动实现，故平静呼气时膈肌与肋间外肌舒张正确。斜角肌和胸锁乳突肌仅在用力吸气时参与；膈肌和肋间外肌属吸气肌而非呼气肌；用力呼吸时呼吸加深同时频率也改变"},{"q":"临床上多胎妊娠主要的因素是","o":["初级卵泡生长停滞","窦状卵泡生长过快","优势卵泡选择机制异常","垂体分泌卵泡刺激素减少","下丘脑分泌GnRH减少"],"a":2,"e":"正常情况下每个月经周期只有一个优势卵泡发育成熟并排卵，若优势卵泡选择机制异常，多个卵泡同时发育排卵，易发生多胎妊娠。A项初级卵泡生长停滞致发育障碍；B项窦状卵泡生长过快并非多胎主因；D项FSH分泌减少、E项GnRH减少均抑制卵泡发育，不利于多卵泡成熟"},{"q":"血清与血浆的最主要区别在于血清缺乏","o":["纤维蛋白","纤维蛋白原","凝血酶","血小板","凝血因子"],"a":1,"e":"血液凝固后析出淡黄色透明液体即为血清，凝血过程中纤维蛋白原已转变为纤维蛋白并随血块除去，故血清缺乏纤维蛋白原，这是其与血浆最主要的区别。纤维蛋白是凝块成分而非血浆原有蛋白；凝血酶、血小板及多种凝血因子也可有差别，但最本质的缺失是纤维蛋白原"},{"q":"前庭器官的静纤毛向动纤毛一侧弯曲或偏转时","o":["毛细胞膜去极化，传入神经纤维放电频率增高","毛细胞膜超极化，传入神经纤维放电频率降低","毛细胞膜去极化，传入神经纤维放电幅度增高","毛细胞膜超极化，传入神经纤维放电幅度降低","毛细胞膜去极化，传入神经纤维放电频率降低"],"a":0,"e":"前庭毛细胞的静纤毛向动纤毛一侧弯曲时，机械门控阳离子通道开放，K+内流使毛细胞膜去极化，进而使传入神经纤维放电频率增高。该弯曲引起的是去极化而非超极化；感受器电位以频率编码，动作电位幅度相对恒定，不因刺激增强而增高，故放电幅度增高的说法错误"},{"q":"如果窦房结突然停止起搏，最先恢复起搏的部位是","o":["心房肌","心室肌","房室结","房室束","浦肯野细胞"],"a":2,"e":"心脏潜在起搏点的自律性高低依次为窦房结、房室结、房室束、浦肯野细胞。窦房结停止起搏后，自律性次高的房室结最先恢复起搏并控制心律。心房肌、心室肌无自律性，浦肯野细胞自律性最低，均不可能最先起搏"},{"q":"应用阿托品后可出现的生理活动改变是","o":["心率减慢","气道阻力增加","闭汗","肠蠕动增加","缩瞳"],"a":2,"e":"阿托品阻断M胆碱受体，抑制汗腺即交感胆碱能支配的分泌，导致闭汗、皮肤干燥。A项心率应加快而非减慢；B项气道阻力因支气管舒张、分泌减少而降低；D项肠蠕动减弱而非增加；E项瞳孔散大而非缩小，这些都是阿托品阻断M受体后的相反效应"},{"q":"青春期男性第二性征的表现不包括","o":["骨骼粗壮","肌肉发达","体态丰满","喉结出现","声音变粗"],"a":2,"e":"青春期男性在雄激素作用下骨骼粗壮、肌肉发达、喉结突出、声音变粗，属男性第二性征。体态丰满是雌激素作用下女性第二性征的表现，脂肪沉积于臀、胸等处，男性一般不出现；其余四项均为雄激素促进蛋白质合成与喉部发育的结果"},{"q":"以下按研究器官、系统划分的生理学科为","o":["植物生理学","人体生理学","电生理学","高原生理学","心血管生理学"],"a":4,"e":"心血管生理学按研究的器官、系统划分，属器官系统生理学范畴。人体生理学按研究对象整体划分；电生理学按研究方法划分；高原生理学按特殊环境划分；植物生理学按生物类别划分，均非按器官系统划分"},{"q":"凝血因子FⅧ的作用是","o":["激活FⅨ","使FⅩa对FⅡ的激活加快","使FⅨa对FⅩ的激活加快","使FⅡa对FⅠ的激活加快","使FⅨ活化成FⅨa的速度加快"],"a":2,"e":"FⅧ活化后作为辅因子，与FⅨa、Ca2+及血小板磷脂表面组成复合物，显著加快FⅨa对FⅩ的激活，参与内源性凝血。FⅨ的激活由FⅪa完成；FⅩa对FⅡ（凝血酶原）的激活由FⅤa辅助；FⅡa对FⅠ（纤维蛋白原）的激活无需FⅧ参与"},{"q":"下列哪项不是糖皮质激素的生理作用","o":["使血中嗜酸性粒细胞增加","促进肝外蛋白质分解","促进四肢脂肪分解","增强机体对有害刺激的耐受力","增加胃酸和胃蛋白酶的分泌"],"a":0,"e":"糖皮质激素使外周血嗜酸性粒细胞和淋巴细胞减少，故使血中嗜酸性粒细胞增加一项不属于其作用。促进肝外蛋白质分解、促进四肢脂肪分解、增强机体对有害刺激的耐受力、增加胃酸和胃蛋白酶分泌均为糖皮质激素的生理作用"},{"q":"在神经纤维发生动作电位期间，按照下图中的箭头所示给予一次阈上刺激后，会发生的情况是","o":["出现较小幅度的动作电位","出现正常幅度的动作电位","延迟发生动作电位","不会发生动作电位","出现局部电位"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。动作电位期间膜上钠通道处于失活状态，细胞处于绝对不应期，此时无论给予阈上刺激都不会爆发新的动作电位。若刺激落在相对不应期且强度足够，可产生幅度较小的动作电位；完全恢复后刺激才出现正常幅度动作电位。局部电位由阈下刺激引起，不形成动作电位\n\n官方题库中缺失图片"},{"q":"抑制抗利尿激素释放的主要原因是","o":["血浆晶体渗透压增加","大量出汗","情绪紧张","大量饮水","血浆胶体渗透压升高"],"a":3,"e":"大量饮水使血浆晶体渗透压降低，渗透压感受器兴奋性下降，神经垂体抗利尿激素释放减少，尿量增多，称水利尿。血浆晶体渗透压增加（A项）、大量出汗（B项）、情绪紧张（C项）均促进ADH释放；血浆胶体渗透压升高（E项）主要影响组织液回流，不是ADH的主要调节因素"},{"q":"降钙素的主要作用是","o":["升高血钙和血磷","降低血钙和血磷","降低血钙，升高血磷","升高血钙，降低血磷","主要参与正常血钙的调节"],"a":1,"e":"降钙素抑制破骨细胞活动、减少骨钙释放，同时抑制肾小管重吸收钙和磷，使血钙、血磷均降低。升高血钙的是甲状旁腺激素和维生素D；PTH升血钙而降低血磷，与降钙素的作用方向不同。降钙素由甲状腺C细胞分泌，血钙升高时释放增多"},{"q":"关于动脉脉搏的描述，正确的是","o":["动脉脉搏图记录的是外周肱动脉的脉搏波形图","射血速度加快时，脉搏图波形上升支变平坦","主动脉瓣关闭不全患者脉搏图波性较正常人波形平缓","外周阻力增大或心输出量增多时，降中峡位置降低","老年人动脉脉搏图的每个波形所占的时间要比青年人的长"],"a":4,"e":"动脉脉搏波每个波形历时取决于心动周期，老年人心率偏慢且动脉弹性减退，单个波形所占时间较青年人长。脉搏图常记录颈动脉等大动脉而非肱动脉；射血速度加快时上升支变陡而非平坦；主动脉瓣关闭不全者上升支高陡；外周阻力增大时降中峡升高而非降低"},{"q":"能较好评价肺通气功能的指标是","o":["潮气量","补呼气量","余气量","用力肺活量","功能余气量"],"a":3,"e":"用力肺活量结合时间因素（如第一秒用力呼气量及其比值）能动态反映气道通畅程度，是评价肺通气功能的较好指标。A项潮气量、B项补呼气量、C项余气量、E项功能余气量仅为静态肺容量指标，受呼吸深浅影响大，不能敏感反映通气障碍，均不如用力肺活量"},{"q":"医学生在生理学实验中经静脉给家兔注射25%葡萄糖2ml，随后观察到尿量明显增加，其原因是","o":["血管升压素分泌减少","肾小球滤过率增加","肾血浆晶体渗透压增高","肾血流量增多","肾小管液溶质浓度增高"],"a":4,"e":"静脉注射高浓度葡萄糖使血糖超过肾糖阈，葡萄糖进入小管液后不能被完全重吸收，小管液溶质浓度升高产生渗透性利尿，尿量明显增加。血管升压素分泌减少并非主要原因；肾小球滤过率与肾血流量无明显增加；肾血浆晶体渗透压增高也不是本实验的机制，关键在于肾小管腔内溶质浓度"},{"q":"葡萄糖或氨基酸逆浓度梯度跨细胞膜转运的方式是","o":["单纯扩散","经载体易化扩散","经通道易化扩散","原发性主动转运","继发性主动转运"],"a":4,"e":"葡萄糖与氨基酸逆浓度梯度跨膜转运依赖Na+耦合的继发性主动转运，载体利用钠泵建立的Na+浓度势能，将物质与Na+同向转运入细胞。D项原发性主动转运直接消耗ATP并逆梯度转运如钠泵本身；B、C项易化扩散顺浓度梯度不耗能；A项单纯扩散仅限脂溶性小分子，都不能解释逆梯度转运"},{"q":"脊髓灰质炎患者出现肢体肌肉萎缩的主要原因是","o":["失去神经冲动的影响","因肌肉瘫痪使血供减少所致","肌肉受到病毒的侵害","失去了运动神经的营养作用","失去了神经营养因子的作用"],"a":3,"e":"脊髓灰质炎病毒破坏脊髓前角运动神经元，骨骼肌失去运动神经末梢的营养性作用，出现去神经性萎缩，这是主要原因。失去神经冲动影响（A项）导致瘫痪但非萎缩主因；血供减少（B项）、病毒直接侵害肌肉（C项）不是主要机制；神经营养因子（E项）表述笼统，教材强调运动神经的营养作用"},{"q":"孕妇使用PGE2易导致流产，主要原因是由于","o":["PGE2会增加子宫收缩","PGE2会增加胎盘主动脉收缩","PGE2可以刺激催产素的释放","PGE2可以增加孕酮的分泌","PGE2可以增加雌激素的分泌"],"a":0,"e":"PGE2能直接兴奋子宫平滑肌，增强子宫收缩的幅度和频率，临床用于催产引产，妊娠期使用易诱发流产。刺激催产素释放并非其主要途径。增加孕酮分泌会抑制子宫收缩、安胎，与流产效应相反；PGE2对胎盘主动脉收缩、雌激素分泌亦非导致流产的机制"},{"q":"长期使用糖皮质激素治疗，停药时应注意","o":["检查患者血细胞","检查胃黏膜有无损伤","补充蛋白质","逐渐减量停药","避免各种伤害性刺激"],"a":3,"e":"长期应用糖皮质激素经负反馈抑制下丘脑-垂体-肾上腺皮质轴，使肾上腺皮质萎缩、内源性激素分泌不足，突然停药可致肾上腺皮质功能不全，故须逐渐减量停药。检查血细胞、胃黏膜、补充蛋白质、避免伤害性刺激均为辅助措施，非停药关键"},{"q":"心血管的基本中枢位于","o":["脊髓","延髓","中脑","下丘脑","大脑"],"a":1,"e":"调节心血管活动的基本中枢位于延髓，包括心迷走中枢、心交感和交感缩血管中枢，整合压力感受器等传入信息以维持血压稳定。A项脊髓有低级心血管反射中枢；C项中脑、D项下丘脑、E项大脑为较高级中枢，对心血管活动起调节整合作用，但基本中枢在延髓"},{"q":"关于Na＋泵生理作用的描述，不正确的是","o":["产生内向电流","将Na＋移出膜外，将K＋移入膜内","建立势能储备","细胞外高Na＋可维持细胞内外正常渗透压","细胞内高K＋可保证细胞代谢反应的正常进行"],"a":0,"e":"钠泵每水解1个ATP泵出3个Na+、泵入2个K+，净移出1个正电荷，形成外向电流而非内向电流，故产生内向电流一项不正确。泵活动建立Na+势能储备，为继发性主动转运供能；细胞外高Na+维持细胞内外渗透压，细胞内高K+是胞质代谢酶活性的保证，这些均为钠泵的生理作用"},{"q":"心电图中可以看到的变化是","o":["窦房结去极化","窦房结复极化","心房肌去极化","房室结去极化","房室束去极化"],"a":2,"e":"心电图记录的是体表可检测到的心脏综合电活动，心房肌去极化形成P波，可在心电图上观察到。窦房结和房室结去极化电位太小，体表无法记录；房室束去极化也被淹没在复杂的综合波中，不能单独辨认。故能直接看到的变化是心房肌去极化产生的波形"},{"q":"血红蛋白水平为10g/100ml血液，其携氧能力约为","o":["10mlO2 /100ml血液","13mlO2 /100ml血液","16mlO2 /100ml血液","20mlO2 /100ml血液","25mlO2 /100ml血液"],"a":1,"e":"每克血红蛋白可结合约1.34ml O2，血红蛋白10g/100ml血液时携氧能力约为13ml O2/100ml血液。10ml（A项）数值偏低；16ml（C项）约为正常血红蛋白15g时的水平；20ml（D项）、25ml（E项）明显过高，均与按血红蛋白浓度换算的结果不符"},{"q":"胆碱能M型受体存在于","o":["所有副交感节后纤维支配的效应器上","神经-肌接头的后膜上","交感、副交感神经节细胞的突触后膜上","所有副交感神经节后纤维支配的效应器上及汗腺、骨骼肌血管上","大多数副交感神经节后纤维支配的效应器上及汗腺、骨骼肌血管上"],"a":4,"e":"毒蕈碱型（M）受体分布于大多数副交感节后纤维支配的效应器，以及支配汗腺和骨骼肌血管的交感胆碱能纤维所支配的组织。少数副交感节后纤维为非胆碱能，故不能用“所有”；神经-肌接头后膜为N2受体，交感和副交感神经节突触后膜为N1受体，均非M受体分布部位"},{"q":"急性和慢性肾脏损伤时，尿中可出现白蛋白，称白蛋白尿，其出现的原因是","o":["大量的白蛋白从肾小球滤过膜滤过到肾小管","近端小管对白蛋白的重吸收明显减少","远端小管和集合管分泌白蛋白的量明显增加","钠离子主动重吸收障碍，导致其他物质的协同转运降低，包括白蛋白","白蛋白在集合管的重吸收减少"],"a":0,"e":"急慢性肾损伤时肾小球滤过膜受损、通透性增加，大量白蛋白从滤过膜滤入肾小管，超过近端小管重吸收能力，随尿排出形成白蛋白尿。近端小管重吸收明显减少（B项）不是原发原因；远端小管和集合管分泌白蛋白（C项）不存在；钠协同转运障碍（D项）与白蛋白无关；集合管重吸收减少（E项）非主要机制"},{"q":"在下列组织中，代谢产热功能最强的是","o":["心肌","骨骼肌","平滑肌","脑","褐色脂肪组织"],"a":4,"e":"褐色脂肪组织富含线粒体和解偶联蛋白UCP1，使氧化磷酸化解偶联，能量直接以热能释放，代谢产热功能最强，是新生儿及寒冷适应中非战栗产热的主要组织。A项心肌、B项骨骼肌、C项平滑肌、D项脑虽也产热，但以做功、维持张力或基础代谢为主，产热强度与专门程度均不及褐色脂肪组织"},{"q":"下列有关交感神经系统的描述，不正确的是","o":["交感神经分布广泛","交感节前纤维往往和多个节内神经元发生突触联系","交感神经系统可促使机体适应环境的急变","交感神经系统可使肝糖原分解加速","交感神经系统的意义主要在于保护机体、休整恢复"],"a":4,"e":"交感神经系统分布广泛，节前纤维与多个节内神经元联系，兴奋时促使机体适应环境急变并加速肝糖原分解；保护机体、休整恢复是副交感神经系统的意义，故该描述不正确。A项分布广、B项辐散式联系、C项适应急变、D项促进肝糖原分解均为交感神经的正确特征"},{"q":"传入侧支性抑制和回返性抑制均属于","o":["突触前抑制","突触后抑制","外周性抑制","负反馈抑制","交互性抑制"],"a":1,"e":"传入侧支性抑制与回返性抑制均通过抑制性中间神经元释放抑制性递质，在突触后膜产生抑制性突触后电位，故同属突触后抑制。A项突触前抑制通过轴突-轴突突触减少递质释放，不直接产生突触后电位；C项外周性抑制发生于外周神经；D项负反馈仅描述回返性抑制；E项交互性抑制仅指传入侧支性抑制，均不能涵盖两者"},{"q":"下列关于食管下括约肌的叙述，正确的是","o":["由环行肌增厚而形成","括约肌部位压力低于胃内压","主要受激素调节而不受神经调节","血管活性肠肽引起括约肌紧张","功能障碍与反流性食管炎有关"],"a":4,"e":"食管下括约肌功能障碍，如压力降低或一过性松弛增多，使胃内容物反流，与反流性食管炎密切相关。LES在解剖上并无明显环行肌增厚形成的括约肌；其静息压高于胃内压；受神经与激素共同调节而非仅激素；血管活性肠肽使LES舒张而非紧张"},{"q":"γ-运动神经元的机能是","o":["使梭外肌兴奋收缩","降低肌梭的敏感性","使梭内肌收缩","使梭内肌弛缓","使梭外肌弛缓"],"a":2,"e":"γ运动神经元支配肌梭内的梭内肌纤维，兴奋时使梭内肌两端收缩，提高肌梭对牵拉刺激的敏感性，参与肌紧张的调节。支配梭外肌收缩的是α运动神经元；γ神经元兴奋而非降低肌梭敏感性，也不会使梭内肌或梭外肌弛缓"},{"q":"压力感受性反射的生理意义是","o":["减慢心率","增加冠脉血流量","降低平均动脉压","重新分配各器官血流量","稳定快速波动的血压"],"a":4,"e":"压力感受性反射对快速变化的血压起缓冲作用，使动脉血压在体位改变、运动等情况下保持相对稳定，主要调节短期波动，对长期血压调节作用有限。减慢心率与降低平均动脉压是其效应之一，但不是最主要的生理意义；增加冠脉血流和重新分配器官血流也不是该反射的核心意义"},{"q":"临床上给患者补液时，容易被遗漏计入的体液丢失部分是","o":["腹泻","呕吐","不感蒸发","尿多","发汗"],"a":2,"e":"不感蒸发持续不断地从皮肤和呼吸道散失水分，不被察觉且无明显感觉，临床补液时最易遗漏计入。腹泻、呕吐、尿多、发汗的丢失量较明显、易被察觉和评估，故不易被遗漏"},{"q":"下列哪项不属于胆汁的作用","o":["分解脂肪","乳化脂肪","促进脂肪吸收","刺激胆汁分泌","中和进入十二指肠内的胃酸"],"a":0,"e":"胆汁不含消化酶，不能分解脂肪；其作用为乳化脂肪、促进脂肪及脂溶性维生素吸收、刺激胆汁分泌、中和进入十二指肠的胃酸。分解脂肪是胰脂肪酶等的作用，不属于胆汁作用，故为答案。乳化、促进吸收、刺激胆汁分泌、中和胃酸均为胆汁的正常生理作用"},{"q":"下列关于突触前抑制特点的描述，正确的是","o":["以树突-树突式突触为结构基础","多见于运动传出通路中","潜伏期和持续时间均较长","因突触前膜发生超极化而产生","意义在于使神经元的活动及时终止"],"a":2,"e":"突触前抑制经轴突-轴突式突触、由中间神经元中介，属多突触活动，故潜伏期和持续时间均较长。其结构基础为轴突-轴突式突触而非树突-树突式；多见于感觉传入通路而非运动传出通路；由突触前膜去极化使递质释放减少所致，意义在于调控感觉传入而非使活动及时终止"},{"q":"下列哪项不是甲状腺激素的作用","o":["分泌过多时，蛋白质合成增加","提高神经系统的兴奋性","促进骨骼和脑的生长发育","使心跳加快加强","生理剂量可以促进蛋白质合成"],"a":0,"e":"甲状腺激素生理剂量促进蛋白质合成，但分泌过多时转为促进蛋白质分解，致肌肉消瘦、骨质疏松，故分泌过多时蛋白质合成增加一项错误。提高神经系统兴奋性、促进骨骼与脑发育、使心跳加快加强均属其生理作用；生理剂量促进蛋白质合成的表述正确"},{"q":"下列因素可导致脑血管舒张的是","o":["平均动脉压下降","H+浓度下降","CO2分压降低","腺苷生成减少","K+通道激活"],"a":4,"e":"脑血管平滑肌K+通道激活使膜超极化、电压门控Ca2+通道关闭，Ca2+内流减少，血管因而舒张。B项H+浓度下降与C项CO2分压降低均使脑血管收缩，二者升高才引起舒张；D项腺苷为舒血管代谢产物，生成减少会减弱舒张；A项平均动脉压下降主要通过自身调节改变阻力，并非K+通道介导的直接舒张"},{"q":"肺活量等于","o":["潮气量＋补吸气量","潮气量＋补呼气量","潮气量＋补吸气量＋补呼气量","潮气量＋功能余气量","余气量＋补吸气量"],"a":2,"e":"肺活量是尽力吸气后从肺内所能呼出的最大气体量，等于潮气量、补吸气量与补呼气量之和，反映肺一次通气的最大能力。潮气量加补吸气量（A项）为深吸气量；潮气量加补呼气量（B项）未计入补吸气量；潮气量加功能余气量（D项）、余气量加补吸气量（E项）均非肺活量的组成"},{"q":"以下不属于本能行为的活动是","o":["咳嗽反射","饮水","摄食","性行为","睡眠"],"a":0,"e":"本能行为为先天遗传、种属特异的行为模式，如摄食、饮水、性行为和睡眠。咳嗽反射是保护性防御反射，由刺激感受器引起，不属本能行为范畴"},{"q":"下列关于Na+-K+泵的描述，错误的是","o":["仅分布在可兴奋细胞的细胞膜上","是一种镶嵌在细胞膜上的蛋白质","能分解ATP获能","活动增强时使细胞静息膜电位增大","能将Na+移出细胞外，将K+移入细胞内"],"a":0,"e":"Na+-K+泵普遍存在于几乎所有细胞的细胞膜上，并非仅可兴奋细胞所有，故该项错误。B项它是镶嵌于膜的蛋白质、C项分解ATP获能、D项活动增强使膜超极化（静息电位增大）、E项将Na+移出、K+移入均为钠泵的正确描述，其对维持渗透压和静息电位至关重要"},{"q":"血液如果储存时间较长，可引起氧解离曲线由正常位置左移的原因是","o":["二氧化碳分压降低","2，3-DPG浓度降低","pH升高","温度降低","吸入气中CO含量增加"],"a":1,"e":"血液储存过久时，红细胞内2,3-DPG含量逐渐降低，使血红蛋白对氧的亲和力增高，氧解离曲线左移。CO2分压降低、pH升高、温度降低确可使曲线左移，但储存血中这些条件并非主要变化；吸入气CO增加生成碳氧血红蛋白，虽影响携氧，但不是库存血曲线左移的原因"},{"q":"下列关于淋巴回流意义的描述，错误的是","o":["回收蛋白质","调节血管内外水分交换","回收部分组织液","清除细菌","运输被吸收的脂质"],"a":1,"e":"淋巴回流可回收组织液中的蛋白质、带走部分组织液及吸收的脂质，并清除细菌等异物，是组织液回流的重要补充。调节血管内外水分交换（错误项）主要依靠毛细血管血压与血浆胶体渗透压构成的Starling力量，并非淋巴回流的功能。回收蛋白质（A项）、回收部分组织液（C项）、清除细菌（D项）、运输脂质（E项）均为淋巴回流的确实作用"},{"q":"激素传递的方式不包括","o":["血液运送","经组织液扩散","神经轴浆运输","经腺体导管分泌","自分泌"],"a":3,"e":"激素由内分泌腺或内分泌细胞分泌，不经导管，其传递方式包括远距分泌（血液运送）、旁分泌（组织液扩散）、神经分泌（下丘脑轴浆运输）以及自分泌。经腺体导管分泌是外分泌腺的特征，如消化腺、汗腺，不属于激素传递方式。C项神经轴浆运输见于下丘脑神经内分泌细胞；E项自分泌为局部反馈调节"},{"q":"引起生长激素分泌作用最强的因素是","o":["高血糖","低血糖","高血脂","低血脂","血中氨基酸浓度增高"],"a":1,"e":"低血糖是引起生长激素分泌最强的刺激因素，血糖下降可迅速兴奋腺垂体促生长细胞释放GH，升高血糖；此外睡眠、运动、应激和血中氨基酸升高也可促进分泌。高血糖（A项）抑制GH分泌；高血脂（C项）、低血脂（D项）影响较小；血中氨基酸增高（E项）有促进作用但不及低血糖"},{"q":"能促进ACTH分泌的下丘脑调节肽是","o":["TRH","GnRH","GHRH","CRH","PRF"],"a":3,"e":"促肾上腺皮质激素释放激素（CRH）由下丘脑分泌，作用于腺垂体促肾上腺皮质激素细胞，促进ACTH合成与释放。A项TRH促进TSH和催乳素；B项GnRH促进FSH、LH；C项GHRH促进生长激素；E项PRF促进催乳素分泌，均不主要促进ACTH"},{"q":"甲状腺激素对靶细胞的作用，是通过下列哪个信息传递途径而产生的","o":["cAMP-PKA系统","三磷酸肌醇/二酰甘油-蛋白激酶C系统","cGMP-PKG系统","PG的介导","进入核内调控DNA转录"],"a":4,"e":"甲状腺激素为脂溶性含碘氨基酸衍生物，可进入细胞核与核受体结合，调控靶基因转录而发挥作用。cAMP-PKA系统、IP3/DAG-PKC系统、cGMP-PKG系统均为含氮激素经膜受体与第二信使发挥作用的途径；前列腺素介导也属局部化学信号，均不是甲状腺激素的主要作用方式"},{"q":"下列哪项属于雌激素的生理作用","o":["促进破骨细胞活动","刺激血管平滑肌增殖","促进神经细胞生长","降低高密度脂蛋白浓度","降低肾小管对Na+、水重吸收"],"a":2,"e":"雌激素可促进神经细胞生长、发育与突触形成，对中枢神经系统有保护作用。A项促进破骨细胞活动与事实相反，雌激素抑制破骨细胞、减少骨吸收；B项刺激血管平滑肌增殖亦相反，雌激素抑制平滑肌增殖、保护血管；D项降低高密度脂蛋白错误，雌激素升高HDL；E项降低肾小管Na+、水重吸收错误，雌激素促进其重吸收"},{"q":"关于消化道运动作用的描述，下列说法错误的是","o":["磨碎食物","使食物与消化液充分混合","使食物大分子水解成小分子","向消化道远端推送食物","和化学性消化同时进行"],"a":2,"e":"消化道运动（机械性消化）的作用是磨碎食物、使食物与消化液充分混合、向远端推送，并与化学性消化同时进行。使食物大分子水解成小分子属于化学性消化，靠消化酶完成，而非运动作用，故该项错误。A项磨碎、B项混合、D项推送、E项与化学消化同时进行均为运动的正常作用"},{"q":"下列关于胰岛激素相互作用的叙述，错误的是","o":["胰岛素抑制胰高血糖素的分泌","胰高血糖素抑制胰岛素的分泌","生长抑素抑制胰高血糖素的分泌","促胰液素、抑胃肽促进胰岛素分泌","生长抑素抑制胰岛素的分泌"],"a":1,"e":"胰高血糖素可升高血糖并直接刺激胰岛B细胞，促进胰岛素分泌，而非抑制，故该项错误。胰岛素抑制胰高血糖素（A项）、生长抑素抑制胰高血糖素与胰岛素（C、E项）、促胰液素与抑胃肽促进胰岛素分泌（D项）均为正确的相互作用"},{"q":"下列哪项不是血浆蛋白的主要功能","o":["运输物质","参与机体的免疫","缓冲pH值","参与生理止血","维持血浆晶体渗透压"],"a":4,"e":"血浆晶体渗透压主要由Na＋、Cl-等小分子电解质形成，与血浆蛋白无关，故该项不是血浆蛋白的功能。血浆蛋白可结合运输激素、胆红素等物质；免疫球蛋白参与机体免疫；纤维蛋白原等参与生理止血；白蛋白是维持血浆胶体渗透压的主要成分，注意与晶体渗透压区分"},{"q":"细胞内能使蛋白质磷酸化的酶是","o":["磷脂酶C","蛋白激酶","磷酸二酯酶","乙酰胆碱酯酶","蛋白磷酸酶"],"a":1,"e":"蛋白激酶催化ATP的磷酸基转移到蛋白质特定氨基酸残基上，使蛋白质磷酸化并改变其活性，是信号转导中重要的酶。磷脂酶C水解磷脂生成IP3和DAG；磷酸二酯酶降解环核苷酸；乙酰胆碱酯酶水解ACh；蛋白磷酸酶则催化去磷酸化，作用相反"},{"q":"下列属于快适应感受器的是","o":["肌梭","关节囊感受器","环层小体","颈动脉体化学感受器","颈动脉窦压力感受器"],"a":2,"e":"环层小体（帕氏小体）是典型的快适应感受器，对皮肤压觉和振动觉敏感，刺激持续时传入冲动迅速减少，利于感受变化。肌梭（A项）、关节囊感受器（B项）、颈动脉体化学感受器（C项）、颈动脉窦压力感受器（E项）均为慢适应感受器，持续刺激下仍保持发放，与环层小体不同"},{"q":"肌梭感受器的适宜刺激是","o":["梭外肌收缩","梭外肌松弛","梭外肌受牵拉","梭内肌紧张性降低","梭内肌受压迫"],"a":2,"e":"肌梭与梭外肌纤维平行排列，其适宜刺激是梭外肌受牵拉而被拉长，感受肌肉长度变化，引发牵张反射。A项梭外肌收缩时肌梭随之缩短、张力解除，传入减少；B项梭外肌松弛使肌梭传入减少；D项梭内肌紧张性降低与E项梭内肌受压迫均非引起肌梭兴奋的适宜刺激"},{"q":"近端小管重吸收的特点是","o":["重吸收的物质种类少","各种物质重吸收的量少","小管上皮管腔膜两侧电位差很大","是神经和体液因素调节的重要部位","小管液与上皮细胞内液体保持等渗"],"a":4,"e":"近端小管重吸收为等渗性重吸收，小管液与上皮细胞内液及管周液保持等渗。该段重吸收物质种类多、量大，管腔膜两侧电位差不大，且不是神经体液调节的主要部位，故相关选项均不符合其重吸收特点"},{"q":"有关继发性主动转运描述，下列选项正确的是","o":["顺着转运物质的浓度梯度进行转运","转运动力均来自于钠离子的跨膜浓度梯度","Na+-Ca2+交换体是Ca2+顺着浓度梯度运出细胞","Na+-H+交换体主要分布在胃黏膜上皮细胞顶端膜","甲状腺上皮细胞的钠-碘转运体属于同向转运体"],"a":4,"e":"甲状腺上皮细胞的钠-碘转运体将Na+与I-同向转入细胞，属同向转运体，是继发性主动转运的实例。继发性主动转运动力也可来自H+梯度，并非均为Na+梯度；Na+-Ca2+交换体为反向转运、Ca2+逆浓度排出；Na+-H+交换体主要分布于肾小管和小肠上皮，而非胃黏膜"},{"q":"下列关于胃黏液-碳酸氢盐屏障的叙述，错误的是","o":["与胃黏膜屏障是同一概念","由黏液及胃黏膜分泌的碳酸氢根组成","使胃黏膜表面处于中性或偏碱性状态","防止胃酸及胃蛋白酶对胃黏膜的侵蚀","保护胃黏膜免受食物的摩擦损伤"],"a":0,"e":"黏液-碳酸氢盐屏障由黏液和HCO3-构成，中和胃酸、隔离胃蛋白酶，并保护黏膜免受食物摩擦。胃黏膜屏障则指上皮细胞及其紧密连接构成的屏障，二者概念不同，故与胃黏膜屏障是同一概念一项错误。其余各项均为黏液-碳酸氢盐屏障的正确描述"},{"q":"食物的氧热价是指","o":["1g食物氧化时所释放的能量","1g食物燃烧时所释放的能量","食物氧化消耗1L氧气所释放的能量","氧化1g食物、消耗1L氧气时所释放的能量","食物氧化释放1L二氧化碳时所产生的能量"],"a":2,"e":"食物的氧热价指某种食物氧化分解时每消耗1升氧气所释放的能量，用于间接测定能量代谢率。1克食物氧化或燃烧释放的能量是食物的热价，与氧热价不同。物理热价是体外燃烧值，生物热价是体内氧化值，均与耗氧量无关，不能与氧热价混同"},{"q":"心室舒张功能障碍的患者","o":["舒张速率减慢，等容舒张期延长","舒张速率减慢，等容舒张期不变","舒张速率加快，等容舒张期延长","舒张速率减慢，等容舒张期缩短","舒张速率加快，等容舒张期缩短"],"a":0,"e":"心室舒张功能障碍时心肌主动舒张能力下降或顺应性降低，室内压下降速率减慢，等容舒张期因压力下降延迟而延长，充盈受限。等容舒张期不变、缩短或舒张速率加快均不符合舒张功能障碍的病理生理，加快见于舒张功能增强或正常情况下的代偿，而非障碍"},{"q":"经载体易化扩散的特点是","o":["逆浓度梯度转运","转运过程消耗生物能","是气体分子和类固醇激素的转运方式","转运物浓度越高，转运速度越快，呈线性增加","两种结构相似的物质同时转运时会发生竞争性抑制"],"a":4,"e":"经载体易化扩散依赖载体蛋白构象变化转运物质，结构相似的两种底物同时存在时会竞争同一载体，发生竞争性抑制，且存在饱和现象。A项逆浓度梯度、B项消耗生物能属主动转运；C项气体和类固醇激素以单纯扩散跨膜；D项呈线性增加错误，载体数量有限使速率达饱和后不再随浓度线性上升"},{"q":"促胃液素的主要作用是","o":["促进胃酸分泌","刺激胰液中碳酸氢盐分泌","促进胰液中胰酶分泌","促进胆汁分泌","促进胃蛋白酶分泌"],"a":0,"e":"促胃液素由胃窦G细胞分泌，主要作用是促进胃腺壁细胞分泌胃酸，并促进胃黏膜生长。B项刺激胰液碳酸氢盐分泌主要是促胰液素；C项促进胰酶分泌主要是缩胆囊素；D项促进胆汁分泌以促胰液素为主；E项胃蛋白酶分泌主要由迷走神经等促进，但促胃液素主要作用仍在胃酸"},{"q":"消化道平滑肌细胞动作电位产生的离子基础是","o":["K+内流","Na+内流","Ca2+内流","Ca2+与K+内流","Cl-的外流"],"a":2,"e":"消化道平滑肌动作电位的去极化主要由L型钙通道介导的Ca2+内流引起，复极化则由K+外流完成，与骨骼肌、神经以Na+内流去极化不同。B项Na+内流是神经纤维和骨骼肌动作电位上升支的基础；A项K+内流、E项Cl-外流均导致超极化而非去极化；D项把Ca2+与K+内流并列也不符合平滑肌电生理特点"},{"q":"大脑皮层功能一侧优势指的是","o":["一侧大脑半球神经元特别多","一侧大脑半球经常强烈兴奋","人类脑的语言功能向一侧半球集中的现象","人类脑的功能全部集中在一侧半球","人类脑的非语词性的认知功能向一侧半球集中的现象"],"a":2,"e":"大脑皮层功能一侧优势指人类语言功能向一侧半球集中，多数人为左侧半球优势，与遗传及用手习惯相关。它并非神经元数量或兴奋强度的差异，也不是全部脑功能集中于一侧；非语词性认知功能如空间知觉多由右半球承担，不属此概念内涵"},{"q":"当流经致密斑的小管液流量增加时，管-球反馈使得","o":["同一肾单位的肾小球滤过率下降","同一肾单位的肾小球血流量增加","肾素分泌增加","近端小管对水和溶质的重吸收减少","肾交感神经兴奋"],"a":0,"e":"流经致密斑的小管液流量及NaCl增加时，通过管-球反馈使入球小动脉收缩，同一肾单位的肾小球滤过率下降，从而稳定滤过负荷。此时肾素分泌受抑制而非增加，肾血流量减少而非增多；近端小管重吸收减少、肾交感神经兴奋并非管-球反馈的直接效应"},{"q":"Rh阴性母亲，怀第二胎Rh阳性胎儿时，胎儿最易发生的危险是","o":["血友病","白血病","红细胞增多症","新生儿溶血病","巨幼红细胞性贫血"],"a":3,"e":"Rh阴性母亲第一胎Rh阳性胎儿致敏产生抗D抗体，第二胎仍为Rh阳性时，抗体通过胎盘进入胎儿，破坏胎儿红细胞，引起新生儿溶血病。血友病（A项）为凝血因子缺乏的遗传病；白血病（B项）为造血系统恶性病；红细胞增多症（C项）、巨幼红细胞性贫血（E项）与Rh免疫无关"},{"q":"对机体产热活动影响最重要的体液因素是","o":["去甲肾上腺素","肾上腺素","甲状腺激素","甲状旁腺激素","生长激素"],"a":2,"e":"甲状腺激素能提高机体绝大多数组织的耗氧率和产热量，是调节产热最重要的体液因素。去甲肾上腺素、肾上腺素亦可促进产热但作用较次要；甲状旁腺激素调节钙磷代谢；生长激素促生长，均非产热的主要体液因素"},{"q":"下列哪种激素对儿茶酚胺心血管效应起允许作用","o":["甲状腺激素","生长激素","糖皮质激素","醛固酮","抗利尿激素"],"a":2,"e":"糖皮质激素本身对血管平滑肌无直接收缩作用，但能提高血管对儿茶酚胺的敏感性，缺乏时儿茶酚胺升压效应减弱，此即允许作用。A项甲状腺激素主要提高基础代谢与心率；B项生长激素、D项醛固酮、E项抗利尿激素均无典型的对儿茶酚胺的允许作用，只有糖皮质激素是经典的允许作用激素"},{"q":"某人的血浆中只含有抗A凝集素，则该人的血型不可能是","o":["A型","B型","O型","AB型","Rh型"],"a":0,"e":"血清中只含抗A凝集素者为B型，其红细胞带B抗原；A型个体红细胞带A抗原，血清中应为抗B凝集素，不可能含抗A，否则会凝集自身红细胞。O型血清含抗A和抗B；AB型血清不含凝集素；Rh型属另一血型系统，不影响ABO凝集素的判断"},{"q":"患者CO中毒后，血液运输氧的能力严重降低，这是因为","o":["CO降低Hb对O2的亲和力","CO使Hb分子结构向紧密型转变","CO使Hb分子中的Fe2＋氧化成了Fe3＋","CO与Hb亲和力远远高于O2，并妨碍O2与Hb的解离","CO使氧解离曲线右移"],"a":3,"e":"CO与血红蛋白的亲和力约为O2的210倍，结合后占据血红素位点使血红蛋白丧失携氧能力，并使其余结合位点对O2的亲和力异常增高、妨碍氧的解离释放，导致组织严重缺氧。CO并不降低而是异常增高Hb对O2的亲和力；使Fe2+氧化为Fe3+是高铁血红蛋白的变化；氧解离曲线左移而非右移"},{"q":"实现胃的容受性舒张的途径是","o":["交感神经","迷走神经末梢释放的乙酰胆碱","迷走神经末梢释放的血管活性肠肽","壁内神经释放的生长抑素","内分泌细胞释放促胃泌素"],"a":2,"e":"胃的容受性舒张由迷走神经介导，其末梢释放血管活性肠肽或NO，使胃底、胃体平滑肌舒张，以容纳大量食物。交感神经不参与此反射；迷走神经末梢释放乙酰胆碱引起收缩而非舒张；壁内生长抑素与促胃泌素主要抑制胃酸或刺激分泌，均非容受性舒张的递质机制"},{"q":"使肛门外括约肌开放的是","o":["腹下神经兴奋","迷走神经兴奋","盆神经兴奋","阴部神经抑制","交感神经抑制"],"a":3,"e":"肛门外括约肌为骨骼肌，受阴部神经躯体运动纤维支配，排便时阴部神经活动减弱（抑制），外括约肌舒张，肛门开放。A项腹下神经（交感）兴奋使内括约肌收缩；B项迷走神经主要支配上消化道；C项盆神经兴奋促进直肠收缩和内括约肌舒张，但外括约肌开放靠阴部神经抑制；E项交感抑制并非关键"},{"q":"刺激支配唾液腺的副交感神经，可引起","o":["量多、固体成分少的唾液分泌","量少、固体成分少的唾液分泌","量少、固体成分多的唾液分泌","量多、固体成分多的唾液分泌","唾液量不变"],"a":0,"e":"支配唾液腺的副交感神经兴奋时，末梢释放乙酰胆碱作用于M受体，引起血管舒张、分泌旺盛，产生量多而固体成分少的稀薄唾液，便于湿润与消化。量少固体成分多（C项）为交感兴奋的表现；量多固体成分多（D项）不符合任一神经兴奋特点；量少固体成分少（B项）与唾液分泌实际不符；唾液量不变（E项）错误"},{"q":"第一心音特点为","o":["在心尖搏动处听诊，音调较低，持续时间较长","在心尖搏动处听诊，音调较高，持续时间较短","在心尖搏动处听诊，音调较低，持续时间较短","在主动脉瓣听诊区听诊，音调较低，持续时间较长","在主动脉瓣听诊区听诊，音调较高，持续时间较短"],"a":0,"e":"第一心音由房室瓣关闭及心室肌收缩引起，在心尖搏动处听诊最清楚，音调较低、持续时间较长，标志心室收缩开始。音调较高、持续时间较短是第二心音的特点；第二心音在主动脉瓣或肺动脉瓣听诊区更清楚，标志心室舒张开始，故其余组合均不符合第一心音特征"},{"q":"特殊动力效应最为显著的食物是","o":["糖类","蛋白质","胆固醇","甘油三酯","混合性食物"],"a":1,"e":"食物的特殊动力效应指进食后额外增加的产热量，蛋白质最为显著，可达其本身热量的30%左右，源于氨基酸脱氨基等耗能过程。糖类和脂肪分别约为6%和4%，混合食物居中。D项甘油三酯即脂肪，产热效应最低；C项胆固醇不属主要供能营养素；E项混合性食物低于纯蛋白质，故均非最强"},{"q":"当细胞膜上的电压门控Ca2+通道开放增加后，细胞的膜电位","o":["将向钾离子的平衡电位移动","细胞膜内外电位差增大","将远离钠离子的平衡电位","将远离钙离子的平衡电位","将发生去极化"],"a":4,"e":"Ca2+平衡电位为正值，电压门控Ca2+通道开放使Ca2+内流，正电荷进入细胞，膜电位向钙平衡电位方向移动即发生去极化，膜内负电位减小。A项向K+平衡电位移动是K+外流的复极或超极化；B项膜内外电位差减小而非增大；C项实际是靠近钠平衡电位方向；D项应为靠近而非远离钙平衡电位"},{"q":"恒定强度的刺激持续作用于一个感受器时，其传入神经纤维上动作电位的频率逐渐降低，这一现象称为感受器的","o":["适宜刺激","换能作用","编码功能","适应现象","特异现象"],"a":3,"e":"恒定强度刺激持续作用时，感受器及传入纤维的动作电位频率逐渐下降，称为感受器的适应现象，与感受器及离子通道特性有关。A项适宜刺激指感受器最敏感的能量形式；B项换能作用指将刺激能量转为电信号；C项编码功能指以放电频率编码刺激信息；E项特异现象指对特定刺激敏感性高，均非该现象"},{"q":"对肾素-血管紧张素系统的描述，正确的是","o":["肾素由肾小球外系膜细胞合成和分泌","血浆中钠离子含量减少可刺激肾素分泌","肾素可转变血管紧张素Ⅰ为血管紧张素Ⅱ","血管紧张素Ⅱ主要刺激醛固酮分泌","血管紧张素Ⅲ主要使血管收缩"],"a":1,"e":"肾素-血管紧张素系统中，流经致密斑的小管液Na+减少可刺激球旁细胞分泌肾素，故该项正确。肾素由球旁细胞而非球外系膜细胞分泌；将血管紧张素Ⅰ转为Ⅱ的是血管紧张素转换酶；血管紧张素Ⅱ主要收缩血管并刺激醛固酮，血管紧张素Ⅲ才更突出刺激醛固酮、收缩作用弱"},{"q":"以下按研究对象所处的环境划分的生理学科为","o":["人体生理学","呼吸生理学","肾脏生理学","高原生理学","动物生理学"],"a":3,"e":"高原生理学以高原低氧等特殊环境条件下机体功能为研究对象，属按研究对象所处环境划分的分支学科。A项人体生理学、E项动物生理学按研究对象物种划分；B项呼吸生理学、C项肾脏生理学按器官系统划分；只有高原生理学体现环境维度的分类"},{"q":"去极化过程中，Na＋的电化学驱动力","o":["持续增大","持续减小","没有变化","先增大，后变小","先减小，后增大"],"a":1,"e":"去极化过程中膜电位由负值向Na+平衡电位靠近，Na+的电化学驱动力（膜电位与Na+平衡电位之差）持续减小，Na+内流随之减少，直至达到平衡电位时驱动力为零。持续增大（A项）、没有变化（C项）、先增大后变小（D项）、先减小后增大（E项）均不符合膜电位逼近平衡电位时驱动力递减的规律"},{"q":"肝素抗凝的主要机制是","o":["抑制凝血酶原的激活","抑制FⅩ的激活","促进纤维蛋白吸附凝血酶","增强抗凝血酶的活性","抑制血小板聚集"],"a":3,"e":"肝素主要通过与抗凝血酶Ⅲ结合并增强其活性，加速对凝血酶及FⅩa、FⅨa等活化凝血因子的灭活，从而发挥强大抗凝作用。它并不直接抑制凝血酶原或FⅩ的激活，也不通过促进纤维蛋白吸附凝血酶或抑制血小板聚集来实现抗凝"},{"q":"红细胞的主要功能是","o":["提供营养","缓冲H＋","运输激素","运输氧气和二氧化碳","运输铁"],"a":3,"e":"红细胞含血红蛋白，主要功能是运输氧气和二氧化碳，血红蛋白在肺结合氧、在组织释放氧，并将组织产生的CO2运至肺排出。提供营养（A项）为血浆功能；缓冲H+（B项）为血红蛋白次要作用；运输激素（C项）主要靠血浆；运输铁（E项）为转铁蛋白功能，均非红细胞主要功能"},{"q":"生活在高原地区的人，检测其血红蛋白氧饱和度达到90%以上，该地区的PO2大于","o":["60mmHg","70mmHg","80mmHg","90mmHg","100mmHg"],"a":0,"e":"氧解离曲线呈S形，当PO2达60mmHg时，血红蛋白氧饱和度约为90%，曲线在此后趋于平坦。故饱和度90%以上对应PO2大于60mmHg。70、80、90、100mmHg对应的饱和度更高，并非达到90%的临界值"},{"q":"影响人胚胎脑发育的关键激素是","o":["胰岛素","生长激素","肾上腺素","甲状腺激素","绒毛膜生长激素"],"a":3,"e":"甲状腺激素是胎儿和新生儿脑发育的关键激素，促进神经元增殖、分化、突触形成和髓鞘化，缺乏可致呆小症。A项胰岛素、B项生长激素、C项肾上腺素、E项绒毛膜生长激素主要调节代谢或躯体生长，对胚胎脑发育并非关键决定因素"},{"q":"关于唾液的描述，下列哪项是正确的","o":["进食时唾液分泌的调节不依赖于体液调节","唾液不能排泄汞","只有食物刺激口腔感受器才能刺激唾液分泌","唾液中的消化酶可以消化脂类物质","迷走神经促进唾液的分泌，但是交感神经抑制唾液的分泌"],"a":0,"e":"进食时唾液分泌主要通过条件反射和非条件反射的神经调节完成，基本不依赖体液调节。唾液可排泄汞等物质，故不能排泄汞错误；除食物刺激外，条件反射也能引起分泌；唾液淀粉酶只消化淀粉不消化脂类；交感与副交感神经兴奋均促进唾液分泌，只是性质和量不同"},{"q":"主动吸收胆盐和维生素B12的部位是","o":["十二指肠","回肠末端","空肠","结肠上段","结肠下段"],"a":1,"e":"回肠末端是胆盐和维生素B12主动吸收的特定部位，胆盐在此经Na+依赖性转运重吸收并参与肠肝循环，维生素B12与内因子结合后于回肠末端被摄取。A项十二指肠、C项空肠主要吸收铁、钙及多数营养物质，不主动吸收胆盐；D、E项结肠主要吸收水和电解质，无胆盐与B12的主动吸收功能"},{"q":"可不经细胞核受体介导调节靶细胞活动的激素是","o":["促甲状腺素","糖皮质激素","钙三醇","孕激素","睾酮"],"a":0,"e":"促甲状腺素为含氮激素，水溶性，与靶细胞膜受体结合后经第二信使途径发挥作用，无需细胞核受体介导。B项糖皮质激素、C项钙三醇（活性维生素D3）、D项孕激素、E项睾酮均为脂溶性类固醇激素，需与胞内（胞浆或核）受体结合、调控基因转录而起作用"},{"q":"兴奋通过神经-肌接头时，乙酰胆碱与受体结合使终板膜","o":["对钠、钾离子通透性增加，发生超极化","对钠、钾离子通透性增加，发生去极化","仅对钾离子通透性增加，发生超极化","仅对钙离子通透性增加，发生超极化","对乙酰胆碱通透性增加，发生超极化"],"a":1,"e":"乙酰胆碱与终板膜N2受体结合后，使终板膜对Na+与K+的通透性同时增加，因Na+内流占优势而出现去极化，形成终板电位。通透性增加并非超极化；仅对钾或仅对钙通透性增加、对乙酰胆碱通透性增加等说法均不符合终板膜离子通道的实际变化"},{"q":"贫血患者呼吸幅度和频率未见明显异常变化，主要是因为","o":["化学感受器的敏感性降低","血液PO2正常","血液pH值正常","血液氧含量正常","血液PCO2正常"],"a":1,"e":"外周化学感受器感受的是溶解氧分压而非氧含量，贫血时血红蛋白减少使氧含量下降，但动脉血PO2正常，故呼吸幅度和频率无明显变化。血液pH、PCO2正常并非主因；贫血时氧含量实际降低，故氧含量正常一说错误"},{"q":"血中氢离子浓度升高使呼吸运动增强，主要通过刺激下列哪一部位而实现","o":["延髓呼吸中枢","脑桥呼吸中枢","中枢化学敏感区","颈动脉体和主动脉体","颈动脉窦和主动脉弓"],"a":3,"e":"血中H+浓度升高时，H+不易通过血脑屏障，难以直接刺激中枢化学敏感区，主要兴奋颈动脉体和主动脉体等外周化学感受器，反射性增强呼吸。C项中枢化学敏感区主要感受CO2透过后生成的H+，对血液H+敏感性低；A项延髓呼吸中枢、B项脑桥呼吸中枢非直接化学感受部位；E项颈动脉窦主动脉弓为压力感受器"},{"q":"以下几个方面，哪个方面是动脉血压形成的必要条件","o":["足够的血液充盈","心脏射血","外周阻力","主动脉和大动脉的弹性贮器作用","循环血量与血管容积的比例"],"a":1,"e":"动脉血压形成的前提是循环系统有足够血液充盈，心脏射血为血液提供动能与势能，是形成血压的动力与必要条件。足够血液充盈（A项）为前提而非动力；外周阻力（C项）参与形成但非动力来源；大动脉弹性贮器（D项）维持舒张压；循环血量与血管容积比例（E项）决定充盈程度"},{"q":"血细胞比容主要指的是","o":["红细胞与血浆容积之比","红细胞与白细胞容积之比","血细胞在血液中所占的重量百分比","红细胞的容积","血细胞在血液中所占的容积百分比"],"a":4,"e":"血细胞比容指血细胞在全血中所占的容积百分比，因红细胞占绝大多数，临床常称红细胞比容，可反映红细胞数量与血液浓缩状态。A项红细胞与血浆容积之比非比容定义；B项红细胞与白细胞容积之比无意义；C项按重量百分比计算错误，比容按容积计；D项单纯红细胞容积未说明其在血液中所占比例"},{"q":"副交感神经兴奋可引起","o":["瞳孔扩大","糖原分解","胃肠运动增强","骨骼肌血管舒张","竖毛肌收缩"],"a":2,"e":"副交感神经兴奋时节后纤维释放乙酰胆碱，促进胃肠平滑肌收缩和消化液分泌，使胃肠运动增强。瞳孔扩大、糖原分解、骨骼肌血管舒张及竖毛肌收缩均为交感神经兴奋的效应，副交感兴奋时瞳孔缩小、糖原合成增加，与上述表现相反"},{"q":"有关脂肪的消化和吸收的叙述，正确的是","o":["胆盐能使脂肪水解","胆汁中含有脂肪酶，因而能分解脂肪","小肠内的脂肪小滴就是乳糜微粒","脂肪形成乳糜微粒转运至乳糜管","部分胆盐在十二指肠内吸收"],"a":3,"e":"脂肪消化产物被小肠上皮吸收后在细胞内重新合成甘油三酯，与载脂蛋白等形成乳糜微粒，经高尔基体释放进入乳糜管，故该叙述正确。A项胆盐只起乳化作用，水解脂肪的是胰脂肪酶；B项胆汁不含脂肪酶；C项脂肪小滴为乳化产物，乳糜微粒在上皮细胞内形成；E项胆盐主要在回肠末端重吸收，不在十二指肠"},{"q":"静脉注射20%葡萄糖50ml，尿量增加的主要原因是","o":["肾小管液溶质浓度增高","肾小球滤过率增高","有效滤过压增高","醛固酮分泌增加","血浆晶体渗透压增高"],"a":0,"e":"静注高浓度葡萄糖使血糖急剧升高，超过肾糖阈后葡萄糖不能被完全重吸收，小管液溶质浓度升高、渗透压增大，阻碍水的重吸收，产生渗透性利尿，尿量增加。B项滤过率增高、C项有效滤过压增高并非主因；D项醛固酮增加会保钠保水、减少尿量；E项血浆晶体渗透压增高刺激抗利尿激素释放，反使尿量减少"},{"q":"分娩前没有乳汁分泌，是因为","o":["血中催乳素浓度过低","乳腺细胞上催乳素受体的数目不足","缺乏缩宫素的刺激","血中雌激素和孕激素水平很高","催乳素释放因子分泌不足"],"a":3,"e":"妊娠期血中雌激素和孕激素水平很高，二者抑制乳腺的泌乳功能，虽有催乳素升高但不出现大量乳汁分泌；分娩后胎盘排出，雌孕激素骤降，乳汁开始分泌。血中催乳素浓度并不低，乳腺催乳素受体也非不足，缩宫素只负责排乳而非乳汁生成，催乳素释放因子不足并非原因"},{"q":"肾脏髓质渗透压梯度的维持主要靠","o":["小叶间动脉","髓袢","弓形动脉","弓形静脉","直小血管"],"a":4,"e":"肾髓质渗透压梯度的维持依赖直小血管的逆流交换，其在下行时失水、上行时重吸收溶质，避免梯度被血流带走。髓袢通过逆流倍增建立该梯度，而非维持；小叶间动脉、弓形动脉、弓形静脉不参与髓质高渗梯度的维持"},{"q":"体内交感-肾上腺髓质系统兴奋，心输出量增加是主要通过动用","o":["心率储备和收缩期储备","心率储备和舒张期储备","收缩期储备和舒张期储备","搏出量储备","舒张期储备"],"a":0,"e":"心交感兴奋和儿茶酚胺释放使心率加快、心肌收缩力增强，主要通过动用心率储备和收缩期储备（收缩末期容积减小、射血分数增加）来增加心输出量。B项舒张期储备、E项单纯舒张期储备并非主要途径；C项收缩期储备与舒张期储备组合、D项搏出量储备的表述均不如心率加收缩期储备准确"},{"q":"机体内温度最高的器官是","o":["脑","肝脏","肾脏","胰腺","十二指肠"],"a":1,"e":"肝脏代谢最为旺盛，是安静时机体产热最多的器官，其温度高于其他内脏。脑、肾、胰腺虽血流丰富、代谢活跃，但单位时间产热量与温度均不及肝脏；十二指肠属消化道，产热量更低，均非体内温度最高的器官"},{"q":"关于促肾上腺皮质激素的分泌，下列各项错误的是","o":["在应激状态下分泌增多","受下丘脑促肾上腺皮质激素释放激素的调节","受糖皮质激素的负反馈调节","受醛固酮的负反馈调节","长期大量使用糖皮质激素的患者，其分泌减少"],"a":3,"e":"ACTH分泌在应激时增多，受下丘脑CRH促进和糖皮质激素负反馈抑制，长期大量用糖皮质激素会抑制其分泌；醛固酮盐皮质激素不参与ACTH的负反馈调节，故该项错误。A项应激增多、B项CRH调节、C项糖皮质激素反馈、E项长期激素抑制均属正确描述"},{"q":"下列属于主动转运的是","o":["安静时K＋由细胞内向细胞外转运","兴奋时Na＋由细胞外进入细胞内","葡萄糖由细胞外液进入一般细胞","Na＋由细胞内向细胞外转运","肌质网终池内的Ca2＋流入胞质"],"a":3,"e":"Na+由细胞内向细胞外逆浓度梯度转运依赖钠-钾泵并消耗ATP，属原发性主动转运。A项安静时K+外流、B项兴奋时Na+内流均为顺电化学梯度的经通道易化扩散；C项葡萄糖进入一般细胞为经载体易化扩散；E项肌质网Ca2+流入胞质为经通道易化扩散，均属被动转运"},{"q":"某运动员比赛时大量出汗（1L），此时该运动员会出现","o":["细胞外液量降低，细胞内液量降低和血浆胶体渗透压升高","细胞外液量降低、细胞内液量不变和晶体渗透压升高","细胞外液量降低、细胞内液量不变和胶体渗透压升高","细胞外液量降低、晶体渗透压升高和胶体渗透压不变","细胞外液量降低、细胞内液量升高和晶体渗透压升高"],"a":0,"e":"大量出汗丢失低渗液体，细胞外液量减少且渗透压升高，水由细胞内移向细胞外，使细胞内液量也减少；血浆水分减少使蛋白相对浓缩，胶体渗透压升高。称细胞内液量不变或胶体渗透压不变的组合均不符合高渗性脱水；细胞内液量升高的组合方向相反，故其余均不成立"},{"q":"使糜蛋白酶原活化的物质是","o":["糜蛋白酶本身","胰蛋白酶","肠激酶","盐酸","胰淀粉酶"],"a":1,"e":"糜蛋白酶原由胰腺分泌进入小肠后被胰蛋白酶水解激活，成为有活性的糜蛋白酶，二者同属胰蛋白酶家族的级联激活过程。C项肠激酶的作用是激活胰蛋白酶原而非直接激活糜蛋白酶原；D项盐酸激活的是胃蛋白酶原；A项糜蛋白酶可自催化但初始激活依赖胰蛋白酶；E项胰淀粉酶消化淀粉，与蛋白酶原活化无关"},{"q":"下列关于糖在小肠被吸收的叙述，正确的是","o":["单糖是小肠吸收的唯一形式","单糖的吸收都与钠离子同向转运","果糖的吸收速度比葡萄糖快","果糖的吸收速度比半乳糖慢","毒毛花苷可抑制果糖的吸收"],"a":3,"e":"小肠吸收单糖时葡萄糖与半乳糖经Na+依赖性SGLT1继发性主动转运，而果糖经GLUT5易化扩散，故果糖吸收速度慢于半乳糖。B项单糖都与Na+同向转运错误，果糖为Na+非依赖性；C项称果糖快于葡萄糖与事实相反；E项毒毛花苷抑制钠泵，影响的是葡萄糖和半乳糖的转运，对Na+非依赖的果糖无抑制作用"},{"q":"下列关于前庭器官适宜刺激的叙述正确的为","o":["前庭器官各类毛细胞的适宜刺激都是与纤毛的生长面相垂直的机械力的作用","半规管壶腹嵴的适宜刺激是匀速旋转运动","椭圆囊囊斑的适宜刺激是水平方向的直线变速运动","球囊囊斑的适宜刺激是垂直方向的角加速度运动","当头部以冠状轴为轴心进行旋转时，水平半规管受到的刺激最大"],"a":2,"e":"椭圆囊囊斑的毛细胞适宜刺激是水平方向的直线变速运动及头部静态倾斜；球囊囊斑感受垂直方向的直线变速运动。B项半规管壶腹嵴感受旋转的角加速度而非匀速旋转；D项球囊囊斑感受垂直直线变速而非角加速度；E项头部绕冠状轴旋转主要刺激前半规管而非水平半规管；A项毛细胞适宜刺激是纤毛弯曲的机械力，方向描述不当"},{"q":"终尿中的钾离子主要是由","o":["肾小管滤过","近曲小管分泌","髓袢降支分泌","髓袢升支分泌","远曲小管和集合管分泌"],"a":4,"e":"终尿中的K+主要由远曲小管和集合管的主细胞分泌而来，其分泌受醛固酮和血钾浓度调节。肾小球滤过的K+绝大部分已在近端小管被重吸收，髓袢降支、升支并非K+分泌的主要部位；近曲小管以重吸收为主，不构成终尿钾的主要来源"},{"q":"产生抑制性突触后电位（IPSP）的主要机制是","o":["突触前末梢递质释放减少","突触后膜Ca2+电导降低","突触后膜Na+电导降低","中间神经元受抑制","突触后膜发生超极化"],"a":4,"e":"抑制性突触后电位是突触后膜对Cl-（或K+）通透性增加，Cl-内流使膜电位向更负方向变化，发生超极化，使突触后神经元兴奋性降低。递质释放减少（A项）为突触前抑制；Ca2+电导降低（B项）、Na+电导降低（C项）非IPSP主要机制；中间神经元受抑制（D项）是去抑制，产生兴奋效应"},{"q":"平静吸气主要由哪组肌肉收缩所致","o":["肋间外肌和肋间内肌","肋间外肌和膈肌","肋间内肌和膈肌","肋间外肌和腹肌","肋间内肌和腹肌"],"a":1,"e":"平静吸气为主动过程，主要由膈肌和肋间外肌收缩完成，使胸廓扩大、肺扩张。A项肋间外肌和肋间内肌、C项肋间内肌和膈肌、E项肋间内肌和腹肌中的肋间内肌为呼气肌；D项肋间外肌和腹肌中的腹肌为用力呼气肌。这些肌肉参与呼气而非平静吸气"},{"q":"终板膜上与终板电位产生有关的离子通道是","o":["电压门控钠离子通道","电压门控钾离子通道","电压门控钙离子通道","化学门控非特异性镁通道","化学门控钠离子和钾离子通道"],"a":4,"e":"终板膜上N型乙酰胆碱受体为化学门控非选择性阳离子通道，ACh结合后开放，Na+内流为主伴K+外流，形成去极化的终板电位。A、B、C项电压门控Na+、K+、Ca2+通道参与动作电位，并非终板膜受体通道；D项化学门控非特异性镁通道表述错误，该通道非镁选择性，实为钠钾通透"},{"q":"在蛙坐骨神经-腓肠肌标本的刺激神经观察肌肉收缩实验中，若给予连续刺激，则肌肉收缩容易出现疲劳，其原因是","o":["神经传导的AP幅度越来越小","神经传导AP的频率越来越低","神经-肌接头处兴奋传递的能力越来越弱","肌纤维疲劳，产生AP的能力越来越弱","肌细胞三联管结构的兴奋-收缩耦联能力越来越弱"],"a":2,"e":"连续刺激神经时，神经-肌接头处兴奋传递最易疲劳，因乙酰胆碱释放与合成一时供不应求、受体脱敏，导致终板电位减小，肌肉收缩减弱。神经传导AP幅度（A项）与频率（B项）在刺激下基本稳定；肌纤维产生AP能力（D项）、三联管耦联能力（E项）并非该标本疲劳的首要部位"},{"q":"下列哪种维生素的激活形式，可作为一种能显著影响钙吸收与代谢的激素","o":["维生素A","维生素B复合体","维生素C","维生素D","维生素K"],"a":3,"e":"维生素D的活性形式1,25-二羟维生素D3由肝、肾羟化生成，作为激素促进小肠黏膜对钙、磷的吸收并参与骨钙动员，显著影响钙磷代谢。维生素A参与视觉与上皮分化，维生素C参与胶原合成与抗氧化，维生素K参与凝血因子合成，维生素B族多为辅酶成分，均不直接作为调节钙代谢的激素"},{"q":"某物质从肾小球滤过后又被全部重吸收，该物质的肾血浆清除率为","o":["大于肾小球滤过率","等于肾小球滤过率","小于肾小球滤过率","等于零","等于肾小球血浆流量"],"a":3,"e":"肾血浆清除率指单位时间内肾脏能将某物质完全清除的血浆毫升数。某物质滤过后又被全部重吸收，尿中排泄量为零，清除率等于零，葡萄糖即此类。B项等于滤过率见于菊粉等只滤过不重吸收不分泌的物质；A项大于滤过率见于有分泌的物质；E项等于肾血浆流量见于碘锐特等"},{"q":"压力感受性反射","o":["平时不起作用","只起降压作用而无升压效应","主要对动脉血压进行快速调节","随动脉血压水平升高而敏感性增强","对心率几乎没有影响作用"],"a":2,"e":"压力感受性反射主要对动脉血压进行快速、短期调节，尤其缓冲体位变动等引起的血压波动。该反射平时持续起作用；血压下降时反射减弱可产生升压效应，并非只降压；动脉血压升高时传入增加，敏感性并非随血压升高而单调增强；对心率有明显影响"},{"q":"心动周期中，主动脉压最低见于","o":["等容舒张期末","快速充盈期末","减慢充盈期末","心房收缩期末","等容收缩期末"],"a":4,"e":"心动周期中动脉血压在舒张期持续下降，至等容收缩期末主动脉瓣开放前达最低。快速充盈期末（B项）、减慢充盈期末（C项）血压仍较高。心房收缩期末（D项）已进入舒张末。等容舒张期（A项）血压尚在较高水平"},{"q":"某患者检测血型时，红细胞与B型血的血清发生凝集，而其血清与B型血的红细胞不发生凝集，分析该患者的血型为","o":["A型","B型","O型","AB型","Rh阳性"],"a":3,"e":"B型血血清含抗A凝集素，患者红细胞与其发生凝集，说明红细胞带A抗原；患者血清与带B抗原的B型红细胞不凝集，说明血清中无抗B凝集素。既有A抗原又无抗B凝集素者为AB型。A型血清含抗B，会凝集B型红细胞；O型红细胞无A、B抗原，不与B型血清凝集"},{"q":"下列关于小脑对肌紧张调节的描述，正确的是","o":["前叶蚓部具有易化肌紧张的作用","前叶两侧部具有抑制肌紧张的作用","易化区和抑制区在前叶均呈正立式空间分布","进化过程中，前叶的易化作用逐渐占主要地位","半球中间部也有抑制肌紧张的作用"],"a":3,"e":"小脑前叶对肌紧张具有抑制和易化双重作用，蚓部主要抑制、两侧部主要易化；在进化过程中抑制肌紧张的作用逐渐减弱，易化作用渐占主要地位。前叶蚓部并非易化肌紧张，两侧部也不是抑制肌紧张；易化区和抑制区在前叶呈倒置而非正立分布"},{"q":"人坐在飞机里面，当飞机在升降时，做吞咽动作有助于平衡（ ）两侧的压力，缓解耳部耳鸣、耳痛等不适感","o":["鼓膜","前庭窗膜","圆窗膜","前庭膜","基底膜"],"a":0,"e":"飞机升降时外界气压变化，咀嚼、吞咽动作使咽鼓管开放，鼓室经咽鼓管与咽部相通，从而平衡鼓膜两侧即外耳道与鼓室的压力，缓解耳鸣、耳痛。B项前庭窗膜、C项圆窗膜为内耳与中耳间的膜；D项前庭膜、E项基底膜为耳蜗内结构，均与咽鼓管调压无关"},{"q":"单纯扩散、易化扩散和主动转运的共同特点是","o":["要消耗能量","顺浓度梯度","需要膜蛋白帮助","转运的物质都是小分子","有饱和性"],"a":3,"e":"单纯扩散、易化扩散与主动转运同属跨细胞膜的物质转运，转运对象均为小分子物质或离子，大分子颗粒则依赖出胞入胞。A项消耗能量仅主动转运具备；B项顺浓度梯度只见于单纯与易化扩散；C项需膜蛋白帮助不适用于单纯扩散；E项饱和性源于载体或通道数量有限，单纯扩散无饱和现象，故共同点只是转运小分子"},{"q":"从精原细胞有丝分裂开始到发育成为精子大约需要","o":["14天","28天","36天","48天","64天"],"a":4,"e":"从精原细胞有丝分裂开始，经初级精母细胞、次级精母细胞、精子细胞到形成精子，约需64天，之后还需在附睾中成熟约2周才具受精能力。14天、28天、36天均短于一个生精周期；48天也不足，不符合精子发生完整过程所需时间"},{"q":"交感舒血管纤维末梢释放的递质是","o":["去甲肾上腺素","乙酰胆碱","肾上腺素","阿片肽","谷氨酸"],"a":1,"e":"交感舒血管纤维末梢释放乙酰胆碱，引起骨骼肌血管舒张，参与运动时的血流调节。A项去甲肾上腺素是大多数交感缩血管纤维的递质；C项肾上腺素主要由肾上腺髓质分泌；D项阿片肽、E项谷氨酸不是该纤维的主要递质。需注意与释放去甲肾上腺素的交感缩血管纤维区分"},{"q":"在做胆囊造影时，为检查胆囊的收缩功能，让受试者进食油煎荷包蛋是为了促进","o":["胆固醇合成","胆盐合成","迷走神经兴奋","缩胆囊素的分泌","胃泌素的分泌"],"a":3,"e":"油煎荷包蛋富含脂肪与蛋白质，进入十二指肠后刺激I细胞释放缩胆囊素，促使胆囊收缩、Oddi括约肌舒张，便于造影剂排出以观察胆囊收缩功能。胆固醇与胆盐合成不受此直接刺激；迷走神经兴奋主要影响胃液分泌与胃运动；胃泌素主要刺激胃酸分泌，均非胆囊造影观察收缩功能的机制"},{"q":"心室射血的后负荷是指","o":["心室内压","主动脉血压","主动脉脉压","总外周阻力","中心静脉压"],"a":1,"e":"心室射血时遇到的阻力即后负荷，主要指主动脉血压，动脉压升高会使射血受阻、搏出量减少。心室内压是射血的动力来源而非后负荷；主动脉脉压只是收缩压与舒张压之差；总外周阻力影响动脉血压但不是射血的直接后负荷；中心静脉压反映前负荷，属心室舒张末期的充盈压力"},{"q":"调节血钙浓度最主要的激素是","o":["生长激素","降钙素","甲状腺激素","甲状旁腺激素","肾上腺皮质激素"],"a":3,"e":"甲状旁腺激素是调节血钙最主要的激素，通过促进骨钙释放、肾小管重吸收钙及激活维生素D增加肠钙吸收，升高血钙。降钙素降低血钙但作用较弱；生长激素、甲状腺激素、肾上腺皮质激素虽影响骨代谢，均非血钙调节的主导激素"},{"q":"抑制性突触后电位导致突触后神经元活动减弱的原因在于","o":["突触前神经元活动减弱","兴奋性突触释放递质量减少","后膜电位超极化","轴丘始段去极化","后膜电位去极化"],"a":2,"e":"抑制性突触后电位由抑制性递质使后膜Cl-内流或K+外流，导致后膜超极化，膜电位远离阈电位，突触后神经元兴奋性下降、活动减弱。后膜去极化属兴奋性变化；轴丘始段去极化是动作电位爆发的前提；突触前神经元活动减弱、兴奋性递质释放减少并非IPSP的直接成因"},{"q":"某患者肾上腺皮质功能亢进，血浆中醛固酮水平升高，可预期该患者会出现","o":["血钠升高，细胞外液量增加","血钾升高，细胞外液量增加","血钠升高，细胞外液量减少","血钾下降，细胞外液量减少","血钠下降，细胞外液量增加"],"a":0,"e":"醛固酮升高促进远曲小管和集合管保Na+排K+、伴水重吸收，使血钠升高、细胞外液量增加。血钾应下降而非升高；细胞外液量减少、血钠下降均与醛固酮的潴钠扩容量效应相反"},{"q":"1位32岁健康女性在进行有氧运动中，会出现下列哪项情况","o":["PaO2升高","动脉血乳酸水平上升","动脉血pH降低","PaCO2降低","呼吸运动加深加快"],"a":4,"e":"有氧运动时肺通气量增加主要通过呼吸加深加快实现，以增进摄氧和排出CO2。有氧供能充分，乳酸生成少，动脉血乳酸与pH基本稳定；肺换气储备大，PaO2不升高；CO2产生与排出相称，PaCO2基本不变。动脉血乳酸上升、pH降低多见于剧烈无氧运动，PaCO2降低也非有氧运动恒定表现"},{"q":"与心输出量和心指数有关的正确说法是","o":["心输出量=心率×搏出量","心输出量是每分钟由两侧心室输出的血液量","心输出量是一次心搏由两侧心室射出的血液量","心指数是单位体重计算的心输出量","20岁左右青年的静息心指数最高"],"a":0,"e":"心输出量等于心率与搏出量的乘积，指每分钟由一侧心室射出的血液量。它由一侧心室而非两侧心室输出，一次心搏由一侧心室射出的血量是搏出量；心指数是按单位体表面积而非单位体重计算的心输出量，且随年龄增长而下降，并非20岁左右最高"},{"q":"铁被吸收最快的部位是","o":["胃","十二指肠","结肠","回肠","直肠"],"a":1,"e":"铁主要在十二指肠及空肠上段吸收，以十二指肠最快，食物中铁需还原为二价铁后经载体转运吸收，胃酸与维生素C促进其吸收。胃（A项）主要分泌胃酸、不吸收铁；结肠（C项）、直肠（E项）基本不吸收铁；回肠（D项）主要吸收胆盐和维生素B12，铁吸收很少"},{"q":"下列关于胃排空的叙述，错误的是","o":["胃内食糜由胃排入十二指肠的过程称为胃排空","胃排空是连续进行的","胃排空决定于幽门两侧的压力差","胃排空受十二指肠内容物pH值的影响","混合食物需4～6小时方可完全排空"],"a":1,"e":"胃排空是间断进行的，进食后胃内压升高时排出一部分食糜，随后幽门关闭、排空暂停，如此反复，故连续进行一项错误。胃排空的动力来自幽门两侧压力差，定义即食糜由胃排入十二指肠，受十二指肠内容物pH等因素影响，混合食物约4～6小时排空"},{"q":"肺换气是指","o":["外呼吸","机体与外界环境的气体交换","肺与外界环境的气体交换","血液与组织细胞之间O2和CO2的交换","肺泡与肺毛细血管血液之间O2和CO2的交换"],"a":4,"e":"肺换气指肺泡气与肺毛细血管血液之间氧气和二氧化碳的交换，依靠分压差以单纯扩散方式进行。外呼吸包括肺通气与肺换气，肺与外界环境的气体交换属于肺通气。血液与组织细胞之间的气体交换为组织换气（内呼吸），均不同于肺换气"},{"q":"下列关于牵张反射的叙述，错误的是","o":["牵张反射的感受器是肌梭","只有快速牵拉肌腱时才会发生牵张反射","牵张反射是维持姿势的基本反射","牵张反射在抗重力肌表现最为明显","在脊髓突然与高位中枢离断后，牵张反射可暂时消失"],"a":1,"e":"牵张反射包括快速牵拉肌腱引起的腱反射和缓慢持续牵拉肌肉引起的肌紧张，感受器均为肌梭，是维持姿势的基本反射，在抗重力肌最明显。只有快速牵拉才发生（B项错误）忽略了肌紧张；脊髓与高位中枢离断后牵张反射暂时消失（E项）为脊休克表现，可恢复；A、C、D项均为牵张反射的正确叙述"},{"q":"外界声音通过中耳时，可使声压增加约","o":["1、3倍","3、2倍","17、2倍","22、4倍","55倍"],"a":3,"e":"声波经中耳传递时，鼓膜有效振动面积与镫骨底板面积之比加上听骨链的杠杆作用，使声压增益约22倍（约22.4倍），有效克服声波由空气传入内耳淋巴液的阻抗。1.3倍（A项）、3.2倍（B项）、17.2倍（C项）数值过低，未计入鼓膜面积比与杠杆的综合效应；55倍（E项）过高"},{"q":"精子获能的特点不包括","o":["暴露精子表面与卵子的识别部位","解除对精子顶体反应的抑制","精子细胞膜流动性增加","精子发生超激活反应","只能在女性生殖道内完成"],"a":4,"e":"精子获能是精子获得受精能力的过程，表现为膜流动性增加、表面识别部位暴露、解除顶体反应抑制并出现超激活运动。获能不仅能在女性生殖道内完成，也可在体外适宜培养液中诱导实现，只能一说过于绝对；其余四项均为获能过程中真实发生的变化，属于获能的典型特点"},{"q":"在骨骼肌细胞兴奋-收缩耦联过程中，胞质内的钙离子来自","o":["横管膜上电压门控钙离子通道开放引起的胞外钙离子内流","细胞膜上NMDA受体通道开放引起的胞外钙离子内流","肌质网上钙离子释放通道开放引起的胞内钙离子释放","肌质网上钙离子泵的反向转运","线粒体内钙离子的释放"],"a":2,"e":"骨骼肌兴奋-收缩耦联中，横管膜动作电位激活终末池膜上的钙释放通道，使肌质网内Ca2+释放入胞质，触发肌肉收缩，不依赖胞外Ca2+内流。横管钙通道内流（A项）、NMDA受体（B项）为心肌或中枢机制；钙泵反向转运（D项）不存在；线粒体释放（E项）量微，均非主要来源"},{"q":"渗透压感受器位于","o":["球旁器","下丘脑","延髓","右心房","颈动脉体"],"a":1,"e":"渗透压感受器位于下丘脑视上核附近，感受血浆晶体渗透压变化，调节血管升压素释放与渴觉。A项球旁器为肾内感受肾血流与致密斑Na+的结构；C项延髓有心血管、呼吸中枢及化学感受器传入；D项右心房有容量感受器并分泌心房钠尿肽；E项颈动脉体为外周化学感受器，感受血氧、二氧化碳和H+"},{"q":"不属于第二信使的物质是","o":["cGMP","cAMP","ADP","DG","Ca2+"],"a":2,"e":"第二信使是细胞内传递信号的分子，包括cAMP、cGMP、DG、IP3及Ca2+等，介导激素等胞外信号的级联放大。ADP是能量代谢产物，参与血小板聚集等，但不作为第二信使。cGMP、DG、Ca2+均属公认的第二信使，故ADP为例外"},{"q":"PTH分泌后能迅速引起血钙升高的机制是","o":["促进肾小管重吸收钙","促进骨液中的钙转运至血液中","刺激破骨细胞，增强骨溶解，释放骨钙","刺激成骨细胞活动，促进骨盐沉积","促进肾内钙三醇形成，增强小肠钙吸收"],"a":1,"e":"PTH升高血钙包括快速效应和延迟效应：前者促进骨细胞中骨液的钙迅速转入血液，数分钟内起效；后者刺激破骨细胞、增强骨溶解。题干强调“迅速”，故为促进骨液中的钙转运入血。C项刺激破骨细胞属延迟效应；A项肾小管重吸收钙、E项钙三醇增强肠钙吸收均非最迅速；D项成骨活动会降血钙"},{"q":"下列哪种因素将导致静脉血氧分压降低、呼吸增强","o":["贫血","CO中毒","亚硝酸盐中毒","剧烈运动","过度通气"],"a":3,"e":"剧烈运动时组织代谢增强、耗氧增多，静脉血氧分压明显降低，同时产生大量CO2和H＋，刺激呼吸使通气加强。贫血与CO中毒时动脉血PO2正常，不引起呼吸加强；亚硝酸盐中毒使Hb失去携氧能力但PO2正常；过度通气使CO2排出过多，呼吸反而受抑制"},{"q":"下列哪种激素来自下丘脑","o":["TSH","LH","FSH","ACTH","GnRH"],"a":4,"e":"促性腺激素释放激素即GnRH由下丘脑弓状核等神经元分泌，经垂体门脉作用于腺垂体，促进LH与FSH释放。A项TSH、B项LH、C项FSH、D项ACTH均由腺垂体分泌，属促激素；只有GnRH为下丘脑释放激素，经门脉调节腺垂体的促性腺激素分泌"},{"q":"动物实验中，静脉注射乳酸使动物的呼吸加深、加快与下列哪种感受器有关","o":["细支气管平滑肌中的牵张感受器","呼吸肌本体感受器","颈动脉窦、主动脉弓感受器","颈动脉体、主动脉体感受器","中枢化学感受器"],"a":3,"e":"静脉注射乳酸使血中H+升高，乳酸不易通过血脑屏障，主要刺激颈动脉体和主动脉体等外周化学感受器，反射性使呼吸加深加快。E项中枢化学感受器主要感受脑脊液中的H+，对血液中固定酸的H+不敏感；A项牵张感受器、B项呼吸肌本体感受器、C项压力感受器与血H+引起的化学感受性呼吸调节无关"},{"q":"内环境的稳态是指","o":["细胞内液的各种理化性质保持不变","细胞外液的各种理化性质保持不变","细胞内液的各种理化性质在一定范围内变动又保持相对稳定","细胞外液的各种理化性质在一定范围内变动又保持相对稳定","细胞内液和细胞外液中各种成分基本保持相同"],"a":3,"e":"内环境稳态指细胞外液的理化性质如温度、pH、渗透压和化学成分等，在生理调节下于一定范围内小幅变动并保持相对稳定，是一种动态平衡。说细胞内液保持不变或细胞外液绝对不变都否认了动态波动；成分完全相同更不符合稳态的实际含义"},{"q":"下列关于脊髓α运动神经元的描述，正确的是","o":["是躯体骨骼肌运动反射的最后公路","大α运动神经元及其支配的肌纤维组成大的运动单位","小α运动神经元及其支配的肌纤维组成小的运动单位","轴突末梢释放的递质是谷氨酸","兴奋性较高，常以较高的频率持续放电"],"a":0,"e":"α运动神经元支配骨骼肌梭外肌，是躯体骨骼肌运动反射传出通路的最后公路。其轴突末梢释放乙酰胆碱而非谷氨酸；安静时仅支配慢肌的小α运动神经元有低频持续放电维持肌紧张，并非高频放电；运动单位大小以所支配肌纤维数目计，大、小运动神经元分别支配快肌与慢肌，并不简单等同于神经元大小"},{"q":"下列关于脊髓γ运动神经元的描述，正确的是","o":["支配骨骼肌梭外肌纤维","轴突末梢释放甘氨酸递质","兴奋性较α运动神经元低","活动随α运动神经元活动增强而减弱","可调节肌梭对牵张刺激的敏感性"],"a":4,"e":"γ运动神经元支配肌梭内的梭内肌纤维，其活动可调节肌梭对牵张刺激的敏感性，参与肌紧张调节。A项支配梭外肌纤维的是α运动神经元；B项其轴突末梢释放乙酰胆碱而非甘氨酸；C项γ运动神经元兴奋性较α运动神经元高；D项其活动随α运动神经元活动增强而增强（α-γ共同激活），而非减弱"},{"q":"下列神经中，属于肾上腺素能纤维的是","o":["支配肾上腺髓质的神经","骨骼肌交感舒血管神经","交感缩血管神经","骨骼肌运动神经","支配大部分汗腺的神经"],"a":2,"e":"交感缩血管神经节后纤维释放去甲肾上腺素，属肾上腺素能纤维。A项支配肾上腺髓质的是交感节前纤维，释放乙酰胆碱；B项骨骼肌交感舒血管神经、E项支配汗腺的神经均为交感胆碱能纤维；D项骨骼肌运动神经属胆碱能，终板释放乙酰胆碱，都不是肾上腺素能纤维"},{"q":"抵御化脓性细菌入侵的细胞是","o":["中性粒细胞","嗜碱性粒细胞","嗜酸性粒细胞","淋巴细胞","血小板"],"a":0,"e":"中性粒细胞是抵御化脓性细菌入侵的主要细胞，具趋化、吞噬和杀菌功能，急性化脓性感染时显著增多。嗜碱性粒细胞参与过敏反应；嗜酸性粒细胞主要抗寄生虫并参与过敏；淋巴细胞主司特异性免疫；血小板参与止血与凝血，均非抗化脓菌的主力"},{"q":"下列有关γ运动神经元的描述，错误的是","o":["胞体较α运动神经元为小","其轴突经前根支配梭内肌","末梢释放乙酰胆碱","兴奋性较低","主要功能是调节肌梭对牵张刺激的敏感性"],"a":3,"e":"γ运动神经元胞体小于α运动神经元，其轴突经前根支配梭内肌，末梢释放乙酰胆碱，主要调节肌梭对牵张刺激的敏感性；其兴奋性较高、常持续放电，故兴奋性较低一说错误。A项胞体较小、B项支配梭内肌、C项释放乙酰胆碱、E项调节肌梭敏感性均属正确描述，只有兴奋性较低与γ神经元高紧张性放电的特点相悖"},{"q":"临床上不用异丙肾上腺素喷雾剂治疗支气管哮喘，原因是它","o":["同时激活α1受体，引起血压升高","同时激活α2受体，引起血压降低","同时激活β1受体，引起心脏活动加强","激活β2受体作用过强，引起通气过度","同时激活β3受体，引起脂肪代谢紊乱"],"a":2,"e":"异丙肾上腺素为非选择性β受体激动剂，在激动β2受体舒张支气管的同时也激动β1受体，使心率加快、心肌收缩力增强，易致心悸和心律失常，故不宜喷雾用于哮喘。A、B项异丙肾上腺素几乎不激动α受体；D项β2激动过度并非主要顾虑；E项β3受体与脂肪代谢的关系并非其临床限制，关键是β1心脏兴奋"},{"q":"进食引起的胰液和胆汁分泌属于","o":["神经调节","体液调节","神经和体液双重调节","正反馈调节","负反馈调节"],"a":2,"e":"进食引起的胰液与胆汁分泌同时受神经与体液调节：迷走神经兴奋直接促进分泌，食物及其分解产物刺激胃肠激素如促胰液素、缩胆囊素释放，经体液途径促进分泌。单纯神经调节或单纯体液调节均不全面；正反馈、负反馈是反馈调节方式，不属于此处调节途径的基本分类"},{"q":"关于耳蜗微音器电位，正确的是","o":["其电位随着刺激强度的增加而减小","是多个毛细胞在接受声音刺激时所产生的感受器电位的复合表现","有较长的潜伏期和不应期","易疲劳","在人和动物的听域范围内无法重复声波的频率"],"a":1,"e":"耳蜗微音器电位是多个毛细胞接受声波刺激时产生的感受器电位的复合表现，其波形与声波一致。它无潜伏期和不应期、不易疲劳，可重复声波频率，且幅度随刺激强度增大而增加，故有较长潜伏期、易疲劳、随强度减小等描述均属错误"},{"q":"正常情况下肺弹性阻力的主要来源是","o":["肺泡表面张力","肺表面活性物质","气道阻力","肺组织本身的弹性阻力","惯性阻力"],"a":0,"e":"肺弹性阻力由肺泡表面张力和肺组织本身弹性回缩力构成，其中肺泡表面张力约占三分之二，是主要来源；肺表面活性物质可降低此张力。B项肺表面活性物质本身是降低表面张力的物质而非阻力来源；C项气道阻力、E项惯性阻力属动态阻力；D项肺组织本身弹性阻力仅占约三分之一，居次要地位"},{"q":"氧解离曲线是表示下列哪种关系的曲线","o":["血红蛋白含量与血氧含量","血红蛋白氧饱和度与血氧分压","血红蛋白氧饱和度与血红蛋白氧含量","血红蛋白浓度与血红蛋白氧容量","血红蛋白浓度与血红蛋白氧含量"],"a":1,"e":"氧解离曲线以血氧分压为横坐标、血红蛋白氧饱和度为纵坐标，表示不同PO2下Hb与O2结合或解离的百分比，整体呈S形。A项血红蛋白含量与血氧含量、D项血红蛋白浓度与氧容量反映血液携氧能力而非饱和度随分压的变化；C项氧饱和度与氧含量近似成正比；E项浓度与氧含量也不是该曲线表示的关系"},{"q":"神经纤维的阈电位是","o":["Na＋通道大量开放的膜电位临界值","Na＋通道开始关闭的膜电位临界值","K＋通道开始关闭的膜电位临界值","K＋通道大量开放的膜电位临界值","Na＋通道少量开放的膜电位临界值"],"a":0,"e":"阈电位是使膜上Na+通道大量开放、爆发动作电位的临界膜电位水平，达到此值即触发再生性去极化。B项Na+通道开始关闭发生在复极期；C项K+通道开始关闭、D项K+通道大量开放与复极有关；E项Na+通道少量开放不足以引发动作电位，均非阈电位定义"},{"q":"乙型血友病是由于血浆中缺乏凝血因子","o":["Ⅱ","Ⅲ","Ⅷ","Ⅸ","Ⅹ"],"a":3,"e":"乙型血友病即血友病B，因血浆缺乏凝血因子Ⅸ，属内源性凝血途径障碍，表现为凝血时间延长与出血倾向。因子Ⅷ缺乏为甲型血友病；因子Ⅱ为凝血酶原，其缺乏影响多途径凝血；因子Ⅲ为组织因子，参与外源性凝血启动；因子Ⅹ为共同途径因子，均非乙型血友病的缺陷所在"},{"q":"下列关于记忆的描述，哪一项是正确的","o":["陈述性记忆与意识无关","反射性记忆容易遗忘","长时程记忆与海马对信息的加工处理有关","影像记忆属于长时程记忆","非陈述性记忆依赖于海马的功能活动"],"a":2,"e":"长时程记忆的形成与海马对信息的加工处理密切相关，海马损伤可阻碍短时记忆向长时记忆转化。陈述性记忆与意识有关（A项错）；反射性记忆即非陈述性记忆，不易遗忘（B项错）；影像记忆属短时感觉记忆（D项错）；非陈述性记忆依赖基底神经节、小脑而非海马（E项错）"},{"q":"腋窝是临床上最常用的测定体温的部位，下面哪项要求对用腋窝温度代表体温的影响不大","o":["夹紧","保持腋窝干燥","平卧","测定10分钟","保持安静"],"a":2,"e":"腋窝测温需夹紧上臂以闭合腋窝、保持局部干燥避免蒸发散热、测量足够时间（约10分钟）使温度平衡，这些方法学要求直接决定读数准确性。平卧或坐位等体位改变对腋窝局部温度形成影响不大，故该项要求影响最小。保持安静虽也会减少产热干扰，但相较体位，平卧与腋窝温度代表性关系更弱"},{"q":"异相睡眠所特有的表现是","o":["脑电呈现慢波","机体感觉增强","交感神经系统活动增强","骨骼肌肌紧张增强","眼球快速运动、躯体抽动等阵发性表现"],"a":4,"e":"异相睡眠即快速眼动睡眠，其特有表现是眼球快速运动及躯体抽动等阵发性活动，与此期脑电去同步化、肌紧张减弱相对应。脑电慢波见于慢波睡眠；感觉减弱而非增强；交感活动减弱；骨骼肌肌紧张明显减退而非增强，均非异相睡眠特点"},{"q":"下列哪种情况不能使血流阻力增大","o":["血流黏度增加","红细胞比容增加","血液温度升高","血管收缩","由层流变成湍流"],"a":2,"e":"血流阻力与血液黏滞度成正比、与血管半径四次方成反比，温度升高使血液黏滞度下降，故不能使阻力增大反而减小。A项血流黏度增加、B项红细胞比容增加均提高黏滞度，D项血管收缩减小半径，E项层流变为湍流使阻力显著增大，这四项都以不同机制增加血流阻力"},{"q":"肺气肿患者","o":["肺弹性阻力增大","吸气困难明显","呼气困难明显","吸气时程延长","呼气时程缩短"],"a":2,"e":"肺气肿时肺弹性回缩力减弱、顺应性增大，呼气动力不足，且小气道易陷闭，气体排出受阻，故呼气困难明显。肺弹性阻力增大（A项）错误，肺气肿时弹性阻力减小；吸气困难明显（B项）不符，吸气靠主动肌收缩尚可进行；吸气时程延长（C项）、呼气时程缩短（E项）与实际呼气延长相反"},{"q":"自身调节指组织、细胞在不依赖于神经或体液调节的情况下对刺激所产生的","o":["适应性反应","旁分泌反应","稳态反应","非自控调节","前馈调节"],"a":0,"e":"自身调节指组织、细胞不依赖神经或体液调节，自身对刺激产生的适应性反应，如肾血流量的自身调节。旁分泌、前馈调节属其他调节方式；稳态是内环境稳定的状态而非反应类型；自身调节本身即为一种自控调节，非所谓非自控调节"},{"q":"在自动控制系统中，从受控部分发出到达控制部分的信息称为","o":["偏差信息","干扰信息","控制信息","反馈信息","自控信息"],"a":3,"e":"反馈信息由受控部分发出并返回控制部分，用以纠正偏差。控制信息由控制部分发向受控部分，如迷走神经传出冲动；偏差信息是参考信息与反馈信息之差，干扰信息来自内外环境的扰乱因素。反馈分负反馈与正反馈，前者维持稳态，后者加速过程"},{"q":"关于胃液分泌的描述，错误的是","o":["主细胞分泌胃蛋白酶原","主细胞分泌内因子","壁细胞分泌盐酸","幽门腺和贲门腺分泌黏液","G细胞分泌促胃液素"],"a":1,"e":"胃腺主细胞分泌胃蛋白酶原，壁细胞分泌盐酸和内因子，故“主细胞分泌内因子”错误。内因子实由壁细胞产生，与维生素B12结合促进其吸收；幽门腺和贲门腺分泌黏液；G细胞分泌促胃液素，刺激胃酸与胃蛋白酶原分泌"},{"q":"由膜固有电学性质决定，而非离子通道激活的膜电位是","o":["动作电位","局部反应","终板电位","电紧张电位","突触后电位"],"a":3,"e":"电紧张电位由膜的被动电学特性即膜电阻、电容及轴向电阻决定，是外来电流引起的膜电位被动扩布，不依赖离子通道的激活。A项动作电位、B项局部反应、C项终板电位、E项突触后电位均涉及离子通道开放或离子流变化；只有电紧张电位是纯被动的膜固有电学反应"},{"q":"以下哪项属于负反馈调节的生理过程","o":["分娩","排尿反射","降压反射","动作电位形成","血液凝固"],"a":2,"e":"降压反射（压力感受性反射）在血压升高时增强，反射性降低心率、扩张血管使血压回落，属于典型负反馈，维持血压稳态。分娩（A项）、排尿反射（B项）、血液凝固（E项）均为正反馈，过程不断加强直至完成；动作电位形成（D项）中Na+内流去极化也是正反馈，均非负反馈"},{"q":"脑桥呼吸调整中枢的主要功能是","o":["促使吸气转为呼气","促使呼气转为吸气","减慢呼吸频率","接受肺牵张反射的传入信息","使吸气缩短和呼气延长"],"a":0,"e":"脑桥上部的呼吸调整中枢作用于延髓吸气中枢，促使吸气及时向呼气转换，限制吸气时长并加快呼吸频率。B项呼气转吸气主要依赖延髓吸气中枢及迷走传入；D项接受肺牵张反射传入是延髓相关核团的作用；E项使吸气缩短而呼气延长与其促进转换、缩短吸气的效应不符"},{"q":"O2的利用系数是指","o":["血液流经组织时所含O2量占血O2容量的百分数","血液流经组织释放出的O2容积占动脉血O2含量的百分数","血液流经组织释放出的O2容积占动脉血O2容量的百分数","血液流经组织时释放出的O2含量占动脉血O2含量的百分数","动脉血流经组织时释放出的O2含量占动脉血O2容量的百分数"],"a":1,"e":"氧利用系数指血液流经组织时释放出的O2容积占动脉血O2含量的百分数，反映组织摄取氧的能力，安静时约四分之一。A项为血氧饱和度相关概念；C项分母应为O2含量而非O2容量，后者是Hb充分氧合时的最大携氧量；D、E项中容积与含量、动脉血限定的表述均不准确"},{"q":"迷走神经对胰腺分泌的调节是","o":["引起酶多、水和碳酸氢根少的分泌","引起水、碳酸氢根多而酶少的分泌","引起水、碳酸氢根和酶均多的分泌","无明显的促进作用","起明显的抑制作用"],"a":0,"e":"迷走神经兴奋时末梢释放乙酰胆碱，主要作用于胰腺腺泡细胞，促进酶原颗粒排出，引起酶多而水与碳酸氢根少的分泌物。水与碳酸氢根多而酶少（B项）为促胰液素的作用；三者均多（C项）不符合迷走效应；无明显促进（D项）与明显抑制（E项）均错误，迷走神经对胰液分泌有明确促进作用"},{"q":"关于体温的正常生理变动，正确的是","o":["新生儿体温最稳定","老年人体温偏高","午后1～6时体温最低","通常成年女性的体温略低于男性","育龄期女性黄体期基础体温偏高"],"a":4,"e":"育龄女性基础体温随月经周期波动，排卵后进入黄体期，因孕激素作用体温升高约0.3～0.5℃，故黄体期偏高。新生儿体温调节不完善、波动大；老年人代谢率低体温偏低；正常人清晨2～6时最低、午后1～6时最高；成年女性体温略高于男性"},{"q":"关于肾上腺髓质激素的叙述，下列各项错误的是","o":["肾上腺素和去甲肾上腺素都是由髓质分泌的","髓质激素的化学本质是类固醇","肾上腺素受体有α和β两大类","去甲肾上腺素升血压作用强于肾上腺素","肾上腺髓质激素的分泌受交感神经支配"],"a":1,"e":"肾上腺髓质分泌肾上腺素和去甲肾上腺素，化学本质为儿茶酚胺即胺类，而非类固醇，故该项错误。A项两者均由髓质分泌正确；C项肾上腺素受体分α、β两大类正确；D项去甲肾上腺素以α缩血管为主、升压强于肾上腺素正确；E项髓质分泌受交感节前纤维支配正确"},{"q":"关于静脉血压，下列叙述错误的是","o":["站立时颅内静脉窦的压力低于大气压","正常成人在立正状态时，足背静脉压和主动脉平均压几乎相等","深吸气时中心静脉压高","中心静脉压的高低与心脏的射血能力有关","足背静脉压在行走时比立正时低"],"a":2,"e":"深吸气时胸内负压增大，胸腔内大静脉扩张、外周静脉回流增加，中心静脉压应降低而非升高。站立时颅内静脉窦压力低于大气压；立正时足背静脉压因静水压接近主动脉平均压；中心静脉压与心脏射血能力相关；行走时肌肉泵促进回流，足背静脉压低于立正时，均正确"},{"q":"关于兴奋性突触后电位的描述，正确的是","o":["即突触后神经元处于兴奋状态","经一中间神经元的中介而产生","由突触后膜钾电导增加而产生","由突触后膜钙电导增加而产生","可随突触前递质释放增多而增大"],"a":4,"e":"EPSP是突触前兴奋性递质释放增加导致突触后膜Na＋内流增多、去极化幅度增大的等级性电位，可随递质释放量增加而增大，并可发生总和。它不是突触后神经元已处于兴奋状态，也不一定经中间神经元中介；主要由Na＋电导增加而非K＋或Ca2＋电导增加产生，其余各项均错"},{"q":"浦肯野细胞0期去极化过程中，Na+通道开始迅速失活的条件是当膜电位去极化到以下","o":["-70mV","-50mV","-30mV","0mV","0期去极化的峰值"],"a":3,"e":"浦肯野细胞属快反应细胞，0期由快Na+通道开放引起，随膜去极化，Na+通道失活门关闭，膜电位达0mV时通道迅速失活，Na+内流终止。-70mV为静息电位附近，通道处于备用状态；-50mV、-30mV为阈电位与去极化中期，通道仍在开放；0期峰值时失活已基本完成，并非开始失活的时点"},{"q":"在骨骼肌兴奋-收缩耦联中起关键作用的离子是","o":["Na＋","Ca2＋","Cl-","K＋","Mg2＋"],"a":1,"e":"骨骼肌兴奋-收缩耦联中，动作电位沿横管传至三联管，终池释放Ca2+进入胞质，Ca2+与肌钙蛋白结合触发粗细肌丝滑行，故Ca2+是关键离子。Na+、K+参与动作电位的产生与传导，Cl-和Mg2+不直接触发肌丝滑行，均不是耦联的核心因子"},{"q":"兴奋性突触后电位是发生在","o":["突触前膜上的去极化电位","突触前神经上的锋电位","突触后膜上的去极化电位","突触后神经元上的锋电位","突触后膜上的超极化电位"],"a":2,"e":"兴奋性突触后电位是兴奋性递质作用于突触后膜，使Na+（和K+）通透性变化、以Na+内流为主，引起突触后膜局部去极化，属突触后电位而非动作电位。突触前膜（A项）、突触前神经锋电位（B项）属突触前事件；突触后神经元锋电位（D项）为动作电位；突触后膜超极化（E项）为IPSP"},{"q":"安静时，机体产热的主要器官是","o":["肝脏","肾脏","大脑","骨骼肌","皮肤"],"a":0,"e":"安静时机体产热主要来自内脏器官，其中肝脏代谢最旺盛、产热量最大。肾脏、大脑也有一定产热但少于肝脏；骨骼肌在安静时产热较少，运动时才成为主要产热器官；皮肤是主要散热器官而非产热器官"},{"q":"既能储存能量又能直接供能的物质是","o":["脂肪","葡萄糖","ATP","ADP","磷酸肌酸"],"a":2,"e":"ATP是机体最直接的能量供体，水解高能磷酸键释放能量供各种生命活动，同时其高能磷酸键也可暂时储存能量，故兼具储能与直接供能作用。脂肪和葡萄糖是重要的储能物质但需经氧化分解后才能供能；磷酸肌酸只能储存和转移高能磷酸键，不能直接为生命活动供能；ADP储能很少"},{"q":"下列关于大脑皮层运动区的描述，正确的是","o":["人大脑皮层主要运动区位于中央后回","躯体骨骼肌运动为交叉性支配","头面部肌肉运动均为双侧性支配","躯体和头面部内部均为倒置性安排","肢体远端代表区在前，而近端代表区在后"],"a":1,"e":"大脑皮层主要运动区位于中央前回，对躯干四肢骨骼肌实行交叉性支配，故一侧皮层支配对侧肢体。头面部仅上部面肌受双侧支配，下部面肌和舌肌为对侧支配；躯体呈倒置而头面部为正立安排；运动区定位为下肢在顶部、面舌在底部，该项前后关系错误；中央后回是主要感觉区"},{"q":"临床上，因房水循环障碍引起眼内压升高、视力下降的疾病是","o":["近视眼","远视眼","散光眼","老视眼","青光眼"],"a":4,"e":"房水由睫状体生成，经后房、瞳孔、前房，最后由小梁网等回流；若房水循环受阻则房水积聚、眼内压升高，损害视神经导致视力下降，即为青光眼。A项近视眼、B项远视眼为屈光不正；C项散光眼为角膜曲率异常；D项老视眼为晶状体弹性下降所致调节减退，均与眼压升高无关"},{"q":"进行物质交换的血液不流经下列哪个微循环血管","o":["微动脉","后微动脉","通血毛细血管","真毛细血管","微静脉"],"a":2,"e":"进行物质交换的主要是真毛细血管，血流由微动脉经后微动脉、毛细血管前括约肌进入真毛细血管，再汇入微静脉，该路径慢而充分。通血毛细血管（C项）是微动脉与微静脉间的短路血管，血流快，主要使血液快速回流，几乎不参与物质交换；微动脉（A项）、后微动脉（B项）、微静脉（E项）均为交换通路组成部分"},{"q":"下列属于内脏疼痛的特点是","o":["迅速短暂","定位准确","分辨力好","情绪反应重","对炎症缺血刺激不敏感"],"a":3,"e":"内脏痛由内脏感觉神经传入，定位模糊、发生缓慢而持久，对牵拉、痉挛、缺血、炎症敏感，常伴自主神经反应和明显的情绪反应。迅速短暂、定位准确、分辨力好是皮肤快痛的特点，内脏痛与之相反。对炎症缺血刺激不敏感的说法错误，内脏痛恰恰对此类刺激敏感"},{"q":"在影响能量代谢的因素中，描述错误的是","o":["肌肉活动对能量代谢的影响十分显著","当环境温度低于20℃或高于30℃时，人体能量代谢率开始逐渐增加","与睡眠状态相比，精神活动活跃时脑组织对葡萄糖的代谢率显著增加","安静状态下，每100g脑组织耗氧量为肌肉组织的20倍","食物特殊动力效应由强弱排序为蛋白质>糖>脂肪"],"a":2,"e":"精神活动对全身能量代谢影响很小，脑组织在睡眠与清醒、精神活动时的葡萄糖代谢率基本不变，故该项描述错误。肌肉活动影响显著；环境温度低于20℃或高于30℃时代谢率升高；安静时脑耗氧量约为肌肉的20倍；食物特殊动力效应为蛋白质大于糖大于脂肪，均正确"},{"q":"地震被困于废墟下3天未进食的情况下，机体主要的供能物质是","o":["葡萄糖","肝糖原","肌糖原","脂肪","蛋白质"],"a":3,"e":"饥饿三天时肝糖原早已耗尽，机体转而主要依靠脂肪动员供能，脂肪酸氧化成为多数组织的主要能量来源，同时酮体生成增加供脑利用。葡萄糖和肝糖原储备有限，不能长期维持；肌糖原仅供肌肉自身消耗；蛋白质虽被分解但并非主要供能物质，过早大量分解将危及生命"},{"q":"正常人体内环境的理化特性经常保持","o":["固定不变","相对恒定","随机多变","绝对平衡","与外界一致"],"a":1,"e":"正常人体内环境的温度、pH、渗透压及化学成分等在神经和体液调节下保持相对恒定，即稳态，这是在小范围内动态波动的动态平衡。内环境并非固定不变或绝对平衡，也不随机多变，更不随外界环境同步改变，稳态是其区别于外界环境的根本特征"},{"q":"对心绞痛伴有肺通气不畅的病人进行治疗，应选用","o":["酚妥拉明","育亨宾","普萘洛尔","阿替洛尔","丁氧胺"],"a":3,"e":"阿替洛尔为选择性β1受体阻滞剂，可减慢心率、降低心肌耗氧以缓解心绞痛，且对支气管β2受体影响小，适合伴肺通气不畅者。酚妥拉明、育亨宾阻断α受体，可致反射性心率加快；普萘洛尔为非选择性β阻滞剂，阻断β2可诱发支气管痉挛；丁氧胺为β2阻滞剂，均不适宜"},{"q":"正常人心率超过180次/分时，心输出量减少的原因主要是","o":["快速射血期缩短","减慢射血期缩短","心室充盈期缩短","心室肌氧气供应不足","经减压反射调节后心肌收缩能力减弱"],"a":2,"e":"心率过快时心动周期缩短，其中舒张期即心室充盈期缩短最为明显，心室来不及充分充盈，前负荷和搏出量下降，致心输出量减少。快速射血期与减慢射血期虽也缩短但非主因；心肌供氧不足、减压反射致收缩力减弱均非心率180次/分以上时心输出量下降的主要机制"},{"q":"关于脑干网状结构上行激动系统正确的是","o":["通过丘脑特异投射系统发挥作用","被兴奋后脑电波呈现同步化慢波","可维持大脑皮层的兴奋状态","投射至特定的脑区域","是一个多突触接替的系统，不易受药物的影响"],"a":2,"e":"脑干网状结构上行激动系统经丘脑非特异投射系统弥散投射至大脑皮层，维持其兴奋与觉醒状态。A项借特异投射系统发挥作用错误，特异投射系统传递特定感觉；B项兴奋时脑电呈去同步化快波而非同步化慢波；D项投射并不局限特定脑区；E项多突触接替易受麻醉药影响，并非不易受药物影响"},{"q":"以下最可能使血压在生理范围内趋于下降的情绪类型是","o":["恐惧","发怒","愉快","焦虑","痛苦"],"a":2,"e":"愉快、轻松的情绪使交感活动减弱、迷走活动相对增强，心率减慢、血管舒张，血压在生理范围内趋于下降。A项恐惧、B项发怒、D项焦虑、E项痛苦均为应激性情绪，激活交感-肾上腺髓质系统，使心率加快、心输出量增加、外周阻力升高，血压上升"},{"q":"抗利尿激素主要影响的水通道蛋白是","o":["水通道蛋白-1","水通道蛋白-2","水通道蛋白-3","水通道蛋白-4","都有影响"],"a":1,"e":"抗利尿激素与集合管主细胞V2受体结合，促使胞内含AQP2的囊泡转位并嵌入顶端膜，从而提高对水的通透性，故主要影响水通道蛋白-2。A项AQP1分布于近端小管和髓袢降支，不受ADH调节；C项AQP3、D项AQP4位于基底侧膜，介导水离开细胞；E项都有影响不符合其选择性"},{"q":"感觉的特异投射系统能引起特定感觉的主要原因是","o":["发自丘脑特异感觉接替核","中间不换元，直接投射到大脑皮层","与大脑皮层有点对点的投射关系","投射纤维主要终止于皮层的第四层","很少受内环境理化因素的影响"],"a":2,"e":"特异投射系统经丘脑特异感觉接替核换元后，纤维点对点投射到大脑皮层特定区域，故能引起定位精确的特定感觉。它并非不换元，途中需经丘脑接替；纤维主要终止于皮层第四层是其结构特点，但不决定感觉特异性；很少受内环境影响也不是产生特定感觉的原因"},{"q":"下列选项中，属于人类脊髓小脑损伤所特有的症状是","o":["偏瘫","静止性震颤","意向性震颤","肌张力增强","身体平衡失调"],"a":2,"e":"脊髓小脑主要协调随意运动，其损伤表现为意向性震颤、共济失调与肌张力减退，意向性震颤为其特有症状。B项静止性震颤见于帕金森病即基底神经节病变，安静时出现、活动时减轻；E项身体平衡失调主要属前庭小脑损伤表现；A项偏瘫为锥体束损害；D项肌张力增强多见于锥体系或锥体外系痉挛状态，非脊髓小脑所特有"},{"q":"可阻断心室肌细胞的0期去极化的药物是","o":["河豚毒","四乙基胺","维拉帕米","阿托品","普萘洛尔"],"a":0,"e":"心室肌0期去极化由快Na+通道介导，河豚毒可阻断快Na+通道，从而阻断0期去极化。维拉帕米阻断L型Ca2+通道、影响平台期；普萘洛尔阻断β受体；四乙基胺阻断K+通道；阿托品阻断M受体，均不阻断0期快Na+内流"},{"q":"某患者血沉增快，若将该患者的红细胞置于正常人血浆中，其红细胞沉降的速度将","o":["增快","下降","正常","无变化","先增快后恢复正常"],"a":2,"e":"红细胞沉降率主要取决于血浆成分，血浆中纤维蛋白原、球蛋白增多可促使红细胞叠连而加快血沉，红细胞本身通常并非决定因素。患者红细胞形态正常，置于正常人血浆中缺乏促叠连的异常血浆蛋白，故沉降速度恢复正常，而不是继续增快或先快后恢复"},{"q":"下列哪种激素是神经激素","o":["抗利尿激素","肾上腺素","促甲状腺激素","催乳素","甲状腺激素"],"a":0,"e":"抗利尿激素由下丘脑视上核、室旁核的神经内分泌细胞合成，沿轴突运输至神经垂体释放，属典型神经激素。肾上腺素由肾上腺髓质嗜铬细胞分泌；促甲状腺激素、催乳素来自腺垂体；甲状腺激素来自甲状腺滤泡细胞，均非神经细胞分泌"},{"q":"对基础代谢的下列叙述，错误的是","o":["指“基础状态”下的能量代谢","在清晨、清醒、空腹、静卧时测定","在20～25℃环境中，能量代谢最稳定","基础代谢率与体表面积成正比","基础代谢是机体最低的代谢水平"],"a":4,"e":"基础代谢是基础状态下的能量代谢，并非机体最低代谢水平，睡眠或麻醉时代谢率可更低。基础状态指清晨清醒、空腹、静卧、室温20～25℃（B、C项正确）；基础代谢率与体表面积成正比（D项正确）；A项为其基本定义，均非错误叙述"},{"q":"心血管系统中，顺应性最大的血管是","o":["弹性贮器血管","分配血管","阻力血管","交换血管","容量血管"],"a":4,"e":"静脉系统口径大、管壁薄、可扩张性大，容纳约六至七成循环血量，顺应性最大，称为容量血管。A项弹性贮器血管（主动脉等）弹性好但顺应性小于静脉；B项分配血管（中动脉）、C项阻力血管（小动脉、微动脉）、D项交换血管（毛细血管）顺应性均远小于静脉"},{"q":"血浆晶体渗透压降低时可引起","o":["组织液减少","组织液增加","尿少","红细胞萎缩","红细胞膨胀和破裂"],"a":4,"e":"血浆晶体渗透压降低时水进入红细胞，使其膨胀甚至破裂溶血。晶体渗透压升高才致红细胞皱缩，C项相反。组织液量主要受胶体渗透压影响，A、B项归属错误。尿量减少（E项）与晶体渗透压升高相关，非本题情形"},{"q":"治疗中长期大量应用糖皮质激素类制剂对腺垂体的负反馈影响是","o":["LH分泌减少","FSH分泌减少","TSH分泌减少","PRL分泌减少","ACTH分泌减少"],"a":4,"e":"长期大量应用糖皮质激素通过负反馈抑制下丘脑CRH与腺垂体促肾上腺皮质激素的分泌，使ACTH分泌减少，肾上腺皮质趋于萎缩。LH（A项）、FSH（B项）、TSH（C项）、PRL（D项）分别受各自下丘脑调节肽与靶腺激素调控，不受糖皮质激素负反馈主导"},{"q":"血中激素浓度虽低但生理作用很明显，其原因是","o":["激素随血液分布全身","激素的特异性很高","激素的半衰期很长","激素与受体结合的时间很长","细胞内存在高效能的生物放大系统"],"a":4,"e":"激素血中浓度极低而作用显著，因靶细胞内存在高效的生物放大系统，激素与受体结合后经G蛋白、第二信使逐级放大信号。随血液分布全身只决定作用范围广；激素半衰期多较短，与受体结合时间也不长，均非高效能的原因；特异性高只决定作用于特定靶细胞"},{"q":"下列为快痛特点的是","o":["定位不明确","为“烧灼痛”","主要投射到扣带回","主要投射到皮层第一和第二感觉区","常伴有明显的不愉快情绪"],"a":3,"e":"快痛由Aδ纤维传导，发生快、定位准确、持续时间短，主要投射到大脑皮层第一和第二感觉区，引起明确的刺痛定位。定位不明确、烧灼痛、主要投射到扣带回以及伴明显不愉快情绪，均为慢痛的特点，慢痛由C纤维传导，与快痛的传导通路和投射区域不同"},{"q":"血管升压素在肾脏主要作用于","o":["近球细胞","系膜细胞","肾小球上皮细胞","致密斑","远端小管和集合管上皮细胞"],"a":4,"e":"血管升压素即抗利尿激素，主要作用于远端小管与集合管上皮细胞，通过V2受体促进水通道蛋白插入管腔膜，增加水的重吸收。近球细胞分泌肾素；系膜细胞具收缩与吞噬功能；肾小球上皮细胞参与滤过屏障构成；致密斑感受小管液Na+浓度，均不是ADH的靶细胞"},{"q":"以下心肌组织中，不具有自动节律性的细胞是","o":["窦房结P细胞","心房肌细胞","浦肯野细胞","房室结细胞","房室束细胞"],"a":1,"e":"心肌自律细胞包括窦房结P细胞、房室结、房室束及浦肯野细胞，均具4期自动去极化。心房肌细胞属工作细胞，膜电位稳定，无自动节律性，故为答案。窦房结P细胞是正常起搏点，浦肯野细胞为快反应自律细胞，房室结为慢反应自律细胞，三者皆有自律性"},{"q":"在一般的生理情况下，每分解一分子ATP，钠泵运转可使","o":["2个钠离子移出膜外","2个钾离子移出膜内","2个钠离子移出膜外，同时有2个钾离子移入膜内","3个钠离子移出膜外，同时有2个钾离子移入膜内","2个钠离子移出膜外，同时有3个钾离子移入膜内"],"a":3,"e":"钠泵每水解一分子ATP，可将3个Na+逆浓度梯度移出膜外，同时将2个K+移入膜内，从而维持细胞内外Na+、K+的浓度差，并使膜内电位更负。2个Na+移出、2个K+移出或3个K+移入等表述均不符合钠泵转运的化学计量关系"},{"q":"抑制性突触后电位的产生，是由于突触后膜提高了下列哪种离子的通透性","o":["氯离子","钙离子","钠离子","镁离子","氢离子"],"a":0,"e":"抑制性突触后电位是抑制性递质使突触后膜对Cl-通透性升高，Cl-内流引起膜超极化，突触后神经元兴奋性下降。钙离子内流主要触发递质释放并参与突触可塑性；钠离子内流产生去极化的兴奋性突触后电位；镁离子多在静息时阻断NMDA受体通道"},{"q":"关于胞内受体介导的作用机制描述错误的是","o":["启动DNA转录，促进mRNA形成","诱导新蛋白质生成","细胞内受体是指定位在细胞质或细胞核中的受体","胞内受体介导的过程中细胞内会产生第二信使","可直接进入细胞内与胞质受体结合"],"a":3,"e":"胞内受体位于胞质或胞核，类固醇激素、甲状腺激素等脂溶性配体直接进入细胞与之结合，复合物启动DNA转录、促进mRNA形成并诱导新蛋白质合成，全过程不产生第二信使。第二信使由膜受体途径产生，与胞内受体无关。启动转录、诱导蛋白生成及受体定位于胞质或胞核均为正确描述"},{"q":"由于毛细血管后阻力增大而导致组织液生成增多的是","o":["右心衰引起的全身水肿","肾小球肾病性全身水肿","慢性肝病性全身水肿","丝虫病象皮腿局部水肿","局部炎症性水肿"],"a":0,"e":"右心衰竭时静脉回流受阻，中心静脉压升高，血液淤积于静脉系统使毛细血管后阻力增大，毛细血管内静水压升高，组织液生成增多导致全身性水肿。肾小球肾病性水肿主要因血浆胶体渗透压降低，肝病性水肿与低蛋白和门脉高压有关，丝虫病象皮腿和局部炎症水肿多为局部淋巴或通透性改变所致"},{"q":"急性胰腺炎患者，因持久剧烈腹痛而行禁食和胃肠减压，主要目的是","o":["减少胃蛋白酶分泌","减少胰液分泌","减少胆汁反流","防止胃扩张","防止呕吐"],"a":1,"e":"禁食与胃肠减压可减少食物及胃酸对十二指肠黏膜的刺激，从而减少促胰液素与缩胆囊素释放，降低胰液分泌，减轻胰腺自身消化与炎症。减少胃蛋白酶分泌（A项）非主要目的；减少胆汁反流（C项）、防止胃扩张（D项）、防止呕吐（E项）为次要作用，核心在于抑制胰液分泌"},{"q":"生物活性最高的维生素D3是","o":["24，25-(OH)2-D3","1，25-(OH)2-D3","25-(OH)-D3","7-脱氢胆固醇","25-脱氢胆固醇"],"a":1,"e":"维生素D需经肝25-羟化和肾1α-羟化生成1，25-(OH)2-D3，后者与维生素D受体亲和力最高，是生物活性最强的形式。25-(OH)-D3仅为肝内中间产物，活性弱；24，25-(OH)2-D3活性更低；7-脱氢胆固醇为皮肤中的无活性前体"},{"q":"氨基酸和葡萄糖在小肠的吸收机制是","o":["渗透和滤过","原发性主动转运","入胞作用","继发性主动转运","易化扩散"],"a":3,"e":"葡萄糖和氨基酸在小肠黏膜上皮以Na+依赖性继发性主动转运吸收，载体与Na+同向转运，能量间接来自钠泵建立的Na+浓度梯度。B项原发性主动转运直接消耗ATP，如上皮基底侧钠泵；E项易化扩散顺浓度梯度不耗能；A项渗透滤过与C项入胞分别针对水和颗粒大分子，都不是糖与氨基酸的吸收方式"},{"q":"下列物质不容易通过血脑屏障的是","o":["CO2和O2","乙醇","甘露醇","NH3","氯霉素"],"a":2,"e":"甘露醇为不易通过血脑屏障的多元醇，静脉给药后提高血浆渗透压、使脑组织脱水，故难以透入脑组织。CO2与O2为脂溶性气体，可自由通过；乙醇脂溶性强易通过；NH3可透过并参与氨中毒；氯霉素脂溶性较高，也能进入脑脊液，均较易通过屏障"},{"q":"具有促进青春期女性乳腺基础性发育作用的重要激素是","o":["甲状腺激素","生长激素","催乳素","雌激素","皮质醇"],"a":3,"e":"雌激素促进女性青春期乳腺导管上皮增生、导管延长及脂肪沉积，是乳腺基础性发育的主要激素；孕激素则在雌激素基础上促进腺泡发育。A项甲状腺激素、B项生长激素为全身生长代谢激素，非乳腺发育主导；C项催乳素主要促进乳汁生成而非青春期乳腺发育；E项皮质醇与乳腺发育无直接促进关系"},{"q":"运动神经纤维末梢释放ACh属于","o":["单纯扩散","易化扩散","主动转运","出胞作用","入胞作用"],"a":3,"e":"运动神经纤维末梢释放乙酰胆碱依靠突触小泡与突触前膜融合，以出胞方式将递质量子式释放到突触间隙，需Ca2+内流触发并消耗能量。单纯扩散（A项）与易化扩散（B项）转运小分子，不涉及小泡；主动转运（C项）为离子跨膜泵运，如钠泵；入胞作用（E项）是物质进入细胞，方向相反，均不是递质释放方式"},{"q":"可引起基础代谢率升高的是","o":["垂体性肥胖症","病理性饥饿","Addison病","肾病综合征","甲状腺功能亢进"],"a":4,"e":"甲状腺激素显著提高组织耗氧率和能量代谢水平，甲状腺功能亢进时基础代谢率明显升高，伴怕热、消瘦。垂体性肥胖症、病理性饥饿和Addison病因代谢低下或激素不足使基础代谢率降低；肾病综合征也无基础代谢率升高的特征"},{"q":"人体发烧时，体温每升高1℃，BMR将升高","o":["5%","13%","20%","25%","30%"],"a":1,"e":"体温每升高1℃，基础代谢率约升高13%，故发热时能量代谢显著增强。临床上发热、甲状腺功能亢进使体温升高时代谢率随之上升，需相应增加能量供给；该13%是体温与BMR关系的常用估算依据，5%、20%、25%、30%均偏离这一标准"},{"q":"神经调节的基本方式是","o":["正反馈","负反馈","前馈","反射","神经-体液调节"],"a":3,"e":"神经调节的基本方式是反射，其结构基础为反射弧。适应（A项）、反应（C项）为一般生理概念。正反馈（D项）、负反馈（E项）是调节方式，均非神经调节的基本方式"},{"q":"血液中二氧化碳的含量主要取决于","o":["二氧化碳分压","氧分压","血液的pH","血液的温度","血红蛋白浓度"],"a":0,"e":"血液中CO2含量随二氧化碳分压升高而增加，二者在一定范围内近似成正比，CO2以溶解、碳酸氢盐和氨基甲酰血红蛋白等形式存在，其总量主要取决于PCO2。氧分压（B项）主要影响氧含量；血液pH（C项）受CO2影响而非决定其含量；温度（D项）、血红蛋白浓度（E项）影响有限，均非主要决定因素"},{"q":"肾小球滤过分数是指","o":["肾小球滤过率和体表面积的比值","肾小球滤过率和肾血流量的比值","肾血浆流量和体表面积的比值","肾小球滤过率和肾血浆流量的比值","肾血流量和体表面积的比值"],"a":3,"e":"肾小球滤过分数是肾小球滤过率与肾血浆流量的比值，正常约为19%，表示流经肾脏的血浆有多少比例被滤过。滤过率与体表面积比值（A项）、肾血浆流量与体表面积比值（C项）、肾血流量与体表面积比值（E项）均非滤过分数；滤过率与肾血流量比值（B项）用的是全血流量，概念错误，应为肾血浆流量"},{"q":"心室肌细胞动作电位平台期的离子跨膜流动是","o":["Na+内流，Cl-外流","Na+内流，K+外流","Na+内流，Cl-内流","Ca2+内流，K+外流","K+内流，Ca2+外流"],"a":3,"e":"心室肌细胞动作电位平台期即2期由L型钙通道介导的Ca2+内流与延迟整流钾通道介导的K+外流同时存在、相互平衡形成，膜电位停滞于0毫伏左右。A、C项的Na+内流发生于0期去极化；B项Na+内流伴K+外流不符合平台期离子机制；E项K+内流、Ca2+外流方向完全相反"},{"q":"突触蛋白（synapsin）在轴浆高钙离子条件下被磷酸化，发生变构，其主要作用是","o":["解除突触囊泡锚定在细胞骨架丝上","帮助突触囊泡着位在活化区","促进v-SNARE与t-SNARE结合","消除对融合的钳制作用","开大融合孔以利于递质出胞"],"a":0,"e":"突触蛋白（synapsin）在静息时将突触囊泡锚定于肌动蛋白细胞骨架，轴浆Ca2+升高时其被磷酸化并发生构象改变，解除囊泡与细胞骨架的锚定，使囊泡得以动员并移向活化区。帮助囊泡着位、促进SNARE结合、解除融合钳制和开大融合孔分别是其他步骤，并非synapsin磷酸化的主要作用"},{"q":"血小板磷脂酶A2激活后可产生的物质是","o":["血小板活化因子","ADP","血栓烷A2","cAMP","组胺"],"a":2,"e":"血小板活化后磷脂酶A2被激活，水解膜磷脂生成花生四烯酸，再经环氧合酶途径生成血栓烷A2，促进血小板聚集与血管收缩。血小板活化因子由另一途径产生而非该酶直接产物；ADP由致密颗粒释放；cAMP为胞内第二信使且抑制聚集；组胺主要由肥大细胞释放"},{"q":"关于兴奋性突触传递的叙述，错误的是","o":["突触前轴突末梢去极化","Ca2+由膜外进入突触前膜内","突触小泡释放递质，并与突触后膜受体结合","突触后膜对Na+、K+ 、Ca2+，特别是对K+的通透性升高","突触后膜电位除极化达阈值时，引起突触后神经元发放冲动"],"a":3,"e":"兴奋性突触传递时，突触前末梢去极化使Ca2+内流，促使囊泡释放兴奋性递质并与后膜受体结合，后膜对Na+、K+尤其Na+的通透性升高，产生去极化的兴奋性突触后电位，达阈值即爆发冲动。对K+（或Cl-）通透性升高是抑制性突触后电位的机制，不是兴奋性突触传递的特点"},{"q":"Hb的构型由R型变为T型时","o":["氧离曲线左移","Hb与O2的亲和力降低","Hb与H+结合能力降低","Hb与CO2结合能力降低","P50降低"],"a":1,"e":"Hb由R型即高亲和型转为T型即低亲和型时，与O2亲和力降低，促进O2释放，对应氧解离曲线右移、P50升高。A项左移、E项P50降低均与T型特征相反；C项T型构象稳定脱氧血红蛋白，与H+结合能力增强而非降低即波尔效应；D项T型更易与CO2形成氨基甲酰血红蛋白，结合能力反而增强"},{"q":"当呼吸幅度减小而呼吸频率加快时，受影响最大的是","o":["肺通气量","无效腔气量","肺泡通气量","功能余气量","肺扩散容量"],"a":2,"e":"呼吸幅度减小而频率加快时，无效腔气量在每分通气量中所占比例增大，肺泡通气量明显减少，受影响最大。肺通气量可由频率加快而维持；无效腔气量本身基本不变；功能余气量与肺扩散容量主要受肺泡结构与气体交换特性影响，受呼吸深度与频率改变的影响相对较小"},{"q":"影响精子生成的因素不包括","o":["环境污染","过量饮酒","放射线照射","抗肿瘤药物","少量吸烟"],"a":4,"e":"环境污染、过量饮酒、放射线照射、抗肿瘤药物均可损伤生精上皮、抑制精子生成。少量吸烟对精子生成的影响尚不确切、程度轻微，题目中列为不包括的因素"},{"q":"构成动态阻力的主要成分是","o":["黏滞阻力","惯性阻力","气道阻力","肺弹性阻力","胸廓弹性阻力"],"a":2,"e":"呼吸的非弹性阻力又称动态阻力，包括气道阻力、惯性阻力和组织黏滞阻力，其中气道阻力最主要，约占八九成，受气道口径、气流速度和气体密度影响。A项黏滞阻力虽属动态阻力但占比较小；D肺弹性阻力、E胸廓弹性阻力属于弹性阻力，不归入动态阻力；B惯性阻力在平静呼吸时很小"},{"q":"属于可兴奋细胞的是","o":["成纤维细胞","肝细胞","腺细胞","施万细胞","红细胞"],"a":2,"e":"可兴奋细胞指受刺激后能产生动作电位的细胞，包括神经细胞、肌细胞和腺细胞，故腺细胞属可兴奋细胞。成纤维细胞、肝细胞、施万细胞为不可兴奋细胞；成熟红细胞无核、无线粒体，亦不能产生动作电位"},{"q":"在胚胎期对脑发育最为重要的激素是","o":["生长激素","胰岛素","甲状腺激素","糖皮质激素","绒毛膜生长素"],"a":2,"e":"甲状腺激素在胚胎期对脑发育至关重要，促进神经细胞增殖分化、迁移和髓鞘形成，缺乏可致不可逆的智力低下。生长激素主要影响出生后躯体生长；胰岛素调节代谢；糖皮质激素与绒毛膜生长素对脑发育的决定性作用远不及甲状腺激素"},{"q":"动物实验中，牵拉颈动脉，使颈动脉窦压力感受器的传入冲动增加时，引起的变化是","o":["心迷走神经的紧张性降低","心交感神经的紧张性增加","交感缩血管神经的紧张性降低","血容量增加，细胞外液量增加","心率加快，血压升高"],"a":2,"e":"牵拉颈动脉使窦内压升高、压力感受器传入冲动增加，反射性引起心迷走紧张增强、心交感和交感缩血管神经紧张性降低，导致心率减慢、血压下降，故交感缩血管神经紧张性降低正确。心迷走紧张降低、心交感紧张增加、心率加快均与反射效应相反"},{"q":"下列哪种情况下GFR增加","o":["交感神经系统强烈兴奋","电刺激心迷走神经外周端","肾入球小动脉收缩","血浆白蛋白浓度降低","平均动脉压从100mmHg升高到130mmHg"],"a":3,"e":"血浆白蛋白浓度降低使血浆胶体渗透压下降，有效滤过压升高，GFR增加。交感神经强烈兴奋、入球小动脉收缩均降低肾血流量和GFR；平均动脉压100～130mmHg处于肾自身调节范围内，GFR基本不变"},{"q":"关于甲状旁腺激素作用的叙述，下列说法错误的是","o":["动员骨钙入血","促进肾小管对Ca2+的重吸收","抑制肾小管对磷的重吸收","抑制1，25-二羟维生素D3的生成","促进小肠对钙磷的吸收"],"a":3,"e":"甲状旁腺激素能激活肾小管细胞内1α-羟化酶，促进25-羟维生素D3转变为活性更强的1,25-二羟维生素D3，故“抑制其生成”错误。动员骨钙入血（A项）、促进肾小管重吸收Ca2+（B项）、抑制磷重吸收（C项）、促进小肠吸收钙磷（E项，间接通过活性维生素D）均为PTH的正确作用"},{"q":"胰液中不含","o":["HCO3-","胰蛋白酶原","糜蛋白酶原","肠激酶","胰淀粉酶"],"a":3,"e":"肠激酶（肠肽酶）由小肠黏膜分泌，作用是激活胰蛋白酶原，不存在于胰液中。胰液含HCO3-、胰蛋白酶原、糜蛋白酶原、胰淀粉酶等多种消化酶原和酶。肠激酶来自肠液而非胰液，是激活胰酶的关键酶，最常被误认为胰液成分"},{"q":"平静呼气末存留于肺内的气量称为","o":["潮气量","余气量","补呼气量","功能余气量","补吸气量"],"a":3,"e":"平静呼气末肺内剩余的气体量称功能余气量，等于补呼气量与余气量之和，可缓冲呼吸过程中肺泡气体分压的变化。B项余气量为最大呼气后仍残留的气量；C项补呼气量为平静呼气末再尽力呼出的气量；A项潮气量为平静呼吸每次进出气量；E项补吸气量为平静吸气末再尽力吸入的气量，都不是平静呼气末的存留气量"},{"q":"下列哪种状态下GH分泌明显增加","o":["觉醒","轻微运动","进餐","慢波睡眠","异相睡眠"],"a":3,"e":"慢波睡眠即非快速眼动睡眠的深度睡眠期，此时生长激素分泌明显增加，尤其入睡后第一个慢波睡眠期出现分泌高峰。觉醒、轻微运动与进餐对GH分泌影响较小或使其受抑；异相睡眠即快速眼动睡眠时GH分泌不高，与慢波睡眠形成对比"},{"q":"调节肾脏钠和钾排泌的激素是","o":["抗利尿激素","心房钠尿肽","血管紧张素","醛固酮","肾上腺素"],"a":3,"e":"醛固酮作用于远曲小管和集合管主细胞，促进Na+重吸收与K+分泌，即保钠排钾，是调节肾脏钠钾排泌的主要激素。A项抗利尿激素主要调节水重吸收；B项心房钠尿肽促进排钠排水但不保钾；C项血管紧张素主要通过刺激醛固酮间接影响；E项肾上腺素对钠钾排泄的调节次要，都不是主要调节激素"},{"q":"下列各项生物电的表现，异相睡眠区别于觉醒的是","o":["脑电波呈δ波","肌电明显减弱","眼电明显减弱","心电明显减弱","脑电波呈α波"],"a":1,"e":"异相睡眠（快速眼动睡眠）脑电呈去同步化的低幅快波，类似觉醒状态，但肌电活动明显减弱甚至消失，肌张力显著降低，这与觉醒时的肌电活跃形成鲜明区别。其脑电并非δ波或α波，眼电反而活跃增强，心电无明显减弱改变"},{"q":"下列哪种情况能使血管升压素释放增加","o":["高钾饮食","大量饮清水","刺激颈动脉窦","刺激颈动脉体","大量出汗"],"a":4,"e":"大量出汗使血浆晶体渗透压升高、血容量减少，双重刺激引起血管升压素释放增加，促进肾集合管重吸收水。大量饮清水使渗透压降低、刺激颈动脉窦使压力升高，均抑制其释放；刺激颈动脉体主要兴奋呼吸，对血管升压素影响很小"},{"q":"以下不具有舒张冠脉血管作用的是","o":["CO2","抗利尿激素","交感神经兴奋","氢离子","前列腺素E"],"a":1,"e":"抗利尿激素对冠脉有收缩作用，不具有舒张冠脉的效应。CO2与氢离子为心肌代谢产物，可舒张冠脉；前列腺素E亦为舒血管物质；交感神经兴奋虽直接激动α受体缩血管，但继发心肌代谢增强，β2受体介导的舒张占优势，总体表现为冠脉舒张"},{"q":"下列选项中，不属于下丘脑的功能的是","o":["调节体温","维持水平衡","协调随意运动","控制生物节律","调控摄食行为"],"a":2,"e":"协调随意运动主要靠小脑与基底神经节等结构完成，不属于下丘脑功能。下丘脑参与体温调节、水平衡、摄食行为调控及生物节律控制，是神经-内分泌整合中枢，故其余四项均为下丘脑的重要功能"},{"q":"关于感觉的非特异投射系统功能的正确描述是","o":["维持和改变大脑皮层的兴奋状态","抑制大脑皮层的活动","提高大脑皮层特异感觉的阈值","对大脑皮层活动无影响","激动大脑皮层产生特定感觉"],"a":0,"e":"感觉非特异投射系统经脑干网状结构上行，广泛投射至大脑皮层，作用是维持和改变大脑皮层的兴奋状态、保持觉醒，而不产生特定感觉。引起特定感觉属特异投射系统；抑制皮层活动、提高感觉阈值、对皮层无影响均与其功能不符"},{"q":"与运动调节有关的基底神经节结构不包括","o":["旧纹状体","黑质","丘脑底核","新纹状体","杏仁核"],"a":4,"e":"参与运动调节的基底神经节包括纹状体（新纹状体与旧纹状体）、黑质、丘脑底核等，通过直接通路与间接通路调节运动。杏仁核（E项）属边缘系统，主要参与情绪、恐惧与记忆，不属于基底神经节运动调节结构；旧纹状体（A项）、黑质（B项）、丘脑底核（C项）、新纹状体（D项）均参与运动调节"},{"q":"关于突触前易化的产生，正确的描述是","o":["突触前膜钾通道通透性增高","到达末梢的动作电位频率增高","多个兴奋同时到达突触前末梢","突触前末梢递质释放增多","突触后膜多个EPSP发生总和"],"a":3,"e":"突触前易化指突触前末梢递质释放量增多，使突触后反应增强，其机制多为突触前膜K+通道关闭、动作电位时程延长、Ca2+内流增加。突触前膜钾通道通透性增高会使复极加快、递质释放减少；动作电位频率增高属其他范畴；多个EPSP总和发生在突触后，属突触后总和而非突触前易化"},{"q":"关于突触前易化的产生，下列哪一项描述是正确的","o":["结构基础与突触前抑制完全不同","到达突触前末梢的动作电位频率高","有多个兴奋同时到达突触前末梢","进入突触前末梢内的钙离子增多","突触后膜有多个EPSP发生总和"],"a":3,"e":"突触前易化与突触前抑制结构基础相同，均基于轴突-轴突式突触；其机制是突触前末梢动作电位时程延长或Ca2+内流增加，使递质释放量增大、突触后电位增强。结构基础完全不同（A项）错误；频率高（B项）或多兴奋同时到达（C项）并非易化的特异机制；突触后膜EPSP总和（E项）属突触后改变，不是突触前机制"},{"q":"关于交感缩血管神经的描述，正确的是","o":["只有某些特殊部位的血管才受交感缩血管神经支配","兴奋时通常引起血管舒张","节后纤维释放肾上腺素","交感缩血管神经的紧张性变化时，对心和脑的血流量影响很大","在α受体为主的血管，交感缩血管神经兴奋时引起血管收缩"],"a":4,"e":"交感缩血管神经节后纤维释放去甲肾上腺素，作用于血管平滑肌α受体；在以α受体为主的血管，其兴奋引起血管收缩。人体绝大多数血管都受交感缩血管神经支配，兴奋时引起收缩而非舒张；其紧张性变化对心和脑血流影响较小，因心脑具有强大的自身调节能力"},{"q":"铁的摄入量不足将导致","o":["再生障碍性贫血","缺铁性贫血","溶血性贫血","巨幼细胞贫血","珠蛋白生成障碍性贫血"],"a":1,"e":"铁是合成血红蛋白的必需原料，摄入不足导致体内缺铁，血红蛋白合成减少，形成小细胞低色素性的缺铁性贫血。再生障碍性贫血由骨髓造血功能低下引起，溶血性贫血因红细胞破坏过多，巨幼细胞贫血由叶酸或维生素B12缺乏所致，珠蛋白生成障碍性贫血为遗传性珠蛋白合成异常"},{"q":"引起氧解离曲线右移的因素是","o":["PCO2升高","2,3-DPG降低","pH升高","温度降低","吸入气CO浓度升高"],"a":0,"e":"氧解离曲线右移表示Hb与O2亲和力降低、P50增大，常见于PCO2升高、pH降低、温度升高及2,3-DPG增多。B项2,3-DPG降低、C项pH升高、D项温度降低均使曲线左移；E项CO与Hb结合后增加其余亚基对O2的亲和力，同样使曲线左移，三者都不是右移因素，只有PCO2升高符合"},{"q":"人体单位时间内的基础代谢率","o":["与身高成正比","与体重成正比","与体表面积成正比","与身高和体重的乘积成正比","与上述各因素都无关"],"a":2,"e":"基础代谢率通常以单位体表面积每小时的能量代谢来表示，机体的产热量与体表面积成正比，体表面积越大散热越多、基础代谢率越高。单纯以身高、体重或二者乘积表示均不能准确反映代谢水平，基础代谢率与体表面积密切相关而非无关"},{"q":"一般情况下，神经细胞的阈电位绝对值较其静息电位绝对值","o":["小40～50mV","小10～20mV","接近静息电位水平","大10～20mV","大40～50mV"],"a":1,"e":"神经细胞静息电位约-90mV，阈电位约-70mV，阈电位绝对值较静息电位绝对值小10～20mV。这一差值决定细胞去极化达到阈电位即爆发动作电位。小40～50mV、大10～20mV等均与静息电位和阈电位的实际数值关系不符"},{"q":"当过度通气时，呼吸会出现暂停的原因是","o":["血液PO2过高","血液PCO2过高","血液PO2过低","血液PCO2过低","血液pH值过低"],"a":3,"e":"过度通气使CO2大量排出，动脉血PCO2过低，对中枢和外周化学感受器的刺激减弱，呼吸中枢兴奋性下降，出现呼吸暂停，直至CO2回升。血液PO2过高并非主要原因，吸氧也不会使呼吸停止；PO2过低与pH过低均会刺激呼吸；PCO2过高同样加强呼吸，不会引起暂停"},{"q":"小血管损伤后止血栓正确定位于损伤部位，是由于血小板的哪种生理特性","o":["吸附","黏附","聚集","收缩","释放"],"a":1,"e":"小血管损伤后，血小板通过表面糖蛋白与暴露的血管内皮下胶原发生黏附，并借助von Willebrand因子加强，使血小板聚集形成的止血栓准确黏着并定位于损伤部位。吸附是一般表面附着，聚集是血小板间相互黏着形成团块，收缩与释放分别指血块回缩和颗粒内容物排出，均不决定定位"},{"q":"当氧分压为40mmHg时，100ml血液中含有的O2量最接近","o":["4ml","6ml","8ml","10ml","12ml"],"a":4,"e":"氧分压40毫米汞柱相当于混合静脉血，血红蛋白氧饱和度约75%，血氧含量约15毫升每100毫升，以偏低血容量估算约为12至13毫升，故最接近12毫升。A项4毫升、B项6毫升、C项8毫升明显过低，相当于严重缺氧；D项10毫升亦偏低，均不如12毫升接近实际氧含量"},{"q":"关于非特异感觉投射系统的描述，正确的是","o":["包括丘脑投向大脑皮层的所有纤维","自大脑皮层返回丘脑的纤维也可归入此系统","是各种不同感觉的共同上传通路","主要与大脑皮层第四层的神经元构成突触联系","电刺激该系统可引起皮层感觉区持续放电"],"a":2,"e":"非特异感觉投射系统由脑干网状结构上行激活系统及丘脑非特异核团组成，是各种感觉传入的共同通路，经多级神经元换元后弥散投射到大脑皮层广泛区域，维持觉醒。特异投射系统才点对点投射至皮层第四层并引起特定感觉。该系统不引起皮层特定感觉区持续放电，皮层返回丘脑的纤维也不归入此系统"},{"q":"自然呼吸情况下，PCO2升高对呼吸的刺激作用增强，其原因是","o":["血液H+浓度也升高","血液PO2降低","中枢化学感受器的敏感性增加","外周化学感受器的敏感性增加","CO2解离曲线的影响"],"a":0,"e":"PCO2升高时，CO2与水结合生成碳酸并解离出H+，使血液H+浓度同时升高，两者共同刺激化学感受器，故刺激作用增强。血液PO2降低是低氧的独立效应，并非CO2升高所致；中枢与外周化学感受器敏感性在PCO2升高时并无特异性增加；CO2解离曲线影响的是CO2运输量，不是刺激作用增强的原因"},{"q":"下列情况使呼吸商变小的是","o":["肺通气过度","肌肉剧烈运动","糖在体内转化为脂肪","肺通气不足","酸中毒"],"a":3,"e":"呼吸商为一定时间内CO2产生量与耗O2量之比，肺通气不足时CO2排出受限，测得的CO2排出量相对减少，呼吸商因而变小。B项剧烈运动以糖酵解供能为主，呼吸商趋近1；C项糖转化为脂肪时释放CO2较多，呼吸商可大于1；A项通气过度、E项酸中毒时CO2排出增多，均使呼吸商增大而非变小"},{"q":"交感神经的“紧张性活动”是指它在","o":["精神紧张时产生的一定频率的冲动","身体剧烈运动时产生的电位改变","内脏平滑肌受牵拉时产生的电位改变","血管平滑肌受牵拉时产生的一定频率的冲动","在安静状态下自主神经系统持续发放一定频率的冲动"],"a":4,"e":"自主神经的紧张性活动是指在安静状态下，交感和副交感神经仍持续发放一定频率的冲动，维持心血管、消化道等器官的基础活动。精神紧张时（A项）、剧烈运动时（B项）的冲动增加为应激反应；内脏平滑肌牵拉（C项）、血管平滑肌牵拉（D项）引起的反射为局部反射，均非紧张性活动的定义"},{"q":"下述关于胃肠激素的描述，错误的是","o":["由散在于黏膜层的内分泌细胞分泌","均为肽类激素","仅存在于胃肠道","可调节消化道的运动和消化腺的分泌","部分激素对消化道黏膜具有营养作用"],"a":2,"e":"胃肠激素由胃肠黏膜内分泌细胞分泌，多为肽类，可调节消化道运动与消化腺分泌，部分对黏膜有营养作用；但许多胃肠激素也分布在中枢神经系统，称脑肠肽，故“仅存在于胃肠道”错误，如胆囊收缩素、生长抑素均见于脑内"},{"q":"在横纹肌，引起肌丝滑行的始动步骤是","o":["肌质中Ca2+与肌钙蛋白结合","横桥ATP酶活性增高，使ATP分解","肌凝蛋白与肌动蛋白结合","横桥与肌动蛋白结合","钙泵活动增强"],"a":0,"e":"横纹肌肌丝滑行的始动步骤是肌质中Ca2+与肌钙蛋白结合，使肌钙蛋白构象改变，牵动原肌球蛋白移位，暴露肌动蛋白上的横桥结合位点。横桥ATP酶活性增高与ATP分解是横桥循环的能量供应环节；肌凝蛋白与肌动蛋白结合、横桥与肌动蛋白结合均发生在结合位点暴露之后；钙泵活动增强促使舒张，并非滑行始动"},{"q":"影响能量代谢最显著的是","o":["食物的特殊动力效应","环境温度为30℃","环境温度为20℃","精神活动","肌肉活动"],"a":4,"e":"肌肉活动是影响能量代谢最显著的因素，剧烈运动时骨骼肌耗氧与产热可较安静时增加十余倍。食物特殊动力效应仅使代谢率升高10%左右；环境温度20℃左右为中性温度区，代谢较稳定，30℃时变化不大；精神活动主要影响脑代谢，对全身能量代谢影响较小"},{"q":"肺通气的直接动力来自","o":["肺内压与跨壁压之间的压力差","胸膜腔内压与跨壁压之间的压力差","胸膜腔内压与大气压之间的压力差","肺内压与大气压之间的压力差","肺内压与胸膜腔内压之间的压力差"],"a":3,"e":"肺通气的直接动力是肺内压与大气压之间的压力差，呼吸肌收缩使胸廓容积变化，造成肺内压周期性高于或低于大气压，推动气体进出。肺内压与胸膜腔内压差（E项）反映跨肺压；胸膜腔内压与大气压差（C项）不是直接动力；肺内压与跨壁压（A项）、胸膜腔内压与跨壁压（B项）均非气体进出肺的直接动力"},{"q":"促胰液素能促进胰腺分泌","o":["大量水分和碳酸氢盐，酶含量较少","少量水分和碳酸氢盐，酶的含量也很少","少量水分和碳酸氢盐，酶的含量很丰富","大量水分，而碳酸氢盐和酶的含量很少","大量的碳酸氢盐，水分和酶含量也丰富"],"a":0,"e":"促胰液素主要作用于胰腺导管上皮细胞，促进分泌大量水分和碳酸氢盐，而酶含量较少，这一碱性胰液可中和进入十二指肠的胃酸。含酶丰富的胰液分泌主要由缩胆囊素刺激腺泡细胞产生，故酶含量丰富的表述不符合促胰液素作用"},{"q":"下列关于突触可塑性的描述，错误的是","o":["功能与形态均可改变","可发生在突触前或突触后","普遍存在于中枢神经系统","突触传递效率改变较持久","是神经系统发育成熟后的表现"],"a":4,"e":"突触可塑性指突触在形态和功能上的可修饰性，可发生在突触前或突触后，广泛存在于中枢神经系统，表现为传递效率的持久改变，在神经系统发育过程中尤为活跃，并是学习记忆的基础。它并非发育成熟后才出现的表现，发育期的突触修剪和可塑性更为显著"},{"q":"下列哪一过程在神经末梢递质释放中起关键作用","o":["动作电位到达神经末梢","神经末梢去极化","神经末梢处的钠离子内流","神经末梢处的钾离子外流","神经末梢处的钙离子内流"],"a":4,"e":"神经末梢递质释放的关键在于动作电位到达后膜去极化使电压门控Ca2+通道开放，Ca2+内流触发突触小泡与突触前膜融合、以胞吐方式释放递质。动作电位到达与末梢去极化是触发前提而非关键耦联环节；钠内流主要参与去极化形成；钾外流与复极有关，均不直接触发递质释放"},{"q":"突触后抑制的产生是由于","o":["兴奋性递质破坏过多","兴奋性递质释放过少","抑制性中间神经元兴奋","抑制性中间神经元产生了抑制","兴奋性中间神经元活动抑制"],"a":2,"e":"突触后抑制由抑制性中间神经元兴奋引起，其末梢释放抑制性递质，使突触后膜产生超极化的抑制性突触后电位，从而降低突触后神经元兴奋性。兴奋性递质破坏过多或释放过少只是兴奋减弱，并非主动抑制；抑制性中间神经元自身兴奋而非产生了抑制，兴奋性中间神经元活动受抑也不属于突触后抑制机制"},{"q":"内脏痛最主要的特点是","o":["尖锐的刺痛","潜伏期和持续时间长","定位不明确","伴有情绪和心血管反应","对牵拉性刺激不敏感"],"a":2,"e":"内脏痛由内脏病变刺激痛觉感受器引起，其最主要特点是定位不明确，常表现为弥漫性疼痛并伴自主神经反应。尖锐刺痛为皮肤快痛的特点；潜伏期与持续时间长、伴情绪和心血管反应虽可见，但不是最主要特点；内脏痛对牵拉、痉挛等刺激敏感，不敏感说法错误"},{"q":"雄激素的生理作用不包括","o":["促进生殖器官的发育","促进附性器官发育","促进肌肉、骨骼蛋白质合成","促进肾脏Na＋、水排出","维持正常性行为"],"a":3,"e":"雄激素促进肾小管对Na+与水的重吸收，造成Na+、水潴留而非排出，故该项不属于其生理作用。雄激素可促进生殖器官与附性器官发育、促进肌肉骨骼蛋白质合成并维持正常性行为，其余均为其生理作用"},{"q":"关于糖皮质激素分泌调节的叙述，错误的是","o":["给摘除腺垂体的动物连续注射ACTH可引起肾上腺皮质增生与肥厚","正常情况下，血浆中ACTH和糖皮质激素的水平相平行","长期服用皮质醇可使ACTH分泌增多","应激时ACTH分泌增加几乎全部受控于下丘脑室旁核释放的CRH","应激情况下，ACTH和糖皮质激素的分泌量明显增多"],"a":2,"e":"长期服用皮质醇通过负反馈抑制下丘脑CRH与腺垂体ACTH分泌，使ACTH减少而非增多，故该项错误。摘除腺垂体后注射ACTH引起皮质增生（A项）、血浆ACTH与皮质醇水平平行（B项）、应激时室旁核CRH主导（D项）、应激时二者分泌明显增多（E项）均正确"},{"q":"人体内O2和CO2进出细胞膜是通过下列哪种方式","o":["单纯扩散","易化扩散","原发性主动转运","继发性主动转运","出胞或入胞"],"a":0,"e":"O2和CO2为脂溶性小分子气体，可直接穿过脂质双分子层，以单纯扩散方式顺分压梯度跨膜转运，不需膜蛋白帮助也不消耗能量。B项易化扩散需载体或通道；C项原发性主动转运与D项继发性主动转运均耗能逆浓度梯度；E项出胞入胞用于大分子颗粒，都不适用于呼吸气体的跨膜移动"},{"q":"椭圆囊和球囊囊斑的适宜刺激是","o":["旋转加速运动","旋转匀速运动","直线加速运动","直线匀速运动","直立静止状态"],"a":2,"e":"椭圆囊和球囊囊斑中的毛细胞感受直线加速度运动及头部静态位置变化，其适宜刺激为直线加速运动，耳石膜的位移牵拉毛细胞产生兴奋。旋转加速运动由半规管壶腹嵴感受，旋转匀速运动与直立静止状态并非囊斑的有效刺激，直线匀速运动因无加速度变化也不引起反应"},{"q":"肾脏中尿素最容易通透的部位是","o":["近曲小管","髓袢升支","髓袢降支细段","远端小管和集合管","内髓集合管"],"a":4,"e":"内髓集合管在抗利尿激素作用下对尿素通透性最高，尿素由此扩散入内髓组织液，参与肾髓质高渗梯度的形成与维持，是尿素再循环的关键部位。A项近曲小管主要重吸收葡萄糖、氨基酸；B项髓袢升支对水不通透并重吸收NaCl；C项髓袢降支细段主要通透水；D项远曲小管和皮质集合管对尿素通透性低"},{"q":"胃黏膜长期处于高酸和胃蛋白酶的环境中，却不会被消化，这是由于存在着自我保护机制。这个机制主要是","o":["黏液屏障","黏液细胞保护","黏液凝胶层保护","黏液-碳酸氢盐屏障","碳酸氢盐屏障"],"a":3,"e":"胃黏膜表面覆盖黏液层并富含HCO3-，形成黏液-碳酸氢盐屏障，可中和胃酸、隔离胃蛋白酶，使黏膜表面保持中性偏碱，是抵御自身消化的主要机制。单纯黏液屏障或碳酸氢盐屏障只是其组成部分，概念不完整"},{"q":"1位病人检查发现其右心室后负荷明显加重，可能由以下哪个疾病引起","o":["高血压病","心肌梗死","严重贫血","肺梗死","心脏瓣膜关闭不全"],"a":3,"e":"右心室后负荷即肺动脉压力，肺梗死可阻塞肺动脉、升高肺血管阻力与肺动脉压，使右心室射血阻力增大、后负荷加重。高血压病（A项）增加左心室后负荷；心肌梗死（B项）主要损害收缩功能；严重贫血（C项）降低外周阻力、增加前负荷；心脏瓣膜关闭不全（E项）多导致容量负荷增加"},{"q":"下列各项中，能使肾小球有效滤过压降低的是","o":["血浆晶体渗透压升高","肾小球毛细血管血压升高","肾小囊内静水压降低","血浆胶体渗透压升高","肾小囊内胶体渗透压升高"],"a":3,"e":"肾小球有效滤过压等于肾小球毛细血管血压减去血浆胶体渗透压与肾小囊内压之和，血浆胶体渗透压升高使有效滤过压降低、滤过减少。A项血浆晶体渗透压不影响滤过；B项肾小球毛细血管血压升高使滤过压升高；C项囊内压降低使滤过压升高；E项囊内胶体渗透压正常近零，升高并非主要原因"},{"q":"治疗“水中毒”应补充","o":["糖皮质激素","盐皮质激素","抗利尿激素","甲状腺激素","胰岛素"],"a":0,"e":"水中毒时细胞外液低渗、水过多，糖皮质激素可维持肾小球滤过率并促进水排泄，有助于纠正稀释性低钠。盐皮质激素保钠保水，会加重水潴留；抗利尿激素促进远曲小管和集合管重吸收水，同样加重水中毒。甲状腺激素与胰岛素不参与水平衡的主要调节"},{"q":"区分心肌快、慢反应细胞的依据是","o":["收缩力的大小","0期去极化的速率","平台期的长短","3期复极化的快慢","4期自动去极化的速度"],"a":1,"e":"区分心肌快、慢反应细胞的依据是0期去极化的速率，快反应细胞由快Na+通道介导，0期快；慢反应细胞由Ca2+通道介导，0期慢。收缩力大小、平台期长短、3期复极快慢及4期自动去极化速度反映其他电生理或机械特性，均非划分快、慢反应细胞的依据"},{"q":"如果某受试者24小时的耗氧量500L，二氧化碳生成量为390L，尿氮排出量15g。请根据这些数据，计算该受试者1小时的能量代谢量","o":["342、28kJ/h","385、82kJ/h","389、21kJ/h","412、59kJ/h","425、12kJ/h"],"a":3,"e":"先由尿氮量算出蛋白质氧化量及其耗氧、产二氧化碳量，再从总量中扣除，得非蛋白呼吸商，据以查表求非蛋白氧热价，乘以非蛋白耗氧量并加上蛋白质供能，换算为每小时约412.59kJ/h。342.28kJ/h（A项）、385.82kJ/h（B项）、389.21kJ/h（C项）、425.12kJ/h（E项）分别为漏算蛋白质供能、呼吸商取错或氧热价取值偏差所致"},{"q":"有关自主性体温调节，下列哪项是错误的","o":["主要作用是维持体温的稳定","有下丘脑调节中枢的参与","是行为性体温调节的基础","不属于体温自身调节系统","使机体深部温度维持在一个稳定的水平"],"a":3,"e":"自主性体温调节通过下丘脑体温调节中枢，依靠负反馈控制产热与散热，使深部体温维持相对稳定，是体温调节系统的核心组成部分，也是行为性体温调节的基础。认为它不属于体温自身调节系统的说法错误，其主要作用正是维持体温稳定"},{"q":"下列符合机体在炎热环境下的表现的是","o":["肌紧张增强","皮肤血流量增加","交感神经的紧张度增强","机体表层的隔热器作用增强","四肢热量逆流交换作用加强"],"a":1,"e":"炎热环境下皮肤血管舒张、血流量增加，将体核热量带至体表散发，是主要散热反应。肌紧张增强与交感神经紧张度增强见于寒冷环境，可增加产热并收缩皮肤血管；表层隔热器作用增强、四肢逆流交换加强也均为保热机制，与炎热时散热需求相反"},{"q":"肾清除率最低的物质是","o":["菊粉","碘锐特","肌酐","尿素","葡萄糖"],"a":4,"e":"葡萄糖经肾小球滤过后在近端小管被几乎完全重吸收，尿中排出量接近零，故其肾清除率最低，约为零。菊粉清除率等于肾小球滤过率；碘锐特和对氨基马尿酸清除率接近肾血浆流量，数值最高；肌酐清除率近似滤过率；尿素部分重吸收，清除率虽低但仍明显高于葡萄糖"},{"q":"患者血浆白蛋白低于30g/L，出现水肿，其主要原因是","o":["毛细血管的通透性增加","组织液胶体渗透压下降","血浆胶体渗透压下降","血浆晶体渗透压下降","淋巴回流增加"],"a":2,"e":"白蛋白是维持血浆胶体渗透压的主要成分，低于30g/L时血浆胶体渗透压下降，毛细血管内保有水分的力量减弱，组织液生成增多而出现水肿。组织液胶体渗透压下降会减少组织液生成，方向相反；血浆晶体渗透压主要调节细胞内外水平衡，与组织水肿无直接关系。毛细血管通透性增加见于炎症，非低蛋白水肿机制"},{"q":"胰岛素缺乏时，一般不出现","o":["多尿","多饮","高血糖","高血压","高血脂"],"a":3,"e":"胰岛素缺乏时组织摄取利用葡萄糖障碍，出现高血糖，超过肾糖阈引起渗透性利尿和多尿，继而多饮，并因脂肪动员增强出现高血脂，均属糖尿病典型表现。高血压不是胰岛素缺乏的直接后果，反而高胰岛素血症可能与高血压相关，故一般不出现高血压"},{"q":"基础体温在月经周期中发生变动，这可能与下列哪种激素有关","o":["促肾上腺皮质激素","胰岛素","孕激素","雌激素","甲状腺激素"],"a":2,"e":"基础体温在月经周期中呈双相变化，排卵后孕激素分泌增加，作用于体温调节中枢使体温升高0.3～0.6℃，故与孕激素有关。促肾上腺皮质激素（A项）、胰岛素（B项）、甲状腺激素（E项）不形成周期性双相体温；雌激素（D项）在排卵前升高但不引起明显升温"},{"q":"血液凝固的内源性与外源性激活途径的主要差别是","o":["FX激活物的形成过程","凝血酶激活过程","纤维蛋白形成过程","是否需要维生素K的参与","有无Ca2+的参与"],"a":0,"e":"内源性与外源性凝血途径的主要差别在于凝血因子X激活物的形成过程不同：内源性由因子XII启动、经内源性级联，外源性由组织因子启动。两者之后的凝血酶激活、纤维蛋白形成过程相同，也均需Ca2+和维生素K参与部分因子，故非主要差别"},{"q":"不属于原发性主动转运的物质是","o":["肌质网钙泵对钙离子的摄取","胃腺壁细胞分泌氢离子","钠-钾泵转运钠离子","质子泵转运氢离子","肾小管对葡萄糖的重吸收"],"a":4,"e":"肾小管对葡萄糖的重吸收由Na+-葡萄糖同向转运体驱动，依赖钠泵建立的Na+浓度梯度，属继发性主动转运。A项肌质网钙泵、B项胃壁细胞分泌氢离子、C项钠-钾泵、D项质子泵转运氢离子均直接水解ATP获能，属原发性主动转运"},{"q":"第二心音的产生主要由于","o":["房室瓣开放","房室瓣关闭","动脉瓣开放","动脉瓣关闭","乳头肌及腱索的振动"],"a":3,"e":"第二心音发生于心室舒张开始时，主要由主动脉瓣与肺动脉瓣（动脉瓣）突然关闭、血流冲击引起的振动产生。第一心音才是房室瓣关闭所致；动脉瓣开放与房室瓣开放不产生心音，乳头肌腱索振动非主因"},{"q":"第二信使是指激素、神经递质、细胞因子等第一信使分子作用于","o":["胞膜受体后产生的细胞内信使分子","胞浆受体后产生的信使分子","核受体后产生的信使分子","胞膜受体及核受体后产生的信使分子","胞膜受体及胞浆受体后产生的信使分子"],"a":0,"e":"第二信使是激素等第一信使与靶细胞膜受体结合后在胞内产生或释放的小分子物质，如cAMP、IP3、DG、Ca2+，负责跨膜传递信号。胞浆受体和核受体介导类固醇激素、甲状腺激素的作用，通过调控基因转录实现，不产生第二信使。把核受体或胞浆受体产物归入第二信使均属混淆"},{"q":"手术切除动物肾上腺皮质后血中ACTH浓度升高，说明糖皮质激素对腺垂体促激素分泌具有哪种调节作用","o":["神经调节","神经-体液调节","正反馈调节","负反馈调节","前馈调节"],"a":3,"e":"切除肾上腺皮质后糖皮质激素减少，对腺垂体的负反馈抑制减弱，ACTH分泌因而升高，此为典型负反馈调节。神经调节与神经-体液调节需有神经参与，本题为激素反馈；正反馈使原活动加强，与ACTH升高由抑制解除所致不符；前馈是预先调节，亦不适用"},{"q":"当心室肌细胞在兴奋后复极至-55~-60mV时，若细胞膜受到外来的阈上刺激，膜电位的变化是","o":["不产生电位变化","产生局部电位","产生慢反应动作电位","产生快反应动作电位","产生超级化"],"a":1,"e":"心室肌细胞复极至-55～-60mV时，Na+通道尚未完全恢复到可激活状态，此时给予阈上刺激不能爆发动作电位，只能产生局部电位。A项完全无电位变化需处于有效不应期更早阶段；C项慢反应动作电位、D项快反应动作电位均需Na+通道充分恢复；E项超极化与此无关"},{"q":"某青年男性在剧烈运动之后心率超过180次/分，心输出量减少。请问是以下哪个时相缩短","o":["快速充盈相","减慢充盈相","等容收缩相","减慢射血相","心房收缩相"],"a":0,"e":"心率超过180次/分时心动周期尤其是舒张期明显缩短，其中快速充盈相缩短最显著，回心血量骤减，前负荷下降，导致每搏输出量与心输出量减少。等容收缩相（C项）、减慢射血相（D项）属收缩期，受影响较小；减慢充盈相（B项）与心房收缩相（E项）虽也缩短，但对充盈量贡献不及快速充盈相"},{"q":"诱发弗雷德里克·格兰特·班廷思考胰岛素提取方法的病例是","o":["胆囊结石","胰腺炎","胰导管结石","肠梗阻","胰腺肿瘤"],"a":2,"e":"班廷注意到胰导管结石患者因胰腺外分泌部（腺泡）退化萎缩而胰岛相对完整，据此推断结扎胰导管使腺泡退化后可提取胰岛分泌物，最终成功提取胰岛素。A项胆囊结石、B项胰腺炎、D项肠梗阻、E项胰腺肿瘤均非启发其思路的关键病例"},{"q":"关于温度感受神经元，下列描述中哪一项是错误的","o":["视前区-下丘脑前部中的热敏神经元，在温度信息的整合中起重要作用","视前区副下丘脑前部存在着冷敏神经元","局部脑组织温度变动在0、3℃以上，温度感受神经元的放电频率才会发生变化","此类神经元全部存在于中枢神经系统内","脑干网状结构中以冷敏神经元为主"],"a":2,"e":"中枢温度敏感神经元对局部脑温度变化极为敏感，变动约0.1℃即可引起放电频率改变，而非需0.3℃以上才变化，故该项错误。A项视前区-下丘脑前部的热敏神经元在体温信息整合中起重要作用，B项该区也存在冷敏神经元，E项脑干网状结构以冷敏神经元为主，均属正确描述；此类中枢温度感受神经元分布于中枢神经系统内"},{"q":"心交感神经兴奋后，对心肌细胞的影响是","o":["肌质网释放钙离子减少","肌质网对钙离子的摄取减慢","自律细胞4期If电流减少","P细胞动作电位0期速度和幅度加大","平台期钙离子内流减少"],"a":3,"e":"心交感神经末梢释放去甲肾上腺素，激动心肌β1受体，使窦房结P细胞4期If电流增强、0期Ca2+内流增加，去极化速度和幅度加大，自律性升高；同时肌质网释放和摄取Ca2+加快、平台期Ca2+内流增多，收缩加强。钙释放减少、摄取减慢、If电流减少或平台期钙内流减少均与交感兴奋效应相反"},{"q":"分泌钾的主要部位是","o":["近曲小管","髓袢降支细段","髓袢升支细段","髓袢升支粗段","远曲小管和集合管"],"a":4,"e":"小管液中的K+主要在远曲小管和集合管由主细胞分泌，受醛固酮、血钾浓度和小管流速调节，与Na+重吸收偶联即保钠排钾。A项近曲小管主要重吸收钾；B项髓袢降支细段、C项髓袢升支细段、D项髓袢升支粗段主要参与NaCl重吸收和尿液浓缩，非分泌K+的主要部位"},{"q":"下列说法正确的是","o":["吸气时腔静脉回到右心房的血量减少","呼气时右心室搏出量增多","吸气时肺静脉回到左心房的血量增加","呼气时肺循环血管扩张","动脉血压在呼气相中期达到最高点"],"a":4,"e":"吸气时胸内负压增大，肺扩张使肺血管容量增加、肺静脉回流左心减少，动脉血压略降；呼气时相反，动脉血压在呼气相中期达最高。吸气时腔静脉回流右心增加而非减少；呼气时右心搏出量并非增多；呼气时肺循环血管回缩而非扩张，均与该时相的血流动力学不符"},{"q":"下列生理过程中，属于正反馈调节的是","o":["降压反射","排尿反射","体温调节","肺牵张反射","血糖浓度的调节"],"a":1,"e":"排尿反射中尿液刺激感受器反射性加强逼尿肌收缩，直至尿液排尽，属于正反馈，使过程不断加强直至完成。A项降压反射、C项体温调节、E项血糖调节均为负反馈以维持稳态；D项肺牵张反射通过抑制吸气、促使呼气转换防止肺过度充气，属负反馈调节"},{"q":"动物实验中，静脉注射乙酰胆碱后，引起动脉血压下降的主要原因是","o":["心肌细胞传导减慢","心肌收缩力减弱","心率减慢，心输出量下降","静脉回流减慢","后负荷增大"],"a":2,"e":"静脉注射乙酰胆碱激动心脏M2受体，产生负性变时和负性变力作用，使心率减慢、心肌收缩力减弱，心输出量明显下降，是动脉血压下降的主要原因。传导减慢、静脉回流减慢和心肌收缩力减弱虽也发生，但血压下降主要归因于心输出量下降；ACh舒张血管使外周阻力下降，后负荷并非增大"},{"q":"外源性凝血途径的始动因子是","o":["FⅠ","FⅡ","FⅢ","FⅦ","FⅩ"],"a":2,"e":"外源性凝血途径由血管外组织释放的组织因子即FⅢ启动，FⅢ与FⅦa形成复合物，进而激活FⅩ。D项FⅦ是参与该途径的因子，但需与FⅢ结合才发挥作用，始动者是FⅢ；A项FⅠ为纤维蛋白原、B项FⅡ为凝血酶原、E项FⅩ为共同通路因子，都不是始动因子"},{"q":"不引起尿量增加的情况是","o":["尿崩症","糖尿病","交感神经兴奋性升高","血管升压素受体缺乏","静脉输入甘露醇"],"a":2,"e":"交感神经兴奋使肾血管收缩、肾血流量和滤过率下降，并促进近端小管重吸收Na+和水，尿量减少。尿崩症因抗利尿激素缺乏、糖尿病因渗透性利尿、血管升压素受体缺乏、静脉输入甘露醇均导致尿量增加"},{"q":"人眼的调节功能主要是由下列哪个来实现的","o":["角膜的曲度变化","角膜和晶体的曲度变化","晶体的曲度变化","玻璃体的曲度变化","晶体和玻璃体的曲度变化"],"a":2,"e":"人眼视近物时的调节主要靠晶状体曲度增大变凸，由睫状肌收缩、悬韧带松弛实现，使折光力增强、物像聚焦于视网膜。角膜曲度固定不可调节，故A项角膜曲度变化、B项角膜和晶体曲度变化均错误；D项玻璃体、E项玻璃体曲度变化不参与调节，晶状体是唯一可改变曲度的折光结构"},{"q":"体内PCO2最高的部位是","o":["组织液","细胞内液","静脉血液","动脉血液","外周毛细血管血液"],"a":1,"e":"二氧化碳由细胞代谢产生，在细胞内液中生成后顺分压差向组织液、血液扩散，故细胞内液的PCO2在体内最高，依次高于组织液、静脉血和动脉血。肺泡气经呼吸更新，PCO2最低；外周毛细血管血液的PCO2介于动静脉之间，均低于细胞内液"},{"q":"人眼暗适应过程的实质是","o":["视力的提高","视野的增大","光感受器的适应","视色素合成增加","色素上皮突起缩回"],"a":3,"e":"暗适应的实质是视杆细胞视紫红质等视色素的合成增加，使视网膜对弱光的敏感度逐渐提高，历时较长。视力提高与视野增大是暗适应的结果表现而非实质；光感受器泛指视杆与视锥，未点明视色素；色素上皮突起缩回是形态变化，不是暗适应的本质"},{"q":"促进肾脏分泌肾素的因素不包括","o":["位于入球小动脉壁的牵张感受器受到的刺激减少","流经致密斑处的小管液中NaCl量减少","急性大出血导致的血压下降","心房钠尿肽","低盐饮食"],"a":3,"e":"心房钠尿肽由心房肌细胞分泌，可抑制肾素分泌，并抑制醛固酮、促进排钠排水，故不属于促进肾素分泌的因素。入球小动脉牵张感受器刺激减少、致密斑处小管液NaCl减少、急性大出血致血压下降及低盐饮食均通过不同机制促进肾素释放"},{"q":"在近端小管后半段，部分钠离子通过细胞旁路重吸收的动力主要来自","o":["管腔内带正电，管腔外带负电","小管液钠离子浓度高于管周液钠离子浓度","小管液静水压高于管周液静水压","管周液胶体渗透压高于小管液胶体渗透压","管周液晶体渗透压低于小管液晶体渗透压"],"a":0,"e":"近端小管后半段因HCO3-重吸收快于Cl-，使小管液带正电、管周液带负电，Na+顺此电位差经细胞旁路即紧密连接被动重吸收。小管液Na+浓度并不高于管周液；静水压差、管周胶体或晶体渗透压差均非该段Na+经细胞旁路重吸收的主要动力"},{"q":"通过轴突反射实现局部血管舒张的是","o":["脊髓背根舒血管纤维","交感舒血管纤维","副交感舒血管纤维","血管活性肠肽神经元","作用于β2受体的交感缩血管纤维"],"a":0,"e":"脊髓背根舒血管纤维的轴突分支可沿传入神经逆向传至皮肤血管，通过轴突反射释放舒血管递质，引起局部血管舒张。交感舒血管纤维支配骨骼肌，副交感舒血管纤维分布于特定腺体与器官；血管活性肠肽神经元与作用于β2受体的交感纤维虽参与舒血管，但不通过轴突反射实现"},{"q":"下列属于机体内环境的是","o":["细胞内液","唾液","尿液","脑脊液","汗液"],"a":3,"e":"脑脊液是脑细胞直接生活的液体环境，与血浆、组织间液、淋巴液相延续，属机体内环境。细胞内液位于细胞内部，不属于内环境；唾液、尿液、汗液为与外界相通的外分泌液或排泄物，属外环境成分，均不属内环境范畴"},{"q":"缺氧使呼吸活动增强，主要通过刺激下列哪一部位而实现","o":["延髓呼吸中枢","中枢化学敏感区","颈动脉窦和主动脉弓","脑桥呼吸中枢","颈动脉体和主动脉体"],"a":4,"e":"缺氧主要刺激颈动脉体和主动脉体的外周化学感受器，传入冲动增加反射性兴奋呼吸中枢，使呼吸增强。中枢化学敏感区对CO2和H+敏感，对缺氧不敏感；延髓、脑桥呼吸中枢及颈动脉窦、主动脉弓压力感受器并非缺氧兴奋呼吸的主要感受装置"},{"q":"窦房结细胞动作电位的主要特点是","o":["去极相有超射现象","去极化速度很快","复极化时间远远长于去极化时间","有明显的2期平台期","有4期自动去极化"],"a":4,"e":"窦房结细胞为慢反应自律细胞，其动作电位最显著的特点是4期自动去极化，构成起搏电位。其0期去极化由Ca2+内流引起、速度慢、幅度小、无超射，无明显平台期，复极化时间未必远长于去极化，故相关选项均不符"},{"q":"下列关于小脑功能的描述，正确的是","o":["前庭小脑主要调节肌紧张","脊髓小脑主要与维持身体平衡有关","皮层小脑主要执行精巧运动","脊髓小脑主要协调随意运动","皮层小脑主要完成本体感受传入冲动信息的处理"],"a":3,"e":"脊髓小脑接受本体感觉传入，主要协调随意运动并调节肌紧张，使运动平稳准确。A项维持身体平衡是前庭小脑的功能；B项把平衡归于脊髓小脑张冠李戴；C项皮层小脑参与精巧运动的设计与计划而非直接执行；E项本体感受信息的处理主要由脊髓小脑完成，其余选项均与小脑各部分的功能分区不符"},{"q":"下列有关微循环的描述正确的是","o":["直捷通路不能与外周组织进行物质交换","动-静脉短路可与外周组织进行少量的物质交换","当环境温度升高时，直捷通路大量开放以增加散热","毛细血管血压取决于毛细血管前、后阻力的比值","微循环的血流量主要受交感神经和迷走神经的调控"],"a":3,"e":"毛细血管血压由毛细血管前阻力与后阻力之比决定，前阻力与后阻力的相对大小直接影响毛细血管内静水压及组织液生成。直捷通路主要使血液快速回流，几乎不进行物质交换；动-静脉短路不参与物质交换，环境温度升高时开放的是动-静脉短路而非直捷通路；微循环主要受局部代谢产物和交感神经调节，无迷走神经支配"},{"q":"睾丸支持细胞合成分泌的（ ）与腺垂体FSH分泌的负反馈调节有关","o":["抑制素","激活素","雄激素","前列腺素","孕激素"],"a":0,"e":"睾丸支持细胞分泌抑制素，可选择性抑制腺垂体合成与释放FSH，构成负反馈调节。激活素促进FSH分泌，方向与抑制素相反；雄激素主要反馈抑制LH；前列腺素、孕激素不参与FSH的该项负反馈"},{"q":"阈刺激的概念是","o":["引起组织兴奋的最小刺激强度","引起组织兴奋的最小刺激作用时间","引起组织抑制的最小刺激","引起膜去极化达到阈电位的最小刺激","引起组织抑制的最小刺激作用时间"],"a":3,"e":"阈刺激是强度恰能使膜去极化达到阈电位、从而触发动作电位的最小刺激，其强度即阈强度，反映组织兴奋性的高低。引起组织兴奋的最小刺激强度（A项）定义的是阈强度而非阈刺激本身；最小作用时间（B、E项）涉及时值；引起抑制（C项）与兴奋无关"},{"q":"下列关于淋巴管及淋巴回流的描述，错误的是","o":["毛细淋巴管以盲端起始于组织","组织液中颗粒可进入毛细淋巴管，但不能倒流","组织液静水压升高时，淋巴回流将减少","组织液中的红细胞、细菌可经淋巴回流重吸收","正常成年人安静时的淋巴回流量约120ml/h"],"a":2,"e":"组织液静水压升高时，液体更易进入毛细淋巴管，淋巴回流应增加而非减少，故该叙述错误。毛细淋巴管以盲端起于组织；其内皮瓣膜使组织液颗粒进入后不能倒流；红细胞、细菌等可经淋巴回流被处理；成年人安静时淋巴回流量约120ml/h，均正确"},{"q":"下列情况下能量代谢率最低的是","o":["室温在20～25°C","熟睡时","进食12小时后","安静时","运动后休息时"],"a":1,"e":"熟睡时骨骼肌完全松弛、意识活动降至最低，能量代谢率在生理状态下最低，低于安静清醒状态。室温20～25℃为最适环境温度，代谢率较低但高于熟睡；进食后存在食物特殊动力作用使代谢升高，运动后恢复期内代谢仍高于基础水平，均不是最低"},{"q":"正常成人的血液总量约相当于体重的","o":["8%","15%","20%","60%","40%"],"a":0,"e":"正常成人血液总量约占体重的7%～8%，即每千克体重约70～80ml，由血浆与血细胞共同构成，维持循环血量与血管容积的匹配。15%（B项）、20%（C项）、40%（E项）明显过高；60%（D项）接近体液总量占体重的比例，不是血液总量，均与血液总量不符"},{"q":"肺心病病人的血液黏稠、红细胞数量增多，是由于","o":["血氧饱和度降低","H＋增多","纤溶酶减少","纤维蛋白原增多","红细胞生成酶增多"],"a":0,"e":"肺心病患者长期通气换气障碍致血氧饱和度降低，组织缺氧刺激肾脏分泌促红细胞生成素，骨髓生成红细胞增多，血液黏稠度随之升高。E项所谓红细胞生成酶并非规范概念，起作用的是促红细胞生成素且由缺氧诱导，不是原发原因；B项H+增多主要影响呼吸与酸碱平衡；C项纤溶酶减少、D项纤维蛋白原增多与红细胞数量增多无直接因果"},{"q":"下列关于肺牵张反射的叙述，正确的是","o":["感受器存在于肺实质中","正常人平静呼吸时，对呼吸节律起重要调节作用","传入神经是迷走神经","可促进呼气及时转入吸气","无明显的种属差异"],"a":2,"e":"肺牵张反射的感受器位于支气管和细支气管平滑肌，传入神经为迷走神经，故该项正确。该反射在正常人平静呼吸时不参与节律调节；其作用是促进吸气及时转入呼气而非呼气转吸气；且存在明显种属差异，在动物较强，故其余说法均错误"},{"q":"炎热的夏天，气温达到40℃，户外活动时人体依靠什么方式散热维持体温的稳定","o":["辐射散热","传导散热","对流散热","蒸发散热","辐射和对流散热"],"a":3,"e":"当环境温度达40摄氏度并高于皮肤温度时，辐射、传导和对流不仅不能散热反使机体吸热，此时蒸发散热即出汗成为唯一有效的散热途径。A项辐射散热、B项传导散热、C项对流散热均依赖环境温度低于皮肤温度；E项辐射和对流在高温下失效，只有蒸发散热能维持体温稳定"},{"q":"神经元之间所存在的电突触结构基础是","o":["缝隙连接","曲张体","混合性突触","交互性突触","串联性突触"],"a":0,"e":"神经元之间电突触的结构基础是缝隙连接，两细胞膜通过连接子形成通道，允许离子与小分子直接通过，实现快速、双向、低电阻的传递。曲张体为突触前神经末梢的膨大结构；混合性突触、交互性突触与串联性突触是按形态或功能划分的突触类型，均不是电突触的结构基础"},{"q":"脊髓半离断可能发生的症状是","o":["离断同侧痛觉障碍","离断同侧粗触压觉障碍","离断对侧温度觉障碍","离断对侧本体觉障碍","离断对侧精细触觉障碍"],"a":2,"e":"脊髓半离断时，脊髓丘脑束在脊髓内交叉后上行，故损伤平面以下对侧痛温觉障碍；后索本体觉纤维未交叉即上行，故同侧本体觉和精细触觉障碍。因此离断对侧温度觉障碍正确，而同侧痛觉、对侧本体觉与精细触觉障碍的说法均与交叉规律相反"},{"q":"人们提取重物时，发挥作用的骨骼肌的工作形式是","o":["单收缩","不完全强直收缩","完全强直收缩","等长收缩","等张收缩"],"a":2,"e":"正常人体骨骼肌的运动由运动神经元连续发放高频冲动引起，收缩完全融合为完全强直收缩，可产生持续稳定的张力以完成提取重物等动作。A项单收缩仅见于单次刺激；B项不完全强直收缩融合不完全；D项等长收缩、E项等张收缩是按长度与张力变化分类，体内骨骼肌收缩本质均为强直收缩"},{"q":"突触前抑制的产生机制是","o":["突触前膜阈电位水平抬高","突触前末梢递质释放减少","突触前末梢释放抑制性递质","抑制性中间神经元兴奋","突触后膜产生IPSP"],"a":1,"e":"突触前抑制由轴突-轴突式突触引起，抑制性中间神经元使突触前末梢去极化，减小其动作电位幅度，使Ca2+内流减少、兴奋性递质释放下降，突触后兴奋性突触后电位减小。C项释放抑制性递质、E项突触后膜产生抑制性突触后电位属突触后抑制；D项中间神经元兴奋参与但不直接表述该机制；A项阈电位抬高并非主要机制"},{"q":"关于激素的信息传递作用，下列哪项是正确的","o":["加强或减弱靶组织的生理生化过程","为靶组织活动提供额外能量","为靶组织代谢添加新成分","内分泌系统的信息是电信号","激素可以作为第二信使发挥作用"],"a":0,"e":"激素作为信息分子，不提供能量也不添加新成分，而是与靶细胞受体结合，传递调节信息，加强或减弱靶组织原有的生理生化过程。提供额外能量（B项）、添加新成分（C项）均非激素作用；内分泌信息为化学信号而非电信号（D项错）；激素为第一信使，第二信使如cAMP在细胞内（E项错）"},{"q":"下列有关中枢化学感受器的描述，正确的是","o":["对低氧敏感","血液中CO2的变化可直接刺激中枢化学感受器","对血液中H＋浓度变化敏感","生理性刺激是脑脊液和局部细胞外液中的H+","中枢化学感受器位于延髓腹内侧"],"a":3,"e":"中枢化学感受器的生理性刺激是脑脊液和局部细胞外液中的H+，血中CO2易透过血脑屏障并生成H+而发挥作用。A项对低氧不敏感是外周化学感受器特征；B项血液CO2需转为H+才间接刺激；C项对血中H+变化不敏感，因H+不易透过血脑屏障；E项该感受器位于延髓腹外侧浅表而非腹内侧"},{"q":"下列药物能阻断心迷走神经的作用的是","o":["普萘洛尔","阿托品","酚妥拉明","肾上腺素","乙酰胆碱"],"a":1,"e":"阿托品为M受体阻断剂，可阻断心迷走神经末梢释放的ACh对心肌M受体的作用，解除迷走神经对心脏的抑制，使心率加快。普萘洛尔阻断β受体、阻断心交感作用；酚妥拉明阻断α受体；肾上腺素激动交感受体；乙酰胆碱本身模拟迷走神经作用，均不能阻断迷走效应"},{"q":"在我国引起急性胰腺炎最常见的病因是","o":["胆道疾病","大量饮酒和暴饮暴食","并发于流行性腮腺炎","高钙血症","手术创伤"],"a":1,"e":"官方答案为大量饮酒和暴饮暴食，但依据教材，正确答案为胆道疾病。在我国，胆道疾病尤以胆石症是急性胰腺炎最常见的病因，占半数以上，称胆源性胰腺炎，因Oddi括约肌痉挛或结石嵌顿致胰液反流。大量饮酒和暴饮暴食是重要诱因，在发达国家更常见，但非我国首位病因；流行性腮腺炎、高钙血症、手术创伤均较少见。原答案混淆了诱因与最常见病因"},{"q":"影响骨骼、肌肉生长发育的最主要的激素是","o":["糖皮质激素","生长激素","盐皮质激素","肾上腺素","甲状腺激素"],"a":1,"e":"生长激素由腺垂体分泌，促进骨骼纵向生长与蛋白质合成、肌肉发育，是影响骨骼与肌肉生长发育最主要的激素，幼年缺乏致侏儒症。糖皮质激素（A项）过多抑制生长；盐皮质激素（C项）调节水盐代谢；肾上腺素（D项）应激动；甲状腺激素（E项）促进发育但非最主要，缺乏致呆小症"},{"q":"骨骼肌兴奋-收缩耦联的关键部位是","o":["肌膜","终板膜","横管系统","纵管系统","三联管结构"],"a":4,"e":"骨骼肌兴奋-收缩耦联的结构基础是三联管，即横管及其两侧终池，横管膜电位变化经耦联因子触发终池释放Ca2+，启动肌丝滑行。肌膜、终板膜参与兴奋产生与传递；横管、纵管仅为三联管的组成部分，单独不能完成耦联"},{"q":"对于丘脑非特异投射系统的特点，下列说法错误的是","o":["失去感觉传入的专一性","主要发自丘脑的髓板内核群","弥散性投射到大脑皮层广泛区域","主要与皮层第四层神经元的胞体形成突触联系","维持与改变大脑皮层的兴奋状态"],"a":3,"e":"丘脑非特异投射系统起自髓板内核群，弥散投射至大脑皮层广泛区域，主要与皮层表层神经元树突联系，维持与改变皮层兴奋状态。感觉传入的专一性在此系统已丧失，故主要与皮层第四层神经元胞体形成突触联系错误，与第四层胞体联系是特异投射系统的特征"},{"q":"为什么胰液中的蛋白水解酶不会消化胰腺自身","o":["胰液中的胰蛋白水解酶以酶原的形式存在于腺泡细胞及通过导管","磷脂酶A2的激活","碳酸氢盐的分泌","胃蛋白酶原的分泌","缩胆囊素释放"],"a":0,"e":"胰液中的蛋白水解酶以无活性的酶原形式在腺泡细胞合成并经导管排入十二指肠，到达肠腔后被肠激酶等激活，故不会消化胰腺自身。磷脂酶A2激活（B项）可致自身消化，是胰腺炎机制；碳酸氢盐分泌（C项）中和胃酸；胃蛋白酶原分泌（D项）、缩胆囊素释放（E项）与此保护机制无直接关系"},{"q":"关于输血的原则，错误的是","o":["必须保证ABO血型相合","输同型血经交叉配血试验主、次侧均不凝集为首选","紧急情况下O型血可少量缓慢接受其他型血液","紧急情况下A型血可少量缓慢输入给AB型血液","反复输血的病人必须保证Rh血型相合"],"a":2,"e":"O型血红细胞无A、B抗原，但血浆含抗A、抗B抗体，只能接受O型血，输入其他型血液会被其抗体凝集，故该说法错误。A项ABO相合为输血基本原则；B项同型血交叉配血主次侧均不凝集为首选；D项AB型血清无抗A抗体，可接受少量A型血；E项反复输血者需Rh相合以防抗D抗体"},{"q":"激素通过血液运输作用于远距离的靶细胞，称为","o":["外分泌","远距分泌","旁分泌","神经分泌","自分泌"],"a":1,"e":"激素经血液运输作用于远距离靶细胞的分泌方式称为远距分泌，即经典内分泌。外分泌指经导管排至体表或管腔；旁分泌作用于邻近细胞；自分泌作用于自身；神经分泌指神经内分泌细胞分泌，均不符合远距传输的特征"},{"q":"腺垂体分泌的激素不包括","o":["生长素","缩宫素","卵泡刺激素","促甲状腺激素","黄体生成素"],"a":1,"e":"腺垂体分泌生长素、卵泡刺激素、黄体生成素、促甲状腺激素、促肾上腺皮质激素和催乳素；缩宫素由下丘脑合成、经神经垂体释放，不属腺垂体分泌。A项生长素、C项卵泡刺激素、D项促甲状腺激素、E项黄体生成素均由腺垂体细胞分泌，只有缩宫素来自神经垂体"},{"q":"胰高血糖素能直接刺激下列哪种激素的分泌","o":["生长激素","胰岛素","糖皮质激素","瘦素","甲状腺激素"],"a":1,"e":"胰高血糖素可直接刺激胰岛β细胞分泌胰岛素，属局部旁分泌调节；血糖升高时也刺激胰岛素分泌。A项生长激素、C项糖皮质激素、D项瘦素、E项甲状腺激素均非胰高血糖素直接刺激分泌的激素。胰高血糖素与胰岛素既相互制约又协同调节糖代谢"},{"q":"血浆胶体渗透压的生理作用是","o":["影响毛细血管内外水的交换","影响细胞内外水的交换","维持细胞正常体积","维持细胞正常形态","决定血浆总渗透压"],"a":0,"e":"血浆胶体渗透压主要由白蛋白等大分子形成，作用于毛细血管内外，调节水的交换，使组织液回流血管。细胞内外水的交换及细胞正常体积、形态的维持主要由晶体渗透压决定；血浆总渗透压由晶体与胶体渗透压共同构成，胶体部分占比很小，不决定总渗透压"},{"q":"下列各项调节中，属于自身调节的是","o":["动脉血压在80～160mmHg范围内变动时，肾血流量可保持相对恒定","全身动脉血压升高时，血压水平下降","过度通气后，呼吸暂停","水量摄入多时，尿量增加","机体酸中毒时，泌酸增加"],"a":0,"e":"动脉血压在80至160mmHg范围内变动时，肾血流量通过入球小动脉的自身调节保持相对恒定，不依赖神经或体液因素。全身血压升高后血压回降属压力感受性反射；过度通气后呼吸暂停为体液调节；多饮水尿量增加涉及ADH与肾调节；酸中毒时泌酸增加为体液机制，均非自身调节"},{"q":"体内组织器官主要依靠糖的有氧氧化供能的是","o":["心肌和平滑肌","心肌和骨骼肌","平滑肌和消化腺","脑和心肌","肾和肾上腺"],"a":3,"e":"脑组织几乎完全依赖葡萄糖的有氧氧化供能，心肌也以有氧氧化为主，二者对缺氧极为敏感。骨骼肌在剧烈运动时可依靠糖酵解供能，平滑肌和消化腺、肾与肾上腺的供能方式并非以糖有氧氧化为最主要特征。故脑和心肌是主要依靠糖有氧氧化供能的器官"},{"q":"静脉注射肝素所引起的体内抗凝作用大于其体外抗凝作用，这主要是因为肝素","o":["体外迅速灭活","在体内增强抗凝血酶的活性","在体内抑制凝血因子的产生","在体内促进抗凝血酶的产生","在体外与抗凝血酶的亲和性低"],"a":1,"e":"肝素主要与抗凝血酶Ⅲ结合并使其构象改变，显著增强其对凝血因子Ⅱa、Ⅹa等的灭活作用，体内抗凝血酶活性被充分放大，故体内抗凝作用强于体外。A项肝素体内并不迅速灭活；C项不抑制凝血因子的产生；D项不促进抗凝血酶的生成而是增强其活性；E项体外抗凝同样依赖抗凝血酶，并非亲和性低"},{"q":"体外受精-胚胎移植的辅助生育技术中，以下不属于应用高效GnRH激动剂目的的是","o":["使腺垂体FSH分泌大量增加","促进卵泡颗粒分泌大量雌激素","使卵泡颗粒细胞FSH受体表达增加","使腺垂体内源性FSH分泌减少","促进卵泡发育成熟"],"a":3,"e":"辅助生殖中用高效GnRH激动剂，是利用其初期兴奋垂体的效应使FSH分泌大量增加，进而促进卵泡颗粒细胞分泌雌激素、上调FSH受体表达并促进卵泡发育成熟。使腺垂体内源性FSH分泌减少是长期连续应用后的降调节效应，并非本题所述应用目的，故为答案"},{"q":"巨大爆炸声响时，迅速张口有利于保护","o":["前庭膜","鼓膜","基底膜","蜗窗膜","耳蜗"],"a":1,"e":"巨大声响使外耳道压力骤增，迅速张口使咽鼓管开放，平衡鼓膜两侧压力，避免鼓膜因压差过大而破裂。C项基底膜为耳蜗内感音结构，不直接承受经外耳道传来的压差；A项前庭膜、D项蜗窗膜位于内耳，E项耳蜗为整体器官，张口动作的保护作用集中体现于直接承受声波压力的鼓膜"},{"q":"下列各项中，不是冠脉循环特点的是","o":["平静状态下冠脉血流量可占心输出量的4%～5%","心肌的摄氧率可比其他器官高30%","剧烈运动时，心肌主要依靠提高从单位血液中摄氧的潜力来满足心肌对氧的需求","心肌深层的冠脉血管可由于心脏的收缩而出现断流甚至逆流","左心室的冠脉血流量一般大于右心室"],"a":2,"e":"心肌安静时摄氧率已高达70%～80%，剧烈运动时进一步增加摄氧的潜力有限，主要依靠冠脉血流量显著增加来满足需氧，故该项错误。平静时冠脉血流约占心输出量4%～5%；心肌深层血管受收缩压迫可断流甚至逆流；左心室壁厚、代谢率高，冠脉血流量大于右心室，均为冠脉循环特点"},{"q":"红细胞表面积与体积比值的下降可引起红细胞","o":["变形性增强","渗透脆性增大","悬浮稳定性增强","对低渗盐溶液的抵抗力增强","血红蛋白含量增加"],"a":1,"e":"红细胞表面积与体积比值下降时，细胞趋于球形，对低渗盐溶液的抵抗力减弱，渗透脆性增大，易发生膨胀破裂溶血。变形性增强（A项）错误，球形红细胞变形能力下降；悬浮稳定性增强（C项）错误，与叠连相关；对低渗抵抗力增强（D项）与脆性增大相反；血红蛋白含量增加（E项）与表面积体积比无关"},{"q":"下列哪项与血-睾屏障的功能无关","o":["对生精细胞具有保护作用","营造精子生成所需的微环境","防止抗精子自身免疫反应","参与雄激素合成和分泌","对生精细胞的支持作用"],"a":3,"e":"血-睾屏障由支持细胞间的紧密连接等构成，可保护生精细胞、营造适宜的微环境、防止精子抗原引发自身免疫反应，并对生精细胞起支持作用。雄激素由睾丸间质细胞合成和分泌，与支持细胞形成的血-睾屏障无直接关系，故该项与血-睾屏障功能无关"},{"q":"骨骼肌收缩时释放到肌浆中的钙离子，主要被何处的钙泵转运","o":["横管","肌膜","线粒体膜","肌质网膜","高尔基体膜"],"a":3,"e":"骨骼肌收缩时胞质Ca2+来自肌质网释放，舒张时由肌质网膜上的钙泵将Ca2+主动泵回肌质网，故钙泵位于肌质网膜。横管（A项）传导动作电位；肌膜（B项）为细胞膜的兴奋部位；线粒体膜（C项）钙摄取次要；高尔基体膜（E项）与钙稳态无关"},{"q":"神经激素是","o":["作用于神经细胞的激素","具有酶功能的神经递质","神经内分泌细胞分泌的激素","具有神经功能的激素","使神经兴奋的激素"],"a":2,"e":"神经激素指由神经内分泌细胞合成并分泌的激素，如丘脑下部神经元，经轴突运输释放入血，如抗利尿激素、催产素等。作用于神经细胞的激素、具有酶功能的递质、使神经兴奋的激素均非其定义，关键在于分泌细胞为神经内分泌细胞"},{"q":"下列哪种激素促进胰岛素分泌的作用最为明显","o":["生长抑素","糖皮质激素","抑胃肽","甲状腺激素","生长激素"],"a":2,"e":"抑胃肽即葡萄糖依赖性促胰岛素释放肽，由小肠黏膜K细胞分泌，在口服葡萄糖时能强力促进胰岛素释放，作用最为明显。生长抑素抑制胰岛素分泌；糖皮质激素、甲状腺激素与生长激素虽可影响糖代谢并间接促进分泌，但促胰岛素作用不及抑胃肽直接而显著"},{"q":"如果外周阻力不变，每搏输出量增大，则动脉血压的变化为","o":["收缩压升高，舒张压降低","收缩压不变，舒张压升高","收缩压升高，舒张压不变","收缩压升高比舒张压升高更明显","舒张压升高比收缩压升高更明显"],"a":3,"e":"每搏输出量增大时收缩期主动脉内血量增加、管壁被牵张更明显，收缩压显著升高；舒张期因外周阻力和心率不变，血液流向外周加快，舒张压升高幅度较小，故收缩压升高更明显、脉压增大。A项舒张压并非降低；B、C项只描述单一变化不全面；E项的对应关系见于外周阻力增大时"},{"q":"下列不是促胰液素作用的是","o":["促进胃酸分泌","促进胰液中水和HCO3-的大量分泌","促进肝细胞分泌胆汁","促进小肠液的分泌","保护小肠黏膜"],"a":0,"e":"促胰液素由十二指肠S细胞分泌，主要促进胰液水和HCO3-大量分泌，并促进胆汁、小肠液分泌及保护小肠黏膜，同时抑制胃酸分泌与胃排空，故促进胃酸分泌不是其作用。B项促胰液HCO3-分泌、C项促胆汁分泌、D项促小肠液分泌、E项保护黏膜均为正确作用，该项与其抑制胃酸的实际效应相反"},{"q":"关于胰岛素分泌调节的叙述，错误的是","o":["血糖降低时胰岛素分泌增加","进食时肠道抑胃肽分泌，促进胰岛素分泌","胰高血糖素直接或间接的促进胰岛素分泌","迷走神经兴奋时分泌增加，交感神经兴奋时分泌减少","胰生长抑素在胰岛局部发挥，抑制胰岛素分泌"],"a":0,"e":"血糖浓度是调节胰岛素分泌的最主要因素，血糖升高时分泌增加、降低时分泌减少，故血糖降低时胰岛素分泌增加的说法错误。进食时肠道抑胃肽分泌促进胰岛素释放，胰高血糖素也可直接或间接促进其分泌，迷走兴奋促进而交感兴奋抑制，生长抑素在胰岛局部抑制胰岛素分泌，均为正确描述"},{"q":"父母一方为A型，另一方为B型，其子女可能的血型为","o":["只有AB型","只有A型或B型","只可能是A型、B型、AB型","A型、B型、AB型、O型都有可能","只可能是AB型或O型"],"a":3,"e":"若父母双方血型基因型分别为Ai和Bi，则子女可分别获得A、B、i、AB等基因组合，表现型可为A型、B型、AB型或O型，四种血型均可能出现。只可能为AB型、只为A型或B型、只限A/B/AB型或只限AB型或O型的说法都忽略了双方为杂合子时可产生O型子女的情况"},{"q":"关于简化眼模型的叙述正确的是","o":["正常人眼在视近物时成像情况的模型","简化眼的角膜前面至节点的距离为15mm","平行光线经过一次折射被聚焦于视网膜上","由曲率半径为15mm的单球面折光体构成","简化眼中单球面的曲率半径为20mm"],"a":2,"e":"简化眼是假想的单球面折光模型，曲率半径约5mm，折光指数1.333，平行光线经一次折射后聚焦在后主焦点，恰位于视网膜处，用于计算视网膜像大小。它模拟的是正常眼视远物（未调节）时的成像，而非视近物。角膜前面至节点约5mm而非15mm，单球面曲率半径也不是15mm或20mm"},{"q":"正常人红细胞在不同浓度的低渗盐溶液中形态不同。在0、5%NaCl溶液中红细胞的形态是","o":["正常","膨胀","缩小","破裂","先缩小后破裂"],"a":1,"e":"0.9%NaCl为等渗溶液，0.5%NaCl属低渗，红细胞吸水膨胀但尚未破裂，故呈膨胀形态。等渗时红细胞形态正常；更低渗约0.45%以下才发生破裂溶血，先缩小后破裂见于高渗转低渗的过程，均非0.5%NaCl下的表现"},{"q":"治疗严重哮喘发作喘息，医生应使用","o":["α1-肾上腺素能受体拮抗剂","β1-肾上腺素能受体拮抗剂","β2-肾上腺素能受体激动剂","M-胆碱能受体激动剂","N-胆碱能受体激动剂"],"a":2,"e":"β2肾上腺素能受体激动剂可激动支气管平滑肌上的β2受体，激活腺苷酸环化酶使平滑肌舒张，迅速缓解支气管痉挛，是治疗哮喘发作的首选。α1受体拮抗剂和β1受体拮抗剂无舒张支气管作用，β1拮抗剂还可能加重痉挛；M胆碱受体激动剂使支气管收缩，N受体激动剂亦无效"},{"q":"调节人体生理功能的生物信息传递系统包括","o":["神经系统和免疫系统","内分泌系统和免疫系统","神经系统和内分泌系统","中枢神经系统和外周神经系统","第一信号系统和第二信号系统"],"a":2,"e":"调节人体生理功能的生物信息传递系统主要是神经系统和内分泌系统，前者以电信号和神经递质快速传递信息，后者以激素经体液远距离传递信息，二者相互配合。中枢与外周神经系统只是神经系统的分部，免疫系统的归属另论，第一、第二信号系统属于大脑皮层功能概念，均不构成这两大传递系统"},{"q":"胃蛋白酶原转变为胃蛋白酶的激活物是","o":["Cl-","Na+","K+","HCl","内因子"],"a":3,"e":"胃蛋白酶原在盐酸作用下切去一小段肽而活化为胃蛋白酶，盐酸同时为其提供酸性作用环境。Cl-、Na+、K+等单纯离子不具有激活胃蛋白酶原的作用；内因子由壁细胞分泌，其作用是结合维生素B12促进回肠吸收，与胃蛋白酶原活化无关"},{"q":"交感和副交感神经的作用不表现对抗效应的器官是","o":["小肠腺","膀胱逼尿肌","唾液腺","心脏","消化道平滑肌"],"a":2,"e":"交感与副交感对唾液腺均促进分泌，只是性质不同，副交感引起量多稀薄的唾液，交感引起量少黏稠的唾液，二者不表现为单纯的兴奋与抑制对抗。小肠腺（A项）、膀胱逼尿肌（B项）、心脏（D项）、消化道平滑肌（E项）均受双重支配且作用相互拮抗，唾液腺是例外"},{"q":"兴奋下丘脑内渗透压感受器可引起","o":["血管升压素释放增加","心房钠尿肽释放增加","血管紧张素Ⅱ合成增加","心肺感受器兴奋","肾素释放增加"],"a":0,"e":"下丘脑渗透压感受器兴奋（如血浆晶体渗透压升高）促使视上核、室旁核合成并经神经垂体释放血管升压素，促进肾集合管重吸收水。B项心房钠尿肽由心房肌细胞分泌，受容量扩张刺激；C项血管紧张素Ⅱ、E项肾素释放在肾灌注压下降时激活；D项心肺感受器兴奋属容量感受机制，渗透压感受器兴奋不引起这些反应"},{"q":"A型标准血清与B型血液混合时可引起","o":["血液凝固","红细胞凝集","红细胞叠连","红细胞收缩","无反应"],"a":1,"e":"A型标准血清含抗B凝集素，B型血红细胞表面含B凝集原，二者相遇发生特异性抗原抗体反应，使红细胞凝集成团。血液凝固是可溶性纤维蛋白原转变为纤维蛋白的过程，与血型不合无关；红细胞叠连主要与血浆成分改变有关，收缩和无反应均不符合抗原抗体凝集规律"},{"q":"实验切断双侧颈迷走神经后，兔的呼吸","o":["频率加快，幅度减小","频率加快，幅度增大","频率和幅度均不变","频率减慢，幅度减小","频率减慢，幅度增大"],"a":4,"e":"切断双侧颈迷走神经后，肺牵张反射即黑伯反射的传入通路中断，吸气不能及时终止而延长，使呼吸变慢变深，表现为频率减慢、幅度增大。A项频率加快幅度减小、B项频率加快幅度增大、C项频率与幅度不变、D项频率减慢幅度减小，均与迷走神经切断后呼吸深而慢的典型改变不符"},{"q":"可由神经细胞分泌的激素是","o":["缩宫素","卵泡刺激素","促甲状腺激素","催乳素","甲状腺激素"],"a":0,"e":"缩宫素由下丘脑视上核、室旁核神经细胞合成，经神经垂体释放，属可由神经细胞分泌的激素。卵泡刺激素、促甲状腺激素、催乳素均由腺垂体细胞分泌，甲状腺激素由甲状腺滤泡细胞分泌，均非神经细胞所分泌"},{"q":"下列哪项是胰高血糖素的作用","o":["抑制磷脂酶C","抑制腺苷酸环化酶","抑制胰岛素的分泌","促进肝脏的糖异生","促进肌肉的糖原分解"],"a":3,"e":"胰高血糖素通过激活腺苷酸环化酶、升高cAMP，促进肝脏的糖原分解和糖异生，强烈升高血糖。它并不抑制磷脂酶C或腺苷酸环化酶，反而激活后者；对胰岛素分泌主要是促进而非抑制；肌肉因缺乏相应受体，其糖原分解不受胰高血糖素调节"},{"q":"引起抗利尿激素分泌的最重要的因素是","o":["循环血量减少","血浆晶体渗透压升高","血浆胶体渗透压升高","血浆晶体渗透压降低","血浆胶体渗透压下降"],"a":1,"e":"抗利尿激素分泌受血浆晶体渗透压与循环血量双重调节，其中血浆晶体渗透压升高是最重要因素，渗透压感受器位于下丘脑。循环血量减少需下降一定幅度才明显兴奋分泌；血浆胶体渗透压主要影响毛细血管内外水交换，其升高或下降均不是ADH分泌的主要刺激；晶体渗透压降低反而抑制分泌"},{"q":"震颤麻痹的主要症状之一是","o":["感觉迟钝","肌张力增强","意向性震颤","运动共济失调","身体平衡失调"],"a":1,"e":"震颤麻痹（帕金森病）因黑质多巴胺能神经元变性，纹状体多巴胺不足，出现肌张力增高（铅管样或齿轮样强直）、静止性震颤和运动迟缓。感觉迟钝并非其表现；意向性震颤、运动共济失调和身体平衡失调是小脑病变的典型体征，与震颤麻痹的肌张力增强机制不同"},{"q":"跨肺压是指","o":["大气压与胸廓回缩压之差","大气压与肺回缩压之差","大气压与胸膜腔内压之差","肺内压与胸膜腔内压之差","肺内压与大气压之差"],"a":3,"e":"跨肺压是肺内压与胸膜腔内压之差，是使肺扩张的有效压力，等于肺回缩压，吸气时增大、呼气时减小。大气压与胸膜腔内压之差为经胸壁压；大气压与肺回缩压之差、大气压与胸廓回缩压之差均非跨肺压；肺内压与大气压之差是驱动气流的压力差，决定气体进出方向"},{"q":"下列关于心输出量的说法错误的是","o":["心肌收缩力增强会增加心输出量","心交感神经兴奋会增加心输出量","左心室壁运动异常会增加心输出量","心输出量是每分钟左心室所泵出的血量","最大心输出量与安静时心输出量之差等于心力贮备"],"a":2,"e":"左心室壁运动异常会削弱心肌收缩、降低搏出量，使心输出量减少，故该说法错误。心肌收缩力增强、心交感神经兴奋均使心输出量增加；心输出量即每分钟左心室泵出的血量；最大心输出量与安静时之差为心力贮备，均正确"},{"q":"血浆的pH值主要取决于下列哪个缓冲对","o":["碳酸氢钾/碳酸","磷酸氢二钾/磷酸二氢钾","碳酸氢钠/碳酸","磷酸氢二钠/磷酸二氢钠","蛋白质-钠盐/蛋白质"],"a":2,"e":"血浆中最重要的缓冲对是碳酸氢钠/碳酸（NaHCO3/H2CO3），其比值保持在20∶1左右，是维持血浆pH约7.4的主要缓冲系统。碳酸氢钾/碳酸及磷酸盐缓冲对在血浆中作用较小，磷酸盐缓冲对主要在肾小管液中发挥作用，蛋白质钠盐缓冲对的重要性不及碳酸氢盐系统"},{"q":"下列关于传入侧支性抑制的描述，正确的是","o":["神经元传入侧支与自身形成负反馈回路","传入纤维的主干与侧支释放不同的递质","通过交互性突触而产生交互抑制的作用","这种抑制形式仅发生于脊髓，脑内不存在","作用意义在于保证伸肌和屈肌活动的协调控制"],"a":4,"e":"传入侧支性抑制是感觉传入纤维进入中枢后发出侧支，兴奋抑制性中间神经元，进而抑制另一中枢神经元，其生理意义在于保证伸肌与屈肌活动的协调控制。与自身形成负反馈回路（A项）实为回返性抑制的特点；主干与侧支释放不同递质（B项）无依据；仅发生于脊髓（D项）错误，脑内同样存在"},{"q":"下列哪种激素可促进的1,25-(OH)2-D3的形成","o":["PTH","三碘甲腺原氨酸","四碘甲腺原氨酸","CT","TSH"],"a":0,"e":"甲状旁腺素可激活肾脏1α-羟化酶，促进25-羟维生素D3进一步羟化为活性形式1,25-(OH)2-D3（钙三醇），从而增强小肠对钙的吸收。B项三碘甲腺原氨酸、C项四碘甲腺原氨酸为甲状腺激素；D项降钙素降低血钙，作用与PTH拮抗；E项TSH调节甲状腺，均不促进钙三醇生成"},{"q":"长期使用大量糖皮质激素可引起肾上腺皮质萎缩，其原因是","o":["直接使束状带与网状带细胞凋亡","负反馈抑制腺垂体分泌ACTH","促进肾上腺皮质细胞蛋白质分解","抑制肾上腺皮质细胞蛋白质合成","促进肾上腺皮质细胞脂肪分解"],"a":1,"e":"长期大量外源性糖皮质激素通过负反馈抑制腺垂体分泌ACTH，使肾上腺皮质束状带、网状带因缺乏ACTH的营养作用而萎缩。激素并非直接诱导皮质细胞凋亡，也不是通过促进蛋白质或脂肪分解、抑制蛋白质合成致萎缩；这些代谢效应是糖皮质激素的全身作用，与皮质萎缩机制无关"},{"q":"耳蜗螺旋器毛细胞的听毛发生弯曲时，可产生","o":["耳蜗静息电位","耳蜗微音器电位","行波运动","动作电位","内淋巴电位"],"a":1,"e":"耳蜗螺旋器毛细胞听毛弯曲时，机械门控离子通道开放，产生随声波频率与振幅变化的感受器电位即耳蜗微音器电位，是毛细胞产生动作电位的前奏。A项耳蜗静息电位为静息时膜电位；C项行波运动是基底膜的机械振动；D项动作电位由听神经产生；E项内淋巴电位为内淋巴与外淋巴间固有的电位差"},{"q":"血细胞的细胞外液是指","o":["体液","细胞内液","细胞外液","血浆","血液"],"a":3,"e":"血细胞悬浮于血浆中，血浆即血细胞直接生活的内环境，是血细胞的细胞外液。A项体液泛指体内所有液体过于宽泛；B项细胞内液位于细胞内部；C项细胞外液是包括血浆、组织液在内的总称不够具体；E项血液由血浆和血细胞组成，不是血细胞的细胞外液本身"},{"q":"以下哪种不是前列腺素主型","o":["PGA","PGC","PGE","PGG","PGJ"],"a":4,"e":"前列腺素按五元环结构分为A、B、C、D、E、F、G、H、I等主型，J型并非公认的主型分类。PGA、PGC、PGE、PGG均为教材列出的基本类型，其中PGG、PGH为环氧合酶途径生成的环内过氧化物中间体，PGJ多为PGD2的代谢产物，故不属主型"},{"q":"内环境中最活跃的部分是","o":["组织液","血浆","细胞内液","脑脊液","淋巴液"],"a":1,"e":"内环境即细胞外液，包括血浆、组织液和淋巴液等，其中血浆因不断循环流动、沟通各组织器官与外界，成为物质交换最活跃的部分。组织液是细胞直接浸浴的环境但相对局限；细胞内液不属于内环境；脑脊液与淋巴液流动性均不及血浆"},{"q":"高浓度降钙素迅速降低血钙水平的作用环节是","o":["抑制肾小管对钙的重吸收","抑制破骨细胞溶骨活动","刺激骨细胞的分化","甲状旁腺激素分泌减少","减少小肠吸收钙"],"a":1,"e":"降钙素主要通过抑制破骨细胞的溶骨活动，减少骨吸收和骨钙动员，迅速降低血钙。抑制肾小管重吸收钙、减少小肠吸收钙作用较弱且缓慢。刺激骨细胞分化与降钙素作用不符；甲状旁腺激素为升钙激素，其分泌减少并非降钙素快速降钙的直接环节"},{"q":"可抑制血小板聚集的物质是","o":["ADP","TXA2","PGI2","胶原","凝血酶"],"a":2,"e":"前列环素PGI2由血管内皮生成，升高血小板内cAMP，抑制血小板聚集。ADP、血栓素A2、胶原与凝血酶均为促进血小板黏附聚集的重要物质，作用方向相反"},{"q":"剧烈运动中，骨骼肌温度的升高将对氧解离曲线产生的影响是","o":["无影响","左移，从而减少骨骼肌毛细血管中氧的释放","右移，从而减少骨骼肌毛细血管中氧的释放","左移，从而增加骨骼肌毛细血管中氧的释放","右移，从而增加骨骼肌毛细血管中氧的释放"],"a":4,"e":"温度升高使血红蛋白与氧的亲和力降低，氧解离曲线右移，在同样氧分压下氧饱和度下降，从而增加骨骼肌毛细血管中氧的释放，满足剧烈运动时的供氧需求。曲线左移表示亲和力升高、氧释放减少，与温度升高效应相反；无影响的说法亦不符合温度对氧解离曲线的影响规律"},{"q":"关于胰腺分泌HCO3-的叙述，错误的是","o":["由胰腺内小导管上皮细胞分泌","缩胆囊素可引起大量分泌","可防止盐酸对十二指肠黏膜的侵蚀","可为胰酶提供适宜的作用环境","迷走神经兴奋引起胰液分泌的特点是HCO3-较少"],"a":1,"e":"胰液中HCO3-由胰腺内小导管上皮细胞分泌，可中和进入十二指肠的盐酸、保护黏膜并为胰酶提供碱性环境，促胰液素是刺激其大量分泌的最强因素。B项称缩胆囊素引起大量HCO3-分泌错误，缩胆囊素主要促进腺泡细胞分泌胰酶，对HCO3-作用弱。E项迷走神经兴奋引起的胰液特点是酶多而HCO3-和水量少，表述正确"},{"q":"自主神经系统活动的特点是","o":["自主神经系统的活动与效应器本身的功能状态有关","自主神经系统根据主观意识对效应器官发放不同频率的冲动","交感和副交感对组织器官的支配作用往往相互协同","交感神经系统的活动一般比较广泛，不同部分的交感神经对相同刺激的反应方式和程度相同","副交感神经系统的活动一般比较广泛"],"a":0,"e":"自主神经系统的活动效应受效应器本身功能状态影响，同一递质作用于不同器官可产生不同甚至相反效应，故活动与效应器状态有关。B项自主神经不受主观意识直接控制；C项交感和副交感对多数器官作用相互拮抗而非协同；D项交感虽广泛但不同部位反应方式程度各异；E项副交感支配局限，活动广泛的是交感神经"},{"q":"催化花生四烯酸转变为廿烷酸衍生物的关键酶是","o":["环加氧酶","磷脂酶A2","磷脂酶C","血栓烷合成酶","前列环素合成酶"],"a":0,"e":"环加氧酶即COX催化花生四烯酸生成前列腺素类等廿烷酸衍生物，是花生四烯酸代谢的关键限速酶，也是阿司匹林等非甾体抗炎药的作用靶点。B项磷脂酶A2作用于膜磷脂释放花生四烯酸，位于COX上游；C项磷脂酶C水解PIP2产生IP3和DAG；D项血栓烷合成酶、E项前列环素合成酶催化下游特定产物，均非关键共同起步酶"},{"q":"血流阻力主要来自","o":["大动脉","小动脉、微动脉","中动脉","微静脉","毛细血管"],"a":1,"e":"血流阻力与血管半径四次方成反比，小动脉和微动脉管径小、管壁平滑肌丰富，是形成外周阻力的主要部位，其舒缩显著影响动脉血压。大动脉和中动脉主要起弹性储器和输送作用，微静脉和毛细血管的阻力较小，均不是血流阻力的主要来源"},{"q":"利用动物实验，如何来证明颈动脉窦压力感受性反射是负反馈调节","o":["注射去甲肾上腺素，引起血压升高","注射肾上腺素，引起心率加快","注射ACh，引起血压下降","刺激迷走神经，引起血压下降","分离颈动脉窦，改变窦内压，观察动物血压的变化"],"a":4,"e":"分离颈动脉窦并人工改变窦内压，观察体循环血压随之反向变化，是证明压力感受性反射属于负反馈的经典方法：窦内压升高则血压下降，窦内压降低则血压升高。静脉注射去甲肾上腺素或ACh只是改变血压，不能直接证明该反射的负反馈性质；刺激迷走神经同样无法隔离窦内压变量"},{"q":"全血的黏滞性主要取决于","o":["血浆蛋白含量","血细胞比容","白细胞数量","红细胞的叠连","NaCl的浓度"],"a":1,"e":"全血的黏滞性主要取决于血液中红细胞所占容积比例即血细胞比容，比容越高红细胞越多，血液黏滞性越大。血浆蛋白含量主要影响血浆黏滞性；白细胞数量很少，影响极小；红细胞叠连影响血沉而非全血黏滞性；NaCl浓度主要通过影响红细胞形态间接起作用"},{"q":"衡量肺通气潜能的指标是","o":["肺通气量","肺泡通气量","用力肺活量","用力呼气量","通气储量百分比"],"a":4,"e":"通气储量百分比等于最大通气量减去平静通气量再除以最大通气量，反映肺通气功能的储备能力，是衡量通气潜能的指标。A项肺通气量、B项肺泡通气量仅反映平静状态的通气量；C项用力肺活量与D项用力呼气量主要评价气道通畅性与呼气功能，不直接表示通气的储备能力"},{"q":"关于神经胶质细胞生理作用的描述中，错误的是","o":["小胶质细胞可清除受损的神经组织碎片","星形胶质细胞可稳定细胞外钾离子浓度","星形胶质细胞参与构成血-脑屏障","施万细胞参与形成髓鞘","成熟的神经胶质细胞不具有增殖的能力"],"a":4,"e":"成熟的神经胶质细胞终身保持分裂增殖能力，中枢神经系统损伤后胶质细胞可增生形成瘢痕，故不具有增殖能力错误。小胶质细胞可清除受损组织碎片；星形胶质细胞稳定细胞外K+并参与构成血-脑屏障；施万细胞在外周形成髓鞘，均正确"},{"q":"感受器能把刺激所包含的环境变化信息，转移到新的电信号系统中，感受器的这种生理特性称为","o":["感受器适宜刺激","感受器换能作用","感受器编码作用","感受器适应现象","感受器的启动电位"],"a":2,"e":"感受器把刺激所包含的环境变化信息转移到动作电位序列和组合这一新的电信号系统中，称为编码作用，实现刺激性质与强度的信息表达。换能作用（B项）是把刺激能量转换为感受器电位；适宜刺激（A项）指最敏感刺激形式；适应现象（D项）指持续刺激下反应减弱；启动电位（E项）为感受器电位，均非信息转移过程"},{"q":"下列哪种情况能使肺的静态顺应性增加","o":["呼吸膜增厚","气道阻力减小","肺惯性阻力减小","肺弹性阻力减小","肺表面活性物质减少"],"a":3,"e":"肺顺应性与弹性阻力成反比，肺弹性阻力减小时，相同跨肺压变化引起的肺容积变化增大，静态顺应性增加。呼吸膜增厚（A项）增加弥散距离；气道阻力（B项）、肺惯性阻力（C项）属非弹性阻力，不影响静态顺应性；肺表面活性物质减少（E项）使弹性阻力增大、顺应性降低"},{"q":"在血液中影响PTH分泌的最关键元素是","o":["磷","钙","镁","钠","氯"],"a":1,"e":"甲状旁腺主细胞通过钙敏感受体感受血钙，低钙刺激PTH分泌、高钙抑制其分泌，故钙是影响PTH分泌最关键的元素。A项磷可间接影响PTH但作用次于钙；C项镁严重缺乏亦可影响PTH但并非常规主导；D项钠、E项氯与PTH分泌调节关系不大，血钙才是最核心的调节因素"},{"q":"下列物质中属于类固醇激素的是","o":["促甲状腺激素","生长激素","生长激素介质","甲状旁腺素","糖皮质激素"],"a":4,"e":"糖皮质激素由肾上腺皮质束状带分泌，属类固醇激素，脂溶性，通过胞内受体调控基因表达。A项促甲状腺激素、B项生长激素、D项甲状旁腺素均为含氮的肽或蛋白质类激素；C项生长激素介质即IGF-1为肽类，它们均非类固醇激素"},{"q":"下列哪种肺容量在严重哮喘病患者降低最为显著","o":["肺活量","肺容量","用力呼气量","深吸气量","补呼气量"],"a":2,"e":"严重哮喘属阻塞性通气障碍，呼气时小气道塌陷、阻力增高，用力呼气量尤其是第一秒用力呼气量下降最为显著，是判断气道阻塞程度的重要指标。肺活量和深吸气量下降不如用力呼气量明显，补呼气量改变较小，肺容量并非具体测定指标"},{"q":"在心动周期中，下列哪一时期的左心房压最大","o":["快速充盈期末","减慢充盈期末","等容舒张期末","快速射血期末","减慢射血期末"],"a":2,"e":"等容舒张期末房室瓣即将开放，此前左心房持续接受肺静脉回流血液而心室尚未充盈，房内血液积聚最多、压力升至最高。A项快速充盈期、B项减慢充盈期房室瓣开放、血液流入心室，房压下降；D项快速射血期末、E项减慢射血期末为心室收缩期，心房非压力最高时刻"},{"q":"保持脑脊液中H+浓度不变而升高脑脊液PCO2，呼吸将会发生什么改变","o":["呼吸变快加深","呼吸变浅变慢","呼吸没有明显变化","呼吸暂停","长吸式呼吸"],"a":2,"e":"中枢化学感受器对CO2敏感，但CO2需进入脑脊液生成H+才发挥刺激作用；若保持脑脊液H+浓度不变，单纯升高PCO2不再兴奋中枢化学感受器，呼吸无明显变化。呼吸变快加深（A项）为H+升高时的反应；变浅变慢（B项）、呼吸暂停（D项）、长吸式呼吸（E项）均与保持H+不变的条件不符，外周化学感受器在此不占主导"},{"q":"根据Laplace定律，大小不一的肺泡彼此相通，且表面张力相等，则导致","o":["小肺泡内压力大，大肺泡内压力小","小肺泡内压力小，大肺泡内压力大","大小肺泡内压力相等","吸气时气体主要进入小肺泡","呼气时气体主要出自大肺泡"],"a":0,"e":"按Laplace定律P=2T/r，表面张力相等时肺泡半径越小，囊内压越大，故小肺泡内压力大、大肺泡内压力小，气体趋于从小泡流向大泡致小泡萎陷。气体不会主要进入小泡；呼气时气体主要出自小泡而非大泡"},{"q":"丘脑的特异投射系统的主要作用是","o":["协调肌紧张","维持觉醒","调节内脏功能","引起特定的感觉","引起牵涉痛"],"a":3,"e":"丘脑特异投射系统投射至大脑皮层特定感觉区，引起特定的感觉并激发皮层发出传出冲动。维持觉醒属脑干网状结构上行激动系统即非特异投射系统的功能；协调肌紧张、调节内脏功能由其他中枢完成；牵涉痛为内脏感觉的定位特点"},{"q":"促胰液素的主要作用是","o":["促进胃酸分泌","刺激胰液中碳酸氢盐分泌","促进胰液中胰酶分泌","促进胆汁分泌","促进胃蛋白酶分泌"],"a":1,"e":"促胰液素由十二指肠S细胞在盐酸刺激下释放，主要作用于胰腺导管细胞，促进分泌水和碳酸氢盐，胰液量大而含酶少。促进胰酶分泌主要是缩胆囊素的作用；促胰液素抑制而非促进胃酸及胃蛋白酶分泌；其促胆汁分泌作用较弱，并非主要功能"},{"q":"颗粒细胞的主要功能是","o":["感受小管液氢离子浓度的变化","感受小管液NaCl浓度的变化","参与球-管平衡","释放血管紧张素原","释放肾素"],"a":4,"e":"球旁器的颗粒细胞（球旁细胞）是入球小动脉壁上的上皮样细胞，主要功能是合成、储存并释放肾素，启动肾素-血管紧张素-醛固酮系统，参与血压与水盐平衡调节。感受小管液氢离子（A项）非其主要功能；感受NaCl浓度（B项）为致密斑；球-管平衡（C项）为近端小管特性；血管紧张素原（D项）由肝脏产生"},{"q":"调节体温的基本中枢在","o":["脊髓","延髓","下丘脑","脑干网状结构","大脑皮质"],"a":2,"e":"体温调节的基本中枢位于下丘脑，其视前区-下丘脑前部含温度敏感神经元，整合中枢与外周温度信息并维持调定点。延髓（B项）为呼吸与心血管活动中枢；脑干网状结构（D项）主要参与觉醒与肌紧张调节；脊髓（A项）仅完成初级体温反射；大脑皮质（E项）参与行为性体温调节，均非基本中枢"},{"q":"在体温调节中起调定点作用的可能是","o":["脊髓温度敏感神经元","延髓温度敏感神经元","网状结构温度敏感神经元","丘脑温度敏感神经元","PO/AH中的温度敏感神经元"],"a":4,"e":"视前区-下丘脑前部（PO/AH）的温度敏感神经元尤热敏神经元在体温调节中起调定点作用，体温偏离时通过反馈调节产热与散热。A项脊髓、B项延髓、C项网状结构、D项丘脑的温度敏感神经元参与温度信息感受与整合，但调定点主要位于PO/AH"},{"q":"当血流流经下列哪一部分时，血压降落最大","o":["主动脉和大动脉","小动脉和微动脉","微静脉和小静脉","大静脉和腔静脉","毛细血管"],"a":1,"e":"血流阻力与血管半径四次方成反比，小动脉和微动脉管径小、阻力大，是外周阻力的主要来源，血液流经时压力降落最大。主动脉和大动脉（A项）为弹性贮器，阻力小；微静脉和小静脉（C项）、大静脉和腔静脉（D项）阻力较小；毛细血管（E项）总横截面积大，压力降落有限"},{"q":"目前已有临床研究采用小剂量、间歇性应用甲状旁腺激素治疗女性骨质疏松，是由于这种给药方法可以","o":["使破骨活动增强","促进骨的吸收","促进成骨细胞凋亡","抑制前成骨细胞继续分化为成骨细胞","使成骨细胞活动增强，促进骨形成，骨量增加"],"a":4,"e":"小剂量、间歇性给予甲状旁腺激素可增强成骨细胞活性、促进骨形成并使骨量增加，故用于骨质疏松治疗。持续大剂量PTH则以促进破骨细胞活动、骨吸收为主；促进成骨细胞凋亡、抑制前成骨细胞分化均会减少骨形成，与该给药改善骨量的效应相反"},{"q":"产生兴奋性突触后电位（EPSP）的主要机制是","o":["突触前末梢递质释放增多","需由中间神经元中介","突触后膜K+电导降低","突触后膜Na+电导增加","突触后神经元受刺激而兴奋"],"a":3,"e":"兴奋性递质与后膜受体结合后使Na+电导增加，Na+内流为主，后膜去极化形成EPSP，故突触后膜Na+电导增加为主要机制。突触前递质释放增多是前提而非后膜机制；EPSP不一定需中间神经元中介；K+电导降低、突触后神经元受刺激兴奋均非EPSP的形成机制"},{"q":"下列脑电波中，频率最快，波幅最小的是","o":["α波","β波","θ波","δ波","棘慢波"],"a":1,"e":"β波频率约14～30次/秒，是脑电波中频率最快、波幅最小的一种，见于清醒安静、睁眼或精神紧张状态。α波频率较慢、波幅较大，见于闭目安静；θ波和δ波频率更慢、波幅更大，多见于困倦和深睡；棘慢波为异常脑电，均不符合频率最快、波幅最小的特征"},{"q":"副交感神经兴奋时，可引起","o":["瞳孔散大","汗腺分泌","胰岛素分泌","糖原分解增加","骨骼肌血管舒张"],"a":2,"e":"副交感神经兴奋促进胰岛素分泌、胃肠运动和消化液分泌，并使瞳孔缩小。瞳孔散大、汗腺分泌、糖原分解增加均为交感神经兴奋的效应；骨骼肌血管舒张主要由交感舒血管纤维或局部代谢因素引起"},{"q":"除了大量的水和无机盐外，下列哪项不属于唾液的成分","o":["唾液淀粉酶","黏蛋白","溶菌酶","尿素和尿酸","内因子"],"a":4,"e":"唾液除水和无机盐外，含唾液淀粉酶、黏蛋白、溶菌酶以及少量尿素、尿酸等代谢废物。内因子是胃腺壁细胞分泌的糖蛋白，作用为保护维生素B12并促进其在回肠吸收，不存在于唾液中，故为答案"},{"q":"关于受体的叙述，下列哪一项是错误的","o":["胆碱能受体包括M型和N型","肾上腺素能受体包括α型和β型","N型受体与乙酰胆碱结合后使骨骼肌收缩","M型受体与乙酰胆碱结合后使心脏活动增强","α型受体与去甲肾上腺素结合后使血管平滑肌收缩"],"a":3,"e":"心肌主要表达M2型胆碱能受体，ACh与之结合后使心率减慢、收缩减弱、传导减慢，即心脏活动受抑制，故M型受体使心脏活动增强一项错误。胆碱能受体分M、N型，肾上腺素能受体分α、β型，N型受体激动使骨骼肌收缩，α型激动使血管收缩，均正确"},{"q":"关于中枢兴奋传播特征的描述，错误的是","o":["单向传递","对内环境变化敏感","不衰减传递","兴奋节律可发生变化","易发生疲劳"],"a":2,"e":"中枢兴奋经突触传递，因突触延搁、总和及递质释放的易变性，信号幅度可发生改变，并非不衰减；不衰减传导是神经纤维动作电位的特点。单向传递指兴奋只能由突触前传向突触后，对内环境变化敏感、易疲劳与兴奋节律改变均为突触传递的特征。故不衰减传递不属于中枢兴奋传播特征"},{"q":"盆神经受损后，排尿功能障碍的表现是","o":["多尿","少尿","尿失禁","尿潴留","尿频"],"a":3,"e":"盆神经为支配膀胱的副交感神经，兴奋时使逼尿肌收缩、内括约肌舒张，促进排尿。盆神经受损后排尿反射传出通路中断，逼尿肌不能收缩，导致尿潴留。B项少尿、A项多尿为尿量生成异常；C项尿失禁多见于括约肌损伤或高位脊髓损伤早期；E项尿频为膀胱刺激征"},{"q":"肾上腺皮质功能不足的患者，排出水分的能力大为减弱，可出现“水中毒”，补充下列哪种激素可缓解症状","o":["胰岛素","糖皮质激素","醛固酮","肾上腺素","胰高血糖素"],"a":1,"e":"肾上腺皮质功能不全时糖皮质激素缺乏，机体排水能力减弱，易发生水中毒，补充糖皮质激素可恢复排水能力、缓解症状。A项胰岛素、E项胰高血糖素调节糖代谢；C项醛固酮主要调节钠钾平衡，缺乏致失钠；D项肾上腺素为髓质激素，均不能纠正该排水障碍"},{"q":"大脑皮层处于紧张活动时脑电活动主要表现为","o":["α波","β波","δ波","棘波","θ波"],"a":1,"e":"大脑皮层紧张活动、觉醒状态时脑电以β波为主，频率14至30赫兹、波幅低，表示皮层兴奋。A项α波为安静闭眼时的觉醒脑电；C项δ波为深睡眠或婴儿脑电；E项θ波见于困倦与浅睡；D项棘波为癫痫等病理脑电，均非皮层紧张活动的主要表现"},{"q":"胃的容受性舒张的实现是通过","o":["交感神经","迷走神经","壁内神经丛","抑胃肽","促胰液素"],"a":1,"e":"胃的容受性舒张由进食刺激咽、食管等处感受器，经迷走神经传入延髓再经迷走神经传出，引起胃底胃体平滑肌舒张以容纳食物，属迷走迷走反射，递质为VIP或NO。A项交感神经兴奋一般抑制胃运动但不介导容受性舒张；C项壁内神经丛参与局部反射但非主要通路；D项抑胃肽、E项促胰液素为抑制性激素，非该反射通路"},{"q":"骨髓受X射线损害将导致","o":["再生障碍性贫血","缺铁性贫血","溶血性贫血","巨幼红细胞性贫血","地中海贫血"],"a":0,"e":"X射线等电离辐射损伤骨髓造血干细胞，使造血功能低下、全血细胞减少，导致再生障碍性贫血。B项缺铁性贫血源于铁缺乏致血红蛋白合成障碍；D项巨幼红细胞性贫血由叶酸或维生素B12缺乏引起DNA合成障碍；C项溶血性贫血乃红细胞破坏过多；E项地中海贫血属遗传性血红蛋白合成缺陷，均与辐射损伤无关"},{"q":"以下哪项抑制胰岛素的分泌","o":["交感神经兴奋","血中氨基酸及脂肪酸增加","抑胃肽分泌增加","迷走神经兴奋","血糖升高"],"a":0,"e":"交感神经兴奋时释放去甲肾上腺素，作用于胰岛β细胞α2受体，抑制胰岛素分泌，以适应应激状态。血中氨基酸与脂肪酸增加、抑胃肽分泌增加、迷走神经兴奋及血糖升高均通过不同途径促进胰岛素分泌，而非抑制"},{"q":"抑制性突触后电位","o":["由突触前末梢递质释放减少而产生","使突触后膜电位远离阈电位水平","由突触后膜钠电导增加而产生","由突触后膜钙电导增加而产生","是一种去极化抑制的突触后电位"],"a":1,"e":"抑制性突触后电位由抑制性递质使突触后膜Cl-电导增加、Cl-内流引起，膜电位超极化，远离阈电位水平，因而抑制突触后神经元兴奋。它并非递质释放减少所致，递质减少只会使EPSP减小；由钠或钙电导增加产生的是去极化性兴奋性电位；IPSP为超极化而非去极化抑制"},{"q":"下列哪一项不符合终板电位的特性","o":["没有“全或无”现象","由ACh受体激活引起","可以总和","呈电紧张性扩布","由钙离子内流形成"],"a":4,"e":"终板电位由ACh激活终板膜N2型受体，引起以Na+内流为主的离子流形成，并非Ca2+内流。终板电位属局部电位，无全或无现象、可总和、呈电紧张性扩布，这些均是其特征。故由钙离子内流形成一项不符合终板电位特性"},{"q":"发热开始时，病人常自感发冷、寒战，最可能的原因是","o":["产热量不足","散热量不足","调定点上移","体温调节机制障碍","皮肤血流量增加"],"a":2,"e":"发热时致热原使体温调定点上移，实际体温低于新的调定点，机体通过寒战产热、皮肤血管收缩减少散热以使体温升至新水平，故病人自感发冷。产热量不足（A项）与寒战产热增加矛盾；散热量不足（B项）是体温上升期结果而非发冷感知的原因；体温调节障碍（D项）、皮肤血流增加（E项）均不符合发热初期机制"},{"q":"下列食物的特殊动力效应最大的是","o":["糖","蛋白质","脂肪","混合食物","糖和脂肪"],"a":1,"e":"食物的特殊动力效应以蛋白质最大，进食蛋白质可使额外产热约达其本身能量的30%，源于氨基酸脱氨基及后续合成、排泄等过程的耗能。A项糖类约5%至6%、C项脂肪约4%至5%，均远低于蛋白质；D项混合食物约10%；E项糖和脂肪的特殊动力效应都很小，不能与蛋白质相比"},{"q":"下列关于神经纤维兴奋传导特征的描述，正确的是","o":["只能从胞体至末梢单向传导","神经干中各纤维之间互不干扰","只要结构完整就能正常传导兴奋","不受内环境因素变化的影响","连续刺激时，传导能力很快下降"],"a":1,"e":"神经纤维兴奋传导具有绝缘性，神经干中每条纤维各自独立传导、互不干扰，保证信息传递准确。A项单根神经纤维在刺激点可双向传导，单向性源于突触；C项传导还需正常离子梯度与代谢，结构完整不等于功能正常；D项内环境理化性质改变会影响传导；E项神经纤维不易疲劳，连续刺激仍能高频传导"},{"q":"在下列哪个平面横断脑干后仍能保持正常的呼吸节律","o":["脊髓与延髓之间","延髓与脑桥之间","脑桥中、上部之间","脑桥与中脑之间","中脑与丘脑之间"],"a":3,"e":"呼吸基本节律产生于延髓，脑桥存在调整中枢，横断脑干若保留延髓与脑桥即可维持正常呼吸节律，故脑桥与中脑之间横断仍正常。脊髓与延髓之间横断中断延髓与脊髓联系，呼吸停止；延髓与脑桥之间横断致长吸式呼吸；脑桥中上部之间横断也可致呼吸节律异常，均不能保持正常"},{"q":"胆汁的主要作用是","o":["激活胰蛋白酶原","促进淀粉水解","促进脂肪的消化和吸收","中和胃液","杀灭细菌"],"a":2,"e":"胆汁中胆盐可将脂肪乳化成微滴，增加脂肪酶作用面积，并形成混合微胶粒促进脂肪酸和甘油一酯吸收，是促进脂肪消化吸收的主要作用，胆汁本身不含消化酶。激活胰蛋白酶原的是肠激酶；促进淀粉水解的是胰淀粉酶；中和胃液主要靠胰液和肠液中的HCO3-；杀灭细菌也不是胆汁的主要功能"},{"q":"人体在寒冷中的反应有","o":["交感神经紧张性增强","皮肤血流量增加","代谢降低","甲状腺激素分泌减少","交感神经紧张性减弱"],"a":0,"e":"寒冷环境中机体通过增强交感神经紧张性，使皮肤血管收缩、血流减少以降低散热，并提高代谢率、增加甲状腺激素与儿茶酚胺分泌来增加产热。B项皮肤血流量应减少而非增加；C项代谢应增强而非降低；D项甲状腺激素分泌应增多而非减少；E项交感紧张性减弱与机体的寒冷防御反应完全相反"},{"q":"影响CO2与Hb结合生成氨基甲酰血红蛋白的主要因素是","o":["血液PO2","血液PCO2","氧化作用","氧合作用","碳酸酐酶的活性"],"a":3,"e":"CO2与血红蛋白结合生成氨基甲酰血红蛋白受氧合作用显著影响：血红蛋白氧合后与CO2结合能力下降，去氧血红蛋白结合CO2增多，故氧合作用是主要影响因素。A项血液PO2通过改变氧合状态间接起作用；B项PCO2影响CO2溶解与运输量；C项氧化作用非生理性主要因素；E项碳酸酐酶主要影响HCO3-生成"},{"q":"下列关于氯离子在近端小管重吸收的描述，正确的是","o":["主要发生在近曲小管","与碳酸氢根重吸收竞争转运体","主要通过细胞旁路重吸收","顺浓度和电位梯度而重吸收","优先于碳酸氢根的重吸收"],"a":2,"e":"近端小管前半段Na+与HCO3-、葡萄糖等同向重吸收，后半段Cl-浓度升高后主要经细胞旁路即紧密连接被动重吸收，故主要通过细胞旁路重吸收正确。Cl-并非主要与HCO3-竞争同一跨膜转运体；其重吸收为被动过程，不优先于HCO3-"},{"q":"下列关于回返性抑制的描述，正确的是","o":["经自身受体抑制递质释放而实现","通过串联性突触而起抑制作用","细胞内共存兴奋性和抑制性递质","能使同一中枢内许多神经元的活动同步化","效应是使兴奋神经元周边的神经元抑制"],"a":3,"e":"回返性抑制是神经元兴奋后经轴突侧支兴奋抑制性中间神经元（如闰绍细胞），再回返抑制原神经元及同一中枢其他神经元，使活动及时终止并趋于同步化。经自身受体抑制释放（A项）属突触前抑制；串联性突触抑制（B项）非其结构基础；胞内共存兴奋与抑制递质（C项）错误；使周边神经元抑制（E项）描述的是传入侧支性抑制"},{"q":"有关神经纤维的动作电位，说法错误的是","o":["其传导为衰减性传导","其幅度具有“全或无”性质","在神经纤维上的传导是双向性的","升支与钠离子内流有关，降支与钾离子外流有关","具有不应期"],"a":0,"e":"神经纤维动作电位沿膜传导时，局部电流使相邻膜依次去极化，幅度不随距离衰减，故衰减性传导错误。其幅度具全或无性质，离体神经纤维上可双向传导；升支由Na+内流形成、降支由K+外流形成，且存在不应期，这些都是动作电位的固有特征"},{"q":"心交感神经节前纤维释放的神经递质是","o":["乙酰胆碱","去甲肾上腺素","血管升压素","谷氨酸","γ-氨基丁酸"],"a":0,"e":"心交感神经节前纤维属胆碱能纤维，末梢释放乙酰胆碱，作用于交感神经节后神经元的N型受体；节后纤维则释放去甲肾上腺素作用于心肌β1受体。去甲肾上腺素（B项）为节后纤维递质；血管升压素（C项）为神经垂体激素；谷氨酸（D项）、γ-氨基丁酸（E项）为中枢氨基酸递质，均非心交感节前递质"},{"q":"心内兴奋传导最易发生阻滞的部位是","o":["窦房结","房室交界","左、右束支","浦肯野纤维","房室束"],"a":1,"e":"房室交界区（尤其房室结）纤维细小、传导速度最慢，兴奋在此延搁约0.1秒，是最易发生传导阻滞的部位。窦房结是正常起搏点；左右束支和浦肯野纤维传导速度快，房室束传导也较快，均不如房室交界易阻滞。这种延搁有利于心房收缩完成后心室再收缩"},{"q":"在If电流中最重要的跨膜离子流是","o":["逐渐衰减的外向钾离子电流","逐渐增强的内向钠离子电流","通过T型钙离子通道的内向钙离子电流","通过L型钙离子通道的内向钙离子电流","通过由ACh控制的钾离子通道的外向钾离子电流"],"a":1,"e":"If电流是窦房结等自律细胞4期自动去极化的主要成分，由HCN通道介导，以Na+内流为主，随时间逐渐增强，推动膜电位自动去极化。逐渐衰减的外向钾电流（A项）参与复极末期；T型钙电流（C项）在4期后段起作用；L型钙电流（D项）主要形成0期；ACh控制的钾电流（E项）使细胞超极化、减慢自律"},{"q":"在动物实验中，当动脉血压在80～180mmHg之间波动时肾血流并不随动脉血压的增高而增加，此时肾血流保持相对稳定。若要证明这是肾脏自身调节的结果，应采用的研究方法是","o":["急性离体动物实验","急性在体动物实验","慢性离体实验","慢性动物实验","动物细胞培养"],"a":0,"e":"采用急性离体动物实验，将肾脏完全脱离机体并控制灌流条件，可排除神经和体液因素的影响，单独观察肾血流量随灌注压变化的自身调节现象。急性在体、慢性在体或慢性实验均保留神经体液联系，无法排除其干扰；细胞培养也不适合研究器官水平的血流调节"},{"q":"以下可以增加动作电位沿神经传导的速度的途径为","o":["刺激Na+-K+泵","抑制Na+-K+泵","减小轴突直径","神经纤维髓鞘化","增加神经纤维长度"],"a":3,"e":"髓鞘化使动作电位以跳跃式传导，在郎飞结间跳跃，离子跨膜移动仅限于结区，传导速度显著提高。A项刺激钠泵与传导速度无直接关系；B项抑制钠泵破坏离子梯度，不利于兴奋；C项减小轴突直径使传导减慢，直径越大越快；E项增加神经纤维长度不改变传导速度"},{"q":"血中二氧化碳分压升高使呼吸运动加强，主要通过刺激下列哪一部位而实现","o":["脑桥呼吸相关神经元","中枢化学敏感区","延髓呼吸神经元","颈动脉窦和主动脉弓","颈动脉体和主动脉体"],"a":1,"e":"血中CO2分压升高时，CO2易透过血脑屏障，在脑脊液中生成H+刺激延髓腹外侧的中枢化学敏感区，是引起呼吸加强的主要途径，约占八成。E项颈动脉体和主动脉体也感受CO2但作用次要，且主要感受低O2；A项脑桥、C项延髓呼吸神经元非直接化学感受部位；D项颈动脉窦主动脉弓为压力感受器"},{"q":"肾脏球旁器的作用包括","o":["选择性地滤过大分子物质","参与血压的调节","主动转运和被动扩散","重吸收（90%溶质）和分泌功能","建立肾脏髓质的渗透梯度"],"a":1,"e":"球旁器由球旁细胞、致密斑和球外系膜细胞组成，球旁细胞分泌肾素，启动肾素-血管紧张素-醛固酮系统，收缩血管、保钠保水，参与血压调节。选择性滤过大分子（A项）为肾小球滤过膜；主动转运与被动扩散（C项）、重吸收与分泌（D项）为肾小管功能；建立髓质渗透梯度（E项）靠髓袢逆流倍增"},{"q":"下列激素或因子中，可由下丘脑以外的组织产生的是","o":["催乳素释放因子","催乳素释放抑制因子","生长激素释放抑制激素","生长激素释放激素","促甲状腺激素释放激素"],"a":2,"e":"生长激素释放抑制激素即生长抑素，除下丘脑外，还可由胰岛D细胞、胃肠道等组织产生，故可由下丘脑以外组织产生。催乳素释放因子、催乳素释放抑制因子、生长激素释放激素、促甲状腺激素释放激素主要由下丘脑分泌，其他组织产生并非其主要来源"},{"q":"氧解离曲线由正常位置向左移","o":["表明血液在一定PO2时氧含量减少","可发生在贫血时","表明血液流经组织时释放氧量增加","可见于贮存了数周的血液","可见于组织代谢增加时"],"a":3,"e":"氧解离曲线左移表示Hb与O2亲和力增高，同一PO2下氧饱和度升高。贮存数周的血液中红细胞内2,3-二磷酸甘油酸含量下降，使Hb与O2亲和力增加，曲线左移。A项左移时同一PO2氧含量增加而非减少；B项贫血多使曲线右移；C项左移时组织释氧减少；E项组织代谢增加使曲线右移、释氧增多"},{"q":"可直接抑制胰岛素分泌的激素是","o":["生长激素","生长抑素","抑胃肽","皮质醇","胰高血糖素"],"a":1,"e":"生长抑素由胰岛D细胞分泌，以旁分泌方式直接抑制邻近B细胞释放胰岛素，是胰岛素分泌的重要抑制性激素。E项胰高血糖素可刺激胰岛素分泌形成旁分泌促进；A项生长激素、D项皮质醇长期过多可致胰岛素抵抗并继发代偿性分泌增多；C项抑胃肽为肠促胰素，进食后促进胰岛素释放，都不是直接抑制"},{"q":"尿素通透性最高的部位是","o":["髓袢降支细段","集合管内髓部","远曲小管","近端小管","髓袢升支粗段"],"a":1,"e":"集合管内髓部即内髓集合管在抗利尿激素作用下尿素通透性最高，尿素由此扩散进入内髓组织液，参与形成和维持肾髓质高渗梯度。A项髓袢降支细段对水通透而对尿素通透性低；C项远曲小管对尿素几乎不通透；D项近端小管虽重吸收部分尿素但通透性不及内髓集合管；E项髓袢升支粗段对尿素不通透"},{"q":"某人因外伤损伤脊髓，经检查发现有痛温觉与轻触觉分离障碍，请问是哪种脊髓的损伤所致","o":["脊髓离断","脊髓空洞症","后角受损","前根病变","脊髓半离断"],"a":4,"e":"脊髓半离断损伤平面以下出现感觉分离：损伤对侧痛温觉障碍因脊髓丘脑束已交叉，同侧精细触觉和本体觉障碍因后索未交叉，轻触觉因双重支配保留较好，故表现为痛温觉与触觉的分离。脊髓离断为完全性感觉运动丧失；后角受损表现为同侧节段性痛温觉障碍；前根病变属运动障碍"},{"q":"下列关于基础代谢的叙述，错误的是","o":["在基础状态下单位时间内的能量代谢","基础代谢一般在餐后12～14小时检测","检测基础代谢的室内温度在20～25℃","精神状态一般不影响基础代谢","肌肉活动明显影响基础代谢"],"a":3,"e":"基础代谢是在基础状态下的能量代谢，测定要求清晨、空腹、静卧、室温20～25℃且精神放松，精神紧张会提高代谢率，故精神状态不影响的说法错误。餐后12～14小时检测（B项）、室温20～25℃（C项）、肌肉活动明显影响（E项）均符合基础状态要求；单位时间内能量代谢（A项）是基础代谢的基本含义"},{"q":"容量血管指的是","o":["肺动脉","毛细血管","微静脉","中动脉","静脉"],"a":4,"e":"静脉管壁薄、顺应性大，可容纳全身约百分之六十至七十的血量，起贮存血液的作用，故称容量血管。A项肺动脉属肺循环血管；B项毛细血管为交换血管，管壁仅一层内皮；C项微静脉属毛细血管后阻力血管；D项中动脉肌层厚、主要分配血流，属阻力血管，都不是容量血管"},{"q":"甲状腺激素合成过程中，由TSH调节的关键酶是","o":["脱碘酶","蛋白水解酶","过氧化物酶","腺苷酸环化酶","磷脂酶C"],"a":2,"e":"TSH促进甲状腺激素合成的关键环节是碘的活化、酪氨酸碘化及偶联，均由甲状腺过氧化物酶催化，故过氧化物酶为关键酶。脱碘酶参与T4向T3转化及碘再利用，蛋白水解酶参与甲状腺球蛋白水解释放激素，腺苷酸环化酶、磷脂酶C为信号转导分子"},{"q":"大肠内的细菌可利用肠内物质合成下列哪种维生素","o":["维生素A","维生素D","维生素E","维生素K","叶酸"],"a":3,"e":"大肠内细菌即肠道菌群可利用肠内容物合成维生素K及B族维生素，供机体利用。维生素A、D、E为脂溶性维生素，主要来自食物或经紫外线作用、肠道吸收，并非大肠细菌合成的产物，故不属于细菌合成范围"},{"q":"肾小球毛细血管血压较高时会导致","o":["肾交感神经兴奋性升高","致密斑感受器兴奋","肾素释放增加","肾小球滤过增加","醛固酮释放增加"],"a":3,"e":"肾小球毛细血管血压是决定有效滤过压的主要因素，其升高使有效滤过压增大，肾小球滤过增加。肾交感神经兴奋、致密斑兴奋与肾素释放增加多由肾灌注压下降或Na+减少触发，是血压降低时的反应；醛固酮释放主要受血管紧张素Ⅱ与血K+调节，均非毛细血管血压升高的直接后果"},{"q":"目前认为控制生物节律的主要核团是","o":["松果体","下丘脑室旁核","下丘脑视交叉上核","下丘脑视上核","外侧膝状体"],"a":2,"e":"下丘脑视交叉上核是哺乳类动物控制昼夜生物节律的主要核团，毁损后昼夜节律消失。室上核和室旁核主要分泌抗利尿激素与缩宫素，参与水平衡和泌乳；松果体分泌褪黑素参与节律调节但非主核团；外侧膝状体为视觉中继结构，均不是控制生物节律的主要核团"},{"q":"当肺容量小于肺总量的67%时","o":["胸廓以其弹性向外扩展，肺的弹性回缩力消失","胸廓以其弹性向内回缩，肺的弹性回缩力向内","胸廓以其弹性向外扩展，肺的弹性回缩力向内","胸廓以其弹性向内回缩，肺的弹性回缩力消失","胸廓的弹性作用消失，肺的弹性回缩力向内"],"a":2,"e":"肺容量低于肺总量67%时，胸廓处于其自然容积以内，胸廓弹性方向向外扩展；而肺组织始终具有向内回缩的弹性回缩力。故此时胸廓向外、肺向内。胸廓弹性向内回缩见于肺容量大于67%时；肺弹性回缩力不会消失"},{"q":"某人因肾病长期大量用糖皮质激素治疗，该患者不会因此而出现","o":["血糖升高","蛋白质合成增加","面部和躯干脂肪合成增加","红细胞、血小板增多","淋巴细胞减少"],"a":1,"e":"糖皮质激素促进肝外组织蛋白质分解并抑制其合成，长期大量使用可致肌肉萎缩、皮肤变薄、伤口愈合延迟。它还能升高血糖、促进面部和躯干脂肪重新分布，使红细胞和血小板增多、淋巴细胞减少。蛋白质合成增加与糖皮质激素的作用相反，故不会出现"},{"q":"酸中毒时远端小管的","o":["钾离子分泌增多，钠离子重吸收增多","钾离子分泌减少，钠离子重吸收减少","钾离子分泌增多，钠离子重吸收减少","钾离子分泌减少，钠离子重吸收增多","钠-氢交换增多，钾-氢交换减少"],"a":1,"e":"酸中毒时远端小管上皮细胞内H+增多，H+-Na+交换增强而K+-Na+交换受抑，使K+分泌减少，出现高血钾；同时H+抑制管腔膜Na+通道，Na+重吸收减少。钾分泌增多（A、C项）为碱中毒表现；钾分泌减少而钠重吸收增多（D项）与酸中毒时钠重吸收受抑不符；E项将交换对象写成钾-氢交换错误，实为钾-钠交换受抑"},{"q":"下列关于受精的叙述，错误的是","o":["精子在雌性生殖道内完成获能反应","获能后的精子具有穿透卵透明带的能力","子宫腔内获能的精子释放出多种蛋白酶水解卵透明带","顶体反应是受精的关键环节","精子进入卵细胞激发卵细胞完成第二次减数分裂"],"a":2,"e":"精子获能主要在女性输卵管等生殖道内完成，获能后的精子在输卵管壶腹部与卵相遇才发生顶体反应，释放顶体酶水解卵透明带。故子宫腔内获能的精子释放蛋白酶水解透明带一句的场所与环节均有误。获能赋予穿透透明带能力、顶体反应为关键环节、入卵激发第二次减数分裂均正确"},{"q":"下列不是唾液的生理作用的是","o":["部分消化淀粉","部分消化蛋白质","湿润与溶解食物","清洁和保护口腔","杀菌作用"],"a":1,"e":"唾液含唾液淀粉酶，可部分消化淀粉，但不能消化蛋白质；其生理作用还包括湿润溶解食物、清洁保护口腔、杀菌（溶菌酶）等。部分消化蛋白质不属于唾液作用，故为答案。其余各项消化淀粉、湿润溶解、清洁保护、杀菌均为唾液的正常生理作用"},{"q":"引起快反应细胞0期去极化的主要电流是","o":["ICa","INa","IK1","Ito","If"],"a":1,"e":"快反应细胞0期去极化由快钠通道开放、Na+快速内流引起，故主要电流为INa。ICa参与慢反应细胞及快反应细胞平台期；IK1为内向整流钾电流，维持静息电位；Ito为瞬时外向钾电流，参与1期复极；If为起搏电流，参与4期自动去极化"},{"q":"与胞质中cAMP生成有直接关系的膜效应器酶是","o":["磷脂酶A","腺苷酸环化酶","磷脂酶C","蛋白激酶","鸟苷酸环化酶"],"a":1,"e":"腺苷酸环化酶是催化ATP生成cAMP的膜效应器酶，由G蛋白偶联受体经Gs蛋白激活，cAMP作为第二信使介导多种激素效应。C项磷脂酶C水解PIP2生成IP3和DAG；E项鸟苷酸环化酶催化生成cGMP；A项磷脂酶A2产生花生四烯酸；D项蛋白激酶为cAMP下游效应分子，均不直接生成cAMP"},{"q":"促进腺垂体TSH分泌的下丘脑调节肽是","o":["CRH","GHRH","GnRH","PRF","TRH"],"a":4,"e":"促甲状腺激素释放激素（TRH）由下丘脑分泌，经垂体门脉作用于腺垂体，促进TSH合成与释放，是调节甲状腺轴的上游激素。CRH（A项）促ACTH释放；GHRH（B项）促GH释放；GnRH（C项）促LH、FSH释放；PRF（D项）促催乳素释放，均不促进TSH"},{"q":"发生突触前抑制的关键结构基础是","o":["轴突-胞体型突触","轴突-轴突型突触","轴突-树突型突触","缝隙连接","胞体-胞体型突触"],"a":1,"e":"突触前抑制的结构基础是轴突-轴突型突触：抑制性神经元末梢作用于兴奋性传入末梢，使其产生去极化，动作电位幅度减小，进入末梢的Ca2+减少，递质释放量下降。轴突-胞体和轴突-树突型突触是突触后抑制的常见形式；缝隙连接为电突触结构，胞体-胞体型突触不参与突触前抑制"},{"q":"小儿排尿次数较多，且易发生夜间遗尿现象，最可能的原因是","o":["膀胱发育不完善","盆神经发育不完善","阴部神经发育不完善","骶髓初级排尿中枢发育不完善","大脑发育不完善"],"a":4,"e":"小儿大脑皮层发育尚未完善，对骶髓排尿低级中枢的控制能力弱，故排尿次数多、夜间遗尿。骶髓初级排尿中枢在婴幼儿已具备反射功能；膀胱、盆神经、阴部神经发育并非导致夜间遗尿的关键因素"},{"q":"以下属于运动单位概念范畴的结构是","o":["α运动神经元","核袋纤维","核链纤维","γ运动神经元","β运动神经元"],"a":0,"e":"运动单位由一个α运动神经元及其轴突支配的全部骨骼肌纤维组成，是肌肉运动的基本功能单位，故α运动神经元属于该范畴。γ运动神经元支配肌梭内肌纤维，调节肌梭敏感性；核袋纤维、核链纤维为肌梭内肌纤维；β运动神经元不属经典运动单位概念"},{"q":"腰骶部脊髓受损时，排尿功能障碍表现为","o":["尿失禁","尿频","尿痛","多尿","尿潴留"],"a":4,"e":"腰骶髓即S2～S4为排尿低级中枢，受损时逼尿肌收缩无力、排尿反射减弱或消失，膀胱充盈却不能排空，表现为尿潴留及充溢性尿失禁。尿频、尿痛多为膀胱刺激征；多尿见于尿崩症或渗透性利尿；尿失禁多见于高级中枢或括约肌损伤"},{"q":"下列关于壁细胞质子泵的叙述，错误的是","o":["存在于顶端膜内凹的分泌小管膜上","是一种氢-钾依赖式的ATP酶","抑制质子泵不影响胃酸的分泌","分泌氢离子同时伴有钾离子进入细胞","分泌氢离子同时伴有碳酸氢根移出细胞"],"a":2,"e":"质子泵即H+-K+-ATP酶，分布于壁细胞顶端膜内凹的分泌小管膜，每分解ATP泵出H+并交换K+入胞，是胃酸分泌的最终环节，抑制它可使胃酸分泌显著减少，奥美拉唑即据此起效。抑制质子泵不影响胃酸分泌一项与机制相悖。分泌H+同时伴HCO3-移出细胞形成餐后碱潮，属正确描述，勿与前者混淆"},{"q":"作用于二级支气管以下部位的感受器而引起咳嗽反射的有效刺激是","o":["机械牵张","温度改变","刺激性气味","二氧化碳浓度升高","缺氧"],"a":2,"e":"分布于二级支气管以下小气道的咳嗽感受器对化学性刺激尤为敏感，刺激性气味可直接刺激该部位感受器，经迷走神经传入引发咳嗽反射。机械牵张主要刺激气管和大支气管的牵张感受器，温度改变作用较弱，二氧化碳升高和缺氧主要通过化学感受器调节呼吸，而非引发下气道咳嗽"},{"q":"以下运动障碍表现中最符合“不全麻痹”概念的是","o":["肌肉张力消失","肌肉强直","巴宾斯基征阳性","腱反射亢进","肌肉力量下降"],"a":4,"e":"不全麻痹即轻瘫，指肌力不同程度下降但并未完全丧失，故肌肉力量下降最符合其概念。A项肌张力消失见于下运动神经元完全损伤或脊休克期；B项肌肉强直、D项腱反射亢进为痉挛性瘫痪即上运动神经元损害的表现；C项巴宾斯基征阳性是锥体束受损的病理反射，这些选项都强调反射或张力改变，而非肌力本身减弱"},{"q":"肾小管超滤液中氨基酸全部被重吸收的部位是","o":["近曲小管","髓袢降支","髓袢升支","远曲小管","集合管"],"a":0,"e":"超滤液中的氨基酸几乎全部在近曲小管被重吸收，依靠Na+依赖的继发性主动转运，与葡萄糖类似，正常尿中不含氨基酸。髓袢降支（B项）主要重吸收水；髓袢升支（C项）重吸收NaCl；远曲小管（D项）与集合管（E项）仅重吸收少量物质并参与分泌，均非氨基酸主要吸收部位"},{"q":"机体受到刺激而发生应激反应的系统是","o":["交感-肾上腺髓质系统","下丘脑-腺垂体-肾上腺皮质系统","下丘脑-腺垂体-甲状腺系统","下丘脑-腺垂体-性腺系统","下丘脑-神经垂体系统"],"a":1,"e":"应激反应主要指机体受创伤、感染等刺激时，下丘脑腺垂体肾上腺皮质轴激活，分泌ACTH与糖皮质激素，提高对不良刺激的耐受；交感肾上腺髓质系统介导的是应急反应。A项属应急系统而非应激；C项甲状腺轴、D项性腺轴、E项神经垂体系统均非应激反应的核心系统"},{"q":"以下关于真毛细血管特点的叙述错误的是","o":["管壁很薄","管壁通透性大","血流缓慢","管壁内皮细胞有吞饮功能","周期性收缩和舒张"],"a":4,"e":"真毛细血管管壁仅由单层内皮细胞构成，壁薄、通透性大、血流缓慢，内皮细胞有吞饮功能，是物质交换的主要部位；其本身无平滑肌，不能周期性收缩舒张。周期性舒缩（E项错误）是毛细血管前括约肌及微动脉的行为；A、B、C、D项均为真毛细血管的正确特点"},{"q":"通常所说的血型是指","o":["红细胞膜上的受体类型","红细胞表面特异凝集素的类型","红细胞膜上特异性抗原的类型","血浆中特异凝集素的类型","血浆中特异凝集原的类型"],"a":2,"e":"通常所说血型是指红细胞膜上特异性抗原即凝集原的类型，据此将血液分为不同血型系统。红细胞膜上无决定血型的受体；凝集素存在于血浆中而非红细胞表面；血浆中含有的是凝集素而非凝集原，故相关选项均混淆了抗原与抗体的分布"},{"q":"消化道平滑肌的紧张性和自动节律性主要依赖于","o":["交感神经的支配","副交感神经的支配","壁内神经丛的作用","平滑肌本身的特性","食物消化产物的刺激作用"],"a":3,"e":"消化道平滑肌具有自发产生的紧张性收缩和自动节律性，这些特性源于平滑肌本身的肌源性活动，在离体并去除神经支配后依然存在。交感和副交感神经及壁内神经丛可调节其运动强度和节律，食物消化产物也可影响活动，但均不是紧张性和节律性产生的根本来源"},{"q":"对于血小板的聚集起重要作用的物质是","o":["纤维蛋白原","凝血酶","钙离子","ADP与血栓烷A2","花生四烯酸"],"a":3,"e":"血小板聚集依赖ADP、血栓烷A2等诱导剂，它们使膜糖蛋白Ⅱb/Ⅲa活化，经纤维蛋白原桥联而聚集，故ADP与血栓烷A2最关键。纤维蛋白原是桥联因子而非诱导物；凝血酶主要促凝并活化血小板；钙离子参与但不具特异性；花生四烯酸须先转为血栓烷A2才起作用"},{"q":"下列关于肌紧张的描述，正确的是","o":["由快速牵拉肌腱而引起","感受器是肌梭","人类以屈肌肌紧张为主要表现","为单突触反射","反射持久进行时易疲劳"],"a":1,"e":"肌紧张是缓慢持续牵拉肌腱时发生的牵张反射，感受器为肌梭，属多突触反射，意义在于维持姿势和肌张力。A项由快速牵拉肌腱引起的是腱反射；C项人类以伸肌肌紧张为主以维持直立；D项腱反射为单突触反射；E项肌紧张不易疲劳、可持久进行"},{"q":"哇巴因抑制甲状腺激素的产热效应是通过","o":["抑制腺苷酸环化酶","抑制脱碘酶","抑制溶酶体酶","抑制Na+-K+-ATP酶","抑制磷酸二酯酶"],"a":3,"e":"甲状腺激素提高基础代谢率的重要机制是增加细胞膜Na+-K+-ATP酶（钠泵）的数量与活性，哇巴因特异性抑制该酶，从而消除甲状腺激素的产热效应。腺苷酸环化酶（A项）与磷酸二酯酶（E项）分别催化和降解cAMP，属第二信使系统；脱碘酶（B项）催化T4转化为T3；溶酶体酶（C项）参与细胞内消化，均与哇巴因作用无关"},{"q":"在牵张反射的相关的神经支配中，外周神经末梢呈螺旋状的是","o":["Ⅰa类纤维","Ⅰb类纤维","Ⅱ类纤维","β运动神经元末梢","γ运动神经元末梢"],"a":0,"e":"Ⅰa类纤维的末梢呈螺旋状环绕梭内肌纤维的感受装置，感受肌肉长度变化与牵张速率，是牵张反射的传入通路。B项Ⅰb类纤维末梢为高尔基腱器官的花枝状末梢，感受张力；C项Ⅱ类纤维末梢呈花球状，感受肌肉长度；D项β运动神经元、E项γ运动神经元为传出纤维，支配梭外肌或梭内肌，末梢不呈螺旋感受结构"},{"q":"下列关于心交感传入反射的叙述，错误的是","o":["交感传入末梢可感受化学刺激","交感传入末梢也可感受心室扩张引起的机械刺激","该反射可增强交感神经活动","该反射属于负反馈调节","该反射有利于在心肌缺血时维持血压"],"a":3,"e":"心交感传入反射在心肌缺血时增强交感神经活动以维持血压，属于正反馈而非负反馈，故该叙述错误。交感传入末梢可感受化学物质与心室扩张的机械刺激；该反射增强交感活动；在心肌缺血时有代偿意义，均正确"},{"q":"胃期胃液分泌的特点是","o":["胃液的酸度含量较高而酶含量较低","胃液的酸度低而酶含量也低","胃液的酸度含量较高而酶含量更高","胃液的酶含量较高而酸度更高","胃液的酶含量较高而酸度较低"],"a":0,"e":"胃期胃液分泌由食物扩张胃与胃泌素介导，特点是酸度高而胃蛋白酶含量较低，消化力弱于头期。B项酸度与酶含量均低是肠期胃液的特点；C项酸度与酶含量均高属头期胃液；D、E项所述酶高于酸的组合不符合胃期以壁细胞泌酸为主、主细胞分泌酶相对较少的实际"},{"q":"患者患SIADHS（抗利尿激素分泌失调综合征），当其ADH分泌过多时，患者的","o":["血钠浓度高于正常","细胞内液量高于正常","尿量多于正常","血浆胶体渗透压高于正常","血浆总渗透压高于正常"],"a":1,"e":"ADH分泌过多使远曲小管和集合管重吸收水增加，水潴留导致细胞外液稀释、渗透压下降，水顺渗透梯度进入细胞内，使细胞内液量高于正常，并出现稀释性低钠血症。血钠浓度低于正常而非升高；尿量减少而非增多；血浆胶体渗透压主要受蛋白影响、不升高；血浆总渗透压因稀释而下降"},{"q":"关于血浆晶体渗透压说法正确的是","o":["当血浆晶体渗透压降低，会使红细胞膨胀、破裂","高于组织液晶体渗透压","对维持血浆容量有重要作用","由离子和大分子胶体物质形成","约占血浆总渗透压的50%"],"a":0,"e":"血浆晶体渗透压主要由Na+、Cl-等小分子晶体物质形成，占血浆总渗透压绝大部分；其降低时水进入红细胞，使细胞膨胀甚至破裂。B项血浆与组织液的晶体渗透压基本相等，差别在胶体渗透压；C项维持血浆容量主要靠胶体渗透压；D项大分子胶体形成的是胶体渗透压；E项晶体渗透压约占总渗透压的99%，远高于50%"},{"q":"左侧大脑皮层中央后回受损后，躯体感觉障碍的部位是","o":["左半身","右半身","左侧头面部","右侧头面部","双侧头面部"],"a":1,"e":"一侧大脑皮层中央后回为躯体感觉投射区，躯体感觉呈交叉投射，左侧受损表现为右侧半身感觉障碍。头面部感觉虽多为双侧投射，但中央后回受损主要影响对侧躯干四肢；左半身、左侧头面部为同侧或非典型表现，双侧头面部更不符合单侧皮层损伤的规律"},{"q":"调节呼吸运动最重要的生理因素是","o":["CO2","O2","H＋","2，3-DPG","CO"],"a":0,"e":"CO2是调节呼吸运动最重要的生理性化学因素，动脉血PCO2轻度升高即可明显增强呼吸，主要通过刺激中枢化学感受器（生成H+）实现。O2（B项）在PaO2降至约80mmHg以下才明显起作用；H+（C项）也参与但CO2更主要；2,3-DPG（D项）调节血红蛋白携氧；CO（E项）为病理气体，均非最重要生理因素"},{"q":"声波经过鼓膜时","o":["改变进入中耳的声波频率","可减小声波的声压","若咽鼓管阻塞，鼓膜将趋于向外凸出","鼓膜实际振动面积与前庭窗大致相等","几乎与声波振动同始同终"],"a":4,"e":"鼓膜振动几乎与声波振动同始同终，能将声波不失真地传入中耳。鼓膜实际振动面积远大于前庭窗，经听骨链杠杆作用增压而非减小声压，也不改变声波频率。咽鼓管阻塞时中耳负压使鼓膜向内凹陷，而非向外凸出"},{"q":"血样氧分压为100mmHg，血氧饱和度为98%，血红蛋白浓度为15g/100ml血。该血样中氧含量为","o":["10mlO2 /100ml血液","15mlO2 /100ml血液","20mlO2 /100ml血液","23mlO2 /100ml血液","25mlO2 /100ml血液"],"a":2,"e":"血氧含量等于血红蛋白浓度乘血氧饱和度再乘1.34，即15乘0.98乘1.34约20ml每100ml血液。10ml明显低于实际携氧量；15ml未计入饱和度；23ml与25ml接近氧容量或超过实际值，均未正确反映该血样的实际携氧水平"},{"q":"细胞在安静时对钠离子的通透性","o":["为零","约为钾离子通透性的2倍","约为钾离子通透性的1/2","约为钾离子通透性的1/100～1/50","约为钾离子通透性的1/1000"],"a":3,"e":"安静状态下细胞膜对K+的通透性远高于Na+，Na+通透性约为K+的1/100～1/50，这一差异是静息电位接近K+平衡电位的原因。通透性为零无法解释兴奋时Na+内流；2倍或1/2会显著改变静息电位水平，1/1000则过低，均与实测不符"},{"q":"下列选项中，属于人类小脑半球中间部受损所特有症状的是","o":["肌张力降低","腱反射增强","静止性震颤","意向性震颤","位置性眼震颤"],"a":3,"e":"小脑半球中间部参与运动协调，受损时出现意向性震颤（动作性震颤）及辨距不良、共济失调。A项肌张力降低可见于小脑广泛损伤；B项腱反射增强为上运动神经元损伤表现；C项静止性震颤为帕金森病（黑质多巴胺能神经元损伤）的特征；E项位置性眼震颤主要与前庭或绒球小结叶有关"},{"q":"健康雄性8周龄Wistar大鼠，通过高脂、高糖、高盐饮食喂养16周，建立代谢综合征大鼠模型，并观察代谢综合征时动物的基本病理改变和相关代谢指标的变化，这种实验方法属于","o":["急性离体动物实验","慢性在体动物实验","急性在体动物实验","急性动物实验","实时在体监测实验"],"a":1,"e":"该实验在活体动物上经16周持续高脂高糖高盐饮食复制代谢综合征模型，属于慢性在体动物实验，用于观察长期病理改变与代谢指标。A项急性离体、C项急性在体、D项急性动物实验均为短时间或单次处理，与16周长期喂养不符；E项实时在体监测强调连续记录指标，并非造模方法的分类"},{"q":"环境温度升高，超过体表温度时，机体维持体温正常的生理活动为","o":["交感神经兴奋，汗腺分泌","交感神经兴奋，皮肤血管平滑肌收缩","寒战","肾上腺素、甲状腺激素分泌明显增加","副交感神经兴奋，全身血管舒张，散热量增加"],"a":0,"e":"当环境温度超过体表温度时，辐射、传导和对流散热均失效，蒸发成为唯一有效的散热方式；交感神经兴奋使汗腺分泌增加，通过汗液蒸发带走热量维持体温。此时皮肤血管应舒张而非收缩，寒战和肾上腺素、甲状腺激素分泌增加是寒冷环境中的产热反应，副交感兴奋导致全身血管舒张也不符合体温调节实际"},{"q":"当去甲肾上腺素与α受体结合时，下列哪一种肌肉舒张","o":["血管平滑肌","子宫平滑肌","虹膜辐射状肌","胃肠括约肌","小肠平滑肌"],"a":4,"e":"去甲肾上腺素与α受体结合通常使平滑肌收缩，如血管平滑肌、虹膜辐射状肌、胃肠括约肌、子宫平滑肌；但小肠平滑肌的α受体兴奋表现为舒张，故小肠平滑肌可出现舒张。血管平滑肌（A项）、虹膜辐射状肌（C项）、胃肠括约肌（D项）、子宫平滑肌（B项）均为收缩效应，不是舒张"},{"q":"能使动脉血压波幅增大的原因是","o":["心动过速","房室瓣狭窄","主动脉瓣狭窄","大动脉硬化","小动脉硬化"],"a":3,"e":"大动脉壁弹性储器作用可缓冲收缩压、维持舒张压；发生硬化时弹性减弱，收缩期不能有效扩张储能、舒张期回弹无力，导致收缩压升高、舒张压降低，脉压（血压波幅）增大。心动过速主要缩短舒张期，房室瓣或主动脉瓣狭窄多使脉压减小，小动脉硬化主要升高舒张压"},{"q":"下列关于输血的叙述，错误的是","o":["再次输入同一相同血型个体的血液不需进行交叉配血","必要时O型血可输给其他血型的受血者","必要时AB型血的人可接受其他血型供血者的血液","Rh阴性的受血者不可接受Rh阳性的血液","Rh阳性的受血者可接受Rh阴性的血液"],"a":0,"e":"输血时必须每次进行交叉配血，即使再次输入同一血型个体的血液也不能省略，因血型亚型与不规则抗体可能导致凝集，故该叙述错误。O型血在紧急时可少量输给其他血型，AB型可少量接受其他血型；Rh阴性受血者不可接受Rh阳性血，Rh阳性可接受Rh阴性血，均正确"},{"q":"小肠对糖的选择性吸收最快的是","o":["果糖","甘露糖","半乳糖","木糖","核糖"],"a":2,"e":"小肠对单糖的吸收具有选择性，半乳糖与葡萄糖可借助Na+葡萄糖同向转运体继发性主动转运，吸收速度最快。果糖经GLUT5易化扩散，速度较慢；甘露糖、木糖与核糖吸收效率更低，且部分不被机体充分利用，均非选择性吸收最快的糖"},{"q":"胎盘合体滋养层细胞分泌的hCG在妊娠的哪个阶段达到高峰","o":["第3～4周","第5～6周","第7～8周","第8～10周","第10～12周"],"a":3,"e":"合体滋养层细胞分泌的hCG在妊娠第8～10周达到高峰，随后逐渐下降，至中晚期维持较低水平。第3～4周、第5～6周为上升阶段，未达峰值；第10～12周已过高峰开始回落，均非峰值时段"},{"q":"平静呼吸时，无论吸气或呼气，胸膜腔内压均为负值，主要因为","o":["肺的生长速度比胸廓快","胸廓自然容积大于肺的自然容积","肺的回缩力小于胸廓回缩力","肺表面活性物质的作用","胸廓的弹性阻力大于肺内压"],"a":1,"e":"胸膜腔内压等于肺内压减去肺回缩力，因胸廓自然容积大于肺自然容积，肺被牵拉而产生向内回缩力，使平静呼吸时胸膜腔内压始终为负。肺生长比胸廓快（A项）与实际相反；肺回缩力小于胸廓回缩力（C项）表述错误，正是肺回缩力形成负压；表面活性物质（D项）稳定肺泡；胸廓弹性阻力大于肺内压（E项）非主要原因"},{"q":"平静呼吸时，在下列时相中肺内压低于大气压的是","o":["吸气初","吸气末","呼气初","呼气末","停止呼吸时"],"a":0,"e":"平静吸气时呼吸肌收缩使胸廓扩大，肺内压降至低于大气压，空气因而进入肺，吸气初压差最明显，至吸气末肺内压回升与大气压相等。B项吸气末、D项呼气末肺内压均等于大气压；C项呼气初肺内压高于大气压、气体呼出；E项停止呼吸时肺内压与大气压相等，只有吸气初低于大气压"},{"q":"神经干中许多纤维同时传导兴奋时互不干扰的主要原因是","o":["髓鞘的绝缘作用","细胞膜电阻很大","细胞外液的短路作用","跨膜电流很小","不同纤维的传导速度不等"],"a":2,"e":"神经干内多条纤维同时兴奋而互不干扰，主要因细胞外液具有短路作用，局部电流经低电阻的细胞外液回流，各纤维间电场互不影响。髓鞘绝缘有助于有髓纤维传导，但无髓纤维同样互不干扰，故非主因；跨膜电流大小、传导速度差异也不决定这种独立性"},{"q":"下列关于动作电位的描述，正确的是","o":["刺激强度小于阈值时，出现低幅度动作电位","刺激强度达到阈值后，再增加刺激强度能使动作电位幅度增大","动作电位一经产生，便可沿细胞膜作电紧张式扩布","传导距离较长时，动作电位的大小不发生改变","动作电位在离体神经纤维上的传导是单向性的"],"a":3,"e":"动作电位在同一细胞上传导具有全或无和不衰减性，传导距离再长其幅度也不改变，这依赖局部电流不断再生。A项刺激小于阈值只产生局部电位，无动作电位；B项达阈后增大刺激强度不改变幅度；C项动作电位沿膜作再生式传导而非电紧张扩布；E项离体神经纤维上兴奋可双向传导，而非单向"},{"q":"给骨骼肌连续刺激时，如果后1次刺激所引起的收缩过程出现在前1次刺激所引起的收缩过程的收缩期内，所产生收缩总和是","o":["单收缩","不完全强直收缩","完全强直收缩","等张收缩","等长收缩"],"a":2,"e":"后一刺激引起的收缩落在前一次收缩的收缩期内时，新收缩叠加于尚未结束的收缩之上，肌肉持续处于收缩状态，形成完全强直收缩。若刺激落在前次收缩的舒张期则形成不完全强直收缩；单收缩为单次刺激的反应，等张与等长收缩是按收缩形式分类，与刺激频率无关"},{"q":"“Rh阳性”是指红细胞膜上有","o":["C抗原","A抗原","D抗原","E抗原","B抗原"],"a":2,"e":"Rh血型系统的抗原有C、c、D、E、e等多种，其中D抗原抗原性最强，红细胞膜上表达D抗原者称为Rh阳性，不表达者为Rh阴性。C抗原（A项）、E抗原（D项）虽属Rh系统但不作为阴阳性的判据；A抗原（B项）、B抗原（E项）属于ABO血型系统，与Rh分型无关"},{"q":"硫氧嘧啶类药物可用于治疗甲状腺功能亢进，这是由于它能","o":["抑制甲状腺腺泡上皮细胞中的TPO活性","抑制肠吸收碘","抑制甲状腺的聚碘作用","抑制甲状腺激素的释放","促进甲状腺激素的灭活"],"a":0,"e":"硫氧嘧啶类药物通过抑制甲状腺过氧化物酶（TPO）的活性，阻断碘的活化、酪氨酸的碘化及碘化酪氨酸的偶联，从而减少甲状腺激素的合成，用于治疗甲亢。它不抑制肠道吸收碘，也不抑制甲状腺的聚碘作用，更不直接影响激素的释放或灭活过程"},{"q":"主动脉在维持舒张压中起主要作用，主要是由于主动脉的以下特点","o":["主动脉管腔口径大，管壁压力高","主动脉管壁受交感缩血管神经的支配","主动脉管壁有可扩张性和弹性","心室射血期短，血流速度快","主动脉管径大，对血流的摩擦阻力小"],"a":2,"e":"主动脉管壁具有可扩张性和弹性，心室射血期扩张贮存部分血液与势能，舒张期回弹释放，维持舒张压并保证连续血流，这就是弹性贮器作用。管腔口径大、压力高（A项）非主因；交感缩血管支配（B项）主要改变阻力；射血期短、血流快（D项）不解释舒张压维持；摩擦阻力小（E项）影响收缩压与血流，非舒张压关键"},{"q":"某人由于外伤导致耳蜗底部受损，出现听力障碍主要是","o":["高频听力","低频听力","中频听力","中、低频听力","高、中频听力"],"a":0,"e":"耳蜗基底部（底部）感受高频声波，顶部感受低频声波，故耳蜗底部受损主要影响高频听力。低频听力（B项）、中频听力（C项）对应耳蜗顶部或中部；中低频听力（D项）、高中频听力（E项）定位不准，底部损伤以高频下降为主"},{"q":"下列对血管升压素的叙述，正确的是","o":["又叫抗利尿激素","在下丘脑合成，腺垂体释放","收缩血管作用较强，是调节血压的主要体液因子","循环血量增多时，其分泌量增多","机体失血时，其分泌量减少"],"a":0,"e":"血管升压素又称抗利尿激素，由下丘脑视上核、室旁核合成，经轴突运输至神经垂体释放，主要促进远曲小管和集合管重吸收水。B项释放部位为神经垂体而非腺垂体；C项生理浓度下以抗利尿为主，缩血管作用弱、并非调节血压的主要体液因子；D项循环血量增多时分泌减少；E项失血时分泌反而增多"},{"q":"能显著提高血钙水平的激素是","o":["ACTH","CRH","CT","PTH","TSH"],"a":3,"e":"甲状旁腺素是调节血钙最重要的激素，通过促进骨钙释放、肾小管重吸收钙及活性维生素D3生成，显著提升血钙。A项ACTH、B项CRH、E项TSH均不直接调节血钙；C项降钙素降低血钙，与PTH作用拮抗"},{"q":"钙通道阻断剂维拉帕米对浦肯野细胞动作电位的影响是","o":["0期去极化幅度降低","0期去极化速度减慢","1期复极化时程缩短","2期复极化时程缩短","3期复极化时程缩短"],"a":3,"e":"维拉帕米阻断L型钙通道，减少浦肯野细胞动作电位2期即平台期的Ca2+内流，使2期复极化时程缩短。A项0期去极化幅度和B项0期速度由快钠内流决定，钙拮抗剂影响小；C项1期复极化主要由瞬时外向K+电流引起；E项3期复极化以K+外流为主，都不是维拉帕米主要作用的时相"},{"q":"具有亲脂特性的激素是","o":["甲状腺激素","生长激素","胰岛素","缩宫素","肾上腺素"],"a":0,"e":"甲状腺激素为含碘氨基酸衍生物，脂溶性强，可穿过细胞膜与核受体结合，属亲脂性激素。生长激素、胰岛素、缩宫素均为肽类或蛋白质激素，肾上腺素为儿茶酚胺类，皆为水溶性，需与膜受体结合并经第二信使发挥作用，不具亲脂特性"},{"q":"与浦肯野细胞相比较，窦房结细胞的跨膜电位的特点是","o":["阈电位绝对值大","0期去极化幅度高","0期去极化速度快","最大复极电位绝对值大","4期自动去极化速度快"],"a":4,"e":"窦房结为慢反应自律细胞，其最大复极电位绝对值小、阈电位低，4期自动去极化速度快，自律性最高，成为正常起搏点；0期由Ca2+内流引起，幅度低、速度慢。阈电位绝对值大（A项）、0期幅度高（B项）、速度快（C项）、最大复极电位绝对值大（D项）均为快反应细胞浦肯野细胞的特点，与窦房结相反"},{"q":"产生生物电的跨膜离子移动主要属于","o":["单纯扩散","入胞","出胞","通道中介的易化扩散","载体中介的易化扩散"],"a":3,"e":"生物电的产生源于离子经电压门控或化学门控离子通道跨膜移动，属通道中介的易化扩散，顺电化学梯度、速度快。单纯扩散针对脂溶性物质；入胞、出胞用于大分子颗粒；载体中介的易化扩散转运速度较慢、有饱和性，均非生物电离子流的主要方式"},{"q":"根据激素作用原理论述中的第二信使学说，可以看作第一信使的物质是","o":["含氮激素","甾体激素","类固醇激素","cAMP","钙离子"],"a":0,"e":"第二信使学说中，含氮激素作为第一信使与靶细胞膜受体结合，激活膜内酶产生cAMP、钙离子等第二信使，再引发细胞反应。B、C项甾体即类固醇激素通过胞内受体直接调控基因转录，不经第二信使；D项cAMP与E项钙离子本身即为第二信使，不是第一信使"},{"q":"触发骨骼肌细胞收缩的离子是","o":["钠离子","钾离子","钙离子","氯离子","镁离子"],"a":2,"e":"肌细胞膜兴奋后肌质网终池释放Ca2+进入胞质，Ca2+与肌钙蛋白结合触发横桥循环，引起肌丝滑行和肌肉收缩，故Ca2+是兴奋-收缩耦联的关键离子。A项Na+参与动作电位产生；B项K+与复极有关；D项Cl-、E项Mg2+不触发收缩"},{"q":"排便感由下列哪种原因引起","o":["横结肠积聚粪便","降结肠积聚粪便","乙状结肠积聚粪便","粪便进入直肠","粪便刺激肛门"],"a":3,"e":"粪便进入直肠后刺激直肠壁内感受器，冲动沿盆神经与骶髓传入，产生便意即排便感。横结肠、降结肠、乙状结肠仅储存与输送粪便，未直接触发排便反射；粪便刺激肛门主要引起括约肌反应，便意的产生以直肠充盈扩张为始动因素"},{"q":"胃肠平滑肌收缩的强度主要取决于","o":["慢波频率","慢波的幅度","动作电位的幅度","动作电位的频率","动作电位的时程"],"a":3,"e":"胃肠平滑肌每个动作电位引起一次收缩，收缩强度主要取决于动作电位的频率，频率越高收缩越强并可融合为强直收缩。慢波频率（A项）决定收缩节律；慢波幅度（B项）非主要因素；动作电位幅度（C项）呈全或无；动作电位时程（E项）影响单收缩时长，均非决定收缩强度的关键"},{"q":"内分泌细胞分泌激素到组织液的过程属于","o":["入胞","易化扩散","出胞","主动转运","单纯扩散"],"a":2,"e":"内分泌细胞释放激素时，分泌囊泡与细胞膜融合并将内容物排出，属出胞。载体与通道介导的易化扩散、原发性和继发性主动转运都是跨膜转运小分子的方式，不用于大分子激素释放"},{"q":"下列选项的描述不是“膜泡运输”特征的是","o":["批量运输","转运过程不消耗能量","包括入胞和出胞两个过程","转运的是大分子和颗粒物质","运输过程有多种蛋白质参与"],"a":1,"e":"膜泡运输包括入胞与出胞，用于转运大分子和颗粒物质，具有批量运输特点，过程涉及膜运动与多种蛋白质参与，并消耗ATP，故“不消耗能量”不是其特征。批量运输（A项）、包括入胞和出胞（C项）、转运大分子颗粒（D项）、多种蛋白质参与（E项）均为膜泡运输的正确特征"},{"q":"下列关于消化道平滑肌基本电节律的论述，错误的是","o":["在胃肠不收缩的情况下，也可记录到基本电节律","基本电节律的波幅和频率与平滑肌组织的种类无关","基本电节律起源于环行肌与纵行肌层之间的间质细胞","基本电节律的产生是肌源性的","动作电位是在基本电节律的基础上产生的"],"a":1,"e":"消化道平滑肌基本电节律的波幅和频率因部位和肌组织种类而异，如胃约每分钟3次、十二指肠约12次，故与平滑肌组织种类无关一项错误。基本电节律起源于环行肌与纵行肌之间的Cajal间质细胞，属肌源性，静息时也可记录，动作电位在其基础上产生"},{"q":"肾上腺皮质功能减退时可出现","o":["血容量增多","血容量减少","血浆钠浓度升高","血浆钾浓度降低","血压升高"],"a":1,"e":"肾上腺皮质功能减退时醛固酮和皮质醇分泌不足，Na+与水排出增多，导致血容量减少、血压下降。此时血钠降低而非升高，血钾升高而非降低，血容量增多亦与实际相反，故相应选项均不成立"},{"q":"窦房结细胞的起搏活动是由于","o":["递减性K＋外流","递增性净内向电流","递减性K＋外流与递增性Na＋内流","经T型Ca2＋通道的递增性内流","递减性K＋外流与L型Ca2＋通道的递增性内流"],"a":1,"e":"窦房结4期自动去极化由随时间递增的净内向电流形成，包括If钠内流、T型Ca2+内流及递减的K+外流，故起搏活动源于递增性净内向电流。递减性K+外流与递增性Na+内流只是部分机制，未涵盖钙内流，不够全面；单独T型Ca2+通道或L型Ca2+通道内流仅为其中成分，不足以解释全部起搏电流"},{"q":"根据听觉的行波原理，临床上高频听力受损的病人，其受损的部位应更靠近","o":["蜗底部","蜗顶部","耳蜗中段","耳蜗全段","耳蜗前1/3"],"a":0,"e":"按行波原理，不同频率声波在耳蜗基底膜不同部位形成最大振幅，频率越高越靠近蜗底部，越低越靠近蜗顶部，故高频听力受损部位更靠近蜗底部。耳蜗中段、全段及前1/3均非高频声波最大振幅区"},{"q":"调节红细胞生成的主要体液因素是","o":["雄激素","雌激素","甲状腺激素","促红细胞生成素","生长激素"],"a":3,"e":"促红细胞生成素主要由肾（及肝）产生，是调节红细胞生成的主要体液因素，缺氧时分泌增加并促进骨髓红系造血。A项雄激素可刺激红细胞生成但非主要因素；B项雌激素抑制红细胞生成；C项甲状腺激素、E项生长激素影响代谢与生长，对红细胞生成仅有辅助作用"},{"q":"下列关于人体生理学的叙述，错误的是","o":["是生物科学的一个分支","研究人体功能活动及其规律","是1门连接基础和临床学科的桥梁学科","大多数资料来自人体实验","为临床实践提供思维方法和研究手段"],"a":3,"e":"人体生理学的大多数研究资料来自动物实验，因人体实验受伦理和条件限制，故大多数资料来自人体实验一项错误。人体生理学是生物科学分支，研究人体功能活动规律，是连接基础与临床的桥梁学科，并为临床实践提供思维方法和研究手段"},{"q":"在下列类型心肌细胞中，属于快反应自律细胞的是","o":["窦房结P细胞","心房肌细胞","心室肌细胞","浦肯野细胞","房室结细胞"],"a":3,"e":"浦肯野细胞属快反应自律细胞，0期去极化由快Na+通道介导、速度快，并有4期自动去极化。窦房结P细胞与房室结细胞为慢反应自律细胞，去极化依赖Ca2+内流、速度慢。心房肌细胞和心室肌细胞是快反应非自律细胞，无自动去极化"},{"q":"大脑皮层调节内脏活动的主要结构是","o":["颞叶","边缘叶","枕叶","额叶","顶叶"],"a":1,"e":"边缘叶包括扣带回、海马等，是大脑皮层调节内脏活动的主要结构，属边缘系统，参与情绪、摄食与自主神经功能调节。颞叶、枕叶、顶叶主要参与感觉与认知功能；额叶与随意运动和高级认知有关，均非调节内脏活动的主要皮层结构"},{"q":"出现去大脑僵直现象是由于","o":["切除了大部分脑干网状结构抑制区","切除了大部分脑干网状结构易化区","切断了网状结构和皮层运动区及纹状体之间的联系","切断了网状结构和小脑之间的联系","切断了网状结构和前庭核之间的联系"],"a":2,"e":"去大脑僵直是在中脑水平切断脑干，使大脑皮层运动区、纹状体与网状结构抑制区的联系中断，抑制区活动减弱，易化区活动相对占优势，导致全身伸肌肌紧张亢进。切除抑制区本身并不能造成该现象；易化区、小脑或前庭核与网状结构的联系切断也不是去大脑僵直的机制"},{"q":"关于缩宫素的主要生理作用，描述正确的是","o":["刺激输卵管收缩，促进卵子运行","刺激催乳素分泌，促进乳汁分泌","刺激乳腺肌上皮细胞收缩，使乳汁排出","促进非孕子宫收缩","大剂量可引起子宫肌发生节律性收缩"],"a":2,"e":"缩宫素由下丘脑合成、神经垂体释放，能使乳腺肌上皮细胞收缩，促使乳汁排出；对妊娠子宫平滑肌也有强烈收缩作用。非孕子宫对缩宫素不敏感，雌激素可提高其敏感性。刺激催乳素分泌的是吸吮反射，并非缩宫素；输卵管收缩亦非其主要作用。大剂量缩宫素引起子宫强直性收缩而非节律性收缩"},{"q":"在中脑上下丘之间切断动物脑干，将会出现","o":["脊休克","去大脑僵直","昏睡不醒","站立不稳","运动共济失调"],"a":1,"e":"在中脑上、下丘之间切断脑干，破坏了大脑皮层及纹状体对网状结构抑制区的下行影响，使易化区活动相对占优势，导致伸肌肌张力显著增强，出现去大脑僵直。A项脊休克见于脊髓与高位中枢离断；C项昏睡与网状结构上行激活系统受损有关，非该切面典型表现；D、E项为小脑或前庭损伤的表现"},{"q":"红细胞渗透脆性指的是","o":["红细胞对高渗盐溶液的抵抗力","红细胞在低渗盐溶液中膨胀破裂的特性","红细胞在生理盐溶液中破裂的特性","红细胞耐受机械撞击的能力","红细胞相互撞击破裂的特性"],"a":1,"e":"红细胞渗透脆性指红细胞在低渗盐溶液中因吸水膨胀而破裂溶血的特性，脆性越大对低渗溶液抵抗力越小。A项红细胞对高渗盐溶液表现为皱缩而非破裂；C项生理盐水中红细胞形态正常；D项耐受机械撞击的能力为机械脆性；E项红细胞相互撞击破裂并非渗透脆性的定义，均不符合"},{"q":"下列关于电突触传递的描述，正确的是","o":["结构基础是离子通道","传递速度慢，潜伏期长","允许所有带电物质通过","一般为单向传递","可促进神经元的同步电活动"],"a":4,"e":"电突触以缝隙连接为结构基础，离子可直接通过，传递速度快、几乎无潜伏期，多为双向传递，有利于相邻神经元活动同步化。A项结构基础应为缝隙连接而非一般离子通道；B项速度慢、潜伏期长是化学突触特征；C项并非所有带电物质都能通过，有选择性；D项一般为双向传递而非单向"},{"q":"胰高血糖素对糖代谢作用的靶器官是","o":["肌肉","小肠","肝","大脑","肾"],"a":2,"e":"胰高血糖素主要作用于肝脏，通过cAMP-PKA途径促进肝糖原分解和糖异生，升高血糖。肌肉组织缺乏胰高血糖素受体，其糖原分解主要由肾上腺素和运动引起，不能被胰高血糖素调动。小肠、大脑和肾也不是胰高血糖素调节糖代谢的主要靶器官"},{"q":"葡萄糖在小肠黏膜上皮处的吸收是通过继发性主动转运实现的，抑制下列哪种功能活动可以影响该葡萄糖的吸收","o":["钠泵","钙泵","质子泵","钠钙交换体","钠氢交换体"],"a":0,"e":"小肠葡萄糖吸收依靠顶端膜Na+-葡萄糖同向转运体，其动力来自钠泵建立的Na+浓度梯度，抑制钠泵即削弱该梯度，从而影响葡萄糖吸收。钙泵、质子泵维持其他离子梯度；钠钙交换体、钠氢交换体不参与葡萄糖的跨膜转运"}];
